var __index = {"config":{"lang":["en"],"separator":"[\\s\\u200b\\u3000\\-\u3001\u3002\uff0c\uff0e\uff1f\uff01\uff1b]+","pipeline":["stemmer"]},"docs":[{"location":"index.html","title":"Home","text":""},{"location":"index.html#home","title":"Home","text":"<p>\u8fd9\u662f\u6211\u7684Blog\u3002</p> <p>\u53ef\u4ee5\u5728\u4e0a\u65b9\u83dc\u5355\u5bfb\u627e\u9700\u8981\u7684\u5185\u5bb9\u3002</p> <p>\u6211\u7684\u90ae\u7bb1\uff1afanyc22[at]mails.tsinghua.edu.cn</p> <p>This is my blog.</p> <p>You can explore this site via the nav above.</p> <p>Contact me: fanyc22[at]mails.tsinghua.edu.cn</p>"},{"location":"APHP/C1.html","title":"1. Introduction","text":"<p>\u9884\u53d6\u673a\u5236\u5e94\u5f53\u8003\u8651\u4ee5\u4e0b\u51e0\u70b9\uff1a</p> <ul> <li>Accuracy: \u77e5\u9053\u9884\u53d6\u5730\u5740\u662f\u4ec0\u4e48</li> <li>Timeliness: \u77e5\u9053\u4f55\u65f6\u53d1\u51fa\u9884\u53d6\u8bf7\u6c42</li> <li>Placement: \u77e5\u9053\u653e\u5728\u54ea\u91cc\uff0c\u5fc5\u8981\u65f6\u8fd8\u9700\u786e\u5b9a\u88ab\u66ff\u6362\u6570\u636e</li> </ul>"},{"location":"APHP/C1.html#11-accuracy","title":"1.1 Accuracy","text":"<p>\u8861\u91cfAccuracy\u6307\u6807\uff1a</p> <ul> <li>\u8986\u76d6\u7387\u8861\u91cf\u663e\u5f0f\u5904\u7406\u5668\u8bf7\u6c42\u4e2d\u9884\u53d6\u6210\u529f\u7684\u6bd4\u4f8b\uff08\u5373\u901a\u8fc7\u9884\u53d6\u6d88\u9664\u7684\u7f3a\u9875\u8bf7\u6c42\u6bd4\u4f8b\uff09</li> <li>\u51c6\u786e\u7387\u8861\u91cf\u9884\u53d6\u5668\u53d1\u8d77\u7684\u8bbf\u95ee\u4e2d\u5b9e\u9645\u6709\u7528\u7684\u6bd4\u4f8b\uff08\u5373\u6b63\u786e\u9884\u5360\u5360\u5168\u90e8\u9884\u53d6\u7684\u6bd4\u4f8b\uff09\u3002</li> </ul> <p>\u8bb8\u591a\u7b80\u5355\u9884\u53d6\u5668\u80fd\u4ee5\u727a\u7272\u51c6\u786e\u7387\u4e3a\u4ee3\u4ef7\u63d0\u5347\u8986\u76d6\u7387\uff0c\u800c\u7406\u60f3\u7684\u9884\u53d6\u5668\u5e94\u540c\u65f6\u5177\u5907\u9ad8\u51c6\u786e\u7387\u548c\u9ad8\u8986\u76d6\u7387\u3002</p>"},{"location":"APHP/C1.html#12-timeliness","title":"1.2 Timeliness","text":"<p>\u7406\u60f3\u60c5\u51b5\u4e0b\uff0c\u9884\u53d6\u673a\u5236\u5e94\u63d0\u524d\u53d1\u8d77\u9884\u53d6\u64cd\u4f5c\u5e76\u63d0\u4f9b\u8db3\u591f\u7684\u9884\u53d6\u6570\u636e\u5b58\u50a8\u7a7a\u95f4\uff0c\u4ee5\u5b8c\u5168\u9690\u85cf\u5185\u5b58\u8bbf\u95ee\u5ef6\u8fdf\u3002</p> <p>\u5373\u4f7f\u5730\u5740\u9884\u6d4b\u6b63\u786e\uff0c\u8fc7\u65e9\u53d1\u8d77\u9884\u53d6\u7684\u9884\u53d6\u5668\u53ef\u80fd\u65e0\u6cd5\u5728\u8bbf\u95ee\u524d\u5c06\u5168\u90e8\u9884\u53d6\u5185\u5b58\u957f\u671f\u4fdd\u5b58\u5728\u5904\u7406\u5668\u8fd1\u7aef\uff1a</p> <ul> <li>\u6700\u4f73\u60c5\u51b5\u4e0b\uff0c\u8fc7\u65e9\u9884\u53d6\u4f1a\u56e0\u9884\u53d6\u4fe1\u606f\u5728\u4f7f\u7528\u524d\u88ab\u9010\u51fa\u800c\u5931\u6548</li> <li>\u6700\u5dee\u60c5\u51b5\u4e0b\uff0c\u53ef\u80fd\u9a71\u9010\u5176\u4ed6\u6709\u7528\u4fe1\u606f\uff08\u5982\u5176\u4ed6\u9884\u53d6\u5185\u5b58\u6216\u9ad8\u5c42\u7f13\u5b58\u4e2d\u7684\u6709\u6548\u6570\u636e\u5757\uff09\u3002</li> </ul> <p>\u82e5\u5185\u5b58\u9884\u53d6\u8fc7\u665a\uff1a</p> <ul> <li>\u5219\u4f1a\u5728\u5185\u5b58\u8bbf\u95ee\u65f6\u66b4\u9732\u8bbf\u95ee\u5ef6\u8fdf\uff0c\u524a\u5f31\u9884\u53d6\u6548\u679c</li> <li>\u6781\u7aef\u60c5\u51b5\u4e0b\uff0c\u5ef6\u8fdf\u9884\u53d6\u53ef\u80fd\u56e0\u589e\u52a0\u5185\u5b58\u7cfb\u7edf\u6d41\u91cf\u4ee5\u53ca\u4e0e\u65f6\u6548\u6027\u9700\u6c42\u8bbf\u95ee\u4f18\u5148\u673a\u5236\u7684\u76f8\u4e92\u5e72\u6270\u800c\u5bfc\u81f4\u6027\u80fd\u4e0b\u964d\u3002</li> </ul>"},{"location":"APHP/C1.html#13-placement","title":"1.3 Placement","text":"<p>\u9884\u53d6\u503c\u7684\u5b58\u653e\u4f4d\u7f6e\u6700\u57fa\u7840\u4e14\u5386\u53f2\u6700\u60a0\u4e45\u7684\u6570\u636e\u9884\u53d6\u8f6f\u4ef6\u7b56\u7565\u662f\u5c06\u6570\u636e\u52a0\u8f7d\u81f3\u5904\u7406\u5668\u5bc4\u5b58\u5668\uff0c\u8fd9\u4e0e\u5e38\u89c4\u663e\u5f0f\u52a0\u8f7d\u64cd\u4f5c\u7c7b\u4f3c\u3002\u8bb8\u591a\u4f53\u7cfb\u7ed3\u6784\uff08\u7279\u522b\u662f\u73b0\u4ee3\u4e71\u5e8f\u5904\u7406\u5668\uff09\u5728\u53d1\u51fa\u52a0\u8f7d\u6307\u4ee4\u65f6\u4e0d\u4f1a\u6682\u505c\u6267\u884c\uff0c\u4ec5\u5f53\u52a0\u8f7d\u503c\u88ab\u5176\u4ed6\u6307\u4ee4\u9700\u8981\u65f6\u624d\u6682\u505c\u76f8\u5173\u6307\u4ee4\u3002\u8fd9\u79cd\u9884\u53d6\u7b56\u7565\u5e38\u88ab\u79f0\u4e3a\u7ed1\u5b9a\u5f0f\u9884\u53d6\uff0c\u56e0\u4e3a\u6570\u636e\u540e\u7eed\u4f7f\u7528\u7684\u503c\u5728\u9884\u53d6\u53d1\u51fa\u65f6\u5373\u88ab\u7ed1\u5b9a\u3002\u8be5\u65b9\u6cd5\u5b58\u5728\u82e5\u5e72\u7f3a\u9677\uff1a</p> <ol> <li>\u5360\u7528\u5b9d\u8d35\u7684\u5904\u7406\u5668\u5bc4\u5b58\u5668</li> <li>\u5373\u4f7f\u5185\u5b58\u7cfb\u7edf\u8d1f\u8f7d\u8f83\u91cd\u4ecd\u5f3a\u5236\u786c\u4ef6\u6267\u884c\u9884\u53d6</li> <li>\u5f53\u9884\u53d6\u5730\u5740\u9519\u8bef\u65f6\u5f15\u53d1\u8bed\u4e49\u96be\u9898\uff08\u4f8b\u5982\u5bf9\u65e0\u6548\u5730\u5740\u7684\u9884\u53d6\u662f\u5426\u5e94\u89e6\u53d1\u5185\u5b58\u4fdd\u62a4\u9519\u8bef\uff09</li> <li>\u96be\u4ee5\u5c06\u8be5\u7b56\u7565\u5e94\u7528\u4e8e\u6307\u4ee4\u9884\u53d6\u3002</li> </ol> <p>\u5b9e\u9645\u4e0a\uff0c\u5927\u591a\u6570\u786c\u4ef6\u9884\u53d6\u6280\u672f\u4f1a\u5c06\u9884\u53d6\u503c\u76f4\u63a5\u5b58\u5165\u7f13\u5b58\u5c42\u6b21\u7ed3\u6784\uff0c\u6216\u662f\u5b58\u5165\u7528\u4e8e\u6269\u5c55\u7f13\u5b58\u5c42\u7ea7\u7684\u8f85\u52a9\u7f13\u51b2\u533a\u4e2d\uff0c\u5e76\u652f\u6301\u5e76\u53d1\u8bbf\u95ee\u3002\u5728\u591a\u6838\u4e0e\u591a\u5904\u7406\u5668\u7cfb\u7edf\u4e2d\uff0c\u8fd9\u4e9b\u7f13\u5b58\u4e0e\u7f13\u51b2\u533a\u9700\u9075\u5faa\u7f13\u5b58\u4e00\u81f4\u6027\u534f\u8bae\uff0c\u56e0\u6b64\u9884\u53d6\u7684\u5185\u5b58\u4f4d\u7f6e\u503c\u53ef\u80fd\u5728\u9884\u53d6\u64cd\u4f5c\u4e0e\u540e\u7eed\u8bbf\u95ee\u4e4b\u95f4\u7684\u65f6\u95f4\u6bb5\u5185\u53d1\u751f\u53d8\u66f4\uff1b\u786c\u4ef6\u9700\u786e\u4fdd\u8bbf\u95ee\u65f6\u80fd\u83b7\u53d6\u5230\u6700\u65b0\u503c\u3002\u6b64\u7c7b\u9884\u53d6\u7b56\u7565\u88ab\u79f0\u4e3a\u975e\u7ed1\u5b9a\u5f0f\u9884\u53d6\u3002\u5728\u8fd9\u4e9b\u65b9\u6848\u4e2d\uff0c\u9884\u53d6\u7eaf\u7cb9\u662f\u6027\u80fd\u4f18\u5316\u624b\u6bb5\uff0c\u4e0d\u4f1a\u6539\u53d8\u7a0b\u5e8f\u8bed\u4e49\u3002</p> <p>\u672c\u4e66\u6d89\u53ca\u7684\u6240\u6709\u786c\u4ef6\u9884\u53d6\u5668\u5747\u5c5e\u4e8e\u540e\u4e00\u79cd\u975e\u7ed1\u5b9a\u5f0f\u7c7b\u522b\u3002\u5b83\u4eec\u7684\u6838\u5fc3\u5dee\u5f02\u5728\u4e8e\u9884\u53d6\u503c\u7684\u5177\u4f53\u5b58\u653e\u4f4d\u7f6e\uff0c\u4ee5\u53ca\u4e3a\u5bb9\u7eb3\u65b0\u9884\u53d6\u5185\u5b58\u800c\u5b9e\u65bd\u7684\u66ff\u6362\u7b56\u7565\u3002</p>"},{"location":"APHP/C2.html","title":"2. Instruction Prefetching","text":"<p>\u6307\u4ee4\u83b7\u53d6\u505c\u987f\u5bf9\u5177\u6709\u5927\u6307\u4ee4\u5de5\u4f5c\u8d1f\u8f7d\u7684\u6027\u80fd\u6781\u4e3a\u4e0d\u5229\uff1b\u5f53\u6307\u4ee4\u4f9b\u5e94\u901f\u5ea6\u51cf\u6162\u65f6\uff0c\u5904\u7406\u5668\u6d41\u6c34\u7ebf\u7684\u6267\u884c\u8d44\u6e90\uff08\u65e0\u8bba\u591a\u4e48\u4e30\u5bcc\uff09\u5c06\u88ab\u6d6a\u8d39\u3002\u5c3d\u7ba1\u684c\u9762\u548c\u79d1\u5b66\u8ba1\u7b97\u5de5\u4f5c\u8d1f\u8f7d\u901a\u5e38\u8868\u73b0\u51fa\u8f83\u5c0f\u7684\u6307\u4ee4\u5de5\u4f5c\u96c6\uff0c\u4f46\u4f20\u7edf\u670d\u52a1\u5668\u5de5\u4f5c\u8d1f\u8f7d\u548c\u65b0\u5174\u4e91\u5de5\u4f5c\u8d1f\u8f7d\u7684\u4e3b\u8981\u6307\u4ee4\u5de5\u4f5c\u96c6\u5f80\u5f80\u8fdc\u8d85\u4e0a\u5c42\u7f13\u5b58\u6240\u80fd\u5bb9\u7eb3\u7684\u8303\u56f4\u3002\u968f\u7740\u5feb\u901f\u8f6f\u4ef6\u5f00\u53d1\u3001\u811a\u672c\u5316\u7f16\u7a0b\u8303\u5f0f\u4ee5\u53ca\u8f6f\u4ef6\u6808\u6df1\u5ea6\u4e0d\u65ad\u589e\u52a0\u7684\u865a\u62df\u5316\u73af\u5883\u7684\u53d1\u5c55\u8d8b\u52bf\uff0c\u4e3b\u8981\u6307\u4ee4\u5de5\u4f5c\u96c6\u4e5f\u5728\u8fc5\u901f\u589e\u957f\u3002\u73b0\u4ee3\u786c\u4ef6\u6307\u4ee4\u8c03\u5ea6\u6280\u672f\uff0c\u5982\u4e71\u5e8f\u6267\u884c\uff0c\u901a\u5e38\u80fd\u6709\u6548\u9690\u85cf\u56e0\u6570\u636e\u8bbf\u95ee\u548c\u5176\u4ed6\u957f\u5ef6\u8fdf\u6307\u4ee4\u5f15\u8d77\u7684\u90e8\u5206\u6216\u5168\u90e8\u505c\u987f\u3002\u7136\u800c\uff0c\u4e71\u5e8f\u6267\u884c\u901a\u5e38\u65e0\u6cd5\u9690\u85cf\u6307\u4ee4\u83b7\u53d6\u5ef6\u8fdf\u3002\u56e0\u6b64\uff0c\u5728\u670d\u52a1\u5668\u4e2d\uff0c\u6307\u4ee4\u505c\u987f\u5f80\u5f80\u5360\u6574\u4f53\u5185\u5b58\u505c\u987f\u7684\u5f88\u5927\u4e00\u90e8\u5206\u3002</p>"},{"location":"APHP/C2.html#21-next-line-prefetching","title":"2.1 Next-Line Prefetching","text":"<p>\u4e0b\u4e00\u884c\u9884\u53d6[5]\u662f\u6307\u4ee4\u9884\u53d6\u7684\u6700\u7b80\u5355\u5f62\u5f0f\uff0c\u5728\u5927\u591a\u6570\u73b0\u4ee3\u5904\u7406\u5668\u8bbe\u8ba1\u4e2d\u666e\u904d\u5b58\u5728\u3002\u7531\u4e8e\u4ee3\u7801\u5728\u5185\u5b58\u4e2d\u6309\u987a\u5e8f\u5e03\u5c40\u5728\u8fde\u7eed\u7684\u5b58\u50a8\u5668\u5730\u5740\u4e0a\uff0c\u6307\u4ee4\u7f13\u5b58\u4e2d\u8d85\u8fc7\u4e00\u534a\u7684\u67e5\u627e\u901a\u5e38\u9488\u5bf9\u987a\u5e8f\u5730\u5740\u3002\u751f\u6210\u987a\u5e8f\u5730\u5740\u5e76\u83b7\u53d6\u5b83\u4eec\u6240\u9700\u7684\u903b\u8f91\u6781\u5c11\uff0c\u5e76\u4e14\u76f8\u5f53\u5bb9\u6613\u96c6\u6210\u5230\u5904\u7406\u5668\u548c\u7f13\u5b58\u5c42\u6b21\u7ed3\u6784\u4e2d\u3002</p>"},{"location":"APHP/C2.html#22-fetch-directed-prefetching-fdip","title":"2.2 Fetch-Directed Prefetching (FDIP)","text":"<p>\u4e0b\u4e00\u884c\u9884\u53d6\u5668\u975e\u5e38\u9ad8\u6548\uff0c\u4f46\u4ec5\u6709\u4e00\u534a\u7684\u6307\u4ee4\u67e5\u627e\u662f\u987a\u5e8f\u7684\u3002\u63a7\u5236\u6d41\u6307\u4ee4\u4f1a\u6253\u7834\u987a\u5e8f\u53d6\u6307\u5e76\u9020\u6210\u95f4\u65ad\uff0c\u56e0\u6b64\u9700\u8981\u9884\u6d4b\u672a\u6765\u63a7\u5236\u6d41\u5e76\u8fdb\u884c\u524d\u77bb\u3002</p> <p></p> <p>\u5c3d\u7ba1FDIP\u80fd\u6709\u6548\u51cf\u5c11\u6307\u4ee4\u83b7\u53d6\u5ef6\u8fdf\uff0c\u4f46\u5176\u9884\u53d6\u524d\u77bb\u80fd\u529b\u5b58\u5728\u6839\u672c\u6027\u5c40\u9650\u3002\u56fe2.5\u91cf\u5316\u4e86\u5206\u652f\u9884\u6d4b\u5e26\u5bbd\u4e0e\u9884\u53d6\u524d\u77bb\u80fd\u529b\u7684\u5173\u7cfb\uff1a\u8fd1\u534a\u6570\u6307\u4ee4\u7f13\u5b58\u7f3a\u5931\u9700\u8981\u8fde\u7eed16\u6b21\u4ee5\u4e0a\u6b63\u786e\u5206\u652f\u9884\u6d4b\uff08\u4e0d\u542b\u5185\u5faa\u73af\u5206\u652f\uff09\u624d\u80fd\u751f\u6210\u5019\u9009\u9884\u53d6\u5730\u5740\u3002</p> <p></p>"},{"location":"APHP/C2.html#23-discontinuity-prefetching","title":"2.3 Discontinuity Prefetching","text":"<p>\u66f4\u4e25\u5cfb\u7684\u6311\u6218\u5728\u4e8e\u83b7\u53d6\u65ad\u70b9\u5904\u7684\u9884\u53d6\u2014\u2014\u5373\u7531\u51fd\u6570\u8c03\u7528\u3001\u6761\u4ef6\u5206\u652f\u8df3\u8f6c\u548c\u9677\u9631\u5bfc\u81f4\u7684\u987a\u5e8f\u6307\u4ee4\u83b7\u53d6\u5e8f\u5217\u4e2d\u65ad\u3002</p> <p>\u9488\u5bf9\u63a7\u5236\u6d41\u975e\u8fde\u7eed\u6027\u5b58\u5728\u591a\u79cd\u89e3\u51b3\u65b9\u6848\u3002\u9519\u8bef\u8def\u5f84\u9884\u53d6[16]\u662f\u4e00\u79cd\u901a\u8fc7\u4f7f\u7528\u5206\u652f\u9884\u6d4b\u5668\u4f46\u9884\u6d4b\u76f8\u53cd\u8def\u5f84\u6765\u89e3\u51b3FDIP\u57fa\u7840\u95ee\u9898\u7684\u7b80\u5355\u65b9\u6cd5\u3002\u5c3d\u7ba1\u6548\u679c\u6709\u9650\uff0c\u9884\u6d4b\u9519\u8bef\u8def\u5f84\u80fd\u591f\u8d8a\u8fc7\u6570\u636e\u76f8\u5173\u5206\u652f\u8fdb\u884c\u9884\u53d6\uff0c\u5e76\u4e14\u901a\u8fc7\u540e\u5411\u5faa\u73af\u5206\u652f\u7684\u51fa\u53e3\u53ef\u4ee5\u9884\u53d6\u5230FDIP\u65e0\u6cd5\u83b7\u53d6\u7684\u6307\u4ee4\u3002</p> <p>\u57fa\u4e8e\u5206\u652f\u5386\u53f2\u7684\u9884\u53d6\u5668[17]\u3001\u57fa\u4e8e\u6267\u884c\u5386\u53f2\u7684\u9884\u53d6\u5668[18]\u3001\u591a\u6d41\u9884\u6d4b\u5668[10]\u3001\u4e0b\u4e00\u6761\u8e2a\u8ff9\u9884\u6d4b\u5668[19]\u4ee5\u53ca\u8c03\u7528\u56fe\u9884\u53d6[20]\u7b49\u6280\u672f\uff0c\u5747\u901a\u8fc7\u524d\u5e8f\u6307\u4ee4\u4f5c\u4e3a\u7d22\u5f15\u6765\u9884\u6d4b\u975e\u8fde\u7eed\u6027\uff0c\u5176\u8ffd\u8e2a\u673a\u5236\u72ec\u7acb\u4e8e\u5206\u652f\u9884\u6d4b\u5668\u3002\u57fa\u4e8e\u670d\u52a1\u5668\u5e94\u7528\u5177\u6709\u6df1\u5c42\u91cd\u590d\u51fd\u6570\u8c03\u7528\u6808\u7684\u89c2\u5bdf\uff0c\u8c03\u7528\u56fe\u9884\u53d6[20]\u81f4\u529b\u4e8e\u540c\u65f6\u9884\u6d4b\u6574\u4e2a\u8c03\u7528\u6808\u7684\u8d70\u5411\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u4e0b\u4e00\u4e2a\u975e\u8fde\u7eed\u70b9\u3002</p> <p>\u8be5\u65b9\u6848\u7684\u6700\u65b0\u5b9e\u4f8b\u662f\u975e\u8fde\u7eed\u6027\u9884\u6d4b\u5668[21]\uff08\u5982\u56fe2.6\u6240\u793a\uff09\uff0c\u5176\u7ef4\u62a4\u4e86\u4e00\u4e2a\u53d6\u6307\u975e\u8fde\u7eed\u6027\u6620\u5c04\u8868\uff0c\u5c06\u5305\u542b\u5df2\u6267\u884c\u5206\u652f\u7684\u7a0b\u5e8f\u8ba1\u6570\u5668\u6620\u5c04\u81f3\u5206\u652f\u76ee\u6807\u3002\u636e\u4f20\u67d0\u4e9b\u5546\u7528\u5904\u7406\u5668\u4ea7\u54c1\u4e2d\u5df2\u6709\u7c7b\u4f3c\u5b9e\u73b0\u3002\u5f53\u4e0b\u4e00\u884c\u6307\u4ee4\u9884\u53d6\u5668\u5728\u53d6\u6307\u5355\u5143\u524d\u65b9\u63a2\u7d22\u65f6\uff0c\u4f1a\u4f7f\u7528\u6bcf\u4e2a\u5757\u5730\u5740\u67e5\u8be2\u975e\u8fde\u7eed\u6027\u8868\uff0c\u82e5\u5339\u914d\u6210\u529f\uff0c\u5219\u9664\u4e86\u987a\u5e8f\u8def\u5f84\u5916\u8fd8\u4f1a\u9884\u53d6\u975e\u8fde\u7eed\u8def\u5f84\u3002\u867d\u7136\u8be5\u65b9\u6848\u7b80\u5355\u4e14\u786c\u4ef6\u9700\u6c42\u6781\u4f4e\uff0c\u4f46\u975e\u8fde\u7eed\u6027\u9884\u6d4b\u5668\u4ec5\u80fd\u8de8\u8d8a\u5355\u6b21\u53d6\u6307\u975e\u8fde\u7eed\u6027\uff1b\u82e5\u901a\u8fc7\u9012\u5f52\u67e5\u627e\u63a2\u7d22\u66f4\u591a\u8def\u5f84\uff0c\u4f1a\u5bfc\u81f4\u9884\u53d6\u5757\u6570\u5448\u6307\u6570\u7ea7\u589e\u957f\u3002\u6700\u591a\u904d\u5386\u4e00\u4e2a\u975e\u8fde\u7eed\u70b9\u7684\u9650\u5236\u7ea6\u675f\u4e86\u9884\u53d6\u5668\u7684\u524d\u77bb\u80fd\u529b\u3002\u6b64\u5916\uff0c\u7531\u4e8e\u6bcf\u4e2a\u7f13\u5b58\u5757\u4ec5\u80fd\u8bb0\u5f55\u4e00\u4e2a\u975e\u8fde\u7eed\u70b9\uff0c\u800c\u5f53\u6307\u4ee4\u5757\u5185\u5b58\u5728\u591a\u4e2a\u5df2\u6267\u884c\u5206\u652f\u65f6\uff0c\u5176\u8986\u76d6\u8303\u56f4\u5c06\u53d7\u5230\u9650\u5236\u3002</p> <p></p>"},{"location":"APHP/C2.html#24-prescient-fetch","title":"2.4 Prescient Fetch","text":"<p>\u5229\u7528\u7a7a\u95f2\u6216\u5e76\u884c\u8d44\u6e90\u8fdb\u884c\u6307\u4ee4\u9884\u53d6\u5df2\u88ab\u63d0\u51fa\u3002\u9884\u77e5\u5f0f\u9884\u53d6\u6280\u672f [22, 23, 24, 25] \u4f7f\u7528\u8f85\u52a9\u7ebf\u7a0b\u6765\u8bc6\u522b\u5173\u952e\u8ba1\u7b97\u548c\u63a7\u5236\u8f6c\u79fb\uff0c\u5e76\u63d0\u524d\u6267\u884c\u8fd9\u4e9b\u64cd\u4f5c\uff0c\u4ee5\u8f85\u52a9\u8fd0\u884c\u8f83\u6162\u4e14\u4e0e\u8f85\u52a9\u7ebf\u7a0b\u5e76\u884c\u6267\u884c\u7684\u4e3b\u7ebf\u7a0b\u3002\u5c3d\u7ba1\u8fd9\u4e9b\u65b9\u6cd5\u53ef\u7528\u4e8e\u8d85\u8d8a\u5faa\u73af\u548c\u51fd\u6570\u8c03\u7528\u7684\u6307\u4ee4\u9884\u53d6\uff0c\u4f46\u53ea\u6709\u9884\u77e5\u6307\u4ee4\u9884\u53d6 [22] \u662f\u4e13\u95e8\u4e3a\u6b64\u76ee\u7684\u8bbe\u8ba1\u7684\u3002\u63a8\u6d4b\u5f0f\u7ebf\u7a0b\u6280\u672f\u8bc6\u522b\u6240\u9700\u7684\u5173\u952e\u6267\u884c\u4fe1\u606f\uff0c\u5e76\u5229\u7528\u8be5\u4fe1\u606f\u9886\u5148\u4e8e\u4e3b\u7ebf\u7a0b\u53d1\u8d77\u6307\u4ee4\u9884\u53d6\u3002\u867d\u7136\u63a8\u6d4b\u5f0f\u7ebf\u7a0b\u6280\u672f\u80fd\u591f\u8de8\u8d8a\u591a\u4e2a\u53d6\u6307\u95f4\u65ad\u70b9\uff0c\u4f46\u5176\u524d\u77bb\u80fd\u529b\u4ecd\u7136\u6709\u9650\uff0c\u56e0\u4e3a\u5b83\u4eec\u4ee5\u5355\u4e2a\u6307\u4ee4\u7684\u7c92\u5ea6\u904d\u5386\u672a\u6765\u6307\u4ee4\u6d41\uff0c\u56e0\u6b64\u901a\u5e38\u9700\u8981\u904d\u5386\u5927\u91cf\u6307\u4ee4\u624d\u80fd\u53d1\u73b0\u65b0\u7684\u9884\u53d6\u7f13\u5b58\u5757\u3002</p>"},{"location":"APHP/C2.html#25-temporal-instruction-fetch-streaming-tifs","title":"2.5 Temporal Instruction Fetch Streaming (TIFS)","text":"<p>\u65f6\u5e8f\u6307\u4ee4\u53d6\u6307\u6d41\uff08TIFS\uff09[7] \u65e8\u5728\u89e3\u51b3\u8f85\u52a9\u7ebf\u7a0b\u548c\u57fa\u4e8e\u53d6\u6307/\u95f4\u65ad\u70b9\u673a\u5236\u7684\u524d\u77bb\u5c40\u9650\u6027\u3002TIFS \u4e0d\u63a2\u7d22\u7a0b\u5e8f\u7684\u63a7\u5236\u6d41\u56fe\uff0c\u800c\u662f\u901a\u8fc7\u8bb0\u5f55\u5e76\u91cd\u653e\u91cd\u590d\u51fa\u73b0\u7684 L1 \u6307\u4ee4\u7f3a\u5931\u5e8f\u5217\uff0c\u76f4\u63a5\u9884\u6d4b\u672a\u6765\u7684\u6307\u4ee4\u7f13\u5b58\u7f3a\u5931\u3002</p> <p></p> <p>\u56fe 2.7\u5c55\u793a\u4e86 TIFS \u7684\u8bbe\u8ba1\u3002L1 \u6307\u4ee4\u7f13\u5b58\u7f3a\u5931\u88ab\u8bb0\u5f55\u5728\u6307\u4ee4\u7f3a\u5931\u65e5\u5fd7\u4e2d\uff0c\u8fd9\u662f\u4e00\u4e2a\u5faa\u73af\u7f13\u51b2\u533a\uff0c\u53ef\u5728\u4e13\u7528\u5b58\u50a8\u533a\u6216 L2 \u7f13\u5b58\u5185\u7ef4\u62a4\u3002\u72ec\u7acb\u7684\u7d22\u5f15\u8868\u4fdd\u5b58\u4ece\u6307\u4ee4\u5757\u5730\u5740\u5230\u8be5\u5730\u5740\u5728\u65e5\u5fd7\u4e2d\u6700\u540e\u8bb0\u5f55\u4f4d\u7f6e\u7684\u6620\u5c04\u3002\u5bf9\u5730\u5740 C \u7684 L1-I \u7f3a\u5931\u4f1a\u67e5\u8be2\u7d22\u5f15\u8868 (1)\uff0c\u8be5\u8868\u6307\u5411\u6307\u4ee4\u7f3a\u5931\u65e5\u5fd7\u4e2d\u7684\u4e00\u4e2a\u6761\u76ee (2)\u3002\u7d27\u968f C \u4e4b\u540e\u7684\u5730\u5740\u6d41\u4ece\u65e5\u5fd7\u4e2d\u8bfb\u53d6\uff0c\u7f13\u5b58\u5757\u5730\u5740\u88ab\u53d1\u9001\u5230\u6d41\u5f0f\u503c\u7f13\u51b2\u533a (3)\u3002\u6d41\u5f0f\u503c\u7f13\u51b2\u533a\u5411 L2 \u8bf7\u6c42\u6d41\u4e2d\u7684\u5757 (4)\uff0cL2 \u8fd4\u56de\u5185\u5bb9 (5)\u3002\u4e4b\u540e\uff0c\u5728\u540e\u7eed\u5bf9 D \u7684 L1-I \u7f3a\u5931\u65f6\uff0c\u7f13\u51b2\u533a\u5c06\u5185\u5bb9\u8fd4\u56de\u7ed9 L1-I (6)\u3002</p>"},{"location":"APHP/C2.html#26-ras-directed-instruction-prefetching-rdip","title":"2.6 RAS-Directed Instruction Prefetching (RDIP)","text":"<p>\u4f20\u7edf\u53d6\u6307\u5bfc\u5411\u9884\u53d6\u5668\u56e0\u65e0\u6cd5\u9884\u6d4b\u5faa\u73af\u8fd4\u56de\u5206\u652f\u548c\u4e0d\u53ef\u63a7\u6761\u4ef6\u5206\u652f\u800c\u53d7\u9650\u3002\u975e\u8fde\u7eed\u6027\u9884\u53d6\u5668\u867d\u89e3\u51b3\u8fd9\u4e9b\u5c40\u9650\uff0c\u4f46\u4ec5\u4f9d\u8d56\u5355\u4e2aPC\u503c\u9884\u6d4b\u540e\u7eed\u53d6\u6307\u975e\u8fde\u7eed\u6027\u3002\u540c\u6837\uff0c\u5c3d\u7ba1TIFS\u589e\u5f3a\u4e86\u9884\u8bfb\u80fd\u529b\uff0c\u4ecd\u4ec5\u7ef4\u62a4\u4ece\u7f13\u5b58\u5757\u5230\u65e5\u5fd7\u4f4d\u7f6e\u7684\u5355\u4e00\u6307\u9488\u3002\u8fd9\u4e24\u79cd\u673a\u5236\u5728\u9047\u5230\u7f13\u5b58\u5757\u5b58\u5728\u591a\u63a7\u5236\u6d41\u8def\u5f84\u65f6\u90fd\u4f1a\u5931\u51c6\uff0c\u8fd4\u56de\u6307\u4ee4\u548cswitch\u8bed\u53e5\u7b49\u5e38\u89c1\u6a21\u5f0f\u5c31\u4f1a\u4ea7\u751f\u591a\u8def\u5f84\u3002</p> <p>\u8fd4\u56de\u5730\u5740\u6808\u5bfc\u5411\u6307\u4ee4\u9884\u53d6\uff08RDIP\uff09[26] \u5229\u7528\u989d\u5916\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u4fe1\u606f\u63d0\u5347\u9884\u6d4b\u7cbe\u5ea6\u4e0e\u9884\u8bfb\u80fd\u529b\u3002\u5176\u8bbe\u8ba1\u57fa\u4e8e\u4e24\u70b9\u53d1\u73b0\uff1a\uff081\uff09\u8c03\u7528\u6808\u6355\u83b7\u7684\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u4e0eL1\u6307\u4ee4\u7f13\u5b58\u672a\u547d\u4e2d\u5f3a\u76f8\u5173\uff1b\uff082\uff09\u73b0\u6709\u9ad8\u6027\u80fd\u5904\u7406\u5668\u4e2d\u7684\u8fd4\u56de\u5730\u5740\u6808\uff08RAS\uff09\u53ef\u7cbe\u70bc\u6982\u62ec\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u3002RDIP\u5c06\u9884\u53d6\u64cd\u4f5c\u4e0eRAS\u5185\u5bb9\u6784\u6210\u7684\u7b7e\u540d \u5173\u8054\uff0c\u628a\u7b7e\u540d\u53ca\u5bf9\u5e94\u9884\u53d6\u5730\u5740\u5b58\u5165\u7ea664KB\u7684\u7b7e\u540d\u8868\u3002\u6bcf\u6b21\u8c03\u7528\u548c\u8fd4\u56de\u64cd\u4f5c\u65f6\u67e5\u8be2\u8be5\u8868\u89e6\u53d1\u9884\u53d6\uff0c\u6700\u7ec8\u5b9e\u73b0\u7406\u60f3L1\u7f13\u5b58\u6f5c\u5728\u52a0\u901f\u6548\u679c\u768470%\uff0c\u5728\u670d\u52a1\u5668\u5de5\u4f5c\u8d1f\u8f7d\u5957\u4ef6\u4e0a\u8f83\u65e0\u9884\u53d6\u57fa\u51c6\u63d0\u534711.5%\u3002</p>"},{"location":"APHP/C2.html#27-proactive-instruction-fetch","title":"2.7 Proactive Instruction Fetch","text":"<p>TIFS \u878d\u5408\u4e86\u9010\u884c\u9884\u53d6\u5668\u7684\u987a\u5e8f\u8bbf\u95ee\u9884\u6d4b\u80fd\u529b\uff0c\u4f46\u5176\u6027\u80fd\u4f18\u52bf\u66f4\u4e3a\u663e\u8457\uff0c\u56e0\u4e3a\u9884\u6d4b\u66f4\u7cbe\u51c6\u3001\u66f4\u53ca\u65f6\u3002\u51c6\u786e\u6027\u7684\u63d0\u5347\u6e90\u4e8e TIFS \u4f7f\u7528\u5386\u53f2\u8bb0\u5f55\u6765\u786e\u5b9a\u9700\u8981\u9884\u53d6\u7684\u8fde\u7eed\u540e\u7eed\u5757\u6570\u91cf\u3002</p> <p>TIFS \u901a\u8fc7\u591a\u79cd\u65b9\u5f0f\u63d0\u5347\u9884\u8bfb\u80fd\u529b\uff1a\u9996\u5148\uff0c\u5b83\u4ee5\u7f13\u5b58\u5757\u7c92\u5ea6\u800c\u975e\u5355\u6761\u6307\u4ee4\u8fdb\u884c\u64cd\u4f5c\uff0c\u89e3\u51b3\u4e86\u8f85\u52a9\u7ebf\u7a0b\u65b9\u6cd5\u7684\u5173\u952e\u5c40\u9650\u3002\u56e0\u6b64\uff0c\u5b83\u53ef\u4ee5\u8df3\u8fc7\u7f13\u5b58\u5757\u5185\u7684\u5c40\u90e8\u5faa\u73af\u548c\u6b21\u8981\u63a7\u5236\u6d41\u3002\u901a\u8fc7\u5c06\u975e\u8fde\u7eed\u5206\u652f\u548c\u95f4\u63a5\u8df3\u8f6c\u76ee\u6807\u5355\u72ec\u8bb0\u5f55\u4e3a\u6307\u4ee4\u6d41\u7ec4\u6210\u90e8\u5206\uff0cTIFS \u80fd\u591f\u652f\u6301\u4efb\u610f\u6570\u91cf\u7684\u975e\u8fde\u7eed\u5206\u652f\u3002\u6b64\u5916\uff0c\u7531\u4e8e\u8bb0\u5f55\u4e86\u6307\u4ee4\u7f13\u5b58\u672a\u547d\u4e2d\u7684\u6269\u5c55\u5e8f\u5217\uff0c\u5b83\u80fd\u5feb\u901f\u9884\u6d4b\u8fdc\u671f\u6307\u4ee4\uff0c\u5b9e\u73b0\u663e\u8457\u66f4\u5f3a\u7684\u9884\u8bfb\u80fd\u529b\u3002\u4f8b\u5982\uff0c\u9010\u884c\u9884\u6d4b\u5668\u4ec5\u80fd\u5728\u8bbf\u95ee\u51fd\u6570\u9996\u6307\u4ee4\u5757\u540e\u6b63\u786e\u9884\u53d6\u51fd\u6570\u4f53\uff0c\u800c TIFS \u901a\u8fc7\u9884\u6d4b\u51fd\u6570\u8c03\u7528\u53ca\u5176\u5728\u8fdb\u5165\u51fd\u6570\u524d\u7684\u987a\u5e8f\u8bbf\u95ee\uff0c\u80fd\u5728\u8c03\u7528\u65b9\u6267\u884c\u81f3\u8c03\u7528\u70b9\u524d\u5c31\u63d0\u524d\u9884\u6d4b\u5e76\u9884\u53d6\u76f8\u540c\u6307\u4ee4\u5757\u3002</p> <p>\u9664\u4e86\u65e0\u6cd5\u533a\u5206\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u5916\uff0cTIFS \u7684\u9884\u6d4b\u51c6\u786e\u6027\u8fd8\u53d7\u5230\u5176\u4ed6\u63a7\u5236\u4e0d\u89c4\u5219\u6027\u7684\u5f71\u54cd\uff0c\u8fd9\u4e9b\u4e0d\u89c4\u5219\u6027\u5bfc\u81f4 L1 \u6307\u4ee4\u7f13\u5b58\u7f3a\u5931\u5e8f\u5217\u51fa\u73b0\u7ec6\u5fae\u5dee\u5f02\u3002\u5177\u4f53\u800c\u8a00\uff0c\u539f\u672c\u91cd\u590d\u7684\u6307\u4ee4\u6d41\u53ef\u80fd\u56e0\u7f13\u5b58\u66ff\u6362\u7684\u5fae\u5c0f\u5dee\u5f02\u3001\u6cbf\u8bef\u9884\u6d4b\u5206\u652f\u8def\u5f84\u7684\u6307\u4ee4\u9884\u53d6\u5f71\u54cd\uff0c\u4ee5\u53ca\u5f02\u6b65\u4e2d\u65ad\u548c\u64cd\u4f5c\u7cfb\u7edf\u9677\u9631\u7684\u5f71\u54cd\u800c\u88ab\u5206\u5272\u6216\u8fc7\u6ee4\u3002\u4e3b\u52a8\u6307\u4ee4\u9884\u53d6 [27] \u5bf9 TIFS \u8bbe\u8ba1\u8fdb\u884c\u4e86\u6539\u8fdb\uff0c\u4ee5\uff081\uff09\u8bb0\u5f55\u5df2\u63d0\u4ea4\u6307\u4ee4\u5e8f\u5217\u8bbf\u95ee\u7684\u7f13\u5b58\u5757\u5e8f\u5217\uff08\u800c\u975e\u7f13\u5b58\u7f3a\u5931\u7684\u6307\u4ee4\u9884\u53d6\uff09\uff0c\u5e76\uff082\uff09\u5355\u72ec\u8bb0\u5f55\u5728\u4e2d\u65ad/\u9677\u9631\u5904\u7406\u7a0b\u5e8f\u4e0a\u4e0b\u6587\u4e2d\u6267\u884c\u7684\u6d41\u3002\u8be5\u8bbe\u8ba1\u7684\u4e00\u4e2a\u5173\u952e\u521b\u65b0\u662f\u91c7\u7528\u4f4d\u5411\u91cf\u5bf9\u6307\u4ee4\u5e8f\u5217\u8fdb\u884c\u538b\u7f29\u8868\u793a\uff0c\u4ece\u800c\u9ad8\u6548\u7f16\u7801\u9884\u53d6\u5730\u5740\u95f4\u7684\u7a7a\u95f4\u5c40\u90e8\u6027\u3002\u540e\u7eed\u7814\u7a76 [28] \u5c06\u9884\u53d6\u5668\u5143\u6570\u636e\u96c6\u4e2d\u5b58\u50a8\u4e8e\u591a\u6838\u5171\u4eab\u7684\u7ed3\u6784\u4e2d\uff0c\u8fd9\u5728\u5143\u6570\u636e\u88ab\u591a\u6838\u5171\u4eab\u7684\u540c\u6784\u8bbe\u8ba1\u4e2d\u663e\u8457\u964d\u4f4e\u4e86\u5b58\u50a8\u6210\u672c\u3002\u96c6\u4e2d\u5316\u5c06\u6bcf\u6838\u5143\u6570\u636e\u964d\u81f3\u6700\u5c0f\u5bb9\u91cf\uff0c\u4f7f\u5f97\u9884\u53d6\u5668\u5373\u4fbf\u5728\u91c7\u7528\u5c0f\u6838\uff08\u4f8b\u5982\u79fb\u52a8/\u5d4c\u5165\u5f0f\u5e73\u53f0\u4e2d\u7684\u6838\u5fc3\uff09\u7684\u591a\u6838\u8bbe\u8ba1\u4e2d\u4e5f\u80fd\u5b9e\u7528\u3002</p>"},{"location":"APHP/C2.html#28-conclusion","title":"2.8 Conclusion","text":"\u9884\u53d6\u5668\u540d\u79f0 \u4f7f\u7528\u7684\u5173\u952e\u4fe1\u606f \u9884\u53d6\u6df1\u5ea6 \u51c6\u786e\u7387 \u9762\u79ef Next-Line \u5730\u5740\u987a\u5e8f\u6027 \u51e0\u4e2acache\u5757 50% &lt;1KB FDIP BPU\u4ea7\u751f\u7684\u9884\u6d4b \u53d6\u51b3\u4e8e\u5176\u51c6\u786e\u6027 &gt;50% &lt;1KB Discontinuity \u9884\u6d4b\u7a0b\u5e8f\u7684\u201c\u65ad\u70b9\u201d \u5178\u578b\u60c5\u51b5\u662f\u63d0\u524d\u4e00\u4e2a\u5206\u652f &gt;50% &gt;1KB Prescient Fetch \u8f85\u52a9\u7ebf\u7a0b \u53d6\u51b3\u4e8e\u8f85\u52a9\u7ebf\u7a0b\u6267\u884c\u901f\u5ea6 &gt;50% &gt;1KB TIFS \u5229\u7528\u5355\u6b21 L1miss \u9884\u6d4b\u540e\u7eed\u4e00\u7cfb\u5217 L1miss \u4e0d\u548ccache blocks\u6570\u91cf\u7ed1\u5b9a 95% ~64K/core RAS-directed \u5229\u7528\u4e0a\u4e0b\u6587\u4fe1\u606f\u8fdb\u4e00\u6b65\u533a\u5206\u65f6\u5e8f\u6d41 \u540c\u4e0a &gt;95% ~64K/core Proactive-Fetch \u5229\u7528\u5f53\u524d L1 cache\u72b6\u6001\u4fe1\u606f\u9884\u6d4b L1miss \u5e8f\u5217 \u540c\u4e0a &gt;99% ~256K/chip"},{"location":"APHP/C3.html","title":"3. Data Prefetching","text":"<p>\u6570\u636e\u7f3a\u5931\u6a21\u5f0f\u6e90\u4e8e\u7b97\u6cd5\u548c\u9ad8\u7ea7\u7f16\u7a0b\u7ed3\u6784\u4e3a\u7ec4\u7ec7\u548c\u904d\u5386\u5185\u5b58\u6570\u636e\u6240\u65bd\u52a0\u7684\u5185\u5728\u7ed3\u6784\u3002\u4f20\u7edf\u51af\u00b7\u8bfa\u4f9d\u66fc\u8ba1\u7b97\u673a\u7cfb\u7edf\u4e2d\u7684\u6307\u4ee4\u7f3a\u5931\u6a21\u5f0f\u5f80\u5f80\u8f83\u4e3a\u7b80\u5355\u2014\u2014\u9075\u5faa\u7ed3\u6784\u5316\u63a7\u5236\u6d41\u56fe\u4e2d\u7684\u987a\u5e8f\u6a21\u5f0f\u6216\u91cd\u590d\u63a7\u5236\u8f6c\u79fb\uff0c\u800c\u6570\u636e\u8bbf\u95ee\u6a21\u5f0f\u5219\u53ef\u80fd\u590d\u6742\u5f97\u591a\uff0c\u5c24\u5176\u662f\u5728\u652f\u6301\u591a\u91cd\u904d\u5386\u7684\u6307\u9488\u94fe\u63a5\u6570\u636e\u7ed3\u6784\u4e2d\u3002\u6b64\u5916\uff0c\u4ee3\u7801\u901a\u5e38\u662f\u9759\u6001\u7684\u56e0\u800c\u6613\u4e8e\u9884\u53d6\uff08\u9664\u5374\u8fd1\u671f\u53ef\u80fd\u5e72\u6270\u6307\u4ee4\u9884\u53d6\u7684\u865a\u62df\u5316\u548c\u5373\u65f6\u7f16\u8bd1\u673a\u5236\uff09\uff0c\u4f46\u6570\u636e\u7ed3\u6784\u4f1a\u5728\u6267\u884c\u8fc7\u7a0b\u4e2d\u52a8\u6001\u53d8\u5316\uff0c\u5bfc\u81f4\u904d\u5386\u6a21\u5f0f\u53d1\u751f\u6539\u53d8\u3002\u8fd9\u79cd\u8bbf\u95ee\u6a21\u5f0f\u7684\u9ad8\u5ea6\u590d\u6742\u6027\u50ac\u751f\u4e86\u8fdc\u6bd4\u6307\u4ee4\u9884\u53d6\u5668\u66f4\u4e30\u5bcc\u591a\u5143\u7684\u6570\u636e\u9884\u53d6\u65b9\u6848\u8bbe\u8ba1\u7a7a\u95f4\u3002</p> <p>\u6211\u4eec\u5c06\u6570\u636e\u9884\u53d6\u5668\u7684\u8bbe\u8ba1\u7a7a\u95f4\u5212\u5206\u4e3a\u56db\u5927\u7c7b\u522b\u3002\u7b2c\u4e00\u7c7b\u662f\u57fa\u4e8e\u7b80\u5355\u6b65\u957f\u6a21\u5f0f\u7684\u9884\u53d6\u5668\uff0c\u8fd9\u7c7b\u9884\u53d6\u5668\u76f4\u63a5\u5c06\u9010\u884c\u6307\u4ee4\u9884\u53d6\u6982\u5ff5\u63a8\u5e7f\u81f3\u6570\u636e\u9886\u57df\u3002\u7b2c\u4e8c\u7c7b\u4f9d\u8d56\u91cd\u590d\u904d\u5386\u5e8f\u5217\uff0c\u901a\u5e38\u5229\u7528\u5730\u5740\u95f4\u7684\u6307\u9488\u5173\u8054\u6027\u3002\u7b2c\u4e09\u7c7b\u4f9d\u6258\u89c4\u6574\uff08\u4f46\u53ef\u80fd\u975e\u7b49\u8ddd\u6b65\u957f\uff09\u7684\u6570\u636e\u7ed3\u6784\u5e03\u5c40\u3002\u6700\u540e\u4e00\u7c7b\u5219\u662f\u7a81\u7834\u4f20\u7edf\u4e71\u5e8f\u6307\u4ee4\u7a97\u53e3\u7684\u524d\u77bb\u63a2\u7d22\u673a\u5236\uff0c\u5176\u4e0d\u4f9d\u8d56\u4e8e\u5185\u5b58\u8bbf\u95ee\u5730\u5740\u6d41\u7684\u89c4\u5f8b\u6027\u6216\u91cd\u590d\u6027\u3002</p>"},{"location":"APHP/C3.html#31-stride-and-stream-prefetchers-for-data","title":"3.1 Stride and Stream Prefetchers for Data","text":"<p>\u6211\u4eec\u7814\u7a76\u7684\u7b2c\u4e00\u7c7b\u6570\u636e\u9884\u53d6\u5668\u662f\u6b65\u957f\u4e0e\u6d41\u9884\u53d6\u5668\uff0c\u5b83\u4eec\u662f\u7531\u6307\u4ee4\u9884\u53d6\u4e2d\u7684\u9010\u884c\u9884\u53d6\u548c\u6d41\u9884\u53d6\u673a\u5236\u76f4\u63a5\u6f14\u5316\u800c\u6765\u3002\u8fd9\u7c7b\u9884\u53d6\u5668\u80fd\u6355\u6349\u5728\u865a\u62df\u5730\u5740\u7a7a\u95f4\u4e2d\u8fde\u7eed\u5206\u5e03\u6216\u6309\u56fa\u5b9a\u6b65\u957f\u95f4\u9694\u7684\u6570\u636e\u8bbf\u95ee\u6a21\u5f0f\uff0c\u5bf9\u5bc6\u96c6\u77e9\u9635\u548c\u6570\u7ec4\u8bbf\u95ee\u6a21\u5f0f\u6781\u4e3a\u6709\u6548\uff0c\u4f46\u5bf9\u57fa\u4e8e\u6307\u9488\u7684\u6570\u636e\u7ed3\u6784\u901a\u5e38\u6536\u6548\u751a\u5fae\u3002\u4ece\u53e4\u8001\u7684IBM System/370\u7cfb\u5217\u5230\u73b0\u4ee3\u9ad8\u6027\u80fd\u5904\u7406\u5668\uff0c\u6b65\u957f\u6570\u636e\u9884\u53d6\u5668\u5df2\u5728\u5de5\u4e1a\u5904\u7406\u5668\u8bbe\u8ba1\u4e2d\u5e7f\u6cdb\u5e94\u7528\u3002\u76f4\u81f3\u8fd1\u671f\uff0c\u8fd9\u7c7b\u786c\u4ef6\u6570\u636e\u9884\u53d6\u5668\u4ecd\u88ab\u8ba4\u4e3a\u662f\u552f\u4e00\u5b9e\u73b0\u5546\u4e1a\u90e8\u7f72\u7684\u7c7b\u522b\u3002</p> <p>\u65e9\u57281978\u5e74\u5c31\u6709\u6587\u732e[5]\u63cf\u8ff0\u4e86\u4ec5\u652f\u6301\u8fde\u7eed\u5730\u5740\u5757\u9884\u53d6\u7684\u987a\u5e8f\u6570\u636e\u9884\u53d6\u5668\u5b9e\u73b0\u3002\u52301990\u5e74\u4ee3\u521d\uff0c\u6b64\u7c7b\u9884\u53d6\u5668\u5df2\u6269\u5c55\u81f3\u80fd\u68c0\u6d4b\u5e76\u9884\u53d6\u975e\u56fa\u5b9a\u6b65\u957f\u7684\u8bbf\u95ee\u5e8f\u5217[29]\u3002\u8fd9\u7c7b\u6b65\u957f\u8bbf\u95ee\u6a21\u5f0f\u5728\u904d\u5386\u591a\u7ef4\u6570\u7ec4\u65f6\u9891\u7e41\u51fa\u73b0\uff0c\u5f53\u805a\u5408\u6570\u636e\u7c7b\u578b\uff08\u4f8b\u5982C\u8bed\u8a00\u4e2d\u7684\u7ed3\u6784\u4f53\uff09\u5b58\u50a8\u5728\u6570\u7ec4\u4e2d\u65f6\u4f1a\u51fa\u73b0\u8de8\u6b65\u8bbf\u95ee\u3002\u5373\u4f7f\u5728\u4f7f\u7528\u6307\u9488\u7684\u6570\u636e\u7ed3\u6784\u4e2d\uff0c\u5f53\u52a8\u6001\u5185\u5b58\u5206\u914d\u5668\u5c06\u56fa\u5b9a\u5927\u5c0f\u7684\u5bf9\u8c61\u8fde\u7eed\u6392\u5217\u5728\u5185\u5b58\u4e2d\u65f6\uff08\u7531\u4e8e\u6c60\u5206\u914d\u5668\u7684\u666e\u904d\u4f7f\u7528\uff0c\u8fd9\u79cd\u60c5\u51b5\u5f88\u5e38\u89c1\uff09\uff0c\u8de8\u6b65\u8bbf\u95ee\u4e5f\u53ef\u80fd\u5076\u7136\u51fa\u73b0\u3002Dahlgren\u548cStenstrom\u8be6\u7ec6\u7814\u7a76\u4e86\u987a\u5e8f\u9884\u53d6\u4e0e\u8de8\u6b65\u9884\u53d6\u673a\u5236\u7684\u4f18\u52bf\u4e0e\u6709\u6548\u6027[30]\u3002</p> <p>\u8de8\u6b65\u9884\u53d6\u5668\u5b9e\u73b0\u4e2d\u7684\u5173\u952e\u6311\u6218\u5728\u4e8e\u533a\u5206\u591a\u4e2a\u4ea4\u9519\u7684\u8de8\u6b65\u5e8f\u5217\uff0c\u4f8b\u5982\u77e9\u9635-\u5411\u91cf\u4e58\u6cd5\u4e2d\u53ef\u80fd\u51fa\u73b0\u7684\u60c5\u51b5\u3002\u56fe3.1\u5c55\u793a\u4e86Baer\u548cChen\u57fa\u4e8e\u5355\u6761\u52a0\u8f7d\u6307\u4ee4\u8ddf\u8e2a\u8de8\u6b65\u7684\u65b9\u6848\u793a\u610f\u56fe\u3002\u5176\u53c2\u8003\u9884\u6d4b\u8868\u662f\u4e00\u4e2a\u5e26\u6807\u7b7e\u7684\u7ec4\u76f8\u8054\u7ed3\u6784\uff0c\u4f7f\u7528\u52a0\u8f7d\u6307\u4ee4\u7684\u7a0b\u5e8f\u8ba1\u6570\u5668\u4f5c\u4e3a\u67e5\u627e\u952e\u3002\u6bcf\u4e2a\u8868\u9879\u4fdd\u5b58\u8be5\u52a0\u8f7d\u6307\u4ee4\u6700\u540e\u5f15\u7528\u7684\u5730\u5740\uff0c\u4ee5\u53ca\u524d\u4e24\u6b21\u5730\u5740\u4e4b\u95f4\u7684\u5dee\u503c\uff08\u5373\u8de8\u6b65\uff09\u3002\u5f53\u8fde\u7eed\u4e24\u6b21\u89c2\u5bdf\u5230\u76f8\u540c\u8de8\u6b65\u65f6\uff0c\u7cfb\u7edf\u5c06\u4f7f\u7528\u6700\u540e\u5f15\u7528\u5730\u5740\u548c\u8de8\u6b65\u503c\u8ba1\u7b97\u4e00\u4e2a\u6216\u591a\u4e2a\u9884\u53d6\u5730\u5740\u3002\u540e\u7eed\u6301\u7eed\u5339\u914d\u8bb0\u5f55\u8de8\u6b65\u7684\u8bbf\u95ee\u5c06\u89e6\u53d1\u66f4\u591a\u9884\u53d6\u64cd\u4f5c\u3002\u8fd9\u79cd\u8fde\u7eed\u7684\u8de8\u6b65\u8bbf\u95ee\u5e8f\u5217\u88ab\u79f0\u4e3a\u6d41\uff0c\u4e0e\u6307\u4ee4\u6d41\u9884\u53d6\u5668\u7c7b\u4f3c\u3002Ishii\u7b49\u5b66\u8005\u63d0\u51fa\u4e86\u80fd\u7d27\u51d1\u8868\u793a\u591a\u91cd\u8de8\u6b65\u7684\u66f4\u590d\u6742\u786c\u4ef6\u7ed3\u6784[31]\uff0c\u800cSair\u56e2\u961f\u5219\u901a\u8fc7\u9884\u6d4b\u8de8\u6b65\u957f\u5ea6\u5c06\u6d41\u9884\u53d6\u6269\u5c55\u81f3\u66f4\u4e0d\u89c4\u5219\u7684\u8bbf\u95ee\u6a21\u5f0f[32]\u3002</p> <p>\u7b2c\u4e8c\u4e2a\u5173\u952e\u5b9e\u73b0\u95ee\u9898\u662f\u786e\u5b9a\u68c0\u6d4b\u5230\u8de8\u6b65\u6d41\u65f6\u5e94\u9884\u53d6\u591a\u5c11\u6570\u636e\u5757\u3002\u8be5\u53c2\u6570\u901a\u5e38\u79f0\u4e3a\u9884\u53d6\u5ea6\u6216\u9884\u53d6\u6df1\u5ea6\uff0c\u7406\u60f3\u60c5\u51b5\u4e0b\u5e94\u8db3\u591f\u5927\u4ee5\u786e\u4fdd\u9884\u53d6\u6570\u636e\u5728\u5904\u7406\u5668\u5f15\u7528\u524d\u5230\u8fbe\uff0c\u4f46\u53c8\u4e0d\u80fd\u8fc7\u5927\u5bfc\u81f4\u6570\u636e\u5757\u5728\u8bbf\u95ee\u524d\u88ab\u66ff\u6362\u6216\u5bf9\u77ed\u6d41\u9020\u6210\u8fc7\u5ea6\u6c61\u67d3\u3002Hur\u548cLin\u63d0\u51fa\u4e86\u80fd\u8ddf\u8e2a\u8fd1\u671f\u6d41\u957f\u5ea6\u76f4\u65b9\u56fe\u7684\u7b80\u6613\u72b6\u6001\u673a\uff0c\u53ef\u81ea\u9002\u5e94\u786e\u5b9a\u6bcf\u4e2a\u72ec\u7acb\u6d41\u7684\u5408\u9002\u9884\u53d6\u6df1\u5ea6\uff0c\u4f7f\u5f97\u6d41\u9884\u53d6\u5668\u5373\u4f7f\u5bf9\u4ec5\u542b\u5c11\u6570\u5730\u5740\u7684\u77ed\u6d41\u4e5f\u4fdd\u6301\u9ad8\u6548[33]\u3002</p> <p>\u4f20\u7edf\u4e0a\uff0c\u8de8\u6b65\u9884\u53d6\u5668\u5c06\u83b7\u53d6\u7684\u6570\u636e\u76f4\u63a5\u5b58\u5165\u7f13\u5b58\u5c42\u6b21\u7ed3\u6784\u3002\u4f46\u82e5\u9884\u53d6\u8fc7\u4e8e\u6fc0\u8fdb\uff0c\u5219\u53ef\u80fd\u6c61\u67d3\u7f13\u5b58\uff0c\u7f6e\u6362\u6389\u6709\u7528\u6570\u636e\u3002Jouppi[34]\u63cf\u8ff0\u4e86\u4e00\u79cd\u66ff\u4ee3\u67b6\u6784\uff1a\u6d41\u9884\u53d6\u5668\u5c06\u6570\u636e\u5b58\u5165\u79f0\u4e3a\u6d41\u7f13\u51b2\u533a\u7684\u72ec\u7acb\u7f13\u51b2\u533a\uff0c\u8fd9\u4e9b\u7f13\u51b2\u533a\u5728L1\u7f13\u5b58\u4e4b\u540e\u6216\u5e76\u884c\u88ab\u8bbf\u95ee\u3002\u901a\u8fc7\u5c06\u6570\u636e\u7f6e\u4e8e\u6d41\u7f13\u51b2\u533a\uff0c\u4f4e\u51c6\u786e\u5ea6\u7684\u6d41\uff08\u5373\u8bb8\u591a\u6570\u636e\u88ab\u9884\u53d6\u4f46\u672a\u88ab\u4f7f\u7528\uff09\u4e0d\u4f1a\u7f6e\u6362\u7f13\u5b58\u4e2d\u7684\u6709\u7528\u6570\u636e\uff0c\u4ece\u800c\u964d\u4f4e\u9519\u8bef\u9884\u53d6\u7684\u98ce\u9669\u3002\u4f46\u9519\u8bef\u9884\u53d6\u4ecd\u4f1a\u6d88\u8017\u80fd\u91cf\u4e0e\u5e26\u5bbd\u3002Palacharla\u4e0eKessler\u8bc4\u4f30\u4e86\u4e00\u79cd\u7528\u6d41\u7f13\u51b2\u533a\u5b8c\u5168\u66ff\u4ee3\u4e8c\u7ea7\u6570\u636e\u7f13\u5b58\u7684\u5185\u5b58\u7cfb\u7edf\u67b6\u6784[35]</p> <p>\u6bcf\u4e2a\u6d41\u7f13\u51b2\u533a\u5bb9\u7eb3\u6765\u81ea\u5355\u4e00\u6570\u636e\u6d41\u7684\u7f13\u5b58\u5757\u3002\u5904\u7406\u5668\u7684\u8bbf\u95ee\u8bf7\u6c42\u4f1a\u67e5\u8be2\u6d41\u7f13\u51b2\u533a\u5185\u5bb9\uff0c\u901a\u5e38\u4e0eL1\u7f13\u5b58\u8bbf\u95ee\u5e76\u884c\u6267\u884c\u3002\u6d41\u7f13\u51b2\u533a\u547d\u4e2d\u65f6\uff0c\u8bf7\u6c42\u7684\u7f13\u5b58\u5757\u901a\u5e38\u4f1a\u88ab\u8f6c\u79fb\u81f3L1\u7f13\u5b58\uff0c\u5e76\u9884\u53d6\u8be5\u6570\u636e\u6d41\u7684\u53e6\u4e00\u4e2a\u7f13\u5b58\u5757\u3002\u67d0\u4e9b\u53d8\u4f53\u4e2d\uff0c\u6d41\u7f13\u51b2\u533a\u4e25\u683c\u9075\u5faa\u5148\u8fdb\u5148\u51fa\u539f\u5219\uff0c\u4ec5\u5141\u8bb8\u8bbf\u95ee\u6bcf\u4e2a\u6d41\u7f13\u51b2\u533a\u7684\u5934\u90e8\u3002\u5176\u4ed6\u53d8\u4f53\u5219\u91c7\u7528\u5173\u8054\u641c\u7d22\u65b9\u5f0f\u8bbf\u95ee\u6d41\u7f13\u51b2\u533a\u3002\u5f53\u6b65\u957f\u68c0\u6d4b\u673a\u5236\u8bc6\u522b\u5230\u65b0\u6570\u636e\u6d41\u65f6\uff0c\u6574\u4e2a\u6d41\u7f13\u51b2\u533a\u4f1a\u88ab\u6e05\u7a7a\u5e76\u91cd\u65b0\u5206\u914d\uff08\u4e22\u5f03\u9648\u65e7\u6570\u636e\u6d41\u4e2d\u6240\u6709\u672a\u88ab\u5f15\u7528\u7684\u7f13\u5b58\u5757\uff09\uff0c\u901a\u5e38\u91c7\u7528\u8f6e\u8f6c\u6216\u6700\u8fd1\u6700\u5c11\u4f7f\u7528\u7b56\u7565\u3002</p>"},{"location":"APHP/C3.html#32-address-correlating-prefetchers","title":"3.2 Address-Correlating Prefetchers","text":"<p>\u6b65\u957f\u9884\u53d6\u5668\u901a\u5e38\u5bf9\u57fa\u4e8e\u6307\u9488\u7684\u6570\u636e\u7ed3\u6784\uff08\u5982\u94fe\u8868\uff09\u6548\u679c\u6709\u9650\uff0c\u800c\u672c\u8282\u8ba8\u8bba\u7684\u7b2c\u4e8c\u7c7b\u9884\u53d6\u5668\u4e13\u95e8\u9488\u5bf9\u6b64\u7c7b\u6570\u636e\u7ed3\u6784\u7684\u6307\u9488\u8ffd\u8e2a\u8bbf\u95ee\u6a21\u5f0f\u8bbe\u8ba1\u3002\u8be5\u7c7b\u9884\u53d6\u5668\u4e0d\u4f9d\u8d56\u5185\u5b58\u4e2d\u6570\u636e\u5e03\u5c40\u7684\u89c4\u5f8b\u6027\uff0c\u800c\u662f\u5229\u7528\u7b97\u6cd5\u503e\u5411\u4e8e\u4ee5\u76f8\u540c\u65b9\u5f0f\u91cd\u590d\u904d\u5386\u6570\u636e\u7ed3\u6784\u7684\u7279\u6027\uff0c\u4ece\u800c\u4ea7\u751f\u91cd\u590d\u51fa\u73b0\u7684\u7f13\u5b58\u7f3a\u5931\u5e8f\u5217\u3002</p> <p>\u5185\u5b58\u5730\u5740\u5bf9\u8bbf\u95ee\u4e4b\u95f4\u7684\u5173\u8054\u6027\u65e9\u57281976\u5e74\u5df2\u88ab\u63d0\u51fa[38]\u3002Charney\u4e0eReeves\u9996\u6b21\u63cf\u8ff0\u4e86\u5229\u7528\u6b64\u7c7b\u6210\u5bf9\u5173\u8054\u5173\u7cfb\u7684\u786c\u4ef6\u9884\u53d6\u5668\uff0c\u5e76\u521b\u9020\u4e86\u201c\u57fa\u4e8e\u5173\u8054\u7684\u9884\u53d6\u5668\u201d\u8fd9\u4e00\u672f\u8bed[39,40]\u3002\u540e\u7eed\u7814\u7a76\u5c06\u5730\u5740\u5173\u8054\u7684\u6982\u5ff5\u4ece\u6210\u5bf9\u5173\u7cfb\u63a8\u5e7f\u81f3\u8bbf\u95ee\u7ec4\u6216\u8bbf\u95ee\u5e8f\u5217[41,42]\u3002Wenisch\u4e0e\u5408\u4f5c\u8005\u63d0\u51fa\u201c\u65f6\u95f4\u5173\u8054\u201d\u672f\u8bed[42]\uff0c\u6307\u4ee3\u5728\u65f6\u95f4\u4e0a\u76f8\u90bb\u88ab\u8bbf\u95ee\u7684\u4e24\u4e2a\u5730\u5740\u672a\u6765\u503e\u5411\u4e8e\u518d\u6b21\u88ab\u5171\u540c\u8bbf\u95ee\u7684\u73b0\u8c61\u3002\u65f6\u95f4\u5173\u8054\u662f\u201c\u65f6\u95f4\u5c40\u90e8\u6027\u201d\u7684\u7c7b\u6bd4\u2014\u2014\u8fd1\u671f\u88ab\u8bbf\u95ee\u7684\u5730\u5740\u5728\u4e0d\u4e45\u540e\u5f88\u53ef\u80fd\u518d\u6b21\u88ab\u8bbf\u95ee\u3002\u7f13\u5b58\u5229\u7528\u65f6\u95f4\u5c40\u90e8\u6027\uff0c\u800c\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u5219\u5229\u7528\u65f6\u95f4\u5173\u8054\u3002</p>"},{"location":"APHP/C3.html#321-jump-pointers","title":"3.2.1 Jump Pointers","text":"<p>\u5173\u8054\u9884\u53d6\u5668\u662f\u9488\u5bf9\u6307\u9488\u8ffd\u8e2a\u8bbf\u95ee\u6a21\u5f0f\u7684\u786c\u4ef6\u4e0e\u8f6f\u4ef6\u673a\u5236\u7684\u6cdb\u5316\u3002\u8fd9\u4e9b\u65e9\u671f\u673a\u5236\u57fa\u4e8e\u8df3\u8f6c\u6307\u9488\u6982\u5ff5[43,44,45,46]\uff0c\u5373\u80fd\u5728\u6570\u636e\u7ed3\u6784\u904d\u5386\u4e2d\u5b9e\u73b0\u5927\u8de8\u5ea6\u524d\u5411\u8df3\u8f6c\u7684\u6307\u9488\u3002\u4f8b\u5982\uff0c\u94fe\u8868\u7684\u8282\u70b9\u53ef\u589e\u52a0\u4e00\u4e2a\u6307\u5411\u5176\u540e\u7b2c\u5341\u4e2a\u8282\u70b9\u7684\u6307\u9488\uff1b\u9884\u53d6\u5668\u53ef\u901a\u8fc7\u8ffd\u8e2a\u8df3\u8f6c\u6307\u9488\uff0c\u5728\u4e3b\u904d\u5386\u8fdb\u884c\u65f6\u83b7\u5f97\u524d\u77bb\u80fd\u529b\u3002\u7531CPU\u6267\u884c\uff0c\u5b9e\u73b0\u53ca\u65f6\u9884\u53d6\u3002\u57fa\u4e8e\u8df3\u8f6c\u6307\u9488\u7684\u9884\u53d6\u5668\u901a\u5e38\u9700\u8981\u8f6f\u4ef6\u6216\u7f16\u8bd1\u5668\u652f\u6301\u6765\u6807\u6ce8\u6307\u9488\u3002\u5185\u5bb9\u5bfc\u5411\u9884\u53d6\u5668[47, 48]\u907f\u5f00\u6807\u6ce8\u673a\u5236\uff0c\u8f6c\u800c\u5c1d\u8bd5\u89e3\u5f15\u7528\u5e76\u9884\u53d6\u4efb\u4f55\u6784\u6210\u6709\u6548\u865a\u62df\u5730\u5740\u7684\u52a0\u8f7d\u503c\u3002\u867d\u7136\u8df3\u8f6c\u6307\u9488\u673a\u5236\u5bf9\u7279\u5b9a\u6570\u636e\u7ed3\u6784\u904d\u5386\uff08\u5982\u94fe\u8868\u904d\u5386\uff09\u975e\u5e38\u6709\u6548\uff0c\u4f46\u5176\u4e3b\u8981\u7f3a\u9677\u5728\u4e8e\uff1a\u8df3\u8f6c\u6307\u9488\u63a8\u8fdb\u904d\u5386\u7684\u8ddd\u79bb\u5fc5\u987b\u7cbe\u7ec6\u5e73\u8861\uff0c\u65e2\u8981\u63d0\u4f9b\u8db3\u591f\u7684\u9884\u8bfb\u91cf\uff0c\u53c8\u4e0d\u80fd\u8df3\u8fc7\u8fc7\u591a\u5143\u7d20\u3002\u8df3\u8f6c\u6307\u9488\u8ddd\u79bb\u96be\u4ee5\u8c03\u4f18\uff0c\u4e14\u6307\u9488\u672c\u8eab\u7684\u5b58\u50a8\u5f00\u9500\u53ef\u80fd\u5f88\u9ad8\u3002</p>"},{"location":"APHP/C3.html#322-pair-wise-correlation","title":"3.2.2 Pair-Wise Correlation","text":"<p>\u672c\u8d28\u4e0a\uff0c\u57fa\u4e8e\u5173\u8054\u7684\u786c\u4ef6\u9884\u53d6\u5668\u662f\u4e00\u4e2a\u67e5\u627e\u8868\uff0c\u5b83\u5c06\u67d0\u4e2a\u5730\u5740\u6620\u5c04\u5230\u8bbf\u95ee\u5e8f\u5217\u4e2d\u53ef\u80fd\u7d27\u968f\u5176\u540e\u7684\u53e6\u4e00\u4e2a\u5730\u5740\u3002\u8fd9\u79cd\u5173\u8054\u4e0d\u4ec5\u80fd\u6355\u83b7\u987a\u5e8f\u8bbf\u95ee\u548c\u6b65\u957f\u8bbf\u95ee\u5173\u7cfb\uff0c\u66f4\u5177\u666e\u9002\u6027\u2014\u2014\u4f8b\u5982\u80fd\u6355\u83b7\u6307\u9488\u5730\u5740\u4e0e\u5176\u6307\u5411\u5730\u5740\u4e4b\u95f4\u7684\u5173\u7cfb\u3002\u6b63\u662f\u6355\u83b7\u6307\u9488\u904d\u5386\u7684\u80fd\u529b\uff0c\u4f7f\u5f97\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u76f8\u6bd4\u6b65\u957f\u9884\u53d6\u5668\u5177\u6709\u66f4\u5927\u7684\u6027\u80fd\u63d0\u5347\u7a7a\u95f4\uff0c\u56e0\u4e3a\u6307\u9488\u8ffd\u9010\u8bbf\u95ee\u6a21\u5f0f\u5728\u73b0\u4ee3\u5904\u7406\u5668\u4e0a\u7684\u8fd0\u884c\u6548\u7387\u5f02\u5e38\u4f4e\u4e0b\u3002\u7136\u800c\uff0c\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u4f9d\u8d56\u8bbf\u95ee\u91cd\u590d\u6027\uff1a\u5b83\u4eec\u65e0\u6cd5\u9884\u53d6\u4e4b\u524d\u4ece\u672a\u88ab\u8bbf\u95ee\u8fc7\u7684\u5730\u5740\uff08\u4e0e\u6b65\u957f\u9884\u53d6\u5668\u76f8\u53cd\uff09\u3002\u6b64\u5916\uff0c\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u9700\u8981\u7ef4\u62a4\u5de8\u5927\u72b6\u6001\u91cf\uff0c\u9700\u4e3a\u6bcf\u4e2a\u5730\u5740\u5b58\u50a8\u5176\u540e\u7ee7\u5730\u5740\u3002\u56e0\u6b64\u5176\u5b58\u50a8\u9700\u6c42\u968f\u5e94\u7528\u7a0b\u5e8f\u5de5\u4f5c\u96c6\u5927\u5c0f\u7ebf\u6027\u589e\u957f\u3002\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u8bbe\u8ba1\u7684\u521b\u65b0\u91cd\u70b9\u5927\u591a\u96c6\u4e2d\u4e8e\u7ba1\u7406\u8fd9\u79cd\u6d77\u91cf\u72b6\u6001\u3002</p>"},{"location":"APHP/C3.html#323-markov-prefetcher","title":"3.2.3 Markov Prefetcher","text":"<p>\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668[49, 50]\u662f\u5229\u7528\u6210\u5bf9\u5730\u5740\u5173\u8054\u7684\u6700\u7b80\u9884\u53d6\u5668\u8bbe\u8ba1\u3002\u5b83\u76f4\u63a5\u901a\u8fc7\u67e5\u627e\u8868\u5b9e\u73b0\u5c06\u89e6\u53d1\u5730\u5740\u6620\u5c04\u81f3\u7247\u5916\u8bbf\u95ee\u5e8f\u5217\u4e2d\u76f4\u63a5\u540e\u7ee7\u5730\u5740\u7684\u673a\u5236\u3002\u4f46\u7531\u4e8e\u5730\u5740\uff08\u5c24\u5176\u4ee5\u7f13\u5b58\u5757\u7c92\u5ea6\u8003\u91cf\uff09\u5e38\u53c2\u4e0e\u591a\u4e2a\u904d\u5386\u8def\u5f84\uff0c\u4ec5\u5b58\u50a8\u5355\u4e2a\u540e\u7ee7\u5730\u5740\u4f1a\u5bfc\u81f4\u6548\u679c\u4e0d\u4f73\u3002\u4e3a\u6b64\uff0c\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u5b58\u50a8\u591a\u4e2a\u5df2\u89c2\u6d4b\u5230\u7684\u540e\u7ee7\u5730\u5740\uff0c\u5f53\u89e6\u53d1\u5730\u5740\u53d1\u751f\u7f13\u5b58\u7f3a\u5931\u65f6\uff0c\u8fd9\u4e9b\u5730\u5740\u4f1a\u88ab\u5168\u90e8\u9884\u53d6\u3002\u901a\u8fc7\u9884\u53d6\u591a\u4e2a\u53ef\u80fd\u540e\u7ee7\u5730\u5740\uff0c\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u4ee5\u727a\u7272\u51c6\u786e\u7387\uff08\u6b63\u786e\u9884\u53d6\u6570\u5360\u603b\u9884\u53d6\u6570\u7684\u6bd4\u4f8b\uff09\u6765\u63d0\u5347\u8986\u76d6\u7387\uff08\u6210\u529f\u9884\u53d6\u7684\u9700\u6c42\u7f3a\u5931\u6bd4\u4f8b\uff09\u2014\u2014\u9884\u53d6\u5668\u53d1\u8d77\u7684\u591a\u4e2a\u5730\u5740\u4e2d\u4ec5\u6709\u4e00\u4e2a\u9884\u671f\u4e3a\u6b63\u786e\u5730\u5740\u3002\u9884\u53d6\u7684\u540e\u7ee7\u5730\u5740\u6570\u91cf\u5e38\u88ab\u79f0\u4e3a\u9884\u53d6\u5bbd\u5ea6\u3002</p> <p></p> <p>\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u91c7\u7528\u7531\u89e6\u53d1\u5730\u5740\u7d22\u5f15\u7684\u7247\u4e0a\u7ec4\u76f8\u8054\u8868\u7ed3\u6784\uff08\u89c1\u56fe3.2\uff09\u3002\u8868\u4e2d\u6bcf\u4e2a\u6761\u76ee\u5305\u542b\u5f85\u9884\u53d6\u7684\u540e\u7eed\u5730\u5740\u96c6\u5408\u53ca\u53ef\u9009\u7684\u7f6e\u4fe1\u5ea6\u6216\u7f6e\u6362\u7b56\u7565\u4fe1\u606f\uff0c\u901a\u5e38\u53ef\u5b58\u50a8\u56db\u4e2a\u540e\u7eed\u5730\u5740\u3002\u539f\u59cb\u7814\u7a76[49]\u63d0\u51fa\u4f7f\u75281MB\u67e5\u627e\u8868\uff0c\u4f46\u968f\u7740\u5e94\u7528\u6570\u636e\u8db3\u8ff9\u7684\u6269\u5927\uff0c\u6240\u9700\u67e5\u627e\u8868\u5bb9\u91cf\u6301\u7eed\u589e\u957f\u3002\u540e\u7eed\u7814\u7a76\u8868\u660e\uff0c\u73b0\u4ee3\u5de5\u4f5c\u8d1f\u8f7d\u9700\u8981\u66f4\u5927\u5bb9\u91cf\u7684\u8868\u624d\u80fd\u5b9e\u73b0\u6709\u6548\u9884\u53d6[51]\u3002</p> <p>\u8be5\u8bbe\u8ba1\u7075\u611f\u6765\u6e90\u4e8e\u5bf9\u7247\u5916\u8bbf\u95ee\u5e8f\u5217\u5efa\u7acb\u9a6c\u5c14\u53ef\u592b\u6a21\u578b\u7684\u6784\u60f3\u3002\u6a21\u578b\u4e2d\u7684\u6bcf\u4e2a\u72b6\u6001\u5bf9\u5e94\u4e00\u4e2a\u89e6\u53d1\u5730\u5740\uff0c\u53ef\u80fd\u7684\u540e\u7eed\u72b6\u6001\u5bf9\u5e94\u76f8\u7ee7\u7684\u7f3a\u5931\u5730\u5740\u3002\u4e00\u9636\u9a6c\u5c14\u53ef\u592b\u6a21\u578b\u4e2d\u7684\u8f6c\u79fb\u6982\u7387\u5bf9\u5e94\u5404\u540e\u7eed\u5730\u5740\u7f3a\u5931\u7684\u4f3c\u7136\u5ea6\u3002\u67e5\u627e\u8868\u7684\u76ee\u6807\u662f\u4e3a\u6700\u5e38\u51fa\u73b0\u7684\u89e6\u53d1\u5730\u5740\u5b58\u50a8\u5177\u6709\u6700\u9ad8\u8f6c\u79fb\u6982\u7387\u7684\u540e\u7eed\u5730\u5740\u3002\u7136\u800c\u73b0\u6709\u786c\u4ef6\u65b9\u6848\u5e76\u672a\u663e\u5f0f\u8ba1\u7b97\u89e6\u53d1\u6982\u7387\u6216\u8f6c\u79fb\u6982\u7387\uff0c\u800c\u662f\u91c7\u7528\u6700\u8fd1\u6700\u5c11\u4f7f\u7528\uff08LRU\uff09\u542f\u53d1\u5f0f\u7b56\u7565\u7ba1\u7406\u89e6\u53d1\u5730\u5740\u53ca\u5176\u5bf9\u5e94\u7684\u540e\u7eed\u5730\u5740\u3002</p> <p>\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u7684\u6548\u80fd\u53d7\u9650\u4e8e\u4e24\u4e2a\u56e0\u7d20\uff1a</p> <ol> <li>\u7531\u4e8e\u4ec5\u5c1d\u8bd5\u9884\u6d4b\u4e0b\u4e00\u6b21\u7f3a\u5931\uff0c\u5176\u524d\u77bb\u80fd\u529b\u548c\u5185\u5b58\u7ea7\u5e76\u884c\u6027\u53d7\u9650\uff1b</li> <li>\u7247\u4e0a\u5173\u8054\u8868\u5bb9\u91cf\u9650\u5236\u4e86\u8986\u76d6\u8303\u56f4\u3002</li> </ol> <p>\u4e0b\u6587\u5c06\u63a2\u8ba8\u9488\u5bf9\u8fd9\u4e9b\u5c40\u9650\u7684\u6539\u8fdb\u65b9\u6848\u3002</p>"},{"location":"APHP/C3.html#324-improving-lookahead-via-prefetch-depth","title":"3.2.4 Improving Lookahead via Prefetch Depth","text":"<p>\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u7684\u9996\u8981\u5c40\u9650\u5728\u4e8e\u6709\u9650\u7684\u524d\u77bb\u80fd\u529b\u2014\u2014\u5373\u4ece\u89e6\u53d1\u5730\u5740\u5230\u540e\u7eed\u5730\u5740\u8bbf\u95ee\u505c\u6ede\u7684\u65f6\u95f4\u95f4\u9694\u8fc7\u77ed\uff0c\u4e0d\u8db3\u4ee5\u63a9\u76d6\u9884\u53d6\u6570\u636e\u7684\u8bbf\u95ee\u5ef6\u8fdf\u3002</p> <p>\u63d0\u5347\u524d\u77bb\u80fd\u529b\u7684\u76f4\u63a5\u65b9\u6cd5\u662f\u9884\u53d6\u66f4\u591a\u5730\u5740\uff0c\u5728\u9884\u6d4b\u7684\u5168\u5c40\u5730\u5740\u5e8f\u5217\u4e2d\u63d0\u524d\u66f4\u8fdc\u8ddd\u79bb[41]\uff0c\u8fd9\u7c7b\u4f3c\u4e8e\u589e\u52a0\u6d41\u9884\u53d6\u5668\u7684\u6df1\u5ea6\u3002\u5728\u7c7b\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u67b6\u6784\u4e2d\uff0c\u53ef\u901a\u8fc7\u57fa\u4e8e\u521d\u59cb\u9884\u6d4b\u5730\u5740\u9012\u5f52\u6267\u884c\u67e5\u8868\u64cd\u4f5c\u6765\u53d1\u8d77\u6df1\u5ea6\u9884\u53d6\u3002\u4f46\u8fd9\u79cd\u65b9\u6cd5\u4f1a\u5bfc\u81f4\u9ad8\u67e5\u8868\u5ef6\u8fdf\uff0c\u5e76\u6025\u5267\u589e\u52a0\u5bf9\u9a6c\u5c14\u53ef\u592b\u8868\u7684\u5e26\u5bbd\u9700\u6c42\u3002\u6b64\u5916\uff0c\u53ef\u80fd\u7684\u9884\u53d6\u5019\u9009\u6570\u91cf\u4f1a\u968f\u9884\u53d6\u6df1\u5ea6\u5448\u51e0\u4f55\u7ea7\u589e\u957f\uff0c\u56e0\u6b64\u9700\u8981\u5236\u5b9a\u9002\u5f53\u7684\u7b56\u7565\u6765\u9650\u5236\u8fd9\u79cd\u589e\u957f\u4ee5\u4fdd\u6301\u51c6\u786e\u6027\u3002</p> <p>\u53e6\u4e00\u79cd\u65b9\u6848\u662f\uff0c\u9884\u53d6\u8868\u53ef\u4ee5\u6298\u53e0\u5b58\u50a8\u77ed\u5e8f\u5217\uff08\u5373\u6d41\uff09\u7684\u540e\u7ee7\u5730\u5740\u4e0e\u6bcf\u4e2a\u9884\u53d6\u89e6\u53d1\u5730\u5740\u76f8\u90bb\uff0c\u800c\u975e\u6267\u884c\u8fde\u7eed\u67e5\u627e[52, 53]\u3002\u4ecd\u9700\u91c7\u7528\u5408\u9002\u7b56\u7565\u6765\u9009\u62e9\u8bb0\u5f55\u54ea\u4e9b\u540e\u7ee7\u6d41\uff0c\u4f8b\u5982\u6700\u8fd1\u6216\u6700\u9ad8\u6982\u7387\u7684\u540e\u7ee7\u5730\u5740\u3002\u8fd9\u79cd\u65b9\u6cd5\u89e3\u51b3\u4e86\u67e5\u627e\u5ef6\u8fdf/\u5e26\u5bbd\u95ee\u9898\uff0c\u4f46\u53ef\u80fd\u4f7f\u8868\u66f4\u65b0\u590d\u6742\u5316\uff0c\u56e0\u4e3a\u4e00\u4e2a\u5730\u5740\u53ef\u80fd\u9700\u8981\u8bb0\u5f55\u5728\u591a\u4e2a\u8868\u9879\u4e2d\uff08\u4f8b\u5982\u76f4\u63a5\u524d\u9a71\u3001\u524d\u9a71\u7684\u524d\u9a71\u7b49\uff09\u3002\u7136\u800c\u66f4\u6df1\u5c42\u7684\u95ee\u9898\u662f\uff1a\u6b64\u7c7b\u8868\u7ed3\u6784\u5fc5\u987b\u5c06\u6700\u5927\u9884\u53d6\u6df1\u5ea6\u56fa\u5b9a\u4e3a\u6bcf\u4e2a\u8868\u9879\u4e2d\u9884\u7559\u7684\u5b58\u50a8\u5bb9\u91cf\u3002\u82e5\u9884\u7559\u5b58\u50a8\u8fc7\u5c11\uff0c\u6d41\u4f1a\u88ab\u622a\u65ad\uff0c\u727a\u7272\u6f5c\u5728\u7684\u8986\u76d6\u8303\u56f4\u548c\u524d\u77bb\u80fd\u529b\uff1b\u82e5\u6df1\u5ea6\u8bbe\u7f6e\u8fc7\u9ad8\uff0c\u5219\u4f1a\u9020\u6210\u5b58\u50a8\u6d6a\u8d39\uff0c\u66f4\u4e25\u91cd\u7684\u662f\uff0c\u5f53\u6d41\u672b\u5c3e\u8bb0\u5f55\u65e0\u5173\u5730\u5740\u65f6\u4f1a\u5bfc\u81f4\u51c6\u786e\u6027\u4e0b\u964d\u3002\u591a\u9879\u7814\u7a76\u8868\u660e\uff0c\u91cd\u590d\u6d41\u7684\u957f\u5ea6\u5dee\u5f02\u53ef\u8fbe\u6570\u91cf\u7ea7\uff0c\u4ece\u5c11\u81f3\u4e24\u6b21\u5230\u591a\u8fbe\u6570\u5343\u6b21\u7f13\u5b58\u7f3a\u5931[41, 42, 52, 54, 55]\u3002\u6211\u4eec\u5c06\u5728\u540e\u7eed\u8ba8\u8bba\u89e3\u51b3\u8be5\u95ee\u9898\u7684\u66ff\u4ee3\u5b58\u50a8\u67b6\u6784\u3002\u901a\u5e38\uff0c\u6d41\u8d77\u59cb\u5904\u7684\u5934\u51e0\u6b21\u7f13\u5b58\u7f3a\u5931\u5e76\u4e0d\u53ca\u65f6\u2014\u2014\u89e6\u53d1\u7f3a\u5931\u4e0e\u540e\u7eed\u5757\u7684\u8bbf\u95ee\u65f6\u95f4\u95f4\u9694\u8fc7\u8fd1\uff0c\u65e0\u6cd5\u5b9e\u73b0\u53ca\u65f6\u9884\u53d6\u3002\u8bb0\u5f55\u5e76\u9884\u53d6\u8fd9\u4e9b\u5730\u5740\u65e2\u6d6a\u8d39\u5b58\u50a8\u7a7a\u95f4\uff0c\u53c8\u4f1a\u5ef6\u8fdf\u6d41\u4e2d\u6709\u7528\u5757\u7684\u9884\u53d6\u3002\u56e0\u6b64\uff0c\u8df3\u8fc7\u524d\u51e0\u4e2a\u5730\u5740\uff0c\u4ece\u80fd\u591f\u83b7\u5f97\u5ef6\u8fdf\u4f18\u52bf\u7684\u7b2c\u4e00\u4e2a\u7f3a\u5931\u5904\u5f00\u59cb\u6784\u5efa\u6d41\u662f\u5408\u7406\u7684\u3002Chou\u53ca\u5176\u5408\u4f5c\u8005\u6307\u51fa\uff0c\u5728\u4e71\u5e8f\u6267\u884c\u6838\u5fc3\u4e2d\uff0c\u6307\u4ee4\u7a97\u53e3\u7ecf\u5e38\u5bfc\u81f4\u591a\u4e2a\u7247\u5916\u7f3a\u5931\u5e76\u53d1\u4ea7\u751f[56]\u3002\u5f53\u8fd9\u7ec4\u7f3a\u5931\u88ab\u5904\u7406\u65f6\uff0c\u6267\u884c\u4f1a\u9677\u5165\u505c\u6ede\u3002\u5f85\u8fd9\u4e9b\u7f3a\u5931\u8fd4\u56de\u540e\uff0c\u6307\u4ee4\u7a97\u53e3\u5f97\u4ee5\u63a8\u8fdb\uff0c\u76f8\u5173\u5730\u5740\u53ef\u88ab\u8ba1\u7b97\uff0c\u4f7f\u5f97\u4e0b\u4e00\u7ec4\u7f3a\u5931\u80fd\u5e76\u884c\u53d1\u51fa\u3002\u4ed6\u4eec\u5c06\u6bcf\u7ec4\u7f3a\u5931\u7684\u5e73\u5747\u6570\u91cf\u79f0\u4e3a\u5e94\u7528\u7a0b\u5e8f\u7684\u5185\u5b58\u7ea7\u5e76\u884c\u5ea6\u3002Chou\u57fa\u4e8e\u6b64\u89c2\u5bdf\u63d0\u51fa\u4e86\u57fa\u4e8e\u65f6\u6bb5\u5173\u8054\u9884\u53d6\u673a\u5236[57]\u3002\u5728EBCP\u4e2d\uff0c\u6bcf\u4e2a\u5e76\u884c\u7ec4\uff08\u65f6\u6bb5\uff09\u5185\u7684\u9996\u6b21\u7f3a\u5931\u88ab\u7528\u4f5c\u89e6\u53d1\u5730\u5740\uff0c\u7528\u4e8e\u67e5\u627e\u4e0b\u4e00\u7ec4\uff08\u6216\u540e\u7eed\u7ec4\uff09\u7684\u7f3a\u5931\uff0c\u4ece\u800c\u8df3\u8fc7\u5728\u89e6\u53d1\u7f3a\u5931\u53d1\u751f\u65f6\u53ef\u80fd\u5df2\u5728\u5904\u7406\u4e2d\u7684\u7f3a\u5931\u5730\u5740\u3002</p>"},{"location":"APHP/C3.html#325-improving-lookahead-via-dead-block-prediction-dbcp","title":"3.2.5 Improving Lookahead via Dead Block Prediction (DBCP)","text":"<p>\u89e3\u51b3\u9a6c\u5c14\u79d1\u592b\u9884\u53d6\u5668\u524d\u77bb\u9650\u5236\u7684\u7b2c\u4e8c\u79cd\u65b9\u6cd5\u662f\u4e3a\u6bcf\u4e2a\u9884\u53d6\u64cd\u4f5c\u9009\u62e9\u66f4\u65e9\u7684\u89e6\u53d1\u4e8b\u4ef6\u3002\u6b7b\u5757\u9884\u6d4b[51, 54, 60, 61, 62]\u57fa\u4e8e\u5173\u952e\u89c2\u5bdf\uff1a\u7f13\u5b58\u5757\u5728\u7f13\u5b58\u4e2d\u5927\u90e8\u5206\u65f6\u95f4\u5904\u4e8e\u6b7b\u4ea1\u72b6\u6001[63, 64, 65]\u2014\u2014\u5373\u5b83\u4eec\u867d\u4fdd\u7559\u5728\u7f13\u5b58\u4e2d\uff0c\u4f46\u5728\u5931\u6548\u6216\u6dd8\u6c70\u524d\u4e0d\u4f1a\u88ab\u518d\u6b21\u8bbf\u95ee\u3002\u6b7b\u4ea1\u7f13\u5b58\u5757\u5360\u636e\u5b58\u50a8\u7a7a\u95f4\u5374\u65e0\u6cd5\u518d\u4ea7\u751f\u7f13\u5b58\u547d\u4e2d\u3002\u8fd9\u6b63\u63d0\u4f9b\u4e86\u673a\u9047\uff1a\u9884\u53d6\u5668\u53ef\u7528\u9884\u53d6\u5757\u66ff\u6362\u6b7b\u5757\uff0c\u4e14\u65e0\u9700\u627f\u62c5\u7f13\u5b58\u6c61\u67d3\u3002\u6b7b\u5757\u5173\u8054\u9884\u53d6\u5668\uff08DBCP\uff09[51] \u65e8\u5728\u9884\u6d4b\u5bf9\u7f13\u5b58\u5757\u7684\u6700\u540e\u4e00\u6b21\u8bbf\u95ee\uff08\u5373\u5176\u6b7b\u4ea1\u4e8b\u4ef6\uff09\uff0c\u5e76\u4ee5\u6b64\u4f5c\u4e3a\u89e6\u53d1\u6761\u4ef6\u9884\u53d6\u5c06\u66ff\u6362\u8be5\u6b7b\u5757\u7684\u7f13\u5b58\u5757\u3002\u4ece\u67d0\u79cd\u610f\u4e49\u4e0a\u770b\uff0cDBCP \u5b9e\u73b0\u4e86\u6700\u5927\u524d\u77bb\u6027\u2014\u2014\u5b83\u5728\u7f13\u5b58\u5b58\u50a8\u7a7a\u95f4\u521a\u91ca\u653e\u53ef\u63a5\u6536\u9884\u53d6\u5757\u7684\u7b2c\u4e00\u65f6\u95f4\u5c31\u53d1\u8d77\u9884\u53d6\u3002</p> <p>DBCP \u4f9d\u8d56\u53cc\u91cd\u9884\u6d4b\u673a\u5236\uff1a\u9996\u5148\u9700\u9884\u6d4b\u7f13\u5b58\u5757\u7684\u6b7b\u4ea1\u65f6\u673a\u3002\u6b7b\u4ea1\u4e8b\u4ef6\u53ef\u901a\u8fc7\u4ee3\u7801\u5173\u8054[51,54,62]\u6216\u65f6\u95f4\u8ffd\u8e2a[61]\u8fdb\u884c\u9884\u6d4b\u3002\u4ee3\u7801\u5173\u8054\u5f0f\u6b7b\u5757\u9884\u6d4b\u901a\u8fc7\u8bc6\u522b\u7f13\u5b58\u5757\u88ab\u9010\u51fa\u524d\u6700\u540e\u4e00\u6761\u8bbf\u95ee\u6307\u4ee4\uff08\u5373\u5bfc\u81f4\u5757\u6b7b\u4ea1\u7684\u8bbf\u95ee\u70b9\uff09\u5b9e\u73b0\uff0c\u5176\u6838\u5fc3\u539f\u7406\u662f\u7f13\u5b58\u5757\u4ece\u521d\u59cb\u7f3a\u5931\u5206\u914d\u5f00\u59cb\uff0c\u5230\u7ecf\u5386\u8fde\u7eed\u8bbf\u95ee\u5e8f\u5217\uff0c\u76f4\u81f3\u6700\u7ec8\u6b7b\u4ea1\u7684\u6574\u4e2a\u8fc7\u7a0b\u4e2d\uff0c\u5f80\u5f80\u4f1a\u88ab\u76f8\u540c\u7684\u52a0\u8f7d/\u5b58\u50a8\u6307\u4ee4\u5e8f\u5217\u8bbf\u95ee\u3002\u4ee3\u7801\u5173\u8054\u6cd5\u7684\u5173\u952e\u4f18\u52bf\u5728\u4e8e\uff1a\u4ece\u4e00\u4e2a\u7f13\u5b58\u5757\u5b66\u4e60\u5230\u7684\u8bbf\u95ee\u5e8f\u5217\u53ef\u6cdb\u5316\u5e94\u7528\u4e8e\u9884\u6d4b\u5176\u4ed6\u5730\u5740\u7684\u6b7b\u4ea1\u4e8b\u4ef6\u3002\u6211\u4eec\u5c06\u5728\u7b2c3.3.3\u8282\u8be6\u7ec6\u8ba8\u8bba\u4ee3\u7801\u5173\u8054\u673a\u5236\u3002</p> <p>\u65f6\u5e8f\u9884\u6d4b\u673a\u5236\u5219\u901a\u8fc7\u9884\u6d4b\u7f13\u5b58\u5757\u7684\u5269\u4f59\u5b58\u6d3b\u65f6\u95f4\uff08\u4ee5\u65f6\u949f\u5468\u671f\u8ba1\u91cf\uff09\u800c\u975e\u5177\u4f53\u6b7b\u4ea1\u8bbf\u95ee\u70b9\u6765\u5b9e\u73b0[61]\u3002\u8be5\u65b9\u6cd5\u7684\u7406\u8bba\u57fa\u7840\u662f\uff1a\u7f13\u5b58\u5757\u6bcf\u6b21\u8f7d\u5165\u7f13\u5b58\u65f6\u7684\u5b58\u6d3b\u5468\u671f\u5177\u6709\u76f8\u4f3c\u6027\u3002\u5728\u6b64\u7c7b\u8bbe\u8ba1\u4e2d\uff0c\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u8868\u4f1a\u65b0\u589e\u8bb0\u5f55\u5b57\u6bb5\u5b58\u50a8\u8be5\u5757\u4e0a\u6b21\u8f7d\u5165\u65f6\u7684\u5b58\u6d3b\u65f6\u957f\uff0c\u5e76\u57fa\u4e8e\u6b64\u8bbe\u5b9a\u9002\u5f53\u5b89\u5168\u8fb9\u9645\uff08\u5982\u4e24\u500d\u4e8e\u524d\u6b21\u5b58\u6d3b\u65f6\u957f\uff09\u6765\u9884\u6d4b\u5757\u6b7b\u4ea1\u65f6\u673a\u3002</p> <p>\u6b7b\u4ea1\u4e8b\u4ef6\u9884\u6d4b\u5b8c\u6210\u540e\uff0c\u8fd8\u9700\u786e\u5b9a\u66ff\u6362\u8be5\u5757\u7684\u9884\u53d6\u76ee\u6807\u3002\u65e9\u671f\u6b7b\u5757\u9884\u53d6\u5668\u91c7\u7528\u7c7b\u9a6c\u5c14\u53ef\u592b\u9884\u6d4b\u8868\u5b9e\u73b0\u8be5\u529f\u80fd[51,61]\uff0c\u540e\u7eed\u7814\u7a76[54]\u5219\u91c7\u7528\u66f4\u590d\u6742\u7684\u65f6\u95f4\u6d41\u9884\u6d4b\u5668\uff08\u8be6\u89c1\u7b2c3.2.9\u8282\uff09\u3002</p>"},{"location":"APHP/C3.html#326-addressing-on-chip-storage-limitations","title":"3.2.6 Addressing on-Chip Storage Limitations","text":"<p>\u5236\u7ea6\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u6548\u80fd\u7684\u7b2c\u4e8c\u4e2a\u5173\u952e\u56e0\u7d20\u662f\u5173\u8054\u8868\u7684\u6709\u9650\u7247\u4e0a\u5b58\u50a8\u5bb9\u91cf\u3002\u672c\u8d28\u4e0a\uff0c\u5730\u5740\u5173\u8054\u6240\u9700\u7684\u5143\u6570\u636e\u89c4\u6a21\u968f\u5e94\u7528\u7a0b\u5e8f\u5de5\u4f5c\u96c6\u6269\u5927\u800c\u589e\u957f\u2014\u2014\u7406\u60f3\u60c5\u51b5\u4e0b\u5173\u8054\u8868\u9700\u8986\u76d6\u5de5\u4f5c\u96c6\u5185\u6240\u6709\u5730\u5740\u7684\u5173\u8054\u5173\u7cfb\u3002\u5b9e\u9645\u6240\u9700\u7684\u5173\u8054\u8868\u5bb9\u91cf\u901a\u5e38\u6bd4\u6570\u636e\u96c6\u672c\u8eab\u5c0f\u4e00\u4e2a\u5e38\u6570\u7cfb\u6570\uff08\u56e0\u5b58\u50a8\u7684\u662f\u5730\u5740\u800c\u975e\u6570\u636e\uff0c\u5176\u5b58\u50a8\u9700\u6c42\u8f83\u5de5\u4f5c\u96c6\u7f29\u5c0f\u7684\u6bd4\u4f8b\u4e3a\u7f13\u5b58\u5757\u5927\u5c0f\u4e0e\u5730\u5740\u5c3a\u5bf8\u4e4b\u6bd4\uff09\u3002</p> <p>\u63d0\u5347\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u6548\u80fd\u7684\u6709\u6548\u9014\u5f84\u662f\u4f18\u5316\u5173\u8054\u8868\u7684\u5b58\u50a8\u6548\u7387\u3002\u6807\u7b7e\u5173\u8054\u9884\u53d6\u5668[66]\u5728\u5173\u8054\u8868\u9879\u4e2d\u4ec5\u5b58\u50a8\u6807\u7b7e\u4f4d\u800c\u975e\u5b8c\u6574\u7f13\u5b58\u5757\u5730\u5740\uff0c\u6b64\u4e3e\u867d\u964d\u4f4e\u4e86\u5355\u8868\u9879\u5b58\u50a8\u9700\u6c42\uff0c\u4f46\u4ec5\u80fd\u901a\u8fc7\u5fae\u5c0f\u5e38\u6570\u56e0\u5b50\u63d0\u5347\u5173\u8054\u8868\u5bb9\u91cf\uff0c\u8fd9\u5bf9\u4e8e\u5177\u6709\u5927\u5de5\u4f5c\u96c6\uff08\u4f8b\u5982\u670d\u52a1\u5668\u5e94\u7528\uff09\u7684\u5e94\u7528\u6765\u8bf4\u4e0d\u8db3\u4ee5\u83b7\u5f97\u9ad8\u8986\u76d6\u7387\u3002</p> <p>\u7b2c\u4e8c\u79cd\u65b9\u6cd5\u662f\u5c06\u5173\u8054\u8868\u8fc1\u79fb\u81f3\u4e3b\u5185\u5b58\uff0c\u4ece\u800c\u6d88\u9664\u7247\u4e0a\u5173\u8054\u8868\u7684\u5bb9\u91cf\u9650\u5236[42, 52, 54, 67, 72]\u3002\u7247\u5916\u5173\u8054\u8868\u5373\u4f7f\u5bf9\u4e8e\u5927\u5de5\u4f5c\u96c6\u7684\u8d1f\u8f7d\u4e5f\u80fd\u5b9e\u73b0\u9ad8\u8986\u76d6\u7387[52]\u3002\u7136\u800c\uff0c\u5c06\u5173\u8054\u8868\u79fb\u81f3\u7247\u5916\u4f1a\u4f7f\u9884\u53d6\u5668\u5143\u6570\u636e\u7684\u8bbf\u95ee\u5ef6\u8fdf\u4ece\u51e0\u4e2a\u65f6\u949f\u5468\u671f\u589e\u52a0\u5230\u7247\u5916\u5185\u5b58\u8bbf\u95ee\u7684\u5ef6\u8fdf\u2014\u2014\u8bbf\u95ee\u9884\u53d6\u5143\u6570\u636e\u56e0\u6b64\u53ef\u80fd\u8017\u65f6\u4e0e\u9884\u53d6\u6240\u9700\u7f13\u5b58\u5757\u4e00\u6837\u957f\u3002</p> <p>\u4e3a\u4fdd\u6301\u9ad8\u6548\uff0c\u7247\u5916\u5173\u8054\u8868\u5fc5\u987b\u63d0\u4f9b\u8db3\u591f\u7684\u9884\u77bb\u8ddd\u79bb\u4ee5\u9690\u85cf\u957f\u5143\u6570\u636e\u8bbf\u95ee\u5ef6\u8fdf\u3002\u4e00\u79cd\u65b9\u6cd5\uff08\u5728\u7b2c3.2.4\u8282\u8ba8\u8bba\uff09\u662f\u8bbe\u8ba1\u9884\u53d6\u5668\u4ee5\u8bb0\u5f55\u672a\u6765\u5e76\u884c\u7ec4\uff08\u5468\u671f\uff09\u4e2d\u53d1\u751f\u7684\u5185\u5b58\u8bbf\u95ee\u5730\u5740\uff0c\u5982EBCP [57]\u6240\u793a\u3002\u7b2c\u4e8c\u79cd\u65b9\u6cd5\u662f\u589e\u52a0\u9884\u53d6\u6df1\u5ea6[52]\uff1b\u5373\u4f7f\u9996\u4e2a\u9884\u53d6\u5757\u4e0d\u53ca\u65f6\uff0c\u540e\u7eed\u5730\u5740\u4ecd\u80fd\u6210\u529f\u9884\u53d6\u3002\u589e\u52a0\u9884\u53d6\u6df1\u5ea6\u7684\u901a\u7528\u5316\u5f62\u5f0f\u662f\u65f6\u5e8f\u6d41[42]\uff08\u5728\u7b2c3.2.9\u8282\u8ba8\u8bba\uff09\uff0c\u5b83\u901a\u8fc7\u9488\u5bf9\u4efb\u610f\u957f\u5ea6\u7684\u6d41\uff08\u5373\u6709\u6548\u65e0\u9650\u7684\u9884\u53d6\u6df1\u5ea6\uff09\u6765\u5206\u644a\u7247\u5916\u5143\u6570\u636e\u8bbf\u95ee[67]\u3002</p>"},{"location":"APHP/C3.html#327-global-history-buffer","title":"3.2.7 Global History Buffer","text":"<p>\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u7684\u7c7b\u7f13\u5b58\u7ed3\u6784\u9650\u5236\u5176\u4ec5\u80fd\u8bb0\u5f55\u56fa\u5b9a\u957f\u5ea6\u7684\u6d41\u2014\u2014\u5355\u4e2a\u8868\u9879\u53ea\u80fd\u5b58\u50a8\u56fa\u5b9a\u9884\u53d6\u6df1\u5ea6\u7684\u5730\u5740\u3002\u7a84\u8868\u9879\u4f1a\u727a\u7272\u6f5c\u5728\u7684\u8986\u76d6\u7387\u548c\u9884\u77bb\u8ddd\u79bb\uff0c\u800c\u5bbd\u8868\u9879\u5bf9\u4e8e\u77ed\u6d41\u5219\u5b58\u50a8\u6548\u7387\u4f4e\u4e0b\u3002\u867d\u7136\u53ef\u901a\u8fc7\u6307\u9488\u94fe\u5f0f\u8fde\u63a5\u8868\u9879\uff0c\u4f46\u8fd9\u4f1a\u589e\u52a0\u67e5\u627e\u5ef6\u8fdf\uff0c\u5c24\u5176\u5f53\u5173\u8054\u8868\u4f4d\u4e8e\u7247\u5916\u65f6\u66f4\u4e3a\u4e0d\u5229\u3002Wenisch\u53ca\u5176\u5408\u4f5c\u8005\u7814\u7a76\u4e86\u5546\u4e1a\u670d\u52a1\u5668\u5e94\u7528\u4e2d\u7684\u91cd\u590d\u65f6\u5e8f\u5173\u8054\u6d41\uff0c\u5e76\u8bc1\u660e\u6d41\u957f\u5ea6\u4ece\u4e24\u4e2a\u5230\u6570\u5343\u4e2a\u7f13\u5b58\u5757\u4e0d\u7b49[55, 67]\u3002\u6700\u5e38\u89c1\u7684\u6d41\u957f\u5ea6\u4ec5\u4e3a\u4e24\u6b21\u7f3a\u5931\uff0c\u8fd9\u610f\u5473\u7740\u5bbd\u9a6c\u5c14\u53ef\u592b\u8868\u9879\u5b58\u50a8\u6548\u7387\u4f4e\u4e0b\u3002\u4f46\u82e5\u6309\u6d41\u4e2d\u7684\u7f3a\u5931\u6b21\u6570\u52a0\u6743\uff08\u5373\u901a\u8fc7\u9884\u53d6\u8be5\u6d41\u53ef\u83b7\u5f97\u7684\u6f5c\u5728\u8986\u76d6\u7387\uff09\uff0c\u6d41\u957f\u5ea6\u4e2d\u503c\u7ea6\u4e3a\u5341\u4e2a\u7f13\u5b58\u5757\u3002</p> <p>Nesbit\u548cSmith\u5728\u5176\u5168\u5c40\u5386\u53f2\u7f13\u51b2\u533a[68]\u4e2d\u5f15\u5165\u7684\u5173\u952e\u8fdb\u5c55\u662f\u5c06\u5173\u8054\u8868\u62c6\u5206\u4e3a\u4e24\u4e2a\u7ed3\u6784\uff1a\u5386\u53f2\u7f13\u51b2\u533a\uff08\u4ee5\u5faa\u73af\u7f13\u51b2\u533a\u5f62\u5f0f\u6309\u53d1\u751f\u987a\u5e8f\u8bb0\u5f55\u7f3a\u5931\u5e8f\u5217\uff09\u548c\u7d22\u5f15\u8868\uff08\u63d0\u4f9b\u4ece\u5730\u5740\u6216\u5176\u4ed6\u9884\u53d6\u89e6\u53d1\u5230\u5386\u53f2\u7f13\u51b2\u533a\u4f4d\u7f6e\u7684\u6620\u5c04\uff09\u3002\u5386\u53f2\u7f13\u51b2\u533a\u5141\u8bb8\u5355\u4e2a\u9884\u53d6\u89e6\u53d1\u6307\u5411\u4efb\u610f\u957f\u5ea6\u7684\u6d41\u3002\u56fe3.3\uff08\u5f15\u81ea[68]\uff09\u5c55\u793a\u4e86\u5168\u5c40\u5386\u53f2\u7f13\u51b2\u533a\u7684\u7ec4\u7ec7\u7ed3\u6784\u3002</p> <p>\u7d22\u5f15\u8868\u4fdd\u7559\u4e86\u4e0e\u539f\u59cb\u9a6c\u5c14\u53ef\u592b\u9884\u53d6\u5668\u7c7b\u4f3c\u7684\u7ec4\u76f8\u8054\u5b58\u50a8\u7ed3\u6784\u3002\u4f46\u7d22\u5f15\u8868\u4e0d\u518d\u5b58\u50a8\u7f13\u5b58\u5757\u5730\u5740\uff0c\u800c\u662f\u5b58\u50a8\u6307\u5411\u5386\u53f2\u7f13\u51b2\u533a\u7684\u6307\u9488\u3002\u5f53\u53d1\u751f\u7f3a\u5931\u65f6\uff0cGHB\u5f15\u7528\u7d22\u5f15\u8868\u4ee5\u67e5\u770b\u662f\u5426\u6709\u4e0e\u7f3a\u5931\u5730\u5740\u5173\u8054\u7684\u4fe1\u606f\u3002\u82e5\u627e\u5230\u8868\u9879\uff0c\u5219\u5faa\u6307\u9488\u5b9a\u4f4d\u81f3\u5386\u53f2\u7f13\u51b2\u533a\u4e2d\u7684\u5bf9\u5e94\u4f4d\u7f6e\uff0c\u5e76\u68c0\u67e5\u5386\u53f2\u7f13\u51b2\u533a\u6761\u76ee\u662f\u5426\u4ecd\u5305\u542b\u7f3a\u5931\u5730\u5740\uff08\u8be5\u6761\u76ee\u53ef\u80fd\u5df2\u88ab\u8986\u76d6\uff09\u3002\u82e5\u662f\uff0c\u5219\u5386\u53f2\u7f13\u51b2\u533a\u4e2d\u7684\u540e\u7eed\u82e5\u5e72\u6761\u76ee\u5c06\u5305\u542b\u9884\u6d4b\u6d41\u3002\u5386\u53f2\u7f13\u51b2\u533a\u6761\u76ee\u8fd8\u53ef\u901a\u8fc7\u94fe\u63a5\u6307\u9488\u6269\u5c55\u81f3\u5176\u4ed6\u5386\u53f2\u7f13\u51b2\u533a\u4f4d\u7f6e\uff0c\u4ee5\u5b9e\u73b0\u6309\u591a\u79cd\u987a\u5e8f\u904d\u5386\u5386\u53f2\u8bb0\u5f55\uff08\u4f8b\u5982\uff0c\u6bcf\u4e2a\u94fe\u63a5\u6307\u9488\u53ef\u6307\u5411\u540c\u4e00\u7f3a\u5931\u5730\u5740\u7684\u5148\u524d\u51fa\u73b0\u4f4d\u7f6e\uff0c\u4ece\u800c\u63d0\u5347\u9884\u53d6\u5bbd\u5ea6\u4e0e\u6df1\u5ea6\uff09\u3002</p> <p></p> <p>\u901a\u8fc7\u6539\u53d8\u7d22\u5f15\u8868\u4e2d\u5b58\u50a8\u7684\u952e\u503c\u4e0e\u5386\u53f2\u7f13\u51b2\u533a\u6761\u76ee\u95f4\u7684\u94fe\u63a5\u6307\u9488\uff0cGHB\u8bbe\u8ba1\u53ef\u6316\u6398\u89e6\u53d1\u4e8b\u4ef6\u4e0e\u9884\u6d4b\u9884\u53d6\u6d41\u95f4\u7684\u591a\u79cd\u5173\u8054\u7279\u6027\u3002Nesbit\u4e0eSmith\u63d0\u51fa\u4e86GHB\u53d8\u4f53\u7684\u5206\u7c7b\u6cd5GHB X/Y\uff0c\u5176\u4e2dX\u8868\u793a\u6d41\u5c40\u90e8\u5316\u65b9\u5f0f\uff08\u5373\u94fe\u63a5\u6307\u9488\u5982\u4f55\u8fde\u63a5\u5e94\u8fde\u7eed\u9884\u53d6\u7684\u5386\u53f2\u7f13\u51b2\u533a\u6761\u76ee\uff09\uff0cY\u8868\u793a\u5173\u8054\u65b9\u6cd5\uff08\u5373\u67e5\u627e\u8fc7\u7a0b\u5982\u4f55\u5b9a\u4f4d\u5019\u9009\u6d41\uff09[68, 69]\u3002\u5c40\u90e8\u5316\u53ef\u5206\u4e3a\u5168\u5c40\u5c40\u90e8\u5316\uff08G\uff09\u4e0e\u6309PC\u5c40\u90e8\u5316\uff08PC\uff09\u3002\u5728\u5168\u5c40\u5c40\u90e8\u5316\u4e0b\uff0c\u8fde\u7eed\u8bb0\u5f55\u7684\u5386\u53f2\u7f13\u51b2\u533a\u6761\u76ee\u6784\u6210\u6d41\u3002\u6bcf\u4e2a\u5386\u53f2\u8868\u6761\u76ee\u5173\u8054\u7684\u6307\u9488\u6216\u6307\u5411\u540c\u4e00\u7f3a\u5931\u5730\u5740\u7684\u8f83\u65e9\u51fa\u73b0\u4f4d\u7f6e\uff08\u5982\u524d\u6587\u6240\u8ff0\u53ef\u63d0\u5347\u9884\u53d6\u5bbd\u5ea6\uff09\uff0c\u6216\u5904\u4e8e\u672a\u4f7f\u7528\u72b6\u6001\u3002\u5728\u6309PC\u5c40\u90e8\u5316\u4e0b\uff0c\u7d22\u5f15\u8868\u4e0e\u94fe\u63a5\u6307\u9488\u5747\u57fa\u4e8e\u89e6\u53d1\u8bbf\u95ee\u7684PC\u8fde\u63a5\u5386\u53f2\u7f13\u51b2\u533a\u6761\u76ee\uff1b\u901a\u8fc7\u8ffd\u8e2a\u7531\u540c\u4e00\u89e6\u53d1PC\u53d1\u51fa\u7684\u8fde\u7eed\u7f3a\u5931\u5730\u5740\u95f4\u7684\u94fe\u63a5\u6307\u9488\u5f62\u6210\u6d41\u3002\u5173\u8054\u65b9\u6cd5\u53ef\u5206\u4e3a\u5730\u5740\u5173\u8054\uff08AC\uff09\u6216\u5dee\u503c\u5173\u8054\uff08DC\uff09\u3002\u672c\u8282\u8ba8\u8bba\u5168\u5c40\u5730\u5740\u5173\u8054\u53d8\u4f53\uff08GHB G/AC\uff09\uff0c\u5176\u7d22\u5f15\u8868\u5c06\u7f3a\u5931\u5730\u5740\u6620\u5c04\u81f3\u5386\u53f2\u7f13\u51b2\u533a\u4f4d\u7f6e\u3002\u7b2c3.3.2\u8282\u5c06\u8ba8\u8bbaGHB PC/DC\uff08\u201c\u7a0b\u5e8f\u8ba1\u6570\u5668\u5c40\u90e8\u5316\u5dee\u503c\u5173\u8054\u201d\uff09\uff0c\u8be5\u53d8\u4f53\u901a\u8fc7\u4e0d\u540c\u65b9\u5f0f\u5b9a\u4f4d\u6761\u76ee\u5e76\u8bb0\u5f55\u5386\u53f2\u2014\u2014\u57fa\u4e8e\u8fde\u7eed\u7f3a\u5931\u4e4b\u95f4\u7684\u6b65\u957f\u6784\u5efa\u5386\u53f2\u8bb0\u5f55\uff0c\u5e76\u6309\u6bcf\u6307\u4ee4\u5730\u5740\uff08PC\uff09\u5b9a\u4f4d\u7f3a\u5931\u5386\u53f2\u3002\u6587\u732e\u4e2d\u8ba8\u8bba\u4e86\u5176\u4ed6\u51e0\u79cd\u5b9a\u4f4d\u4e0e\u5173\u8054\u65b9\u6848[68, 69]\u3002</p> <p>GHB\u67b6\u6784\u4e0b\u7684\u4e00\u4e2a\u6311\u6218\u5728\u4e8e\u5224\u65ad\u6d41\u4f55\u65f6\u7ec8\u6b62\uff0c\u5373\u9884\u53d6\u5668\u4f55\u65f6\u5e94\u505c\u6b62\u6839\u636e\u5386\u53f2\u7f13\u51b2\u533a\u6307\u793a\u7ee7\u7eed\u83b7\u53d6\u5730\u5740\u3002\u8bb8\u591a\u57fa\u4e8eGHB\u67b6\u6784\u7684\u65b9\u6848\uff08\u5982[42]\uff09\u672a\u5c1d\u8bd5\u9884\u6d4b\u6d41\u7684\u7ec8\u6b62\uff0c\u800c\u662f\u4e3a\u6bcf\u6b21\u6210\u529f\u7684\u7d22\u5f15\u8868\u67e5\u627e\u5206\u914d\u6d41\u7f13\u51b2\u533a[34]\uff0c\u5e76\u5728\u6301\u7eed\u4ea7\u751f\u9884\u53d6\u547d\u4e2d\u7684\u60c5\u51b5\u4e0b\u6301\u7eed\u8ffd\u8e2a\u8be5\u6d41\u3002\u5bf9\u5df2\u5931\u6548\u6d41\u5206\u914d\u7684\u6d41\u7f13\u51b2\u533a\u4f1a\u901a\u8fc7\u6700\u8fd1\u6700\u5c11\u4f7f\u7528\u7f6e\u6362\u7b49\u673a\u5236\u56de\u6536\u3002Wenisch\u63d0\u51fa\u4e86\u5728\u8ffd\u8e2a\u6d41\u65f6\u81ea\u9002\u5e94\u8c03\u6574\u9884\u53d6\u901f\u7387\u7684\u65b9\u6cd5[42]\u3002</p>"},{"location":"APHP/C3.html#328-stream-chaining","title":"3.2.8 Stream Chaining","text":"<p>GHB\u7684\u5c40\u9650\u6027\u5728\u4e8e\u5e38\u53d1\u73b0\u77ed\u6d41\uff08\u5c24\u5176\u5728\u6309PC\u5b9a\u4f4d\u6d41\u65f6\uff09\uff0c\u96be\u4ee5\u5b9e\u73b0\u8db3\u591f\u7684\u9884\u53d6\u524d\u77bb\u6df1\u5ea6\u3002\u901a\u8fc7\u8f85\u52a9\u67e5\u627e\u673a\u5236\u9884\u6d4b\u6d41\u95f4\u5173\u8054\u6027[58, 59]\uff0c\u53ef\u5c06\u72ec\u7acb\u5b58\u50a8\u7684\u6d41\u94fe\u5f0f\u8fde\u63a5\u4ee5\u6269\u5c55\u6d41\u957f\u5ea6\u3002\u6d41\u94fe\u5f0f\u8fde\u63a5\u5c06\u4e0d\u540cPC\u751f\u6210\u7684\u6d41\u94fe\u63a5\u8d77\u6765\uff0c\u5f62\u6210\u66f4\u957f\u7684\u9884\u53d6\u5e8f\u5217[59]\u3002\u8be5\u6280\u672f\u57fa\u4e8e\u8fde\u7eedPC\u5b9a\u4f4d\u6d41\u95f4\u5b58\u5728\u65f6\u5e8f\u5173\u8054\u6027\u7684\u6d1e\u5bdf\u2014\u2014\u5373\u76f8\u540c\u7684\u4e24\u4e2a\u6d41\u503e\u5411\u4e8e\u8fde\u7eed\u51fa\u73b0\u3002\u66f4\u5e7f\u4e49\u800c\u8a00\uff0c\u53ef\u6784\u5efa\u6d41\u95f4\u7684\u6709\u5411\u56fe\u6765\u6307\u793a\u6bcf\u4e2a\u524d\u9a71\u6d41\u6700\u53ef\u80fd\u63a5\u7eed\u7684\u540e\u7ee7\u6d41\u3002\u6d41\u94fe\u5f0f\u8fde\u63a5\u4e3a\u6bcf\u4e2a\u7d22\u5f15\u8868\u6761\u76ee\u6269\u5c55\u4e86\u201c\u4e0b\u4e00\u6d41\u6307\u9488\u201d\uff08\u6307\u793a\u672c\u6d41\u4e4b\u540e\u4f7f\u7528\u7684\u7d22\u5f15\u8868\u6761\u76ee\uff09\u548c\u7f6e\u4fe1\u5ea6\u8ba1\u6570\u5668\u3002\u901a\u8fc7\u94fe\u63a5\u72ec\u7acb\u7684PC\u5b9a\u4f4d\u6d41\uff0c\u8be5\u6280\u672f\u80fd\u5728\u5355\u6b21\u89e6\u53d1\u8bbf\u95ee\u4e2d\u5b9e\u73b0\u66f4\u51c6\u786e\u7684\u9884\u53d6\u3002</p>"},{"location":"APHP/C3.html#329-temporal-memory-streaming","title":"3.2.9 Temporal Memory Streaming","text":"<p>\u539f\u59cbGHB\u65b9\u6848\u7684\u7d22\u5f15\u8868\u548c\u5386\u53f2\u8868\u5bb9\u91cf\u8f83\u5c0f\u4e14\u4f4d\u4e8e\u82af\u7247\u4e0a\uff0c\u8fd9\u9650\u5236\u4e86GHB/AC\u53d8\u4f53\u5bf9\u5927\u5de5\u4f5c\u8d1f\u8f7d\u573a\u666f\u7684\u6709\u6548\u6027\u3002\u65f6\u5e8f\u5185\u5b58\u6d41\u5904\u7406\u6280\u672f[42]\u6cbf\u7528GHB\u5b58\u50a8\u67b6\u6784\uff0c\u4f46\u5c06\u7d22\u5f15\u8868\u548c\u5386\u53f2\u7f13\u51b2\u533a\u5747\u79fb\u81f3\u4e3b\u5185\u5b58\u4e2d\uff0c\u4f7f\u5176\u80fd\u8bb0\u5f55\u5e76\u91cd\u653e\u4efb\u610f\u957f\u5ea6\u7684\u6d41\uff0c\u5373\u4f7f\u9762\u5bf9\u5927\u5de5\u4f5c\u8d1f\u8f7d\u573a\u666f\u4ea6\u7136\u3002</p> <p>\u7247\u5916\u8868\u7ed3\u6784\u5e26\u6765\u53cc\u91cd\u6311\u6218\uff1a3.2.6\u8282\u5df2\u8ba8\u8bba\u5143\u6570\u636e\u8bbf\u95ee\u5ef6\u8fdf\u4e0e\u9884\u53d6\u524d\u77bb\u6df1\u5ea6\u7684\u77db\u76fe\uff0c\u4f46\u66f4\u65b0\u7247\u5916\u8868\u540c\u6837\u5b58\u5728\u6311\u6218\u3002\u7531\u4e8e\u6bcf\u6b21\u7f3a\u5931\u90fd\u9700\u66f4\u65b0\u8868\u7ed3\u6784\uff0c\u7b80\u5355\u5b9e\u73b0\u4f1a\u4f7f\u5185\u5b58\u5e26\u5bbd\u589e\u957f\u4e24\u500d\uff08\u4e00\u6b21\u7f3a\u5931\u8bbf\u95ee\uff0c\u5916\u52a0\u7d22\u5f15\u8868\u548c\u5386\u53f2\u7f13\u51b2\u533a\u5404\u4e00\u6b21\u66f4\u65b0\uff09\u3002</p> <p>\u5386\u53f2\u8868\u66f4\u65b0\u5e26\u5bbd\u53ef\u901a\u8fc7\u7247\u5185\u5c0f\u7f13\u51b2\u6c60\u53ca\u5408\u5e76\u8fde\u7eed\u8ffd\u52a0\u5199\u5165\u6765\u7f13\u89e3\uff0c\u800c\u7d22\u5f15\u8868\u66f4\u65b0\u5219\u96be\u4ee5\u901a\u8fc7\u7c7b\u4f3c\u65b9\u5f0f\u4f18\u5316\u3002\u7a7a\u95f4\u5c40\u90e8\u6027\u65e0\u6cd5\u5229\u7528\u76f8\u540c\u7684\u4f18\u5316\u3002\u7136\u800c\uff0cWenisch\u53ca\u5176\u5408\u4f5c\u8005\u6307\u51fa\uff0c\u901a\u8fc7\u91c7\u7528\u7d22\u5f15\u8868\u66f4\u65b0\u91c7\u6837\u6280\u672f\u2014\u2014\u4ec5\u6267\u884c\u968f\u673a\u5b50\u96c6\u7684\u5386\u53f2\u8868\u5199\u5165\u64cd\u4f5c[67, 70]\uff0c\u53ef\u6709\u6548\u7ba1\u7406\u7d22\u5f15\u8868\u66f4\u65b0\u5e26\u5bbd\u3002\u7814\u7a76\u8868\u660e\uff0c\u5360\u636e\u8986\u76d6\u7387\u4e3b\u4f53\u7684\u8bbf\u95ee\u6d41\u901a\u5e38\u5177\u6709\u957f\u5e8f\u5217\u6216\u9ad8\u9891\u590d\u73b0\u7279\u6027\u3002\u5bf9\u4e8e\u957f\u5e8f\u5217\u6d41\uff0c\u5728\u6d41\u8d77\u59cb\u7684\u82e5\u5e72\u6b21\u8bbf\u95ee\u5185\u5373\u6709\u9ad8\u6982\u7387\u8bb0\u5f55\u7d22\u5f15\u8868\u6761\u76ee\uff0c\u76f8\u8f83\u4e8e\u6d41\u7684\u957f\u4e3b\u4f53\u90e8\u5206\u4ec5\u727a\u7272\u53ef\u5ffd\u7565\u7684\u8986\u76d6\u7387\uff1b\u5bf9\u4e8e\u9ad8\u9891\u6d41\uff0c\u5373\u4f7f\u9996\u6b21\u904d\u5386\u65f6\u672a\u8bb0\u5f55\u7d22\u5f15\u8868\u6761\u76ee\uff0c\u968f\u7740\u6d41\u91cd\u590d\u51fa\u73b0\uff0c\u76ee\u6807\u6761\u76ee\u7684\u8bb0\u5f55\u6982\u7387\u4e5f\u4f1a\u5feb\u901f\u8d8b\u8fd1\u4e8e1\u3002\u56fe3.4\uff08\u5f15\u81ea[67]\uff09\u76f4\u89c2\u5c55\u793a\u4e86\u91c7\u6837\u673a\u5236\u7684\u6709\u6548\u6027\u3002</p> <p></p> <p>IBM\u8fd1\u671f\u62ab\u9732\u5176Blue Gene/Q\u7cfb\u7edf\u91c7\u7528\u4e86\u4e00\u79cd\u79f0\u4e3a\u5217\u8868\u9884\u53d6[71]\u7684\u65b0\u65b9\u6848\uff0c\u8be5\u65b9\u6848\u4e0e\u65f6\u5e8f\u5185\u5b58\u6d41\u9884\u53d6\u6280\u672f\u9ad8\u5ea6\u76f8\u4f3c\uff0c\u636e\u6211\u4eec\u6240\u77e5\u662f\u6b64\u7c7b\u9884\u53d6\u5668\u552f\u4e00\u516c\u5f00\u7684\u5546\u4e1a\u5b9e\u73b0\u3002\u5217\u8868\u9884\u53d6\u5f15\u64ce\u53ef\u4ece\u4e3b\u5185\u5b58\u4e2d\u8bb0\u5f55\u7684\u7f3a\u5931\u6d41\u8fdb\u884c\u9884\u53d6\uff0c\u5730\u5740\u5217\u8868\u65e2\u53ef\u901a\u8fc7\u8f6f\u4ef6API\u63d0\u4f9b\uff0c\u4e5f\u53ef\u7531\u786c\u4ef6\u81ea\u52a8\u8bb0\u5f55\u3002\u4f46\u8be5\u65b9\u6848\u672a\u63d0\u4f9b\u7247\u5916\u7d22\u5f15\u8868\uff0c\u9700\u501f\u52a9\u8f6f\u4ef6\u8f85\u52a9\u5b8c\u6210\u6d41\u8bb0\u5f55\u3001\u5b9a\u4f4d\u4e0e\u521d\u59cb\u5316\u64cd\u4f5c\uff0c\u786c\u4ef6\u5219\u8d1f\u8d23\u7ba1\u7406\u9884\u53d6\u65f6\u6548\u6027\u53ca\u8bb0\u5f55\u6d41\u4e0eL1\u7f13\u5b58\u7f3a\u5931\u95f4\u7684\u5fae\u5c0f\u504f\u5dee\u3002</p>"},{"location":"APHP/C3.html#3210-irregular-stream-buffer","title":"3.2.10 Irregular Stream Buffer","text":"<p>\u867d\u7136\u91c7\u6837\u80fd\u964d\u4f4e\u7247\u5916\u6d41\u5143\u6570\u636e\u7ef4\u62a4\u5f00\u9500\uff0c\u4f46\u67e5\u627e\u5ef6\u8fdf\u4ecd\u8f83\u9ad8\uff0c\u9650\u5236\u4e86\u77ed\u6d41\u7684\u9884\u53d6\u524d\u77bb\u8ddd\u79bb\u3002\u6b64\u5916\uff0c\u7247\u5916\u5b58\u50a8\u65e0\u6cd5\u5b9e\u73b0\u7c7b\u4f3cGHB\u7684\u5730\u5740\u5173\u8054\u6d41PC\u672c\u5730\u5316\u2014\u2014\u5728\u7247\u5916\u5386\u53f2\u7f13\u51b2\u533a\u4e2d\u6cbf\u94fe\u63a5\u6307\u9488\u904d\u5386\u6761\u76ee\u901f\u5ea6\u8fc7\u6162\uff08\u5176\u6548\u7387\u4e0d\u9ad8\u4e8e\u89e3\u5f15\u7528\u4f9d\u8d56\u6307\u9488\u94fe\uff0c\u800c\u8fd9\u6b63\u662f\u65f6\u6001\u6d41\u9884\u53d6\u65e8\u5728\u52a0\u901f\u7684\u8bbf\u95ee\u6a21\u5f0f\uff09\u3002\u4e3a\u7a81\u7834\u8fd9\u4e9b\u9650\u5236\uff0cJain\u4e0eLin\u63d0\u51fa\u4e86\u4e0d\u89c4\u5219\u6d41\u7f13\u51b2\u533a\uff08ISB\uff09[72]\u3002\u8be5\u65b9\u6848\u5f15\u5165\u4ec5\u5bf9\u9884\u53d6\u5668\u53ef\u89c1\u7684\u65b0\u578b\u6982\u5ff5\u5730\u5740\u7a7a\u95f4\u2014\u2014\u7ed3\u6784\u5730\u5740\u7a7a\u95f4\u3002\u5f53\u672b\u7ea7\u7f13\u5b58\u4e2d\u7684\u7f13\u5b58\u5757\u88ab\u8bbf\u95ee\u65f6\uff0c\u5b83\u4eec\u4f1a\u88ab\u5206\u914d\u8fde\u7eed\u7684\u7ed3\u6784\u5730\u5740\uff08\u53ef\u80fd\u4f1a\u66ff\u6362\u7279\u5b9a\u7f13\u5b58\u5757\u5148\u524d\u5206\u914d\u7684\u7ed3\u6784\u5730\u5740\uff09\u3002\u901a\u8fc7\u8fd9\u79cd\u91cd\u6620\u5c04\uff0c\u7269\u7406\u5730\u5740\u7a7a\u95f4\u4e2d\u7684\u65f6\u95f4\u76f8\u5173\u6027\u8f6c\u53d8\u4e3a\u7ed3\u6784\u5730\u5740\u7a7a\u95f4\u4e2d\u7684\u7a7a\u95f4\u76f8\u5173\u6027\u3002\u56e0\u6b64\uff0c\u53ef\u4ee5\u901a\u8fc7\u7b80\u5355\u7684\u8fde\u7eedN\u884c\u6d41\u9884\u53d6\u5668\u5bf9\u7269\u7406\u5730\u5740\u7684\u65f6\u95f4\u6d41\u8fdb\u884c\u9884\u53d6\uff0c\u8be5\u9884\u53d6\u5668\u5411\u7ed3\u6784\u5730\u5740\u53d1\u51fa\u8bf7\u6c42\u3002\u4e24\u4e2a\u7247\u4e0a\u8868\u7ef4\u62a4\u7269\u7406\u5730\u5740\u4e0e\u7ed3\u6784\u5730\u5740\u4e4b\u95f4\u7684\u53cc\u5411\u6620\u5c04\u3002\u8fd9\u4e9b\u6620\u5c04\u4f1a\u968f\u7740TLB\u7684\u586b\u5145\u4e0e\u66ff\u6362\u540c\u6b65\u4ece\u7247\u4e0a\u8868\u8f6c\u79fb\u81f3\u7247\u5916\u540e\u5907\u5b58\u50a8\uff0c\u786e\u4fdd\u7247\u4e0a\u7ed3\u6784\u5305\u542b\u5904\u7406\u5668\u5f53\u524d\u53ef\u8bbf\u95ee\u5730\u5740\u96c6\u5408\u7684\u5143\u6570\u636e\u3002</p>"},{"location":"APHP/C3.html#33-spatially-correlated-prefetching","title":"3.3 Spatially Correlated Prefetching","text":"<p>\u7a7a\u95f4\u76f8\u5173\u6027\u9884\u53d6\u673a\u5236\u5229\u7528\u6570\u636e\u5e03\u5c40\u4e2d\u7684\u89c4\u5f8b\u6027\u4e0e\u91cd\u590d\u6027\u3002\u65f6\u95f4\u76f8\u5173\u6027\u4f9d\u8d56\u4e8e\u7f3a\u5931\u5e8f\u5217\u7684\u91cd\u590d\u51fa\u73b0\uff08\u4e0e\u5177\u4f53\u7f3a\u5931\u5730\u5740\u65e0\u5173\uff09\uff0c\u800c\u7a7a\u95f4\u76f8\u5173\u6027\u5219\u4f9d\u8d56\u4e8e\u5728\u65f6\u95f4\u4e0a\u76f8\u90bb\u53d1\u751f\u7684\u5185\u5b58\u8bbf\u95ee\u7684\u76f8\u5bf9\u504f\u79fb\u6a21\u5f0f\u3002\u6b65\u957f\u8bbf\u95ee\u6a21\u5f0f\u662f\u7a7a\u95f4\u76f8\u5173\u6027\u7684\u7279\u4f8b\uff1b\u672c\u8282\u8ba8\u8bba\u7684\u9884\u53d6\u5668\u5c06\u6b65\u957f\u9884\u53d6\u63a8\u5e7f\u81f3\u66f4\u590d\u6742\u7684\u5e03\u5c40\u6a21\u5f0f\u3002</p> <p>\u7a7a\u95f4\u76f8\u5173\u6027\u7684\u4ea7\u751f\u6e90\u4e8e\u6570\u636e\u7ed3\u6784\u5e03\u5c40\u7684\u89c4\u5f8b\u6027\uff0c\u56e0\u4e3a\u7a0b\u5e8f\u7ecf\u5e38\u4f7f\u7528\u5185\u5b58\u4e2d\u5177\u6709\u56fa\u5b9a\u5e03\u5c40\u7684\u6570\u636e\u7ed3\u6784\uff08\u4f8b\u5982\u9762\u5411\u5bf9\u8c61\u7f16\u7a0b\u8bed\u8a00\u4e2d\u7684\u5bf9\u8c61\u3001\u5177\u6709\u56fa\u5b9a\u957f\u5ea6\u5b57\u6bb5\u7684\u6570\u636e\u5e93\u8bb0\u5f55\u3001\u6808\u5e27\uff09\u3002\u8bb8\u591a\u9ad8\u7ea7\u7f16\u7a0b\u8bed\u8a00\u4f1a\u5c06\u6570\u636e\u7ed3\u6784\u5bf9\u9f50\u5230\u7f13\u5b58\u884c\u548c\u9875\u8fb9\u754c\uff0c\u8fd9\u8fdb\u4e00\u6b65\u589e\u5f3a\u4e86\u5e03\u5c40\u89c4\u5f8b\u6027\u3002</p> <p>\u7a7a\u95f4\u76f8\u5173\u6027\u7684\u4f18\u52bf\u4e4b\u4e00\u5728\u4e8e\u76f8\u540c\u5e03\u5c40\u6a21\u5f0f\u901a\u5e38\u4f1a\u5728\u5185\u5b58\u4e2d\u7684\u591a\u4e2a\u5bf9\u8c61\u4e0a\u91cd\u590d\u51fa\u73b0\u3002\u56e0\u6b64\uff0c\u4e00\u65e6\u4e60\u5f97\u7a7a\u95f4\u76f8\u5173\u6027\u6a21\u5f0f\uff0c\u4fbf\u53ef\u5c06\u5176\u7528\u4e8e\u9884\u53d6\u591a\u4e2a\u5bf9\u8c61\uff0c\u8fd9\u4f7f\u5f97\u5229\u7528\u7a7a\u95f4\u76f8\u5173\u6027\u7684\u9884\u53d6\u5668\u5177\u6709\u5f88\u9ad8\u7684\u5b58\u50a8\u6548\u7387\uff08\u5373\u7d27\u51d1\u6a21\u5f0f\u53ef\u91cd\u590d\u7528\u4e8e\u9884\u53d6\u5927\u91cf\u5730\u5740\uff09\u3002\u6b64\u5916\uff0c\u4e0e\u4f9d\u8d56\u4e8e\u7279\u5b9a\u5730\u5740\u7f3a\u5931\u91cd\u590d\u7684\u5730\u5740\u76f8\u5173\u6027\u4e0d\u540c\uff0c\u7a7a\u95f4\u6a21\u5f0f\u53ef\u5e94\u7528\u4e8e\u5148\u524d\u4ece\u672a\u88ab\u5f15\u7528\u8fc7\u7684\u5730\u5740\uff0c\u4ece\u800c\u80fd\u6d88\u9664\u51b7\u7f13\u5b58\u7f3a\u5931\u3002</p> <p>\u4e0e\u5730\u5740\u76f8\u5173\u6027\u9884\u53d6\u5668\u7c7b\u4f3c\uff0c\u7a7a\u95f4\u76f8\u5173\u6027\u9884\u53d6\u5668\u5fc5\u987b\u4f9d\u8d56\u89e6\u53d1\u4e8b\u4ef6\u6765\u542f\u52a8\u9884\u53d6\uff0c\u8be5\u4e8b\u4ef6\u901a\u5e38\u662f\u5185\u5b58\u8bbf\u95ee\u6216\u7f13\u5b58\u7f3a\u5931\u3002\u89e6\u53d1\u4e8b\u4ef6\u5fc5\u987b\uff081\uff09\u63d0\u4f9b\u67e5\u627e\u952e\u4ee5\u68c0\u7d22\u63cf\u8ff0\u5f85\u9884\u53d6\u76f8\u5bf9\u4f4d\u7f6e\u7684\u76f8\u5173\u5e03\u5c40\u6a21\u5f0f\uff1b\uff082\uff09\u63d0\u4f9b\u7528\u4e8e\u8ba1\u7b97\u8fd9\u4e9b\u76f8\u5bf9\u5730\u5740\u7684\u57fa\u5730\u5740\u3002\u57fa\u5730\u5740\u901a\u5e38\u6765\u81ea\u89e6\u53d1\u8bbf\u95ee\u7684\u6709\u6548\u5730\u5740\u3002\u7136\u800c\uff0c\u4e3a\u5b9e\u73b0\u5bf9\u672a\u89c1\u8fc7\u5730\u5740\u7684\u9884\u53d6\uff0c\u5e03\u5c40\u6a21\u5f0f\u7684\u67e5\u627e\u952e\u5fc5\u987b\u72ec\u7acb\u4e8e\u57fa\u5730\u5740\uff08\u4f8b\u5982\uff0c\u82e5\u67e5\u627e\u952e\u76f4\u63a5\u662f\u57fa\u5730\u5740\u2014\u2014\u5982GHB G/AC [68]\u4e2d\u7684\u8bbe\u8ba1\u2014\u2014\u5219\u6211\u4eec\u4f1a\u5c06\u8be5\u9884\u53d6\u5668\u5f52\u7c7b\u4e3a\u5730\u5740\u76f8\u5173\u6027\u9884\u53d6\u5668\uff09\u3002</p>"},{"location":"APHP/C3.html#331-delta-correlated-lookup","title":"3.3.1 Delta-Correlated Lookup","text":"<p>\u589e\u91cf\u5173\u8054\u76f4\u63a5\u5efa\u7acb\u5728\u7a7a\u95f4\u76f8\u5173\u6027\uff08spatial correlation\uff09\u7684\u6982\u5ff5\u4e4b\u4e0a\uff0c\u5b83\u5229\u7528\u8bbf\u95ee\u5e03\u5c40\u6a21\u5f0f\uff08layout pattern\uff09\u672c\u8eab\u7684\u91cd\u590d\u6027\u4f5c\u4e3a\u67e5\u627e\u952e\u3002\u5177\u4f53\u800c\u8a00\uff0c\u4e24\u6b21\u6216\u591a\u6b21\u8fde\u7eed\u8bbf\u95ee\u4e4b\u95f4\u7684\u6b65\u957f\uff08\u6216\u6982\u62ec\u6b64\u7c7b\u6b65\u957f\u5e8f\u5217\u7684\u7279\u5f81\u503c\uff09\u88ab\u7528\u4f5c\u5e03\u5c40\u6a21\u5f0f\u7684\u67e5\u627e\u952e\u3002\u589e\u91cf\u5173\u8054\uff08\u65e9\u671f\u6587\u732e\u4e2d\u79f0\u4e3a\u8ddd\u79bb\u9884\u53d6\uff09\u6700\u521d\u662f\u5728TLB\u9884\u53d6\u80cc\u666f\u4e0b\u63d0\u51fa\u7684[73]\u3002</p>"},{"location":"APHP/C3.html#332-global-history-buffer-pc-localizeddelta-correlating-ghb-pcdc","title":"3.3.2 Global History Buffer PC-Localized/Delta-Correlating (GHB PC/DC)","text":"<p>\u4ece\u5b58\u50a8\u6548\u7387\u548c\u8986\u76d6\u8303\u56f4\u6765\u770b\uff0c\u76ee\u524d\u5df2\u77e5\u6700\u9ad8\u6548\u7684\u9884\u53d6\u5668\u4e4b\u4e00\u662f\u5168\u5c40\u5386\u53f2\u7f13\u51b2\u533a\u7684\u7a0b\u5e8f\u8ba1\u6570\u5668\u5c40\u90e8\u5316\u589e\u91cf\u5173\u8054\u53d8\u4f53\uff08GHB PC/DC\uff09[68, 69]\u3002\u5176\u786c\u4ef6\u67b6\u6784\u4e0e3.2.7\u8282\u8ba8\u8bba\u7684GHB G/AC\uff08\u5168\u5c40\u5730\u5740\u5173\u8054\u53d8\u4f53\uff09\u76f8\u540c\uff0c\u5305\u542b\u7d22\u5f15\u8868\u548c\u5386\u53f2\u8868\u3002GHB PC/DC\u7d22\u5f15\u8868\u4e2d\u5b58\u50a8\u7684\u5173\u952e\u5b57\u662f\u7f3a\u5931\u5185\u5b58\u8bbf\u95ee\u6307\u4ee4\u7684\u7a0b\u5e8f\u8ba1\u6570\u5668\u503c\u3002\u540c\u4e00PC\u89e6\u53d1\u7684\u8fde\u7eed\u7f3a\u5931\u8bbf\u95ee\u901a\u8fc7\u5386\u53f2\u7f13\u51b2\u533a\u4e2d\u7684\u94fe\u63a5\u6307\u9488\u76f8\u4e92\u8fde\u63a5\u3002\u5f53\u7ed9\u5b9aPC\u89e6\u53d1\u7f3a\u5931\u65f6\uff0c\u7cfb\u7edf\u901a\u8fc7\u94fe\u63a5\u6307\u9488\u5728\u5386\u53f2\u8868\u4e2d\u8ffd\u6eaf\u8be5PC\u6700\u8fd1\u4e24\u6b21\u7684\u7f3a\u5931\u8bb0\u5f55\uff0c\u901a\u8fc7\u8ba1\u7b97\u89e6\u53d1\u5730\u5740\u4e0e\u4e4b\u524d\u4e24\u6b21\u7f3a\u5931\u5730\u5740\u7684\u5dee\u503c\u5f97\u5230\u4e24\u6b65\u957f\u5e8f\u5217\u3002\u9884\u53d6\u5668\u968f\u540e\u6cbfPC\u94fe\u63a5\u6307\u9488\u5728\u5386\u53f2\u7f13\u51b2\u533a\u4e2d\u53cd\u5411\u641c\u7d22\uff0c\u5bfb\u627e\u76f8\u540c\u4e24\u6b65\u957f\u5e8f\u5217\u7684\u5148\u524d\u51fa\u73b0\u8bb0\u5f55\u3002\u82e5\u53d1\u73b0\u5339\u914d\u6a21\u5f0f\uff0c\u5219\u4ece\u5339\u914d\u4f4d\u7f6e\u5f00\u59cb\uff0c\u5c06\u540e\u7eed\u7684\u589e\u91cf\u5e8f\u5217\u5e94\u7528\u4e8e\u89e6\u53d1\u7f3a\u5931\u7684\u57fa\u5730\u5740\u6765\u751f\u6210\u9884\u53d6\u5730\u5740\u3002\u6574\u4e2a\u641c\u7d22\u8fc7\u7a0b\u901a\u8fc7\u904d\u5386\u7d22\u5f15\u8868\u548c\u5386\u53f2\u8868\u7684\u72b6\u6001\u673a\u5b9e\u73b0\u3002</p> <p></p> <p>\u5c3d\u7ba1GHB PC/DC\u5728\u6709\u9650\u5b58\u50a8\u7a7a\u95f4\uff08256\u9879\u7d22\u5f15\u8868\u548c\u5386\u53f2\u7f13\u51b2\u533a\u8868\uff09\u4e0b\u5bf9SPEC\u57fa\u51c6\u6d4b\u8bd5\u8868\u73b0\u51fa\u663e\u8457\u6548\u679c\uff0c\u4f46\u8fc4\u4eca\u4e3a\u6b62\uff0c\u5176\u5728\u5927\u4ee3\u7801\u91cf\u548c\u5927\u6570\u636e\u8db3\u8ff9\u5de5\u4f5c\u8d1f\u8f7d\uff08\u5982\u5546\u7528\u670d\u52a1\u5668\u6216\u4e91\u8ba1\u7b97\u5e94\u7528\uff09\u4e2d\u7684\u6709\u6548\u6027\u5c1a\u672a\u5f97\u5230\u7814\u7a76\uff0c\u5176\u6269\u5c55\u884c\u4e3a\u4ecd\u5c5e\u672a\u77e5\u3002</p> <p>\u591a\u9879GHB PC/DC\u9884\u53d6\u5668\u7684\u521b\u65b0\u53d8\u4f53\u5728\u7b2c\u4e00\u5c4a\u6570\u636e\u9884\u53d6\u9526\u6807\u8d5b\u4e2d\u5f97\u5230\u8bc4\u4f30\uff0c\u5e76\u4e8e2011\u5e74\u53d1\u8868\u5728\u300a\u6307\u4ee4\u7ea7\u5e76\u884c\u671f\u520a\u300b\u7279\u520a[31, 74, 75, 76, 77, 78]\u3002</p>"},{"location":"APHP/C3.html#333-code-correlated-lookup","title":"3.3.3 Code-Correlated Lookup","text":"<p>PC\u5c40\u90e8\u5316\u6b65\u957f/\u6d41\u9884\u6d4b\u5668\u4e0ePC\u5c40\u90e8\u5316GHB\u7684\u9ad8\u6548\u6027\u8868\u660e\uff0c\u7279\u5b9a\u5185\u5b58\u8bbf\u95ee\u95f4\u7684\u7a7a\u95f4\u5173\u7cfb\u5e38\u4e0e\u5185\u5b58\u8bbf\u95ee\u6307\u4ee4PC\u5f3a\u76f8\u5173\u3002\u4f8b\u5982\uff0c\u77e9\u9635\u4e58\u6cd5\u5185\u5c42\u5faa\u73af\u4e2d\u7684\u7279\u5b9a\u52a0\u8f7d\u6307\u4ee4\u4f1a\u9891\u7e41\u4ee5\u6052\u5b9a\u6b65\u957f\u904d\u5386\u5185\u5b58\u3002\u4ee3\u7801\u5173\u8054\u901a\u8fc7\u89c2\u5bdf\u5230\u590d\u6742\u904d\u5386\u6a21\u5f0f\uff08\u901a\u5e38\u5305\u542b\u591a\u6761\u5185\u5b58\u8bbf\u95ee\u6307\u4ee4\uff09\u540c\u6837\u4e0e\u53d1\u8d77\u6307\u4ee4\u7684PC\u5f3a\u76f8\u5173\uff0c\u4ece\u800c\u63a8\u5e7f\u4e86PC\u5c40\u90e8\u5316\u6d41\u7684\u6982\u5ff5\u3002\u5373\u7279\u5b9a\u6307\u4ee4\u5e8f\u5217\u4f1a\u4ee5\u76f8\u540c\u7684\"\u997c\u5e72\u6a21\u5177\"\u5f0f\u504f\u79fb\u6a21\u5f0f\uff0c\u5728\u5185\u5b58\u4e2d\u591a\u4e2a\u4e0d\u540c\u57fa\u5730\u5740\u5904\u91cd\u590d\u8bbf\u95ee\u5185\u5b58\u3002\u8fd9\u7c7b\u6a21\u5f0f\u7684\u51fa\u73b0\u662f\u56e0\u4e3a\u9762\u5411\u5bf9\u8c61\u7a0b\u5e8f\u4e2d\u7684\u6808\u5e27\u548c\u5bf9\u8c61\u5177\u6709\u56fa\u5b9a\u5e03\u5c40\uff1b\u6267\u884c\u5efa\u7acb\u6808\u5e27\u7684\u4ee3\u7801\u6216\u8c03\u7528\u5bf9\u8c61\u7684\u7279\u5b9a\u65b9\u6cd5\uff0c\u53ef\u53ef\u9760\u9884\u793a\u540e\u7eed\u5bf9\u6808\u5e27/\u5bf9\u8c61\u5185\u90e8\u5b57\u6bb5\u7684\u5185\u5b58\u8bbf\u95ee\u6a21\u5f0f\u3002</p> <p>\u4ee3\u7801\u5173\u8054\u9884\u6d4b\u6700\u65e9\u5728\u9884\u6d4b\u7f13\u5b58\u4e00\u81f4\u6027\u72b6\u6001\u673a\u8f6c\u6362\u7684\u673a\u5236\u80cc\u666f\u4e0b\u88ab\u63a2\u7d22[60, 79, 80]\u3002\u6211\u4eec\u5148\u524d\u57283.2.5\u8282\u5173\u4e8e\u6b7b\u5757\u9884\u6d4b\u7684\u8ba8\u8bba\u4e2d\uff0c\u5df2\u63d0\u53ca\u5982\u4f55\u901a\u8fc7\u5730\u5740\u5173\u8054\u9884\u53d6\u63d0\u5347\u524d\u77bb\u6027\u3002\u4ee3\u7801\u5173\u8054\u7a7a\u95f4\u9884\u53d6\u5668\u5c06\u7a7a\u95f4\u5173\u7cfb\u4e0e\u89e6\u53d1\u4e8b\u4ef6\u7684\u7a0b\u5e8f\u8ba1\u6570\u5668\u503c\u76f8\u5173\u8054\uff08\u800c\u975e\u8bbf\u95ee\u7684\u6570\u636e\u5730\u5740\u6216\u5176\u5dee\u503c\uff09\u3002\u6b64\u7c7b\u9884\u53d6\u673a\u5236\u7684\u6574\u4f53\u67b6\u6784\u5982\u56fe3.6\u6240\u793a\uff08\u6539\u7f16\u81ea[82]\uff09\u3002\u9884\u53d6\u7684\u89e6\u53d1\u4e8b\u4ef6\u662f\u5bf9\u7279\u5b9a\uff08\u901a\u5e38\u4e3a\u56fa\u5b9a\u5927\u5c0f\uff09\u5185\u5b58\u533a\u57df\u7684\u9996\u6b21\u8bbf\u95ee\u6216\u7f13\u5b58\u7f3a\u5931\u3002\u4e0d\u540c\u9884\u53d6\u5668\u8bbe\u8ba1\u4e2d\u7684\u533a\u57df\u5927\u5c0f\u5404\u5f02\uff0c\u5c0f\u81f3256\u5b57\u8282[81]\uff0c\u5927\u81f38KB[82]\u3002</p> <p></p> <p>\u5f53\u89e6\u53d1\u4e8b\u4ef6\uff08\u5982L1\u7f13\u5b58\u7f3a\u5931\uff09\u53d1\u751f\u65f6\uff0c\u9884\u53d6\u5668\u4f1a\u6839\u636e\u89e6\u53d1\u4e8b\u4ef6\u6784\u5efa\u67e5\u627e\u952e\uff0c\u5e76\u5728\u6a21\u5f0f\u5386\u53f2\u8868\u4e2d\u68c0\u7d22\u8be5\u952e\u3002\u8be5\u8868\u5c06\u952e\u4e0e\u7a7a\u95f4\u6a21\u5f0f\uff08\u5373\u5f85\u9884\u53d6\u6570\u636e\u7684\u76f8\u5bf9\u504f\u79fb\u91cf\u8868\u793a\uff09\u76f8\u5173\u8054\u3002\u5177\u4f53\u9884\u53d6\u5668\u8bbe\u8ba1\u5728\u89e6\u53d1\u4e8b\u4ef6\u3001\u67e5\u627e\u952e\u3001\u7a7a\u95f4\u6a21\u5f0f\u7f16\u7801\u3001\u6a21\u5f0f\u5386\u53f2\u8868\u7ec4\u7ec7\u53ca\u8bad\u7ec3\u673a\u5236\u7b49\u65b9\u9762\u5b58\u5728\u5dee\u5f02\u3002</p> <p>\u67e5\u627e\u952e\u901a\u5e38\u5305\u542b\u89e6\u53d1\u8bbf\u95ee\u7684\u7a0b\u5e8f\u8ba1\u6570\u5668\u90e8\u5206\u6216\u5168\u90e8\u4f4d\u3002\u591a\u9879\u7814\u7a76[81,82,83]\u8868\u660e\uff0c\u989d\u5916\u52a0\u5165\u6570\u636e\u5730\u5740\u7684\u4f4e\u4f4d\uff08\u7279\u522b\u662f\u533a\u57df\u5185\u7684\u504f\u79fb\u91cf\uff09\u53ef\u63d0\u5347\u9884\u53d6\u7cbe\u5ea6\u3002\u8fd9\u4e9b\u4f4e\u4f4d\u6570\u636e\u5730\u5740\u4f4d\u7528\u4e8e\u533a\u5206\u533a\u57df\u8fb9\u754c\u5bf9\u9f50\u65b9\u5f0f\u4e0d\u540c\u4f46\u5e03\u5c40\u76f8\u4f3c\u7684\u5bf9\u8c61\u8bbf\u95ee\u2014\u2014\u9884\u6d4b\u5668\u8868\u4e2d\u4f1a\u4e3a\u6bcf\u79cd\u53ef\u80fd\u7684\u5bf9\u9f50\u65b9\u5f0f\u521b\u5efa\u72ec\u7acb\u8868\u9879\u3002\u53e6\u4e00\u79cd\u65b9\u6848\u7531Ferdman\u7b49\u4eba\u63d0\u51fa[84,85]\uff1a\u4ec5\u4ee5\u7a0b\u5e8f\u8ba1\u6570\u5668\u4f5c\u4e3a\u67e5\u627e\u952e\u5b58\u50a8\u5355\u4e00\u6a21\u5f0f\uff0c\u8f6c\u800c\u4f7f\u7528\u4f4e\u4f4d\u4f4d\u5bf9\u6a21\u5f0f\u8fdb\u884c\u65cb\u8f6c\u4ee5\u5b9e\u73b0\u5bf9\u9f50\u3002</p> <p>\u7a7a\u95f4\u6a21\u5f0f\u6700\u7b80\u8868\u793a\u4e3a\u4f4d\u5411\u91cf\uff0c\u7528\u4e8e\u6807\u8bc6\u533a\u57df\u4e2d\u5e94\u9884\u53d6\u7684\u90e8\u5206\uff08\u5982\u7f13\u5b58\u884c\uff09\u3002\u8be5\u4f4d\u5411\u91cf\u4e0e\u533a\u57df\u57fa\u5730\u5740\uff08\u53d6\u81ea\u89e6\u53d1\u4e8b\u4ef6\u8bf7\u6c42\u7684\u6570\u636e\u5730\u5740\uff09\u7ed3\u5408\uff0c\u5373\u53ef\u751f\u6210\u5f85\u9884\u53d6\u7684\u5730\u5740\u5217\u8868\u3002</p> <p>\u4ee5\u4e0b\u5c0f\u8282\u7b80\u8981\u603b\u7ed3\u4e86\u7279\u5b9a\u4ee3\u7801\u5173\u8054\u9884\u53d6\u5668\u8bbe\u8ba1\u7684\u5173\u952e\u8981\u70b9\u3002</p>"},{"location":"APHP/C3.html#334-spatial-footprint-prediction-sfp","title":"3.3.4 Spatial Footprint Prediction (SFP)","text":"<p>\u6700\u65e9\u4e14\u6700\u7b80\u5355\u7684\u4ee3\u7801\u5173\u8054\u7a7a\u95f4\u9884\u53d6\u5668\u662fKumar\u4e0eWilkerson\u63d0\u51fa\u7684\u7a7a\u95f4\u8db3\u8ff9\u9884\u6d4b\u5668[81]\u3002\u4ed6\u4eec\u5728\u89e3\u8026\u6247\u533a\u7f13\u5b58[86]\u7684\u80cc\u666f\u4e0b\u63a2\u7d22\u4e86L1\u6570\u636e\u7f13\u5b58\u8bbf\u95ee\u7684\u91cd\u590d\u5e03\u5c40\u6a21\u5f0f\u2014\u2014\u8fd9\u79cd\u6807\u7b7e\u7ec4\u7ec7\u7ed3\u6784\u901a\u8fc7\u6253\u7834\u6807\u7b7e\u4e0e\u6570\u636e\u7684\u4e00\u5bf9\u4e00\u5173\u8054\uff0c\u5b9e\u73b0\u4e86\u5c0f\u884c\u5927\u5c0f\u4e0e\u4f4e\u5f00\u9500\u7684\u5e73\u8861\u3002\u89e3\u8026\u6247\u533a\u7f13\u5b58\u662f\u6247\u533a\u7f13\u5b58\uff08\u53c8\u79f0\u5b50\u5757\u7f13\u5b58\uff09\u7684\u4e00\u79cd\u5b58\u50a8\u9ad8\u6548\u5b9e\u73b0\uff0c\u5141\u8bb8\u591a\u4e2a\u5728\u5185\u5b58\u4e2d\u76f8\u90bb\u7684\u5927\u6570\u636e\u9635\u5217\u6761\u76ee\u5171\u4eab\u5c0f\u6807\u7b7e\u9635\u5217\u4e2d\u7684\u6807\u7b7e\u3002\u5355\u4e2a\u6807\u7b7e\u8986\u76d6\u7684\u5185\u5b58\u5757\u79f0\u4e3a\u6247\u533a\uff0c\u800c\u6570\u636e\u9635\u5217\u5b58\u50a8\u8be5\u6247\u533a\u5185\u66f4\u5c0f\u7684\u884c\uff0c\u6bcf\u884c\u62e5\u6709\u72ec\u7acb\u7684\u6709\u6548\u4f4d\u3002\u56e0\u6b64\u5728\u8be5\u67b6\u6784\u4e2d\uff0c\u6807\u7b7e\u9635\u5217\u4e0e\u6570\u636e\u9635\u5217\u7684\u5757\u5927\u5c0f\u4e0d\u540c\uff0c\u5206\u522b\u5bf9\u5e94\u6247\u533a\u5927\u5c0f\u4e0e\u884c\u5927\u5c0f\u3002</p> <p>SFP\u7684\u76ee\u6807\u662f\u8ba9\u89e3\u8026\u6247\u533a\u7f13\u5b58\u65e2\u80fd\u50cf\u4f20\u7edf\u5927\u5757\u7f13\u5b58\u90a3\u6837\u5229\u7528\u7a7a\u95f4\u5c40\u90e8\u6027\uff0c\u53c8\u80fd\u901a\u8fc7\u9884\u53d6\u989d\u5916\u884c\u5728\u5206\u914d\u65b0\u6247\u533a\u65f6\u83b7\u5f97\u5c0f\u5757\u7f13\u5b58\u7684\u5b58\u50a8\u4e0e\u5e26\u5bbd\u4f18\u52bf\u3002\u4f5c\u8005\u7814\u7a76\u4e86\u4e00\u4e2a\u91c7\u752816KB L1\u6570\u636e\u7f13\u5b58\u7684\u7cfb\u7edf\uff0c\u8be5\u7f13\u5b58\u4e3a\u89e3\u8026\u6247\u533a\u67b6\u6784\uff0c\u5177\u6709128\u5b57\u8282\u6247\u533a\u4f46\u4ec58\u5b57\u8282\u884c\u5927\u5c0f\uff0c\u6570\u636e\u9635\u5217\u53ef\u5b58\u50a82048\u4e2a\u6761\u76ee\u4f46\u6807\u7b7e\u4ec5512\u4e2a\u3002</p> <p>\u5982\u56fe3.6\u6240\u793a\u901a\u7528\u67b6\u6784\uff0c\u6027\u80fd\u6700\u4f73\u7684SFP\u53d8\u4f53\u5c06\u5176\u9884\u6d4b\u5b58\u50a8\u4e8e\u7ec4\u76f8\u8054\u6a21\u5f0f\u5386\u53f2\u8868\u4e2d\uff0c\u8be5\u8868\u901a\u8fc7PC\u53ca\u6247\u533a\u5185\u884c\u53f7\u8fdb\u884c\u7d22\u5f15\u548c\u6807\u8bb0\u3002\u6a21\u5f0f\u5386\u53f2\u8868\u7684\u8bad\u7ec3\u65b9\u5f0f\u662f\u5728\u6bcf\u4e2a\u6247\u533a\u6807\u7b7e\u6761\u76ee\u4e2d\u6269\u5c55\u5b58\u50a8\u7a7a\u95f4\uff0c\u8bb0\u5f55\u5f15\u53d1\u6247\u533a\u5206\u914d\u7f3a\u5931\u7684PC\u503c\u3002\u5f53\u6247\u533a\u88ab\u66ff\u6362\u65f6\uff0c\u8be5PC\u503c\u4e0e\u6247\u533a\u5185\u884c\u7684\u6709\u6548\u4f4d\u5411\u91cf\u5c06\u88ab\u5b58\u5165\u6a21\u5f0f\u5386\u53f2\u8868\u3002</p>"},{"location":"APHP/C3.html#335-spatial-pattern-prediction","title":"3.3.5 Spatial Pattern Prediction","text":"<p>Chen\u4e0e\u5408\u4f5c\u8005\u63d0\u51fa\u4e86\u7a7a\u95f4\u6a21\u5f0f\u9884\u6d4b\u5668[83]\uff0c\u5e76\u8bc1\u660e\u5176\u53ef\u5728\u4f20\u7edf\u7ec4\u76f8\u8054\u7f13\u5b58\u4e2d\u9884\u53d664B\u7f13\u5b58\u5757\uff0c\u8986\u76d6\u6700\u59271KB\u7684\u5185\u5b58\u533a\u57df\u3002\u8be5\u7814\u7a76\u7684\u4e00\u4e2a\u60ca\u4eba\u53d1\u73b0\u662f\u7a7a\u95f4\u6a21\u5f0f\u9884\u6d4b\u53ef\u901a\u8fc7\u6781\u5c0f\u7684\u5b58\u50a8\u5b9e\u73b0\uff1a\u4e00\u4e2a256\u9879\u65e0\u6807\u7b7e\u9884\u6d4b\u5668\uff08\u603b\u5b58\u50a8\u91cf\u8fdc\u5c0f\u4e8e1KB\uff09\u80fd\u4e3aSPEC\u5e94\u7528\u63d0\u4f9b95%\u7684\u8986\u76d6\u7387\uff0c\u4e14\u9519\u8bef\u9884\u53d6\u7387\u4f4e\u4e8e20%\u3002\u7814\u7a76\u8fdb\u4e00\u6b65\u5c55\u793a\u4e86\u5982\u4f55\u5c06\u7a7a\u95f4\u6a21\u5f0f\u9884\u6d4b\u4e0e\u7535\u8def\u6280\u672f[87]\u7ed3\u5408\uff0c\u4ee5\u964d\u4f4e\u7f13\u5b58\u884c\u4e2d\u53ef\u80fd\u4e0d\u4f1a\u88ab\u8bbf\u95ee\u90e8\u5206\u7684\u6f0f\u7535\u80fd\u8017\u3002</p>"},{"location":"APHP/C3.html#336-stealth-prefetching","title":"3.3.6 Stealth Prefetching","text":"<p>Cantin\u4e0e\u5408\u8457\u8005\u63d0\u51fa\u4e86\u4e00\u79cd\u9762\u5411\u57fa\u4e8e\u5e7f\u64ad\u4fa6\u542c\u603b\u7ebf\u7684\u591a\u5904\u7406\u5668\u7684\u7a7a\u95f4\u9884\u53d6\u6280\u672f\u2014\u2014\u9690\u5f0f\u9884\u53d6[88]\u3002\u8be5\u6280\u672f\u65e8\u5728\u8bbe\u8ba1\u4e00\u79cd\u80fd\u89c4\u907f\u6fc0\u8fdb\u9884\u53d6\u5171\u4eab\u5185\u5b58\u5757\u5bf9\u7f13\u5b58\u4e00\u81f4\u6027\u4ea7\u751f\u8d1f\u9762\u5f71\u54cd\u7684\u9884\u53d6\u5668\u3002\u5176\u6838\u5fc3\u5728\u4e8e\u5bf9\u5171\u4eab\u4e0e\u79c1\u6709\u5185\u5b58\u533a\u57df\u8fdb\u884c\u7c97\u7c92\u5ea6\u7a7a\u95f4\u8ffd\u8e2a\uff0c\u5c06\u79c1\u6709\u533a\u57df\u6570\u636e\u9884\u53d6\u81f3\u4e13\u7528\u5b58\u50a8\u533a\uff0c\u540c\u65f6\u8df3\u8fc7\u7f13\u5b58\u4e00\u81f4\u6027\u52a0\u8f7d\u4e2d\u7684\u9ad8\u6210\u672c\u64cd\u4f5c\uff1b\u9884\u53d6\u5757\u7684\u4e00\u81f4\u6027\u7531\u5e95\u5c42\u533a\u57df\u8ffd\u8e2a\u6280\u672f\u63d0\u4f9b\u5b89\u5168\u4fdd\u969c\u3002\u9690\u5f0f\u9884\u53d6\u7684\u5173\u952e\u4f18\u52bf\u5728\u4e8e\u9884\u53d6\u64cd\u4f5c\u4e0d\u4f1a\u5f15\u53d1\u5176\u4ed6\u7f13\u5b58\u7684\u7834\u574f\u6027\u4fa6\u542c\u64cd\u4f5c\u3002</p>"},{"location":"APHP/C3.html#337-spatial-memory-streaming","title":"3.3.7 Spatial Memory Streaming","text":"<p>SFP\u4e0eSPP\u4ec5\u9488\u5bf9L1\u7f13\u5b58\u7f3a\u5931\u6d41\u4e14\u4e3b\u8981\u4eceL2\u83b7\u53d6\u6570\u636e\uff0c\u800cSomogyi\u56e2\u961f\u7814\u7a76\u8868\u660e\u4ee3\u7801\u5173\u8054\u7a7a\u95f4\u9884\u53d6\u5bf9\u7247\u5916\u7f3a\u5931\u540c\u6837\u6709\u6548[82]\u3002\u8be5\u7814\u7a76\u9996\u6b21\u5728\u5546\u7528\u670d\u52a1\u5668\u5e94\u7528\u4e2d\u9a8c\u8bc1\u4e86\u7a7a\u95f4\u5173\u8054\u9884\u53d6\u7684\u6709\u6548\u6027\u3002</p> <p>SMS\u8bbe\u8ba1\u91c7\u75288KB\u533a\u57df\u5c3a\u5bf8\uff0c\u5e76\u901a\u8fc7\u5173\u952e\u4f18\u5316\u5b9e\u73b0\u6a21\u5f0f\u5386\u53f2\u8868\u7684\u9ad8\u6548\u5b58\u50a8\u8bad\u7ec3\u3002\u7531\u4e8eSMS\u9700\u8ffd\u8e2a\u7684\u5b58\u50a8\u8db3\u8ff9\uff08\u5168\u7247\u4e0a\u7f13\u5b58\uff09\u8fdc\u5927\u4e8eSFP\u4e0eSPP\uff08\u4ec5L1\u7f13\u5b58\uff09\uff0c\u8fd9\u4e00\u9644\u52a0\u7ed3\u6784\u4e0d\u53ef\u6216\u7f3a\u3002\u6b64\u5916\uff0cSPP\u4e0eSFP\u4ec5\u5bf9\u76f8\u90bb\u7f13\u5b58\u5e27\u7ec4\u8ffd\u8e2a\u5355\u4e00\u7a7a\u95f4\u6a21\u5f0f\uff0c\u800cL2\u7f13\u5b58\u7684\u9ad8\u5173\u8054\u6027\u8981\u6c42SMS\u80fd\u540c\u65f6\u8ffd\u8e2a\u7f13\u5b58\u4e2d\u5e76\u5b58\u7684\u591a\u4e2a\u7a7a\u95f4\u533a\u57df\u3002\u4e3a\u6b64\uff0cSMS\u63d0\u51fa\u7a7a\u95f4\u533a\u57df\u4ee3\u9645\u6982\u5ff5\uff1a\u59cb\u4e8e\u5bf9\u533a\u57df\u5185\u67d0\u5757\u7684\u9996\u6b21\u7f3a\u5931\u8bbf\u95ee\uff0c\u6b62\u4e8e\u8be5\u533a\u57df\u4efb\u610f\u5757\u88ab\u7f6e\u6362\u6216\u5931\u6548\u3002SMS\u8bad\u7ec3\u673a\u5236\u5728\u6574\u4e2a\u4ee3\u9645\u5468\u671f\u5185\u8ffd\u8e2a\u7a7a\u95f4\u6a21\u5f0f\uff0c\u6a21\u5f0f\u6570\u636e\u7d2f\u79ef\u4e8e\u56fe3.7\u6240\u793a\u7684\u6d3b\u8dc3\u4ee3\u9645\u8868\u4e2d\u3002\u8be5\u8868\u7684\u6838\u5fc3\u4f18\u5316\u662f\u901a\u8fc7\u8fc7\u6ee4\u8868\u964d\u4f4e\u5b58\u50a8\u9700\u6c42\u2014\u2014\u5f53\u7f3a\u5931\u89e6\u53d1\u65b0\u7a7a\u95f4\u533a\u57df\u4ee3\u9645\u65f6\uff0c\u5bf9\u5e94\u6807\u7b7e\u4e0e\u89e6\u53d1PC/\u504f\u79fb\u91cf\u5148\u5b58\u5165\u91c7\u7528LRU\u66ff\u6362\u7684\u8fc7\u6ee4\u8868\uff0c\u4ec5\u5f53\u8be5\u533a\u57df\u53d1\u751f\u7b2c\u4e8c\u6b21\u7f3a\u5931\u65f6\uff0c\u8868\u9879\u624d\u8f6c\u5165\u7d2f\u79ef\u8868\u6301\u7eed\u8ffd\u8e2a\u81f3\u4efb\u610f\u5757\u88ab\u7f6e\u6362\uff0c\u6700\u7ec8\u5c06\u7a7a\u95f4\u6a21\u5f0f\u8bb0\u5f55\u81f3\u6240\u6709\u4ee3\u7801\u5173\u8054\u9884\u53d6\u5668\u5171\u7528\u7684\u6a21\u5f0f\u5386\u53f2\u8868\u3002\u8fc7\u6ee4\u8868\u7684\u8fd0\u7528\u81f3\u5173\u91cd\u8981\uff0c\u56e0\u591a\u6570\u7a7a\u95f4\u533a\u57df\u4ee3\u9645\u4ec5\u4e3a\u4ec5\u542b\u89e6\u53d1\u7f3a\u5931\u7684\u5355\u6b21\u7f3a\u5931\uff0c\u8be5\u8bbe\u8ba1\u6709\u6548\u7f13\u89e3\u4e86\u8fd9\u4e9b\u65e0\u6548\u8868\u9879\u5bf9\u7d2f\u79ef\u8868\u9020\u6210\u7684\u5b58\u50a8\u538b\u529b\u3002</p> <p>\u867d\u7136\u6d3b\u52a8\u751f\u6210\u8868\u80fd\u6709\u6548\u964d\u4f4e\u8bad\u7ec3SMS\u9884\u53d6\u5668\u7684\u5b58\u50a8\u9700\u6c42\uff0c\u4f46\u4e3a\u5b9e\u73b0\u6700\u4f73\u6548\u679c\uff0c\u6240\u9700\u7684\u6a21\u5f0f\u5386\u53f2\u8868\u5c3a\u5bf8\u4ecd\u7136\u5f88\u5927\uff0c\u7ea6\u4e3a64KB\u3002\u4e3a\u6b64\uff0cBurcea\u53ca\u5176\u5408\u4f5c\u8005\u5728\u540e\u7eed\u7814\u7a76\u4e2d\u63d0\u51fa\u4e86\u865a\u62df\u5316\u6a21\u5f0f\u5386\u53f2\u8868\u7684\u65b9\u6848\u3002\u8be5\u865a\u62df\u5316\u65b9\u6cd5\u4e0d\u518d\u4f7f\u7528\u5927\u578b\u4e13\u7528\u8868\uff0c\u800c\u662f\u5c06\u9884\u53d6\u5668\u5143\u6570\u636e\u5b58\u50a8\u5728\u672b\u7ea7\u7f13\u5b58\u4e2d\uff0c\u5e76\u901a\u8fc7\u5c0f\u578b\u4e13\u7528\u5143\u6570\u636e\u7f13\u5b58\u6765\u52a0\u901f\u8bbf\u95ee[89]\u3002</p> <p></p>"},{"location":"APHP/C3.html#338-spatio-temporal-memory-streaming","title":"3.3.8 Spatio-Temporal Memory Streaming","text":"<p>\u5c3d\u7ba1\u7a7a\u95f4\u9884\u53d6\u5668\u5bf9\u76ee\u6807\u5185\u5b58\u8bbf\u95ee\u6a21\u5f0f\u6709\u6548\uff0c\u4f46\u5bf9\u4e8e\u5177\u6709\u4efb\u610f\u5185\u5b58\u5e03\u5c40\u7684\u57fa\u4e8e\u6307\u9488\u7684\u6570\u636e\u7ed3\u6784\u901a\u5e38\u6548\u679c\u4e0d\u4f73\uff0c\u4e14\u5728\u8bf8\u5982\u5728\u7ebf\u4e8b\u52a1\u5904\u7406\u7b49\u5305\u542b\u5927\u91cf\u6307\u9488\u8ffd\u9010\u8bbf\u95ee\u6a21\u5f0f\u7684\u5de5\u4f5c\u8d1f\u8f7d\u4e2d\u8868\u73b0\u6709\u9650[90]\u3002\u53cd\u4e4b\uff0c\u5f53\u6570\u636e\u7ed3\u6784\u904d\u5386\u4e0d\u9891\u7e41\u91cd\u590d\u65f6\uff0c\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u4e5f\u4f1a\u5931\u6548\u3002\u4f8b\u5982\uff0c\u5185\u5b58\u590d\u5236\u548c\u626b\u63cf\u8bbf\u95ee\u6a21\u5f0f\u5bb9\u6613\u88ab\u6b65\u957f\u548c\u7a7a\u95f4\u9884\u53d6\u5668\u8bc6\u522b\uff0c\u4f46\u8fd9\u4e9b\u626b\u63cf\u53ef\u80fd\u91cd\u590d\u9891\u7387\u8fc7\u4f4e\uff0c\u5bfc\u81f4\u5730\u5740\u5173\u8054\u9884\u53d6\u5668\u65e0\u6cd5\u6355\u83b7[55]\u3002\u56e0\u6b64\u6700\u65b0\u9884\u53d6\u5668\u65b9\u6848\u81f4\u529b\u4e8e\u5c06\u5730\u5740\u5173\u8054\u9884\u53d6\u4e0e\u7a7a\u95f4\u9884\u53d6\u6574\u5408\u5230\u7edf\u4e00\u8bbe\u8ba1\u4e2d\u3002</p> <p>\u65f6\u7a7a\u5185\u5b58\u6d41[91]\u878d\u5408\u4e86TMS\uff08\u89c1\u7b2c3.2.9\u8282\uff09\u548cSMS\uff08\u89c1\u7b2c3.3.7\u8282\uff09\u3002\u82e5\u76f4\u63a5\u6574\u5408\u8fd9\u4e24\u79cd\u673a\u5236\uff0c\u53ef\u80fd\u4f7f\u7528TMS\u63d0\u4f9b\u9884\u6d4b\u7684\u672a\u6765\u89e6\u53d1\u8bbf\u95ee\u6d41\uff08\u57fa\u5730\u5740\u4e0e\u7a0b\u5e8f\u8ba1\u6570\u5668\uff09\uff0c\u518d\u5c06\u5176\u8f93\u5165SMS\u4ee5\u9884\u6d4b\u5404\u533a\u57df\u5185\u7684\u5269\u4f59\u9884\u53d6\u5730\u5740\u3002\u867d\u7136\u8fd9\u79cd\u7b80\u5355\u65b9\u6cd5\u80fd\u6709\u6548\u9884\u6d4b\u672a\u6765\u8bbf\u95ee\uff0c\u4f46\u7531\u4e8e\u4e27\u5931\u4e86\u4e2a\u4f53\u673a\u5236\u7684\u81ea\u7136\u6392\u5e8f\u4e0e\u8282\u6d41\u529f\u80fd\uff0c\u4f1a\u5bfc\u81f4\u9884\u53d6\u8bf7\u6c42\u7206\u53d1\u5f0f\u589e\u957f\uff0c\u4f7f\u5185\u5b58\u7cfb\u7edf\u4e0d\u582a\u91cd\u8d1f\u3002</p> <p>\u4e3a\u89e3\u51b3\u8fd9\u4e00\u7f3a\u9677\uff0c\u65f6\u7a7a\u5185\u5b58\u6d41\u8f6c\u800c\u81f4\u529b\u4e8e\u5206\u522b\u4ece\u7a7a\u95f4\u673a\u5236\u548c\u65f6\u95f4\u673a\u5236\u72ec\u7acb\u9884\u6d4b\u7684\u5730\u5740\u4e2d\u91cd\u6784\u9884\u53d6\u8bf7\u6c42\u7684\u5b8c\u6574\u5e8f\u5217\u3002\u901a\u8fc7\u7f16\u7801\u7ef4\u62a4\u7f3a\u5931\u987a\u5e8f\u4fe1\u606f\uff0cSMS\u5f97\u5230\u589e\u5f3a\u4ee5\u5c06\u7a7a\u95f4\u6a21\u5f0f\u8868\u793a\u4e3a\u6709\u5e8f\u7684\u504f\u79fb\u6d41\u3002\u867d\u7136\u76f8\u6bd4SFP\u3001SPP\u548c\u4f20\u7edfSMS\u4f7f\u7528\u7684\u4f4d\u5411\u91cf\u4e0d\u591f\u7d27\u51d1\uff0c\u4f46\u504f\u79fb\u6d41\u4fdd\u7559\u4e86\u6b63\u786e\u4ea4\u7ec7\u65f6\u7a7a\u6d41\u6240\u9700\u7684\u987a\u5e8f\u4fe1\u606f\u3002\u4e0e\u57fa\u7840\u96c6\u6210\u65b9\u6848\u7c7b\u4f3c\uff0cTMS\u673a\u5236\u4e3aSMS\u67e5\u627e\u63d0\u4f9b\u89e6\u53d1\u5e8f\u5217\u2014\u2014\u57fa\u5730\u5740\u4e0ePC\u914d\u5bf9\u3002\u4f46\u65f6\u7a7a\u6d41\u4e2d\u7684\u6761\u76ee\u90fd\u989d\u5916\u589e\u52a0\u4e86\u5dee\u503c\u6807\u8bb0\uff0c\u7528\u4e8e\u6307\u793a\u5728\u7279\u5b9a\u7a7a\u95f4\u6d41\u6216\u65f6\u95f4\u6d41\u4e2d\u4e24\u4e2a\u8fde\u7eed\u5730\u5740\u4e4b\u95f4\u4ea4\u7ec7\u7684\u5176\u4ed6\u9884\u53d6\u5730\u5740\u6570\u91cf\u3002\u9884\u53d6\u8fc7\u7a0b\u4e2d\uff0c\u8fd9\u4e9b\u5dee\u503c\u901a\u8fc7\u5c06\u65f6\u95f4\u6d41\u7684\u9884\u53d6\u5730\u5740\u586b\u5165\u91cd\u6784\u7f13\u51b2\u533a\u6765\u91cd\u5efa\u5b8c\u6574\u7f3a\u5931\u987a\u5e8f\uff0c\u540c\u65f6\u7559\u51fa\u7a7a\u4f4d\u4f9b\u540e\u7eed\u7a7a\u95f4\u6d41\u5730\u5740\u586b\u5145\u3002\u91cd\u6784\u673a\u5236\u8be6\u89c1[91]\u3002</p>"},{"location":"APHP/C3.html#34-execution-based-prefetching","title":"3.4 Execution-Based Prefetching","text":"<p>\u6700\u540e\u8fd9\u7c7b\u6570\u636e\u9884\u53d6\u5668\u65e2\u4e0d\u4f9d\u8d56\u7f3a\u5931\u5e8f\u5217\u7684\u91cd\u590d\u6027\uff0c\u4e5f\u4e0d\u4f9d\u8d56\u6570\u636e\u5e03\u5c40\uff1b\u800c\u662f\u901a\u8fc7\u8d85\u524d\u4e8e\u6307\u4ee4\u6267\u884c\u4e0e\u63d0\u4ea4\u7684\u7a0b\u5e8f\u6307\u4ee4\u5e8f\u5217\u63a2\u7d22\u5730\u5740\u8ba1\u7b97\u4e0e\u6307\u9488\u89e3\u5f15\u7528\u3002\u6b64\u7c7b\u9884\u53d6\u5668\u7684\u6838\u5fc3\u76ee\u6807\u662f\u8fd0\u884c\u901f\u5ea6\u8d85\u8d8a\u6307\u4ee4\u6267\u884c\u672c\u8eab\uff0c\u62a2\u5148\u4e8e\u5904\u7406\u5668\u6838\u5fc3\uff0c\u540c\u65f6\u4ecd\u4f7f\u7528\u5b9e\u9645\u5730\u5740\u8ba1\u7b97\u7b97\u6cd5\u8bc6\u522b\u9884\u53d6\u76ee\u6807\u3002\u56e0\u6b64\u8fd9\u4e9b\u673a\u5236\u5b8c\u5168\u4e0d\u4f9d\u8d56\u91cd\u590d\u6027\uff0c\u8f6c\u800c\u91c7\u7528\u4ee5\u4e0b\u65b9\u5f0f\uff1a\u5728\u5ffd\u7565\u8ba1\u7b97\u5176\u4ed6\u65b9\u9762\u7684\u524d\u63d0\u4e0b\u6982\u62ec\u5730\u5740\u8ba1\u7b97\u3001\u76f4\u63a5\u731c\u6d4b\u6570\u503c\uff0c\u6216\u5229\u7528\u505c\u6ede\u5468\u671f\u4e0e\u7a7a\u95f2\u5904\u7406\u5668\u8d44\u6e90\u8fdb\u884c\u6307\u4ee4\u63d0\u4ea4\u524d\u7684\u63a2\u7d22\u3002</p>"},{"location":"APHP/C3.html#341-algorithm-summarization","title":"3.4.1 Algorithm Summarization","text":"<p>\u591a\u79cd\u9884\u53d6\u6280\u672f\u901a\u8fc7\u6982\u62ec\u904d\u5386\u6570\u636e\u7ed3\u6784\u7684\u6307\u4ee4\u5e8f\u5217\uff0c\u4f7f\u904d\u5386\u6a21\u5f0f\u80fd\u4ee5\u5feb\u4e8e\u4e3b\u7ebf\u7a0b\u7684\u901f\u5ea6\u6267\u884c\u4ece\u800c\u5b9e\u73b0\u6570\u636e\u7ed3\u6784\u7684\u9884\u53d6\u3002Roth\u4e0e\u5408\u4f5c\u8005[44,45]\u63d0\u51fa\u5b8c\u5168\u5728\u786c\u4ef6\u4e2d\u6982\u62ec\u904d\u5386\u7684\u673a\u5236\uff0c\u901a\u8fc7\u8bc6\u522b\u6307\u9488\u52a0\u8f7d\uff08\u89e3\u5f15\u7528\u6307\u9488\u7684\u52a0\u8f7d\u6307\u4ee4\uff09\u53ca\u8fde\u63a5\u5b83\u4eec\u7684\u4f9d\u8d56\u6307\u4ee4\u94fe\u3002\u8fd9\u4e9b\u4f9d\u8d56\u5173\u7cfb\u968f\u540e\u88ab\u786c\u4ef6\u7f16\u7801\u4e3a\u7d27\u51d1\u72b6\u6001\u673a\uff0c\u80fd\u4ee5\u8d85\u8d8a\u6307\u4ee4\u6267\u884c\u7684\u901f\u5ea6\u8fed\u4ee3\u4f9d\u8d56\u52a0\u8f7d\u5e8f\u5217\u3002Annavaram\u3001Patel\u548cDavidson\u63d0\u51fa\u901a\u7528\u673a\u5236\uff0c\u53ef\u5728\u786c\u4ef6\u4e2d\u63d0\u53d6\u7a0b\u5e8f\u4f9d\u8d56\u56fe\uff08\u5bfc\u81f4\u7f3a\u5931\u52a0\u8f7d\u7684\u6307\u4ee4\u5b50\u96c6\uff09\uff0c\u5e76\u5728\u4e13\u7528\u9884\u8ba1\u7b97\u5f15\u64ce\u4e2d\u6267\u884c\u8fd9\u4e9b\u4f9d\u8d56\u56fe[92]\u3002</p>"},{"location":"APHP/C3.html#342-helper-thread-and-helper-core-approaches","title":"3.4.2 Helper-Thread And Helper-Core Approaches","text":"<p>\u57fa\u4e8e\u7ebf\u7a0b\u7684\u6570\u636e\u9884\u53d6\u6280\u672f[93-101]\u5229\u7528\u591a\u7ebf\u7a0b/\u591a\u6838\u5904\u7406\u5668\u7684\u7a7a\u95f2\u4e0a\u4e0b\u6587\u8fd0\u884c\u8f85\u52a9\u7ebf\u7a0b\uff0c\u901a\u8fc7\u63a8\u6d4b\u6267\u884c\u5c06\u7f3a\u5931\u5904\u7406\u4e0e\u6267\u884c\u89e3\u8026\u3002\u5404\u9879\u6280\u672f\u56e0\u4ee5\u4e0b\u65b9\u9762\u800c\u5f02\uff1a\u662f\u81ea\u52a8\u6267\u884c\u8fd8\u662f\u9700\u8981\u7f16\u8bd1\u5668/\u8f6f\u4ef6\u652f\u6301\u3001\u662f\u5426\u4f9d\u8d56\u540c\u6b65\u591a\u7ebf\u7a0b\u786c\u4ef6\u4e0e\u7279\u5b9a\u7ebf\u7a0b\u534f\u8c03\u673a\u5236\u3001\u662f\u5426\u4f9d\u8d56\u989d\u5916\u6838\u5fc3\u3001\u4ee5\u53ca\u662f\u5426\u9700\u8981\u989d\u5916\u673a\u5236\u5c06\u6570\u636e\u5757\u63d2\u5165\u8fdc\u7a0b\u7f13\u5b58\u3002\u51e0\u4e4e\u6240\u6709\u6280\u672f\u90fd\u901a\u8fc7\u590d\u7528\u7a7a\u95f2\u6267\u884c\u4e0a\u4e0b\u6587\u6765\u8fd0\u884c\u9884\u53d6\u4ee3\u7801\u3002\u7136\u800c\uff0c\u5f53\u5904\u7406\u5668\u6267\u884c\u5177\u6709\u9ad8\u7ebf\u7a0b\u7ea7\u5e76\u884c\u6027\u7684\u5e94\u7528\u65f6\uff0c\u8f85\u52a9\u7ebf\u7a0b\u6240\u9700\u7684\u95f2\u7f6e\u8d44\u6e90\uff08\u5982\u7a7a\u95f2\u6838\u5fc3\u6216\u7ebf\u7a0b\u4e0a\u4e0b\u6587\uff1b\u53d6\u6307\u4e0e\u6267\u884c\u5e26\u5bbd\uff09\u53ef\u80fd\u65e0\u6cd5\u83b7\u5f97\u3002\u8fd9\u4e9b\u6280\u672f\u7684\u6536\u76ca\u5fc5\u987b\u4e0e\u589e\u52a0\u5e94\u7528\u7ebf\u7a0b\u6570\u91cf\u8fdb\u884c\u6743\u8861\u3002</p>"},{"location":"APHP/C3.html#343-run-ahead-execution","title":"3.4.3 Run-Ahead Execution","text":"<p>\u8d85\u524d\u6267\u884c\u5229\u7528\u6838\u5fc3\u4e2d\u56e0\u957f\u5ef6\u8fdf\u4e8b\u4ef6\uff08\u5982\u7247\u5916\u7f13\u5b58\u7f3a\u5931\uff09\u800c\u672c\u5e94\u505c\u6ede\u7684\u6267\u884c\u8d44\u6e90\uff0c\u5728\u505c\u6ede\u6267\u884c\u70b9\u4e4b\u524d\u8fdb\u884c\u63a2\u7d22\uff0c\u4ee5\u53d1\u73b0\u66f4\u591a\u52a0\u8f7d\u7f3a\u5931\u5e76\u9884\u70ed\u5206\u652f\u9884\u6d4b\u5668\u3002\u5176\u6838\u5fc3\u601d\u60f3\u662f\u5728\u672c\u5e94\u505c\u6ede\u65f6\u6355\u83b7\u6267\u884c\u72b6\u6001\u5feb\u7167\uff0c\u968f\u540e\u8d8a\u8fc7\u505c\u6ede\u6307\u4ee4\u7ee7\u7eed\u83b7\u53d6\u5e76\u6267\u884c\u9884\u6d4b\u6307\u4ee4\u6d41\u3002\u5bf9\u672a\u5b8c\u6210\u6307\u4ee4\u5b58\u5728\u6570\u636e\u4f9d\u8d56\u7684\u6307\u4ee4\u4e0d\u4f1a\u88ab\u6267\u884c\uff08\u4f8b\u5982\u901a\u8fc7\u5bc4\u5b58\u5668\u91cd\u547d\u540d\u673a\u5236\u4f20\u64ad\u6bd2\u5316\u6807\u8bb0\uff09\u3002\u5f53\u957f\u5ef6\u8fdf\u4e8b\u4ef6\u89e3\u51b3\u65f6\uff08\u5982\u539f\u59cb\u7f3a\u5931\u6570\u636e\u8fd4\u56de\uff09\uff0c\u4ece\u5feb\u7167\u6062\u590d\u6267\u884c\u72b6\u6001\u5e76\u7ee7\u7eed\u539f\u6709\u6267\u884c\u6d41\u7a0b\uff0c\u91cd\u65b0\u7ecf\u8fc7\u8d85\u524d\u6267\u884c\u9636\u6bb5\u63a2\u7d22\u8fc7\u7684\u6307\u4ee4\u3002\u8be5\u65b9\u6848\u7684\u4e3b\u8981\u6548\u76ca\u5728\u4e8e\u5bf9\u957f\u5ef6\u8fdf\u52a0\u8f7d\u7684\u9884\u53d6\u6548\u679c\u3002Dundas\u4e0eMudge\u6700\u65e9\u5728\u987a\u5e8f\u6267\u884c\u6838\u5fc3\u80cc\u666f\u4e0b\u63d0\u51fa\u8d85\u524d\u6267\u884c[102]\u3002Mutlu\u4e0e\u5408\u4f5c\u8005\u63a2\u7d22\u4e86\u5728\u4e71\u5e8f\u5904\u7406\u5668\u4e2d\u7684\u9ad8\u6548\u5b9e\u73b0\u65b9\u6848[103, 104, 105, 106]\u3002\u8fd1\u671f\u7814\u7a76\u8005\u5f00\u59cb\u63a2\u7d22\u975e\u963b\u585e\u6d41\u6c34\u7ebf\u5fae\u67b6\u6784\uff0c\u5176\u5728\u957f\u5ef6\u8fdf\u52a0\u8f7d\u65f6\u6301\u7eed\u63a8\u6d4b\u6267\u884c\uff0c\u5e76\u5728\u52a0\u8f7d\u8fd4\u56de\u65f6\u4e0d\u4e22\u5f03\u63a8\u6d4b\u6267\u884c\u7ed3\u679c\uff0c\u4ec5\u91cd\u65b0\u6267\u884c\u4f9d\u8d56\u6307\u4ee4[107, 108]\u3002</p>"},{"location":"APHP/C3.html#344-context-restoration","title":"3.4.4 Context Restoration","text":"<p>\u968f\u7740\u865a\u62df\u5316\u6280\u672f\u666e\u53ca\u53ca\u4e91\u73af\u5883\u4e2d\u5355\u670d\u52a1\u5668\u591a\u5e94\u7528\u590d\u7528\u573a\u666f\u589e\u591a\uff0c\u4e0a\u4e0b\u6587\u5207\u6362\u5bfc\u81f4\u7684\u6307\u4ee4\u7f13\u5b58\u7f3a\u5931\u6210\u4e3a\u91cd\u8981\u7279\u4f8b\u3002\u6bcf\u5f53\u64cd\u4f5c\u7cfb\u7edf\u6216\u865a\u62df\u673a\u76d1\u63a7\u7a0b\u5e8f\u5728\u590d\u7528\u5e94\u7528\u6216\u865a\u62df\u673a\u95f4\u5207\u6362\u65f6\uff0c\u67d0\u4e00\u5e94\u7528\u7684\u7f13\u5b58\u72b6\u6001\u4f1a\u88ab\u5176\u4ed6\u5e94\u7528\u8986\u76d6\u3002\u5f53\u5c06\u5ef6\u8fdf\u654f\u611f\u7684\u670d\u52a1\u5e94\u7528\u4e0e\u540e\u53f0\u6279\u5904\u7406\u4efb\u52a1\u590d\u7528\u65f6\uff08\u8fd9\u662f\u670d\u52a1\u5e94\u7528\u56e0\u7b49\u5f85\u7528\u6237\u8bf7\u6c42\u800c\u963b\u585e\u65f6\u5229\u7528\u7a7a\u95f2\u5468\u671f\u7684\u5e38\u89c1\u505a\u6cd5\uff09\uff0c\u8fd9\u7c7b\u7f3a\u5931\u9020\u6210\u7684\u6027\u80fd\u635f\u5bb3\u5c24\u4e3a\u4e25\u91cd\u3002</p> <p>\u4e0a\u4e0b\u6587\u6062\u590d\u9884\u53d6\u5668[109, 110, 111]\u81f4\u529b\u4e8e\u5728\u4e0a\u4e0b\u6587\u5207\u6362\u65f6\uff08\u6216\u5728\u4e0a\u4e0b\u6587\u5207\u6362\u540e\u7f13\u5b58\u5757\u88ab\u66ff\u6362\u65f6\uff09\u6355\u83b7\u7f13\u5b58\u5185\u5bb9\uff0c\u968f\u540e\u5c06\u8fd9\u4e9b\u6570\u636e\u5757\u6062\u590d\u81f3\u7f13\u5b58\u4e2d\u3002\u4e0e\u5176\u4ed6\u9884\u53d6\u6280\u672f\u4e0d\u540c\uff0c\u4e0a\u4e0b\u6587\u6062\u590d\u65e0\u9700\u9884\u6d4b\u9700\u8981\u9884\u53d6\u7684\u5730\u5740\uff0c\u5176\u76ee\u6807\u4ec5\u662f\u6062\u590d\u5148\u524d\u7f13\u5b58\u4e2d\u7684\u5185\u5bb9\u3002\u76f8\u53cd\uff0c\u8bbe\u8ba1\u6311\u6218\u4e3b\u8981\u96c6\u4e2d\u4e8e\u5c06\u7f13\u5b58\u72b6\u6001\u4e0e\u7279\u5b9a\u6267\u884c\u4e0a\u4e0b\u6587\u76f8\u5173\u8054\u3001\u7ba1\u7406\u9884\u53d6\u7684\u65f6\u6548\u6027\uff0c\u4ee5\u53ca\u9ad8\u6548\u8bb0\u5f55/\u5b58\u50a8\u9884\u53d6\u5668\u5143\u6570\u636e\u3002</p>"},{"location":"APHP/C3.html#345-computation-spreading","title":"3.4.5 Computation Spreading","text":"<p>\u4e00\u79cd\u4e0e\u57fa\u4e8e\u6267\u884c\u7684\u9884\u53d6\u5177\u6709\u76f8\u4f3c\u6027\u4e14\u80fd\u63d0\u5347\u7f13\u5b58\u5c40\u90e8\u6027\u7684\u6b63\u4ea4\u7684\u65b9\u6cd5\u662f\u8ba1\u7b97\u5206\u6563[112, 113]\u3002\u8be5\u6280\u672f\u901a\u8fc7\u7ebf\u7a0b\u8fc1\u79fb\u5c06\u5927\u578b\u8ba1\u7b97\u4efb\u52a1\u62c6\u5206\u5230\u591a\u4e2a\u6838\u5fc3\u4e0a\u6267\u884c\uff0c\u5728\u6bcf\u4e2a\u6838\u5fc3\u4e0a\u805a\u5408\u76f8\u4f3c\u7684\u6267\u884c\u7247\u6bb5\u3002\u91cd\u590d\u6267\u884c\u76f8\u4f3c\u7247\u6bb5\u53ef\u4f7f\u6838\u5fc3\u4e13\u5c5e\u7684\u6307\u4ee4/\u6570\u636e\u7f13\u5b58\uff08\u53ca\u5206\u652f\u9884\u6d4b\u5668\u7b49\u7ed3\u6784\uff09\u9488\u5bf9\u5404\u7c7b\u7247\u6bb5\u8fdb\u884c\u4e13\u95e8\u4f18\u5316\uff0c\u4ece\u800c\u63d0\u5347\u5c40\u90e8\u6027\u3002\u8be5\u65b9\u6cd5\u5df2\u6210\u529f\u5e94\u7528\u4e8e\u5206\u79bb\u5e94\u7528\u7a0b\u5e8f\u4e0e\u64cd\u4f5c\u7cfb\u7edf\u4ee3\u7801\u7247\u6bb5[112]\uff0c\u4ee5\u53ca\u5728\u7ebf\u4e8b\u52a1\u5904\u7406\u7ebf\u7a0b\u7684\u9636\u6bb5\u5212\u5206[113]\u3002</p>"},{"location":"APHP/C3.html#35-prefetch-modulation-and-control","title":"3.5 Prefetch Modulation And Control","text":"<p>\u591a\u4f4d\u7814\u7a76\u8005\u63a2\u8ba8\u4e86\u9884\u53d6\u8c03\u5236\u63a7\u5236\u6280\u672f\u53ca\u5176\u4e0e\u5b58\u50a8\u7cfb\u7edf\u5176\u4ed6\u7ec4\u4ef6\uff08\u5982\u7f13\u5b58\u7f6e\u6362\u7b56\u7565\uff09\u7684\u4ea4\u4e92\u3002\u867d\u7136\u5927\u591a\u6570\u7814\u7a76\u57fa\u4e8e\u6b65\u957f\u6d41\u9884\u53d6\u5668\u5c55\u5f00\uff0c\u4f46\u8fd9\u4e9b\u673a\u5236\u901a\u5e38\u9002\u7528\u4e8e\u4efb\u4f55\u751f\u6210\u9884\u53d6\u5019\u9009\u5730\u5740\u7684\u7b97\u6cd5\u3002</p> <p>Srinath\u7b49\u4eba\u63d0\u51fa\u901a\u8fc7\u786c\u4ef6\u8ffd\u8e2a\u6fc0\u8fdb\u9884\u53d6\u53ef\u80fd\u9020\u6210\u7684\u7f13\u5b58\u6c61\u67d3\uff0c\u5f53\u9884\u53d6\u51c6\u786e\u6027\u4e0e\u65f6\u6548\u6027\u8f83\u5dee\u6216\u6c61\u67d3\u663e\u8457\u589e\u52a0\u9700\u6c42\u7f3a\u5931\u7387\u65f6\uff0c\u52a8\u6001\u964d\u4f4e\u9884\u53d6\u6fc0\u8fdb\u5ea6[114]\u3002Ebrahimi\u7b49\u7814\u7a76\u4e86\u591a\u6838\u7cfb\u7edf\u4e2d\u534f\u8c03\u591a\u4e2a\u6838\u5fc3\u4e13\u5c5e\u9884\u53d6\u5668\u6fc0\u8fdb\u5ea6\u7684\u673a\u5236\uff0c\u4ee5\u5e94\u5bf9\u5e26\u5bbd\u4e89\u7528\u95ee\u9898[115]\u3002Lee\u56e2\u961f\u5206\u6790\u4e86\u9884\u53d6\u5668\u4e0eDRAM\u5b58\u50a8\u4f53\u4e89\u7528\u7684\u76f8\u4e92\u4f5c\u7528\uff0c\u63d0\u51fa\u901a\u8fc7\u91cd\u6392\u5e8f\u9884\u53d6\u8bf7\u6c42\u63d0\u5347DRAM\u5b58\u50a8\u4f53\u7ea7\u5e76\u884c\u6027\uff0c\u4ece\u800c\u6539\u5584\u9884\u53d6\u541e\u5410\u91cf[116]\u3002Hur\u4e0eLin\u63d0\u51fa\u4e86\u52a8\u6001\u68c0\u6d4b\u6d41\u7ec8\u6b62\u7684\u673a\u5236\uff0c\u51cf\u5c11\u56e0\u77ed\u6d41\u8fc7\u91cf\u9884\u53d6\u5bfc\u81f4\u7684\u7f13\u5b58\u6c61\u67d3\u548c\u5e26\u5bbd\u6d6a\u8d39[33]\u3002Lin\u7b49\u4eba\u5efa\u8bae\u5728\u5173\u8054\u7f13\u5b58\u4e2d\u5c06\u9884\u53d6\u5757\u63d2\u5165\u6700\u8fd1\u6700\u5c11\u4f7f\u7528\u4f4d\u7f6e\uff0c\u4ee5\u7ba1\u7406\u6c61\u67d3\u5e76\u8c03\u8282\u9884\u53d6\u53d1\u5c04\u7387[117]\u3002Wu\u56e2\u961f\u5728\u6b64\u57fa\u7840\u4e0a\u63d0\u51fa\u591a\u79cd\u52a8\u6001\u65b9\u6cd5\uff0c\u7528\u4e8e\u9009\u62e9\u9884\u53d6\u5757\u5728\u7f13\u5b58\u7f6e\u6362\u6808\u4e2d\u7684\u63d2\u5165\u4f4d\u7f6e[118]\u3002\u6700\u540e\uff0cVerma\u3001Koppelman\u548cPeng\u63d0\u4f9b\u4e86\u8f6f\u4ef6\u63a7\u5236\u9884\u53d6\u6fc0\u8fdb\u5ea6\u7684\u5b9e\u73b0\u673a\u5236[119]\u3002</p>"},{"location":"APHP/C3.html#36-software-approaches","title":"3.6 Software Approaches","text":"<p>\u7814\u7a76\u4eba\u5458\u63d0\u51fa\u4e86\u591a\u79cd\u5176\u4ed6\u65b9\u6cd5\uff0c\u7528\u4e8e\u7f16\u8bd1\u5668\u6216\u7a0b\u5e8f\u5458\u63d2\u5165\u9884\u53d6\u6307\u4ee4\uff08\u4f8b\u5982 [41, 43, 120, 121, 122, 123]\uff09\u6216\u6570\u636e\u8f6c\u53d1\u64cd\u4f5c [124, 125]\u3002\u6700\u8fd1\uff0c\u7814\u7a76\u4eba\u5458\u5f00\u53d1\u4e86\u67b6\u6784 [126, 127] \u548c\u7f16\u7a0b\u8bed\u8a00 [128, 129]\uff0c\u63d0\u4f9b\u76f4\u63a5\u8868\u8fbe\u548c\u64cd\u4f5c\u6570\u636e\u6d41\u7684\u6784\u9020\u3002\u7136\u800c\uff0c\u8fd9\u4e9b\u7814\u7a76\u4e3b\u8981\u5173\u6ce8\u591a\u5a92\u4f53\u5e94\u7528\uff0c\u5176\u4e2d\u5e94\u7528\u8f93\u5165\u81ea\u7136\u6620\u5c04\u5230\u6570\u636e\u5e8f\u5217\u3002\u76ee\u524d\u5c1a\u4e0d\u6e05\u695a\u5982\u4f55\u5728\u5176\u4ed6\u573a\u666f\uff08\u5982\u5546\u4e1a\u670d\u52a1\u5668\u8f6f\u4ef6\uff09\u4e2d\u5229\u7528\u8fd9\u4e9b\u8fdb\u5c55\u3002\u5bf9\u8f6f\u4ef6\u548c\u7f16\u8bd1\u5668\u6570\u636e\u9884\u53d6\u6280\u672f\u7684\u5168\u9762\u63a2\u8ba8\u8d85\u51fa\u4e86\u672c\u7efc\u8ff0\u8bb2\u5ea7\u7684\u8303\u56f4\u3002</p>"},{"location":"APHP/C3.html#37-conclusion","title":"3.7 Conclusion","text":"\u9884\u53d6\u5668\u540d\u79f0 \u4f7f\u7528\u7684\u5173\u952e\u4fe1\u606f \u9884\u53d6\u6df1\u5ea6 \u51c6\u786e\u7387 \u9762\u79ef Stride/Stream \u6839\u636ePC\u6216\u8005\u8bbf\u95ee\u5730\u5740\u9884\u6d4bcache miss\u6b65\u957f \u51e0\u4e2acache\u5757 \u5bf9\u4e8estride\u6765\u8bf4\u5f88\u51c6\u786e &lt;1KB Simple address correlating \u5c06\u67d0\u4e2a\u8bbf\u95ee\u5730\u5740\u548c\u82e5\u5e72\u4e2acache miss \u5730\u5740\u8054\u7cfb \u4e00\u4e2acache\u5757 &gt;30% &lt;MBs Linked-data correlating \u6784\u5efa\u72b6\u6001\u673a\uff0c\u5229\u7528\u8ffd\u9010\u6307\u9488\u53bb\u9884\u6d4b \u51e0\u4e2acache\u5757 \u5bf9\u4e8e\u67d0\u4e9b\u6570\u636e\u7ed3\u6784\u5f88\u51c6 &lt;1KB Dead-block correlating \u6b7b\u5757\u7684\u66ff\u6362\u65f6\u95f4 &gt;50% MBs Temporal streaming \u5c06\u67d0\u4e2a\u8bbf\u95ee\u5730\u5740\u548c\u82e5\u5e72\u4e2acache miss\u6d41\u5730\u5740\u8054\u7cfb \u8bb8\u591acache\u5757 &gt;50% Off chip Chained  streaming \u901a\u8fc7\u63a7\u5236\u6d41\u6216\u5206\u5c42\u5730\u5740\u9884\u6d4b\u5c06\u591a\u4e2a\u5730\u5740\u6d41\u94fe\u63a5\u5728\u4e00\u8d77 \u540c\u4e0a &gt;50% Off chip Irregular  stream buffer \u901a\u8fc7\u5730\u5740\u95f4\u63a5\u5c42\u5c06\u65f6\u95f4\u76f8\u5173\u6027\u8f6c\u6362\u4e3a\u7a7a\u95f4\u76f8\u5173\u6027 \u540c\u4e0a &gt;50% &lt;32KB Delta  correlation \u8bb0\u5f55\u5e76\u5173\u8054\u8bbf\u5b58\u5730\u5740\u7f3a\u5931\u503c\u4e4b\u95f4\u7684\u589e\u91cf\u5e8f\u5217 \u51e0\u4e2acache\u5757 &gt;30% &lt;32KB Spatial streaming \u5c06PC\u4e0e\u4efb\u610f\u7f13\u5b58\u7f3a\u5931\u5730\u5740\u589e\u91cf\u5e8f\u5217\u76f8\u5173\u8054 \u540c\u4e0a &gt;50% &lt;64KB Execution  based \u8f85\u52a9\u7ebf\u7a0b\u6216\u5bf9\u63a8\u6d4b\u6267\u884c\u7684\u652f\u6301 \u53d7\u9650\u4e8e\u6267\u884c\u5e26\u5bbd \u4e0d\u4e00\u5b9a --"},{"location":"APHP/C4.html","title":"4. Concluding Remarks","text":"<p>\u786c\u4ef6\u9884\u53d6\u4f5c\u4e3a\u5b66\u672f\u7814\u7a76\u4e0e\u5de5\u4e1a\u53d1\u5c55\u7684\u8bfe\u9898\u5df2\u8d85\u8fc740\u5e74\u3002\u7136\u800c\uff0c\u7531\u4e8e\u5904\u7406\u5668\u6027\u80fd\u4e0e\u5185\u5b58\u8bbf\u95ee\u5ef6\u8fdf\u4e4b\u95f4\u7684\u5dee\u8ddd\u968f\u7740\u6280\u672f\u8fed\u4ee3\u6301\u7eed\u6269\u5927\uff0c\u786c\u4ef6\u9884\u53d6\u7684\u91cd\u8981\u6027\u53ca\u9690\u85cf\u5185\u5b58\u7cfb\u7edf\u5ef6\u8fdf\u7684\u9700\u6c42\u6108\u53d1\u51f8\u663e\u2014\u2014\u6301\u7eed\u521b\u65b0\u4f9d\u7136\u81f3\u5173\u91cd\u8981\u3002</p> <p>\u672c\u5165\u95e8\u4e66\u4e2d\uff0c\u6211\u4eec\u68b3\u7406\u4e86\u5df2\u5f00\u53d1\u7684\u4f17\u591a\u9884\u53d6\u6280\u672f\uff0c\u5e76\u91cd\u70b9\u9610\u91ca\u4e86\u8fd9\u4e9b\u6280\u672f\u6240\u4f9d\u8d56\u7684\u6838\u5fc3\u7a0b\u5e8f\u884c\u4e3a\u7279\u5f81\u3002\u6211\u4eec\u5e0c\u671b\u672c\u4e66\u80fd\u6210\u4e3a\u8be5\u9886\u57df\u7684\u5165\u95e8\u6307\u5357\uff0c\u4e3a\u6d69\u5982\u70df\u6d77\u7684\u786c\u4ef6\u9884\u53d6\u6587\u732e\u63d0\u4f9b\u6982\u89c8\uff0c\u5e76\u6fc0\u53d1\u65b0\u7684\u7814\u7a76\u63a2\u7d22\u3002</p> <p>\u672a\u6765\u7814\u7a76\u4ecd\u9700\u5e94\u5bf9\u8bf8\u591a\u6311\u6218\u3002\u6307\u4ee4\u83b7\u53d6\u4ecd\u662f\u57fa\u7840\u6027\u74f6\u9888\uff0c\u5c24\u5176\u5728\u8fd0\u884c\u590d\u6742\u8f6f\u4ef6\u6808\u4e14\u7247\u4e0a\u6307\u4ee4\u5de5\u4f5c\u96c6\u4e0d\u65ad\u6269\u5927\u7684\u670d\u52a1\u5668\u4e2d\u3002\u867d\u7136\u6307\u4ee4\u8db3\u8ff9\u901a\u5e38\u80fd\u5b8c\u6574\u5bb9\u7eb3\u4e8e\u5927\u578b\u672b\u7ea7\u7f13\u5b58\uff0c\u4f46\u5468\u671f\u65f6\u95f4\u9650\u5236\u4e25\u91cd\u5236\u7ea6\u4e86L1\u6307\u4ee4\u7f13\u5b58\u7684\u5bb9\u91cf\uff0c\u800c\u8bbf\u95ee\u5927\u5bb9\u91cf\u7f13\u5b58\u7684\u5ef6\u8fdf\u95ee\u9898\u4f9d\u7136\u5b58\u5728\u3002\u8fd1\u5e74\u6765\u63d0\u51fa\u7684\u65f6\u5e8f\u6307\u4ee4\u6d41\u5148\u8fdb\u65b9\u6848\u5373\u4f7f\u9762\u5bf9\u590d\u6742\u8f6f\u4ef6\u6808\uff0c\u4e5f\u5b9e\u73b0\u4e86\u60ca\u4eba\u7684\u9884\u6d4b\u7cbe\u5ea6\u4e0e\u8986\u76d6\u7387\uff08&gt;99.5%\uff09\u3002\u8fd9\u4e9b\u65b9\u6848\u80fd\u5426\u5e7f\u6cdb\u843d\u5730\u7684\u5173\u952e\uff0c\u5728\u4e8e\u5c06\u5143\u6570\u636e\u5b58\u50a8\u5f00\u9500\u538b\u7f29\u81f3\u5b9e\u7528\u6c34\u5e73\u7684\u6280\u672f\u7a81\u7834\u3002</p> <p>\u6307\u4ee4\u9884\u53d6\u9762\u4e34\u7684\u53e6\u4e00\u91cd\u6311\u6218\u6e90\u4e8e\u7f16\u7a0b\u8bed\u8a00\u4e0e\u8f6f\u4ef6\u5de5\u7a0b\u7684\u53d1\u5c55\u2014\u2014\u5b83\u4eec\u5e38\u5e38\u4f7f\u6211\u4eec\u8ba8\u8bba\u7684\u6280\u672f\u590d\u6742\u5316\u751a\u81f3\u5931\u6548\u3002\u9762\u5411\u5bf9\u8c61\u7f16\u7a0b\u3001\u52a8\u6001\u5206\u6d3e\u4e0e\u6258\u7ba1\u8fd0\u884c\u65f6\u5bfc\u81f4\u77ed\u9891\u51fd\u6570\u8c03\u7528\u6fc0\u589e\uff0c\u51fd\u6570\u6307\u9488\u95f4\u63a5\u5bfb\u5740\u3001\u5bc4\u5b58\u5668\u95f4\u63a5\u8df3\u8f6c\u53ca\u591a\u8def\u63a7\u5236\u8f6c\u79fb\u65e5\u76ca\u666e\u904d\u3002\u52a8\u6001\u4ee3\u7801\u751f\u6210/\u4f18\u5316\u3001\u89e3\u91ca\u578b\u8bed\u8a00\u4e0e\u5373\u65f6\u7f16\u8bd1\u4f7f\u5f97\u7a0b\u5e8f\u63a7\u5236\u7ed3\u6784\u96be\u4ee5\u8ffd\u8e2a\uff0c\u6307\u4ee4\u5730\u5740\u7684\u542b\u4e49\u968f\u65f6\u95f4\u52a8\u6001\u53d8\u5316\u3002\u865a\u62df\u5316\u4e0e\u64cd\u4f5c\u7cfb\u7edf\u5206\u5c42\u5219\u901a\u8fc7\u9891\u7e41\u7684\u865a\u62df\u673a\u9000\u51fa\u548c\u9677\u5165\u6a21\u62df\u7279\u6743\u529f\u80fd\uff0c\u540c\u6837\u4f7f\u63a7\u5236\u6d41\u590d\u6742\u96be\u8fa8\u3002</p> <p>\u5728\u786c\u4ef6\u5c42\u9762\uff0c\u5904\u7406\u5668\u65e5\u76ca\u652f\u6301\u591a\u5e76\u53d1\u786c\u4ef6\u7ebf\u7a0b\uff0c\u8fd9\u4e9b\u7ebf\u7a0b\u5fc5\u987b\u5171\u4eab\u672c\u5df2\u8fc7\u8f7d\u7684\u6307\u4ee4\u7f13\u5b58\u5bb9\u91cf\u3002\u9884\u53d6\u5668\u9700\u5347\u7ea7\u4ee5\u5b9e\u73b0\u7ebf\u7a0b\u95f4\u6709\u9650\u5bb9\u91cf\u4e0e\u5e26\u5bbd\u7684\u5171\u4eab\uff0c\u5206\u79bb\u5404\u7ebf\u7a0b\u7684\u6307\u4ee4\u6d41\uff0c\u5e76\u7edf\u7b79\u9884\u53d6\u7b56\u7565\u4e0e\u7ebf\u7a0b\u4f18\u5148\u7ea7/\u53d6\u6307\u7b56\u7565\u7684\u76f8\u4e92\u4f5c\u7528\u3002</p> <p>\u6570\u636e\u9884\u53d6\u9762\u4e34\u7684\u4e00\u4e2a\u5173\u952e\u6311\u6218\uff0c\u662f\u5728\u5404\u79cd\u5de5\u4f5c\u8d1f\u8f7d\u4e2d\u666e\u904d\u5b58\u5728\u7684\u4f4e\u51c6\u786e\u7387\u548c\u4f4e\u8986\u76d6\u7387\u95ee\u9898\u3002\u968f\u7740\u6570\u636e\u5bc6\u96c6\u578b\u5de5\u4f5c\u8d1f\u8f7d\u548c\u5927\u89c4\u6a21\u5185\u5b58\u6570\u636e\u670d\u52a1\u7684\u51fa\u73b0\uff0c\u5bf9\u9ad8\u6548\u6570\u636e\u9884\u53d6\u7684\u9700\u6c42\u4e0d\u65ad\u589e\u52a0\u3002\u7136\u800c\uff0c\u5185\u5b58\u5bb9\u91cf\u7684\u4e0d\u65ad\u6269\u5927\uff0c\u4f7f\u5f97\u5373\u4fbf\u662f\u672c\u6559\u7a0b\u4e2d\u4ecb\u7ecd\u7684\u6700\u5148\u8fdb\u7684\u57fa\u4e8e\u5386\u53f2\u7684\u9884\u53d6\u6280\u672f\uff0c\u4e5f\u9762\u4e34\u4e24\u4e2a\u95ee\u9898\uff1a\u4e00\u662f\u53ef\u91cd\u590d\u7684\u5386\u53f2\u8bbf\u95ee\u6a21\u5f0f\u65e5\u76ca\u51cf\u5c11\uff0c\u4e8c\u662f\u5143\u6570\u636e\u5b58\u50a8\u9700\u6c42\u53d8\u5f97\u8fc7\u9ad8\u3002\u56e0\u6b64\uff0c\u672a\u6765\u7684\u6570\u636e\u9884\u53d6\u6280\u672f\u9700\u8981\u8fdb\u4e00\u6b65\u53d1\u5c55\uff0c\u80fd\u591f\u4ee5\u66f4\u4f4e\u7684\u5143\u6570\u636e\u5b58\u50a8\u5f00\u9500\u3001\u66f4\u9ad8\u7684\u51c6\u786e\u5ea6\u6765\u6355\u83b7\u53ef\u91cd\u590d\u7684\u8bbf\u95ee\u6a21\u5f0f\u3002</p> <p>\u9488\u5bf9\u56fe\u5f62\u5904\u7406\u5668\u53ca\u5176\u4ed6\u4e13\u7528\u52a0\u901f\u5668\u7684\u9884\u53d6\u6280\u672f\u6b63\u9010\u6e10\u5174\u8d77\uff0c\u8fd9\u4e9b\u8bbe\u5907\u7684\u4ee3\u7801\u548c\u6570\u636e\u8bbf\u95ee\u6a21\u5f0f\u4e0e\u4f20\u7edf\u5904\u7406\u5668\u5b58\u5728\u663e\u8457\u5dee\u5f02\u3002\u4ee5\u56fe\u5f62\u5904\u7406\u5668\u4e3a\u4f8b\uff0c\u5185\u5b58\u8bbf\u95ee\u5ef6\u8fdf\u4e0e\u7ebf\u7a0b/\u7ebf\u7a0b\u675f\u8c03\u5ea6\u4ee5\u590d\u6742\u65b9\u5f0f\u76f8\u4e92\u5f71\u54cd\uff0c\u4e3a\u534f\u540c\u8bbe\u8ba1\u521b\u9020\u4e86\u65b0\u7684\u673a\u9047\u3002</p> <p>\u8fc7\u53bb\u5341\u5e74\u4e2d\u51fa\u73b0\u7684\u4e00\u4e2a\u6839\u672c\u6027\u6311\u6218\u662f\uff1a\u7531\u4e8e\u767b\u7eb3\u5fb7\u7f29\u653e\u5b9a\u5f8b[130, 131]\u7684\u51cf\u901f\u53ca\u4f9b\u7535\u7535\u538b\u8d8b\u4e8e\u7a33\u5b9a\uff0c\u529f\u8017\u5df2\u6210\u4e3a\u9996\u8981\u7ea6\u675f\u6761\u4ef6\u3002\u4e00\u65b9\u9762\uff0c\u9884\u53d6\u5668\u901a\u8fc7\u6d88\u9664\u5ef6\u8fdf\u53ef\u5b9e\u73b0\u786c\u4ef6\u8d44\u6e90\u66f4\u9ad8\u6548\u5229\u7528\uff0c\u4ece\u800c\u63d0\u5347\u80fd\u6548\uff1b\u53e6\u4e00\u65b9\u9762\uff0c\u591a\u6570\u9884\u53d6\u5668\u9700\u8981\u8f85\u52a9\u786c\u4ef6\u7ed3\u6784\uff0c\u8fd9\u4e9b\u7ed3\u6784\u4f1a\u6d88\u8017\u80fd\u91cf\u3002\u6b64\u5916\uff0c\u9884\u53d6\u5668\u5e38\u4f1a\u83b7\u53d6\u9519\u8bef\u6570\u636e\u5757\uff0c\u5bfc\u81f4\u5927\u91cf\u80fd\u91cf\u6d6a\u8d39\u3002\u5b9e\u9645\u4e0a\uff0c\u8bb8\u591a\u7b80\u5355\uff08\u4f46\u5e7f\u6cdb\u90e8\u7f72\uff09\u7684\u8bbe\u8ba1\u51c6\u786e\u7387\u6781\u4f4e\u2014\u2014\u5176\u83b7\u53d6\u7684\u6570\u636e\u5757\u8d85\u8fc7\u534a\u6570\u53ef\u80fd\u6c38\u8fdc\u4e0d\u4f1a\u88ab\u8bbf\u95ee\u3002\u9884\u53d6\u6280\u672f\u7684\u8fdb\u6b65\u5fc5\u987b\u5c06\u80fd\u6548\u4f5c\u4e3a\u6838\u5fc3\u7ea6\u675f\u6307\u6807\uff0c\u5e76\u4e0e\u51c6\u786e\u7387\u3001\u8986\u76d6\u7387\u7b49\u5176\u4ed6\u5173\u952e\u6307\u6807\u5171\u540c\u8bc4\u4f30\u9884\u53d6\u5668\u8bbe\u8ba1\u7684\u6709\u6548\u6027\u3002</p>"},{"location":"APHP/translator.html","title":"\u8bd1\u5e8f","text":"<p>\u672c\u4e66\u4e3a Babak Falsafi \u548c Thomas F. Wenisch \u6240\u8457\u7684\u300aA Primer on Hardware Prefetching\u300b\u3002 \u672c\u4e66\u4e3b\u8981\u4ecb\u7ecd\u4e86\u786c\u4ef6\u9884\u53d6\uff08Hardware Prefetching\uff09\u7684\u57fa\u672c\u6982\u5ff5\u3001\u539f\u7406\u548c\u5e94\u7528\u3002 \u672c\u4e66\u7684\u7ffb\u8bd1\u4e0d\u4fdd\u8bc1\u5b8c\u5168\u5fe0\u4e8e\u539f\u6587\uff0c\u4f46\u4fdd\u6301\u4e86\u539f\u6587\u57fa\u672c\u6240\u6709\u7684\u5185\u5bb9\u3002</p>"},{"location":"OCN2E/Preface.html","title":"\u524d\u8a00\uff08Preface\uff09","text":"<p>\u672c\u4e66\u9762\u5411\u5df2\u719f\u6089\u4f17\u591a\u8ba1\u7b97\u673a\u4f53\u7cfb\u7ed3\u6784\u57fa\u672c\u6982\u5ff5\u7684\u5de5\u7a0b\u5e08\u548c\u7814\u7a76\u4eba\u5458\uff0c\u65e8\u5728\u5e2e\u52a9\u4ed6\u4eec\u6df1\u5165\u4e86\u89e3\u7247\u4e0a\u7f51\u7edc\uff08Network-on-Chip, NoC\uff09\u3002 \u672c\u4e66\u529b\u6c42\u7b80\u660e\u627c\u8981\u5730\u603b\u7ed3\u7247\u4e0a\u7f51\u7edc\u8bbe\u8ba1\u4e2d\u6700\u5173\u952e\u7684\u6982\u5ff5\u3002 \u6211\u4eec\u8bbe\u60f3\u672c\u4e66\u65e2\u53ef\u4f5c\u4e3a\u7406\u89e3\u7247\u4e0a\u7f51\u7edc\u57fa\u7840\u77e5\u8bc6\u7684\u5165\u95e8\u8d44\u6e90\uff0c\u4e5f\u53ef\u7528\u6765\u6982\u89c8\u8be5\u9886\u57df\u7684\u6700\u65b0\u7814\u7a76\u8fdb\u5c55\u3002 \u6211\u4eec\u76f8\u4fe1\uff0c\u517c\u987e\u57fa\u7840\u539f\u7406\u6559\u5b66\u4e0e\u524d\u6cbf\u8bbe\u8ba1\u5c55\u793a\u7684\u6982\u89c8\u6027\u5185\u5bb9\uff0c\u5c06\u5bf9\u7814\u7a76\u751f\u548c\u4e1a\u754c\u5de5\u7a0b\u5e08\u90fd\u6781\u5177\u4ef7\u503c\u3002 \u5c3d\u7ba1\u672c\u4e66\u5e76\u975e\u8be6\u5c3d\u65e0\u9057\u7684\u6559\u79d1\u4e66\uff0c\u6211\u4eec\u5e0c\u671b\u5b83\u80fd\u9610\u660e\u7247\u4e0a\u7f51\u7edc\u7684\u57fa\u672c\u6982\u5ff5\uff0c\u540c\u65f6\u8bc6\u522b\u5f53\u524d\u7814\u7a76\u7684\u8d8b\u52bf\u4e0e\u7a7a\u767d\u3002</p> <p>\u9274\u4e8e\u8be5\u9886\u57df\u7684\u8fc5\u731b\u53d1\u5c55\uff0c\u6211\u4eec\u8ba4\u4e3a\u5728\u672c\u6b21\u7b2c\u4e8c\u7248\u4e2d\u5bf9\u524d\u6cbf\u8fdb\u5c55\u8fdb\u884c\u66f4\u65b0\u4e0e\u56de\u987e\u6070\u9022\u5176\u65f6\u3002 \u672c\u4e66\u5728\u7ed3\u5c3e\u65b0\u589e\u4e86\u4e24\u4e2a\u7ae0\u8282\uff0c\u5177\u4f53\u5c06\u5728\u4e0b\u6587\u8be6\u7ec6\u8bf4\u660e\u3002 \u5728\u5168\u4e66\u4e2d\uff0c\u9664\u4e86\u66f4\u65b0\u8fd1\u5e74\u6765\u7684\u7814\u7a76\u6210\u679c\u4e4b\u5916\uff0c\u6211\u4eec\u8fd8\u6269\u5c55\u4e86\u5bf9\u57fa\u7840\u6982\u5ff5\u7684\u8bb2\u89e3\uff0c\u6db5\u76d6\u4e86\u4e00\u4e9b\u5982\u4eca\u5df2\u5e94\u7528\u4e8e\u5b9e\u9645\u4ea7\u54c1\u4e2d\u7684\u7814\u7a76\u601d\u60f3\u3002 \u5728\u6211\u4eec\u770b\u6765\uff0c\u8fd9\u4e9b\u601d\u60f3\u5e94\u5f53\u6210\u4e3a\u6bcf\u4f4d\u7247\u4e0a\u7f51\u7edc\u7814\u7a76\u4e0e\u8bbe\u8ba1\u4ece\u4e1a\u8005\u90fd\u5e94\u638c\u63e1\u7684\u6559\u79d1\u4e66\u7ea7\u5185\u5bb9\u3002 \u4f8b\u5982\uff0c\u8fd9\u4e9b\u57fa\u7840\u6982\u5ff5\u5305\u62ec\u6d88\u606f\u4f20\u9012\uff08message passing\uff09\u3001\u7ec4\u64ad\u8def\u7531\uff08multicast routing\uff09\u4ee5\u53ca\u6c14\u6ce1\u6d41\u63a7\u5236\u673a\u5236\uff08bubble flow control schemes\uff09\u3002</p> <p>\u672c\u4e66\u7ed3\u6784\u5982\u4e0b\uff1a</p> <p>\u7b2c1\u7ae0\u4ece\u591a\u6838\u67b6\u6784\u7684\u80cc\u666f\u51fa\u53d1\uff0c\u4ecb\u7ecd\u7247\u4e0a\u7f51\u7edc\uff0c\u5e76\u63a2\u8ba8\u5176\u5982\u4f55\u4ece\u65e9\u671f\u7b80\u5355\u7684\u70b9\u5bf9\u70b9\u8fde\u7ebf\u4e0e\u603b\u7ebf\u6f14\u8fdb\u4e3a\u5177\u5907\u53ef\u6269\u5c55\u6027\u7684\u901a\u4fe1\u7ed3\u6784\u3002</p> <p>\u7b2c2\u7ae0\u89e3\u91ca\u4e86\u7f51\u7edc\u5982\u4f55\u5d4c\u5165\u5230\u591a\u6838\u7cfb\u7edf\u7684\u6574\u4f53\u4f53\u7cfb\u7ed3\u6784\u4e2d\u3002 \u6211\u4eec\u5177\u4f53\u5206\u6790\u4e86\u5171\u4eab\u5185\u5b58\u7247\u4e0a\u591a\u5904\u7406\u5668\u7cfb\u7edf\u4e2d\u4e00\u81f4\u6027\u534f\u8bae\u6240\u63d0\u51fa\u7684\u9700\u6c42\uff0c\u5e76\u5c06\u5176\u4e0e\u6d88\u606f\u4f20\u9012\u578b\u591a\u6838\u7cfb\u7edf\u7684\u9700\u6c42\u8fdb\u884c\u5bf9\u6bd4\u3002 \u672c\u7ae0\u8fd8\u63cf\u8ff0\u4e86\u7cfb\u7edf\u4e0e\u7f51\u7edc\u4e4b\u95f4\u7684\u63a5\u53e3\u3002</p> <p>\u5728\u5efa\u7acb\u4e86\u7247\u4e0a\u7f51\u7edc\u7684\u7cfb\u7edf\u4f7f\u7528\u80cc\u666f\u540e\uff0c\u63a5\u4e0b\u6765\u5404\u7ae0\u5c06\u6df1\u5165\u63a2\u8ba8\u7f51\u7edc\u8bbe\u8ba1\u7ec6\u8282\u3002\u7531\u4e8e\u62d3\u6251\u5e38\u5e38\u662f\u7f51\u7edc\u8bbe\u8ba1\u4e2d\u9996\u5148\u8981\u51b3\u5b9a\u7684\u56e0\u7d20\uff0c\u7b2c3\u7ae0\u4ecb\u7ecd\u4e86\u5728\u6210\u672c\u4e0e\u6027\u80fd\u4e4b\u95f4\u8fdb\u884c\u6743\u8861\u7684\u591a\u79cd\u62d3\u6251\u7ed3\u6784\u3002 \u5728\u786e\u5b9a\u4e86\u7f51\u7edc\u62d3\u6251\u540e\uff0c\u5fc5\u987b\u8bbe\u8ba1\u8def\u7531\u7b97\u6cd5\u4ee5\u51b3\u5b9a\u6d88\u606f\u5728\u7f51\u7edc\u4e2d\u4f20\u8f93\u7684\u8def\u5f84\u3002 \u7b2c4\u7ae0\u5bf9\u5404\u79cd\u8def\u7531\u7b97\u6cd5\u8fdb\u884c\u4e86\u8bb2\u89e3\u3002 \u7b2c5\u7ae0\u8ba8\u8bba\u4e86\u7f51\u7edc\u4e2d\u91c7\u7528\u7684\u6d41\u63a7\u5236\u673a\u5236\uff1b\u6d41\u63a7\u5236\u51b3\u5b9a\u4e86\u7f51\u7edc\u8d44\u6e90\uff08\u4e3b\u8981\u662f\u7f13\u51b2\u533a\u4e0e\u94fe\u8def\uff09\u5982\u4f55\u5728\u6d88\u606f\u4ece\u6e90\u7aef\u4f20\u8f93\u5230\u76ee\u7684\u7aef\u7684\u8fc7\u7a0b\u4e2d\u8fdb\u884c\u5206\u914d\u3002 \u62d3\u6251\u3001\u8def\u7531\u4e0e\u6d41\u63a7\u5236\u4e09\u8005\u5171\u540c\u5f71\u54cd\u4e86\u7f51\u7edc\u8def\u7531\u5668\u7684\u5fae\u67b6\u6784\u8bbe\u8ba1\u3002 \u7b2c6\u7ae0\u8be6\u7ec6\u8bb2\u89e3\u4e86\u5404\u79cd\u5fae\u67b6\u6784\u8bbe\u8ba1\u6743\u8861\u53ca\u76f8\u5173\u95ee\u9898\uff0c\u5305\u62ec\u7ec4\u6210\u8def\u7531\u5668\u5fae\u67b6\u6784\u7684\u7f13\u51b2\u533a\u3001\u4ea4\u6362\u5668\u4e0e\u5206\u914d\u5668\u7684\u8bbe\u8ba1\u3002 \u867d\u7136\u529f\u8017\u95ee\u9898\u53ef\u4ee5\u901a\u8fc7\u7247\u4e0a\u7f51\u7edc\u7684\u5404\u4e2a\u65b9\u9762\u52a0\u4ee5\u4f18\u5316\uff0c\u4f46\u6211\u4eec\u5c06\u65b0\u7684\u529f\u8017\u8ba8\u8bba\u96c6\u4e2d\u4e8e\u7b2c6\u7ae0\u4e2d\uff0c\u56e0\u4e3a\u8bb8\u591a\u4f18\u5316\u624b\u6bb5\u6b63\u662f\u5728\u5fae\u67b6\u6784\u5c42\u9762\u5b9e\u73b0\u7684\u3002</p> <p>\u65b0\u589e\u7684\u7b2c7\u7ae0\u4ecb\u7ecd\u4e86\u5bf9\u7247\u4e0a\u7f51\u7edc\u8fdb\u884c\u5efa\u6a21\u4e0e\u8bc4\u4f30\u7684\u6838\u5fc3\u65b9\u6cd5\uff0c\u6db5\u76d6\u4ece\u8f6f\u4ef6\u4eff\u771f\u3001RTL \u8bbe\u8ba1\u4e0e FPGA \u4eff\u771f\uff0c\u5230\u5bf9\u5ef6\u8fdf\u3001\u541e\u5410\u7387\u3001\u9762\u79ef\u4e0e\u529f\u8017\u7684\u67b6\u6784\u7ea7\u5efa\u6a21\u3002\u672c\u7ae0\u8fd8\u6307\u5bfc\u8bfb\u8005\u5982\u4f55\u9009\u62e9\u8bc4\u4f30\u7247\u4e0a\u7f51\u7edc\u7684\u6709\u6548\u6307\u6807\uff0c\u5e76\u4ecb\u7ecd\u53ef\u4f5c\u4e3a\u7406\u60f3\u57fa\u51c6\u7684\u7406\u8bba\u6a21\u578b\u3002</p> <p>\u9274\u4e8e\u5f53\u524d\u4e1a\u754c\u4e0e\u5b66\u672f\u754c\u4e2d\u5df2\u6709\u4f17\u591a\u7247\u4e0a\u7f51\u7edc\u82af\u7247\u95ee\u4e16\uff0c\u6211\u4eec\u5728\u65b0\u589e\u7684\u7b2c8\u7ae0\u4e2d\u5bf9\u8fd9\u4e9b\u8bbe\u8ba1\u8fdb\u884c\u4e86\u7cfb\u7edf\u7efc\u8ff0\u3002 \u672c\u7ae0\u5e2e\u52a9\u8bfb\u8005\u5168\u9762\u7406\u89e3\u524d\u51e0\u7ae0\u4e2d\u63d0\u51fa\u7684\u5404\u79cd\u57fa\u7840\u6982\u5ff5\u5982\u4f55\u5728\u5b9e\u9645\u4e2d\u88ab\u7ed3\u5408\u5e94\u7528\uff0c\u4ee5\u53ca\u8fd9\u4e9b\u8bbe\u8ba1\u6982\u5ff5\u5728\u5b9e\u73b0\u8fc7\u7a0b\u4e2d\u7684\u5177\u4f53\u5f71\u54cd\u3002</p> <p>\u6700\u540e\uff0c\u7b2c9\u7ae0\u603b\u7ed3\u4e86\u672a\u6765\u51e0\u5e74\u5c06\u63a8\u52a8\u7247\u4e0a\u7f51\u7edc\u7814\u7a76\u53d1\u5c55\u7684\u5173\u952e\u6311\u6218\u4e0e\u65b0\u5174\u63a2\u7d22\u65b9\u5411\u3002\u53ef\u4ee5\u660e\u786e\u770b\u5230\uff0c\u5df2\u6709\u5927\u91cf\u65b0\u7684\u7814\u7a76\u6210\u679c\u6d8c\u73b0\u51fa\u6765\uff1b\u672c\u7ae0\u805a\u7126\u4e8e\u5176\u4e2d\u4e00\u4e9b\u91cd\u8981\u8d8b\u52bf\uff0c\u5f3a\u8c03\u4e86\u7247\u4e0a\u7f51\u7edc\u7814\u7a76\u7684\u8de8\u5c42\u7279\u6027\u3002\u65b0\u578b\u4e92\u8fde\u4e0e\u5668\u4ef6\u7684\u51fa\u73b0\u663e\u8457\u6539\u53d8\u4e86\u7247\u4e0a\u7f51\u7edc\u7684\u5b9e\u73b0\u6743\u8861\uff0c\u4ece\u800c\u4fc3\u4f7f\u65b0\u7684\u67b6\u6784\u8bbe\u8ba1\u4e0d\u65ad\u6d8c\u73b0\u3002\u6b64\u5916\uff0c\u7531\u4e8e\u5236\u9020\u5de5\u827a\u4e2d\u65e5\u76ca\u589e\u957f\u7684\u5de5\u827a\u6ce2\u52a8\u6027\uff0c\u9c81\u68d2\u6027\uff08resilience\uff09\u5df2\u6210\u4e3a\u4e00\u9879\u65e5\u76ca\u91cd\u8981\u7684\u8bc4\u4f30\u6307\u6807\uff1b\u800c\u9762\u5411\u540c\u65f6\u8fd0\u884c\u591a\u4e2a\u5de5\u4f5c\u8d1f\u8f7d\u7684\u591a\u6838\u7cfb\u7edf\uff0c\u5bf9\u670d\u52a1\u8d28\u91cf\uff08quality-of-service, QoS\uff09\u7684\u9700\u6c42\u4e5f\u5728\u4e0d\u65ad\u4e0a\u5347\u3002\u8fd9\u4e9b\u65b0\u7ef4\u5ea6\u5c06\u5f15\u53d1\u5168\u793e\u533a\u8303\u56f4\u5185\u7684\u7814\u7a76\u63a2\u7d22\u3002</p>"},{"location":"OCN2E/translator.html","title":"\u8bd1\u5e8f","text":"<p>\u8fd1\u6765\u5728\u5f00\u82af\u9662\u5b9e\u4e60\uff0c\u6070\u597d\u8bfb\u5230\u4e86\u4e00\u4e9b NOC \u7684\u5de5\u4f5c\uff0c\u56e0\u6b64\u9605\u8bfb\u6b64\u4e66\u5e76\u987a\u4fbf\u7ffb\u8bd1\u3002</p>"},{"location":"SBCA/ABSTRACT.html","title":"ABSTRACT","text":"<p>\u5bf9\u4e8e\u672a\u6765\u8ba1\u7b97\u673a\u7684\u8bbe\u8ba1\u800c\u8a00\uff0c\u5b89\u5168\u95ee\u9898\u662f\u975e\u5e38\u91cd\u8981\u7684\u8003\u91cf\u65b9\u9762\u3002 \u7136\u800c\uff0c\u5b89\u5168\u95ee\u9898\u5e76\u6ca1\u6709\u88ab\u76ee\u524d\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u793e\u533a\u5b8c\u5584\u5730\u7406\u89e3\u3002 \u5728\u8fc7\u53bb\u7684\u6570\u5341\u5e74\u4e2d\uff0c\u5305\u62ec\u5bc6\u7801\u5b66\u3001\u64cd\u4f5c\u7cfb\u7edf\u3001\u7f51\u7edc\u7b49\u793e\u533a\u53d1\u5c55\u8d77\u4e86\u4e00\u7cfb\u5217\u5b89\u5168\u95ee\u9898\u7684\u91cd\u8981\u65b9\u9762\u3002 \u672c\u4e66\u5c1d\u8bd5\u5411\u8ba1\u7b97\u673a\u67b6\u6784\u9886\u57df\u7684\u5b66\u751f\u3001\u7814\u7a76\u8005\u3001\u4ece\u4e1a\u4eba\u5458\u4ecb\u7ecd\u5b89\u5168\u7684\u57fa\u672c\u6982\u5ff5\u4ee5\u53ca\u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5\u3002 \u8bb8\u591a\u5b89\u5168\u793e\u533a\u8fc7\u53bb\u7684\u5de5\u4f5c\u53ef\u4ee5\u5bf9\u6211\u4eec\u7684\u601d\u8003\u4ea7\u751f\u79ef\u6781\u5f71\u54cd\uff0c\u5e76\u4e14\u63d0\u4f9b\u7528\u4e8e\u5efa\u7acb\u67b6\u6784\u5c42\u9762\u7684\u5bf9\u5b89\u5168\u7684\u652f\u6301\u7684\u4e30\u5bcc\u7684\u6280\u672f\uff0c\u4ee5\u9002\u7528\u4e8e\u5bf9\u672a\u6765\u7684\u8ba1\u7b97\u673a\u4ee5\u53ca\u5bf9\u5d4c\u5165\u5f0f\u8ba1\u7b97\u8bbe\u5907\u7684\u8bbe\u8ba1\u3002 \u6211\u52aa\u529b\u4f7f\u672c\u4e66\u66f4\u7b80\u77ed\uff0c\u4f46\u8fd9\u4e5f\u5c31\u610f\u5473\u7740\u8bb8\u591a\u6709\u8da3\u7684\u9886\u57df\u548c\u5e94\u7528\u5e76\u6ca1\u6709\u88ab\u672c\u4e66\u6db5\u76d6\u3002 \u672c\u4e66\u5173\u6ce8\u7684\u662f\u6700\u57fa\u7840\u6027\u7684\u5b89\u5168\u7406\u5ff5\uff0c\u6d89\u53ca\u5230\u4e0d\u540c\u7684\u5b89\u5168\u793e\u533a\u3002 \u4efb\u4f55\u5c1d\u8bd5\u8bbe\u8ba1\u6216\u8861\u91cf\u6ce8\u91cd\u5b89\u5168\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u90fd\u5e94\u8be5\u719f\u6089\u8fd9\u4e9b\u6982\u5ff5\u3002</p> <p>\u672c\u4e66\u540c\u6837\u65e8\u5728\u5411\u66f4\u5e7f\u5927\u7684\u5bf9\u57fa\u7840\u7684\u5b89\u5168\u6280\u672f\u611f\u5174\u8da3\u7684\u8bfb\u8005\u3002 \u901a\u8fc7\u7406\u89e3\u8fd9\u4e9b\u5b89\u5168\u6280\u672f\u80cc\u540e\u7684\u5b89\u5168\u7406\u5ff5\uff0c\u8bfb\u8005\u4f1a\u66f4\u52a0\u6e05\u695a\u5730\u660e\u767d\u65b0\u95fb\u4e2d\u8fd1\u671f\u7684\u5b89\u5168\u6f0f\u6d1e\u662f\u4ec0\u4e48\uff0c\u5e76\u52a0\u4ee5\u8bc4\u5224\u6216\u63d0\u51fa\u89e3\u51b3\u65b9\u6848\u3002</p>"},{"location":"SBCA/ABSTRACT.html#keywords","title":"KEYWORDS","text":"<p>computer security, trustworthy somputing, hardware security, cryptography, security policies, access control, secure processors, confidentialty and intergrity</p> <p>\u8ba1\u7b97\u673a\u5b89\u5168\uff0c\u53ef\u4fe1\u8ba1\u7b97\uff0c\u786c\u4ef6\u5b89\u5168\uff0c\u5bc6\u7801\u5b66\uff0c\u5b89\u5168\u7b56\u7565\uff0c\u8bbf\u95ee\u63a7\u5236\uff0c\u5b89\u5168\u5904\u7406\u5668\uff0c\u4fdd\u5bc6\u6027\u548c\u5b8c\u6574\u6027</p>"},{"location":"SBCA/C1.html","title":"Threat-Based Design \u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5","text":"<p>\u8ba1\u7b97\u673a\u8bbe\u8ba1\u65f6\u8003\u8651\u5230\u529f\u80fd\u3001\u6027\u80fd\u3001\u6210\u672c\u3001\u529f\u8017\u3001\u9762\u79ef\u548c\u53ef\u7528\u6027\u3002 \u968f\u7740\u6211\u4eec\u5bf9\u4e8e\u8ba1\u7b97\u673a\u7684\u4f9d\u8d56\u65e5\u76ca\u63d0\u9ad8\uff0c\u4ee5\u53ca\u9488\u5bf9\u6570\u5b57\u7cfb\u7edf\u7684\u7f51\u7edc\u653b\u51fb\u65e5\u76ca\u589e\u591a\uff0c\u8bbe\u8ba1\u63d0\u9ad8\u5b89\u5168\u7684\u8ba1\u7b97\u673a\u7cfb\u7edf\u53d8\u5f97\u81f3\u5173\u91cd\u8981\u3002 \u9762\u5411\u5b89\u5168\u7684\u8bbe\u8ba1\u5047\u5b9a\u653b\u51fb\u8005\u7684\u5b58\u5728\uff0c\u5176\u5c06\u5c1d\u8bd5\u5229\u7528\u8ba1\u7b97\u673a\u7cfb\u7edf\u8fdb\u884c\u6076\u610f\u884c\u4e3a\u3002 \u6211\u4eec\u79f0\u8fd9\u79cd\u8bbe\u8ba1\u65b9\u5f0f\u4e3a\u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5\u3002 \u8fd9\u79cd\u5b89\u5168\u6027\u8bbe\u8ba1\u5e94\u8be5\u4e0e\u6027\u80fd\u3001\u6210\u672c\u3001\u80fd\u6e90\u6548\u7387\u3001\u5c0f\u578b\u5316\u548c\u53ef\u7528\u6027\u8bbe\u8ba1\u540c\u65f6\u8fdb\u884c\u3002</p> <p>\u90a3\u4e48\u4ec0\u4e48\u662f\u6709\u98ce\u9669\u7684\u5462\uff1f \u4e3e\u51e0\u4e2a\u4f8b\u5b50\uff0c\u56fd\u5bb6\u548c\u56fd\u9645\u5b89\u5168\u3001\u91d1\u878d\u4ea4\u6613\u548c\u7ecf\u6d4e\u7ade\u4e89\u529b\u4ee5\u53ca\u4e2a\u4eba\u5b89\u5168\u548c\u9690\u79c1\u90fd\u9762\u4e34\u98ce\u9669\u3002 \u4e00\u822c\u6765\u8bf4\uff0c\u5bf9\u67d0\u4eba\u6216\u67d0\u4e2a\u5b9e\u4f53\u6709\u4ef7\u503c\u7684\u8d44\u4ea7\u90fd\u9762\u4e34\u98ce\u9669\u3002\u8fd9\u4e9b\u8d44\u4ea7\u7684\u5b9a\u4e49\u5f88\u5e7f\u6cdb\uff0c\u53ef\u80fd\u5305\u62ec\u4fe1\u606f\u6280\u672f (IT) \u57fa\u7840\u8bbe\u65bd\u3001\u5173\u952e\u57fa\u7840\u8bbe\u65bd\uff08\u4f8b\u5982\u7535\u7f51\uff09\u3001\u77e5\u8bc6\u4ea7\u6743\u3001\u8d22\u52a1\u6570\u636e\u3001\u670d\u52a1\u53ef\u7528\u6027\u3001\u751f\u4ea7\u529b\u3001\u654f\u611f\u4fe1\u606f\u3001\u4e2a\u4eba\u4fe1\u606f\u548c\u58f0\u8a89\u3002</p> <p>\u6211\u4eec\u79f0\u4e00\u79cd\u5a01\u80c1\u662f\u4e00\u7c7b\u653b\u51fb\uff0c\u5176\u8fdd\u80cc\u4e86\u4e00\u79cd\u6216\u591a\u79cd\u5b89\u5168\u7279\u6027\u3002 \u6211\u4eec\u79f0\u4e00\u4e2a\u653b\u51fb\u662f\u4e00\u4e2a\u5a01\u80c1\u7684\u5b9e\u4f8b\u3002 \u4e3a\u4e86\u66f4\u597d\u5730\u7406\u89e3\u5a01\u80c1\u548c\u653b\u51fb\uff0c\u6211\u4eec\u9700\u8981\u9996\u5148\u5b9a\u4e49\u5b89\u5168\u4e2d\u7684\u4e00\u4e9b\u6982\u5ff5\u3002</p>"},{"location":"SBCA/C1.html#security-properties","title":"SECURITY PROPERTIES \u5b89\u5168\u7279\u6027","text":""},{"location":"SBCA/C1.html#cornerstone-security-properties","title":"CORNERSTONE SECURITY PROPERTIES \u4e09\u5927\u57fa\u77f3\u5b89\u5168\u7279\u6027","text":"<p>\u8ba1\u7b97\u673a\u548c\u901a\u4fe1\u7cfb\u7edf\u9700\u8981\u6216\u671f\u671b\u5177\u6709\u8bb8\u591a\u5b89\u5168\u5c5e\u6027\u3002 \u5176\u4e2d\u4e09\u79cd\u5c5e\u6027\u88ab\u79f0\u4e3a\u57fa\u77f3\u5b89\u5168\u7279\u6027\uff1a</p> <ul> <li>\u673a\u5bc6\u6027(Confidentiality)</li> <li>\u5b8c\u6574\u6027(Integrity)</li> <li>\u53ef\u7528\u6027(Availability)</li> </ul> <p>\u6211\u4eec\u5c06\u5176\u7f29\u5199\u4e3aCIA\uff0c\u8fd9\u5f88\u5bb9\u6613\u8bb0\u5fc6\uff0c\u56e0\u4e3a\u5b83\u4e0e\u7f8e\u56fd\u4e2d\u592e\u60c5\u62a5\u5c40\u540c\u540d\u3002</p> <p>\u673a\u5bc6\u6027\u662f\u6307\u9632\u6b62\u79d8\u5bc6\u6216\u654f\u611f\u4fe1\u606f\u5bf9\u672a\u6388\u6743\u7684\u7528\u6237\u6216\u5b9e\u4f53\u6cc4\u9732\u3002 \u5b8c\u6574\u6027\u662f\u6307\u9632\u6b62\u4e0d\u80fd\u88ab\u5bdf\u89c9\u7684\u672a\u6388\u6743\u7be1\u6539\u3002 \u53ef\u7528\u6027\u662f\u6307\u786e\u4fdd\u7cfb\u7edf\u5bf9\u4e8e\u5408\u6cd5\u7528\u6237\u662f\u968f\u65f6\u53ef\u7528\u7684\u3002 \u53ef\u7528\u6027\u540c\u6837\u4e5f\u662f\u63d0\u4f9b\u4e00\u4e2a\u53ef\u9760\u3001\u53ef\u4fe1\u4e14\u5bb9\u9519\u7cfb\u7edf\u7684\u76ee\u6807\uff0c\u4e0d\u8fc7\u5728\u5b89\u5168\u7684\u610f\u4e49\u4e0b\uff0c\u53ef\u7528\u6027\u5fc5\u987b\u8003\u8651\u5177\u6709\u6076\u610f\u610f\u56fe\u7684\u667a\u80fd\u653b\u51fb\u8005\uff0c\u800c\u4e0d\u4ec5\u4ec5\u662f\u8bbe\u5907\u6545\u969c\u548c\u6545\u969c\u3002 \u540e\u8005\u7684\u7279\u5f81\u66f4\u5bb9\u6613\u5efa\u6a21\uff0c\u76f8\u53cd\u5176\u884c\u4e3a\u901a\u5e38\u5f88\u96be\u7528\u6982\u7387\u5206\u5e03\u5efa\u6a21\u3002</p> <p>\u4e0a\u8ff0\u4e09\u8005\u5f88\u96be\u8bf4\u8c01\u66f4\u91cd\u8981\u3002 \u673a\u5bc6\u6027\u5bf9\u4e8e\u79d8\u5bc6\u7684\u3001\u654f\u611f\u7684\u3001\u79c1\u6709\u7684\u4fe1\u606f\u6700\u91cd\u8981\u3002 \u5bf9\u4e8e\u673a\u5bc6\u6027\u7684\u8fdd\u53cd\u5728\u4eca\u5929\u53ef\u80fd\u6bd4\u4ee5\u5f80\u66f4\u5177\u7834\u574f\u6027\uff0c\u56e0\u4e3a\u4e00\u65e6\u673a\u5bc6\u4fe1\u606f\u5457\u516c\u5f00\u5728\u4e92\u8054\u7f51\u4e0a\uff0c\u5c31\u53ef\u4ee5\u88ab\u6240\u6709\u4eba\u8bbf\u95ee\u4e14\u6c38\u8fdc\u65e0\u6cd5\u5220\u9664\u3002</p> <p>\u5c3d\u7ba1\u5982\u6b64\uff0c\u5bf9\u4e8e\u4f60\u7684\u94f6\u884c\u4f59\u989d\u6765\u8bf4\uff0c\u867d\u7136\u673a\u5bc6\u6027\u5f88\u91cd\u8981\uff0c\u4f46\u5b8c\u6574\u6027\u53ef\u80fd\u66f4\u91cd\u8981\u2014\u2014\u4f60\u5e76\u4e0d\u5e0c\u671b\u4f60\u7684\u94f6\u884c\u8d26\u6237\u88ab\u7b2c\u4e09\u65b9\u6076\u610f\u7be1\u6539\u3002</p> <p>\u53ef\u7528\u6027\u5bf9\u4e8e\u5173\u952e\u4efb\u52a1\u81f3\u5173\u91cd\u8981\uff0c\u8bf8\u5982\u90a3\u4e9b\u5f71\u54cd\u56fd\u5bb6\u5b89\u5168\u6216\u8005\u7ecf\u6d4e\u7ade\u4e89\u7684\u4efb\u52a1\u3002 \u4f8b\u5982\uff0c\u5f53\u80a1\u7968\u7ecf\u7eaa\u4eba\u9700\u8981\u8fdb\u884c\u5728\u7ebf\u80a1\u7968\u4ea4\u6613\u65f6\uff0c\u4e92\u8054\u7f51\u548c\u5728\u7ebf\u4ea4\u6613\u670d\u52a1\u7684\u53ef\u7528\u6027\uff08\u6216\u5176\u53cd\u9762\uff0c\u62d2\u7edd\u670d\u52a1\uff0cDOS\uff09\u53ef\u80fd\u5bfc\u81f4\u5229\u6da6\u6216\u635f\u5931\u7684\u5de8\u5927\u5dee\u5f02\u3002</p>"},{"location":"SBCA/C1.html#access-control","title":"ACCESS CONTROL \u8bbf\u95ee\u63a7\u5236","text":"<p>\u4fdd\u62a4\u654f\u611f\u4fe1\u606f\u7684\u673a\u5bc6\u6027\u3001\u5b8c\u6574\u6027\u6216\u53ef\u7528\u6027\u901a\u5e38\u4e0e\u9650\u5236\u53ea\u6709\u90a3\u4e9b\u88ab\u5141\u8bb8\u8bbf\u95ee\u8be5\u4fe1\u606f\u7684\u4eba\u624d\u80fd\u8bbf\u95ee\u6709\u5173\uff0c\u8fd9\u4e5f\u79f0\u4e3a\u8bbf\u95ee\u63a7\u5236(access control)\u3002 \u4f8b\u5982\uff0c\u4f60\u4f7f\u7528\u5bc6\u7801\u5411\u8ba1\u7b97\u673a\u7cfb\u7edf\u8ba4\u8bc1(authenticate)\u4f60\u7684\u8eab\u4efd\uff0c\u4ee5\u4fbf\u8bbf\u95ee\u5176\u8d44\u6e90\u548c\u5b58\u50a8\u5728\u5176\u4e2d\u7684\u6587\u6863\u3002 \u767b\u5f55\u5230\u540c\u4e00\u7cfb\u7edf\u7684\u7cfb\u7edf\u7ba1\u7406\u5458\u5c06\u88ab\u6388\u6743(authorized)\u6267\u884c\u6bd4\u666e\u901a\u7528\u6237\u66f4\u591a\u7684\u529f\u80fd\u3002 \u56e0\u6b64\uff0c\u6211\u4eec\u8bf4\u8bbf\u95ee\u63a7\u5236\u786e\u4fdd\u53ea\u6709\u88ab\u6388\u6743\u8bbf\u95ee\u67d0\u4e9b\u4fe1\u606f\u7684\u8ba4\u8bc1\u7528\u6237\u624d\u80fd\u8bbf\u95ee\u8be5\u6750\u6599\uff0c\u540c\u65f6\u62d2\u7edd\u672a\u7ecf\u6388\u6743\u7684\u5404\u65b9\u8bbf\u95ee\u3002<sup>1</sup></p> <p>\u8ba4\u8bc1\u56de\u7b54\u7684\u95ee\u9898\u662f\u201c\u8c01\u80fd\u53bb\uff1f\u201d \u6211\u4eec\u8003\u8651\u4e00\u4e2a\u88ab\u8ba4\u8bc1\u4e86\u7684\u4eba\uff0cJohn Bates\u3002 \u6388\u6743\u56de\u7b54\u4e86\u95ee\u9898\u201cJohn Bates\u88ab\u5141\u8bb8\u505a\u4ec0\u4e48\uff1f\u201d \u8fd9\u4e24\u8005\u5728\u4e00\u8d77\u6784\u6210\u4e86\u5bf9\u96e8\u53d7\u4fdd\u62a4\u5bf9\u8c61\u7684\u5408\u6cd5\u8bbf\u95ee\u63a7\u5236\u7684\u91cd\u8981\u7ec4\u6210\u90e8\u5206\u3002 AAA\u7684\u7f29\u5199\u53ef\u4ee5\u5e2e\u52a9\u6211\u4eec\u8bb0\u4f4f\u8fd9\u4e2a\u91cd\u8981\u7684\u5b89\u5168\u65b9\u6cd5\uff1a\u8bbf\u95ee\u63a7\u5236\uff0c\u5305\u62ec\u8ba4\u8bc1\u548c\u6388\u6743(Access control, comprising Authentication and Authorization)\u3002 \u8ba4\u8bc1\u548c\u6388\u6743\u7684\u6982\u5ff5\u53ef\u4ee5\u9002\u7528\u4e8e\u8ba1\u7b97\u673a\u3001\u8bbe\u5907\u548c\u7a0b\u5e8f\uff0c\u800c\u4e0d\u4ec5\u4ec5\u5bf9\u4eba\u7c7b\u3002</p> <p>\u8868\u683c1.1\u5217\u51fa\u4e86\u57fa\u77f3\u5b89\u5168\u7279\u6027\u4ee5\u53ca\u5176\u4ed6\u51e0\u4e2a\u6211\u4eec\u60f3\u8981\u7684\u5b89\u5168\u7279\u6027\u3002 \u4e86\u89e3\u5176\u4ed6\u60f3\u8981\u7684\u5b89\u5168\u5c5e\u6027\u6709\u54ea\u4e9b\u662f\u5f88\u91cd\u8981\u7684\uff0c\u5c3d\u7ba1\u5728\u672c\u4e66\u5269\u4e0b\u7684\u90e8\u5206\u4e2d\uff0c\u6211\u4eec\u4ec5\u5173\u6ce8\u57fa\u77f3\u5b89\u5168\u7279\u6027\uff08CIA\uff09\u3002</p> <p></p> <p>\u6211\u4eec\u5bf9\u5b89\u5168\u5c5e\u6027\u548c\u7279\u6027\u8fdb\u884c\u4e86\u975e\u5e38\u5e7f\u6cdb\u7684\u5b9a\u4e49\uff0c\u5176\u4e2d\u8fd8\u5305\u62ec\u9690\u79c1\u548c\u533f\u540d\u7b49\u5c5e\u6027\uff0c\u8fd9\u4e9b\u5c5e\u6027\u901a\u5e38\u4e0e\u5b89\u5168\u6027\u5206\u5f00\u5217\u51fa\u3002 \u8bf7\u6ce8\u610f\uff0c\u67d0\u4e9b\u5b89\u5168\u5c5e\u6027\u5f7c\u6b64\u77db\u76fe\u3002\u4f8b\u5982\uff0c\u533f\u540d\u548c\u8eab\u4efd\u9a8c\u8bc1\u53ef\u80fd\u76f8\u4e92\u77db\u76fe\u3002 \u8bf7\u6ce8\u610f\uff0c\u533f\u540d\u5bf9\u653b\u51fb\u8005\u6765\u8bf4\u4e5f\u975e\u5e38\u6709\u5229\u3002</p> <p>\u867d\u7136\u201c\u673a\u5bc6\u6027\u201d\u548c\u201c\u9690\u79c1\u201d\u8fd9\u4e24\u4e2a\u672f\u8bed\u5728\u6587\u732e\u4e2d\u6709\u65f6\u53ef\u4ee5\u4e92\u6362\u4f7f\u7528\uff0c\u4f46\u6211\u4eec\u5f3a\u70c8\u5efa\u8bae\u5bf9\u5b83\u4eec\u8fdb\u884c\u5982\u4e0b\u533a\u5206\uff1a \u673a\u5bc6\u6027\u662f\u4fdd\u62a4\u79d8\u5bc6\u6216\u654f\u611f\u4fe1\u606f\u7684\u4e49\u52a1\uff0c\u800c\u9690\u79c1\u662f\u51b3\u5b9a\u5982\u4f55\u5206\u53d1\u6216\u91cd\u65b0\u5206\u53d1\u4e2a\u4eba\u4fe1\u606f\u7684\u6743\u5229\u3002</p>"},{"location":"SBCA/C1.html#trustworthy-versus-trusted","title":"TRUSTWORTHY VERSUS TRUSTED \u53ef\u4fe1\u7684\u4e0e\u4fe1\u4efb\u7684","text":"<p>\u7406\u60f3\u60c5\u51b5\u4e0b\uff0c\u5b89\u5168\u8ba1\u7b97\u673a\u7cfb\u7edf\u81f3\u5c11\u63d0\u4f9b\u673a\u5bc6\u6027\u3001\u5b8c\u6574\u6027\u548c\u53ef\u7528\u6027\u8fd9\u4e09\u4e2a\u57fa\u672c\u5b89\u5168\u5c5e\u6027\u3002 \u7136\u800c\uff0c\u8fd9\u901a\u5e38\u65e2\u4e0d\u53ef\u80fd\u4e5f\u6ca1\u6709\u5fc5\u8981\uff0c\u5728\u8bb8\u591a\u60c5\u51b5\u4e0b\uff0c\u63d0\u4f9b\u8fd9\u4e9b\u5c5e\u6027\u7684\u4e0d\u540c\u5b50\u96c6\uff08\u4e5f\u6709\u53ef\u80fd\u662f\u8d85\u96c6\uff09\u53ef\u80fd\u5c31\u8db3\u591f\u4e86\u3002 \u6211\u4eec\u5c06\u5728\u672c\u7ae0\u540e\u9762\u548c\u6574\u672c\u4e66\u4e2d\u8fdb\u4e00\u6b65\u8ba8\u8bba\u8fd9\u4e00\u70b9\u3002</p> <p>\u4e00\u4e2a\u53ef\u4fe1\u8ba1\u7b97\u673a(trustworthy computer)\u662f\u6307\u88ab\u8bbe\u8ba1\u6210\u53ef\u9760\u7684\u5e76\u63d0\u4f9b\u5b89\u5168\u7279\u6027\uff0c\u5b8c\u6210\u5b83\u88ab\u8bbe\u8ba1\u7684\u5de5\u4f5c\u5e76\u4e14\u4e0d\u4f1a\u4ea7\u751f\u5bf9\u5b83\u6216\u8005\u522b\u7684\u7cfb\u7edf\u7684\u6709\u5bb3\u5f71\u54cd\u3002 \u76f8\u53cd\uff0c\u8fc7\u53bb\u4eba\u4eec\u63d0\u51fa\u7684\u90fd\u662f\u4fe1\u4efb\u7684\u8ba1\u7b97\u673a(trusted computer)\uff0c\u5373\u4eba\u4eec\u4f9d\u8d56\u5b83\u53bb\u5b9e\u73b0\u5b89\u5168\u7b56\u7565\u3002 \u5982\u679c\u4e00\u4e2a\u4fe1\u4efb\u7684\u8ba1\u7b97\u673a\uff08\u6216\u8005\u4fe1\u4efb\u7684\u4eba\uff09\u8fdd\u80cc\u4e86\u4fe1\u4efb\uff0c\u90a3\u4e48\u6267\u884c\u5b89\u5168\u7b56\u7565\u7684\u6240\u6709\u52aa\u529b\u90fd\u5c06\u5931\u8d25\u3002 \u4fe1\u4efb\u7684\u8ba1\u7b97\u673a\u672a\u5fc5\u53ef\u4fe1\uff0c\u53cd\u4e4b\u4ea6\u7136\u3002</p> <p>\u4f8b\u5982\uff0c\u5c06\u519b\u662f\u53d7\u4fe1\u4efb\u7684\uff0c\u4f46\u662f\u4e00\u4e2a\u8150\u8d25\u7684\u5411\u654c\u65b9\u6cc4\u9732\u519b\u4e8b\u673a\u5bc6\u7684\u5c06\u519b\u662f\u4e0d\u53ef\u4fe1\u7684\u3002 \u56e0\u6b64\uff0c\u4ee5\u6765\u53d7\u4fe1\u4efb\u7684\u5c06\u519b\u7684\u5b89\u5168\u7b56\u7565\u53ef\u80fd\u4f1a\u88ab\u7a81\u7834\u3002 \u76f8\u4f3c\u5730\uff0c\u4e00\u4e2a\u8ba1\u7b97\u673a\u7cfb\u7edf\u6709\u65f6\u88ab\u6211\u4eec\u76f2\u76ee\u4fe1\u4efb\uff0c\u7528\u4e8e\u4fdd\u5b58\u67d0\u4e9b\u673a\u5bc6\u4fe1\u606f\uff0c\u4f46\u662f\u5b83\u53ef\u80fd\u4ece\u8bbe\u8ba1\u4e4b\u521d\u5c31\u4e0d\u662f\u53ef\u4fe1\u7684\u3002 \u4e0d\u5e78\u7684\u662f\uff0c\u8fd9\u79cd\u5c31\u662f\u6211\u4eec\u5e73\u65f6\u5927\u91cf\u4f7f\u7528\u7684\u5546\u54c1\u8ba1\u7b97\u673a\u7684\u5e38\u89c1\u60c5\u51b5\u3002</p> <p>\u5bf9\u4e8e\u8ba1\u7b97\u673a\u7cfb\u7edf\uff0c\u672f\u8bed\u4fe1\u4efb\u8ba1\u7b97\u57fa\uff08trusted computing base, TCB\uff09\u6307\u4e00\u7ec4\u786c\u4ef6\u548c\u8f6f\u4ef6\u7ec4\u4ef6\uff0c\u5982\u679c\u8fdd\u53cd\u8be5\u7ec4\u4ef6\uff0c\u5219\u610f\u5473\u7740\u5b89\u5168\u7b56\u7565\u53ef\u80fd\u65e0\u6cd5\u6267\u884c\u3002 \u4e0d\u5e78\u7684\u662f\uff0c\u76ee\u524d\u6ca1\u6709\u4e00\u79cd COTS\uff08Commodity Off-The-Shelf\uff0c\u73b0\u6210\u5546\u54c1\uff09\u8ba1\u7b97\u673a\u7cfb\u7edf\u80fd\u591f\u5b9e\u73b0\u53ef\u9760\u7684\u53ef\u4fe1\u8ba1\u7b97\u57fa\u7840\u3002 \u4e8b\u5b9e\u4e0a\uff0cCOTS \u8ba1\u7b97\u673a\u7684\u8bbe\u8ba1\u5e76\u4e0d\u503c\u5f97\u4fe1\u8d56\u3002 \u5b89\u5168\u6027\u901a\u5e38\u662f\u4e8b\u540e\u624d\u6dfb\u52a0\u7684\uff0c\u8fd9\u4f1a\u5bfc\u81f4\u6027\u80fd\u3001\u6210\u672c\u3001\u4e0a\u5e02\u65f6\u95f4\u548c\u6613\u7528\u6027\u4e0b\u964d\u3002</p> <p>\u4e3a\u4e86\u672a\u6765\u7684 COTS \u8ba1\u7b97\u673a\u53ef\u4ee5\u53d8\u5f97\u53ef\u4fe1\uff0c\u6211\u4eec\u9700\u8981\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u7406\u89e3\u5b89\u5168\u95ee\u9898\u3002 \u4eca\u5929\uff0c\u5b89\u5168\u95ee\u9898\u5728\u7f8e\u56fd\u9ad8\u6821\u7684\u8f6f\u786c\u4ef6\u8bfe\u7a0b\u4e2d\u90fd\u4e0d\u88ab\u6d89\u53ca\u3002 \u53bb\u5f25\u8865\u8fd9\u4e2a\u4e8b\u5b9e\u662f\u5341\u5206\u91cd\u8981\u7684\uff0c\u5373\u4f7f\u5f97\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u3001\u7cfb\u7edf\u8bbe\u8ba1\u8005\u548c\u5b66\u751f\u7406\u89e3\u3001\u7814\u7a76\u3001\u8bbe\u8ba1\u3001\u53d1\u5c55\u53ef\u4fe1\u8ba1\u7b97\u673a\u7cfb\u7edf\u3002</p> <p>\u56e0\u4e3a\u786e\u4fdd\u5de8\u5927\u4e14\u590d\u6742\u7684\u8f6f\u786c\u4ef6\u7cfb\u7edf\u996d\u5708\u4e0d\u53d7bugs\u548c\u5b89\u5168\u6f0f\u6d1e\u5a01\u80c1\u662f\u56f0\u96be\u751a\u81f3\u4e0d\u53ef\u80fd\u7684\uff0c\u6211\u4eec\u9700\u8981\u4f7f\u5f97\u4fe1\u4efb\u8ba1\u7b97\u57fa(TCB)\u5c3d\u53ef\u80fd\u5c0f\uff0c\u4ee5\u6700\u5927\u5316\u5b83\u6b63\u786e\u4e14\u4e0d\u53d7\u5b89\u5168\u6f0f\u6d1e\u5a01\u80c1\u7684\u53ef\u80fd\u6027\u3002 \u6240\u8c13\u5bf9\u4e8e\u4e00\u4e2a\u5b9e\u4f53\uff08\u5982TCB\uff09\u7684\u653b\u51fb\u754c\u9762(attack surface)\u662f\u6307\u653b\u51fb\u8005\u53ef\u4ee5\u7ecf\u7531\u800c\u6e17\u900f\u8fdb\u5b9e\u4f53\u7684\u90e8\u5206\uff1b\u5177\u4f53\u6e17\u900f\u7684\u624b\u6bb5\u548c\u65b9\u6cd5\u6211\u4eec\u79f0\u4e4b\u4e3a\u653b\u51fb\u77e2\u91cf(attack vector)\u3002 \u66f4\u5c0f\u7684TCB\u610f\u5473\u7740\u653b\u51fb\u8005\u53ef\u4ee5\u7528\u4e8e\u6e17\u900f\u8fdb\u5165\u7cfb\u7edf\u3001\u7834\u574f\u5176\u5b8c\u6574\u6027\u6216\u5077\u7a83\u5176\u79d8\u5bc6\u7684\u653b\u51fb\u754c\u9762\u548c\u653b\u51fb\u77e2\u91cf\u66f4\u5c0f\u3002 \u6b64\u5916\uff0c\u8f83\u5c0f\u7684\u4fe1\u4efb\u8f6f\u4ef6\u7ec4\u4ef6\u6bd4\u5927\u578b\u3001\u590d\u6742\u7684\u8f6f\u4ef6\u7ec4\u4ef6\u66f4\u9002\u5408\u5f62\u5f0f\u5316\u9a8c\u8bc1\u6280\u672f\u3002</p>"},{"location":"SBCA/C1.html#threats-and-attacks","title":"THREATS AND ATTACKS \u5a01\u80c1\u548c\u653b\u51fb","text":"<p>\u6240\u8c13\u5b89\u5168\u7f3a\u53e3(security breach)\u662f\u6307\u4e00\u4e2a\u8fdd\u80cc\u5b89\u5168\u7279\u6027\u7684\u4e8b\u4ef6\u3002 (A security breach is an event that violates a security property.) \u4f8b\u5982\uff0c\u5b83\u53ef\u4ee5\u662f\u673a\u5bc6\u6027\u3001\u5b8c\u6574\u6027\u6216\u53ef\u7528\u6027\u7684\u7f3a\u53e3\u3002 \u4e00\u4e2a\u5b89\u5168\u7f3a\u53e3\u53ef\u80fd\u662f\u6545\u610f\u5f15\u8d77\u7684\uff0c\u4e5f\u53ef\u80fd\u662f\u65e0\u610f\u7684\u3002</p> <p>\u5a01\u80c1(threat)\u662f\u6307\u4efb\u4f55\u53ef\u4ee5\u7834\u574f\u6709\u4ef7\u503c\u8d44\u4ea7\u6216\u5f15\u8d77\u5b89\u5168\u7f3a\u53e3\u7684\u884c\u4e3a\u3002 \u4f8b\u5982\uff0c\u5b58\u5728\u6cc4\u9732\u5a01\u80c1\u3001\u4fee\u6539\u5a01\u80c1\u548c\u62d2\u7edd\u670d\u52a1\u5a01\u80c1\uff0c\u5b83\u4eec\u5206\u522b\u5a01\u80c1\u5230\u4fdd\u62a4\u673a\u5bc6\u6027\u3001\u5b8c\u6574\u6027\u548c\u53ef\u7528\u6027\u7684\u4e3b\u8981\u5b89\u5168\u76ee\u6807\u3002</p> <p>\u653b\u51fb(attack)\u662f\u6307\u5a01\u80c1\u7684\u7279\u5b9a\u5b9e\u4f8b\u3002 \u5b83\u5305\u62ec\u4e86\u5bf9\u4e8e\u7cfb\u7edf\u3001\u5229\u7528\u7684\u6f0f\u6d1e\u3001\u653b\u51fb\u7684\u65b9\u5f0f\u548c\u88ab\u653b\u51fb\u7684\u8d44\u4ea7\u7684\u7ec6\u8282\u63cf\u8ff0\u3002</p> <p>\u6f0f\u6d1e(vulnerability)\u662f\u6307\u7cfb\u7edf\u4e2d\u7684\u4e00\u4e2a\u5f31\u70b9\uff0c\u5b83\u53ef\u4ee5\u88ab\u5229\u7528\u53bb\u9020\u6210\u5bf9\u6709\u4ef7\u503c\u8d44\u4ea7\u7684\u7834\u574f\u3002 \u5728\u4e00\u4e2a\u653b\u51fb\u4e2d\uff0c\u653b\u51fb\u8005\u53ef\u80fd\u5229\u7528\u4e00\u4e2a\u6216\u591a\u4e2a\u6f0f\u6d1e\u3002</p> <p>\u8868\u683c1.2\u5217\u51fa\u4e86\u4e00\u4e9b\u5a01\u80c1\u548c\u5178\u578b\u7684\u653b\u51fb\u3002 \u5176\u4e2d\u4e00\u4e9b\u653b\u51fb\u4ece\u540d\u79f0\u4e0a\u5c31\u4e00\u76ee\u4e86\u7136\uff0c\u800c\u5176\u4ed6\u653b\u51fb\u5c06\u5728\u540e\u9762\u7684\u7ae0\u8282\u4e2d\u8be6\u7ec6\u63cf\u8ff0\u3002 \u5217\u8868\u548c\u793a\u4f8b\u65e8\u5728\u8bf4\u660e\u6027\uff0c\u800c\u4e0d\u662f\u5168\u9762\u6027\u3002 \u5927\u591a\u6570\u653b\u51fb\u6700\u7ec8\u90fd\u4f1a\u5bfc\u81f4\u673a\u5bc6\u6027\u3001\u5b8c\u6574\u6027\u6216\u53ef\u7528\u6027\u7684\u7834\u574f\u3002 \u867d\u7136\u6211\u4eec\u4e0d\u4f1a\u5728\u8fd9\u91cc\u63cf\u8ff0\u6bcf\u79cd\u653b\u51fb\uff0c\u4f46\u611f\u5174\u8da3\u7684\u7528\u6237\u53ef\u4ee5\u901a\u8fc7 Google \u641c\u7d22\u8f7b\u677e\u627e\u5230\u5b83\u4eec\u7684\u63cf\u8ff0\u3002 \u8fd9\u91cc\u7684\u76ee\u6807\u53ea\u662f\u8bf4\u660e\u5e7f\u6cdb\u7684\u5df2\u53d1\u73b0\u7684\u653b\u51fb\u3002</p> <p></p> <p>\u4e3a\u4e86\u6210\u529f\u5730\u9632\u5fa1\u653b\u51fb\uff0c\u6211\u4eec\u9700\u8981\u4e86\u89e3\u653b\u51fb\u8005\u7684\u52a8\u673a\u53ca\u5176\u601d\u8003\u65b9\u5f0f\u3002 \u201d\u4e86\u89e3\u4f60\u7684\u654c\u4eba\u201c\u662f\u91cd\u8981\u7684\u9632\u5fa1\u7b56\u7565\u4ee5\u53ca\u201c\u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5\u201d\u7684\u57fa\u7840\u3002</p> <p>\u201c\u9ed1\u5e3d\u9ed1\u5ba2\u201d\u662f\u6307\u4e3a\u4e86\u6076\u610f\u76ee\u7684\u800c\u5b9e\u65bd\u653b\u51fb\u7684\u4eba\uff0c\u800c\u201c\u767d\u5e3d\u9ed1\u5ba2\u201d\u662f\u6307\u50cf\u653b\u51fb\u8005\u4e00\u6837\u601d\u8003\u3001\u63d0\u8bae\u751a\u81f3\u6267\u884c\u90e8\u5206\u653b\u51fb\u4ee5\u63d0\u9192\u7ec4\u7ec7\u52a0\u5f3a\u9632\u5fa1\u7684\u4eba\u3002</p> <p>\u7f51\u7edc\u653b\u51fb\u8005(cyber attackers)\u5df2\u4ece\u4e3a\u4e50\u8da3\u548c\u540d\u58f0\u800c\u53d1\u52a8\u653b\u51fb\u7684\u9ed1\u5ba2\uff0c\u6f14\u53d8\u4e3a\u5229\u7528\u7f51\u7edc\u653b\u51fb\u8fdb\u884c\u52d2\u7d22\u6216\u8bc8\u9a97\u7684\u72af\u7f6a\u5b9e\u4f53\uff0c\u518d\u6f14\u53d8\u4e3a\u8d22\u529b\u96c4\u539a\u3001\u6280\u80fd\u7cbe\u6e5b\u7684\u9ad8\u7aef\u7f51\u7edc\u653b\u51fb\u8005\u3002 \u8fd9\u4e9b\u653b\u51fb\u8005\u53ef\u80fd\u662f\u8bd5\u56fe\u6467\u6bc1\u7535\u7f51\u7b49\u5173\u952e\u57fa\u7840\u8bbe\u65bd\u7684\u7f51\u7edc\u6050\u6016\u7ec4\u7ec7\uff0c\u4e5f\u53ef\u80fd\u662f\u6709\u80fd\u529b\u53d1\u52a8\u7f51\u7edc\u6218\u7684\u56fd\u5bb6\u653b\u51fb\u8005\u3002 \u56e0\u6b64\uff0c\u98ce\u9669\u548c\u6536\u76ca\u66f4\u9ad8\uff0c\u653b\u51fb\u8005\u4e5f\u66f4\u5f3a\u5927\u3002 \u6b64\u5916\uff0c\u653b\u51fb\u5df2\u7ecf\u81ea\u52a8\u5316\uff0c\u56e0\u6b64\u653b\u51fb\u8005\u4e0d\u5fc5\u662f\u4e13\u5bb6\u7a0b\u5e8f\u5458\uff0c\u4e5f\u4e0d\u5fc5\u975e\u5e38\u4e86\u89e3\u7cfb\u7edf\u5373\u53ef\u53d1\u8d77\u6210\u529f\u7684\u653b\u51fb\u3002 \u5176\u4e2d\u4e00\u4e9b\u81ea\u52a8\u5316\u653b\u51fb\u6709\u65f6\u88ab\u79f0\u4e3a\u811a\u672c\u5c0f\u5b50\u653b\u51fb(script kiddie attacks)\u3002</p>"},{"location":"SBCA/C1.html#countermeasures-and-defenses","title":"COUNTERMEASURES AND DEFENSES \u5bf9\u7b56\u548c\u9632\u5fa1","text":"<p>\u5bf9\u7b56(countermeasure)\u662f\u5bf9\u653b\u51fb\u7684\u9632\u5fa1\u3002 \u8be5\u672f\u8bed\u4f53\u73b0\u51fa\u5728\u8fc7\u53bb\u5b89\u5168\u63aa\u65bd\u7684\u88ab\u52a8\u7acb\u573a\uff1a\u653b\u51fb\u53d1\u751f\u540e\uff0c\u6211\u4eec\u63d0\u51fa\u5bf9\u7b56\uff08\u7406\u60f3\u60c5\u51b5\u4e0b\u53ef\u4ee5\u5b9e\u65bd\uff09\u3002 \u66f4\u4e3b\u52a8\u7684\u7acb\u573a\u6b63\u5728\u4e0d\u65ad\u88ab\u91cd\u89c6\u3002 \u201c\u5a01\u80c1\u4e0e\u9632\u5fa1\u201d\u548c\u201c\u653b\u51fb\u4e0e\u5bf9\u7b56\u201d\u8fd9\u4e24\u4e2a\u672f\u8bed\u7ecf\u5e38\u4e00\u8d77\u4f7f\u7528\u3002</p> <p>\u9632\u5fa1\u653b\u51fb\u53ef\u5206\u4e3a\u68c0\u6d4b\u3001\u9884\u9632\u3001\u7f13\u89e3\u3001\u6062\u590d\u548c\u53d6\u8bc1\u9632\u5fa1\u3002 \u4eba\u4eec\u53ef\u4ee5\u5c1d\u8bd5\u68c0\u6d4b\u7cfb\u7edf\u4e2d\u7684\u6f0f\u6d1e\u5e76\u5c1d\u8bd5\u6d88\u9664\u8fd9\u4e9b\u6f0f\u6d1e\u3002 \u4eba\u4eec\u53ef\u4ee5\u5c1d\u8bd5\u9884\u9632\u653b\u51fb\u53d1\u751f\u3002 \u653b\u51fb\u5f00\u59cb\u540e\uff0c\u4eba\u4eec\u53ef\u4ee5\u5c1d\u8bd5\u7f13\u89e3\u653b\u51fb\u7684\u5f71\u54cd\u3002 \u6210\u529f\u653b\u51fb\u540e\uff0c\u4eba\u4eec\u53ef\u4ee5\u5c1d\u8bd5\u5c3d\u5feb\u3001\u5c3d\u53ef\u80fd\u5f7b\u5e95\u5730\u4ece\u653b\u51fb\u4e2d\u6062\u590d\uff0c\u5e76\u4e14\u901a\u5e38\u5bf9\u653b\u51fb\u505a\u51fa\u54cd\u5e94\u3002 \u6700\u540e\uff0c\u8bbe\u8ba1\u673a\u5236\u6765\u6536\u96c6\u53d6\u8bc1\u8bc1\u636e\u5e76\u6b63\u786e\u5f52\u56e0\u653b\u51fb\u662f\u5f88\u6709\u7528\u7684\u3002</p>"},{"location":"SBCA/C1.html#threat-model","title":"THREAT MODEL \u5a01\u80c1\u6a21\u578b","text":"<p>\u4e0d\u540c\u7684\u5e94\u7528\u573a\u666f\u9700\u8981\u4e0d\u540c\u79cd\u7c7b\u548c\u5c42\u7ea7\u7684\u5b89\u5168\u6027\u3002 \u9488\u5bf9\u4e0d\u540c\u5c42\u7ea7\u7684\u5a01\u80c1\uff0c\u6709\u8bb8\u591a\u4e0d\u4e00\u6837\u7684\u8d44\u4ea7\u9700\u8981\u88ab\u4fdd\u62a4\u3002 \u4f8b\u5982\uff0c\u9632\u6b62\u4e0d\u88ab\u5141\u8bb8\u7684\u89c6\u9891\u4e0b\u8f7d\u663e\u7136\u548c\u5bf9\u6838\u6b66\u5668\u673a\u5bc6\u7684\u4fdd\u62a4\u662f\u4e0d\u4e00\u6837\u7684\u3002 \u7834\u574f\u9020\u6210\u7684\u98ce\u9669\u8d8a\u5927\u3001\u8d44\u4ea7\u7684\u4ef7\u503c\u8d8a\u9ad8\uff0c\u6211\u4eec\u5c31\u9700\u8981\u66f4\u9ad8\u7a0b\u5ea6\u7684\u5b89\u5168\u4fdd\u62a4\u3002 \u7531\u4e8e\u6d89\u53ca\u4e00\u4e2a\u9002\u7528\u4e8e\u6240\u6709\u573a\u666f\u7684\u5b89\u5168\u8ba1\u7b97\u673a\u662f\u4e0d\u53ef\u80fd\u4e5f\u4e0d\u5fc5\u8981\u7684\uff0c\u9610\u660e\u8bbe\u8ba1\u548c\u8bc4\u4ef7\u4e00\u4e2a\u8ba1\u7b97\u673a\u7cfb\u7edf\u65f6\u5019\u7684\u5a01\u80c1\u6a21\u578b\u662f\u5f88\u91cd\u8981\u7684\u3002</p> <p>\u5a01\u80c1\u6a21\u578b(threat model)\u9610\u660e\u4e86\u54ea\u4e9b\u79cd\u7c7b\u7684\u7684\u5a01\u80c1\u7cfb\u7edf\u4f1a\u9632\u5fa1\uff0c\u800c\u54ea\u4e9b\u4e0d\u5728\u8003\u91cf\u8303\u56f4\u3002 \u4f8b\u5982\uff0c\u5728\u7279\u5b9a\u7684\u5e94\u7528\u573a\u666f\u4e2d\uff0c\u9632\u6b62\u673a\u5bc6\u6027\u7f3a\u53e3\u662f\u6700\u91cd\u8981\u7684\uff0c\u800c\u53ef\u7528\u6027\u5c31\u4e0d\u592a\u88ab\u8003\u8651\u3002 \u8fd9\u610f\u5473\u7740\u54ea\u6015\u4e00\u4e2a\u62d2\u7edd\u670d\u52a1\u653b\u51fb\u53d1\u751f\u4e86\uff0c\u653b\u51fb\u8005\u4e5f\u65e0\u6cd5\u5f97\u5230\u4efb\u4f55\u654f\u611f\u4fe1\u606f\u3002 \u4f8b\u5982\uff0c\u673a\u5bc6\u4fe1\u606f\u53ef\u4ee5\u88ab\u653b\u51fb\u8005\u65e0\u6cd5\u83b7\u53d6\u7684\u5bc6\u94a5\u52a0\u5bc6\uff0c\u6216\u8005\u5bc6\u94a5\u4f1a\u5728\u653b\u51fb\u53d1\u751f\u540e\u7acb\u5373\u88ab\u9500\u6bc1\u3002 \u8fd9\u88ab\u79f0\u4e3a\u673a\u5bc6\u6027\u4fdd\u62a4\u7684\u6545\u969c\u5b89\u5168(fail-safe)\u7b56\u7565\u3002</p> <p>\u5a01\u80c1\u6a21\u578b\u8fd8\u4f1a\u6307\u5b9a\u662f\u5426\u53ea\u8003\u8651\u5bf9\u8fd0\u884c\u7cfb\u7edf\u7684\u653b\u51fb\uff0c\u6216\u8005\u7cfb\u7edf\u662f\u5426\u8fd8\u8003\u8651\u5728\u7cfb\u7edf\u5f00\u53d1\u8fc7\u7a0b\u4e2d\u7684\u653b\u51fb\uff0c\u4f8b\u5982\u7531\u7cfb\u7edf\u7a0b\u5e8f\u5458\u6216\u786c\u4ef6\u8bbe\u8ba1\u5e08\u8fdb\u884c\u7684\u653b\u51fb\u3002 \u8fd9\u4e9b\u5206\u522b\u79f0\u4e3a\u8fd0\u884c\u653b\u51fb(operational attacks)\u548c\u5f00\u53d1\u653b\u51fb(development attacks)\u3002 \u5f00\u53d1\u653b\u51fb\u662f\u4e00\u7c7b\u5185\u90e8\u653b\u51fb(insider attacks)\uff0c\u901a\u5e38\u66f4\u96be\u9632\u8303\uff0c\u56e0\u4e3a\u8bbe\u8ba1\u8005\uff08\u5185\u90e8\u4eba\u5458\uff09\u5b9e\u9645\u4e0a\u662f\u5728\u7cfb\u7edf\u4e2d\u6784\u5efa\u540e\u95e8\u6216\u4fe1\u606f\u6cc4\u9732\u673a\u5236\u3002 \u7cfb\u7edf\u7684\u5b9e\u73b0\u5c06\u6839\u636e\u8bbe\u8ba1<sup>2</sup>\u8fdb\u884c\u9a8c\u8bc1\uff0c\u4ece\u800c\u9a8c\u8bc1\u5176\u6b63\u786e\u6027\uff0c\u56e0\u4e3a\u540e\u95e8\u6f0f\u6d1e\u662f\u8bbe\u8ba1\u7684\u4e00\u90e8\u5206\u3002</p> <p>\u5a01\u80c1\u540c\u6837\u4e5f\u6709\u4e3b\u52a8(active)\u548c\u88ab\u52a8(passive)\u7684\u533a\u522b\u3002 \u4f8b\u5982\uff0c\u76d1\u542c(eavesdropping)\u516c\u7528\u4e92\u8054\u7f51\u6216\u65e0\u7ebf\u7f51\u662f\u4e00\u79cd\u88ab\u52a8\u7684\u653b\u51fb\uff0c\u800c\u4fee\u6539\u8be5\u7f51\u7edc\u4e0a\u88ab\u53d1\u9001\u7684\u4fe1\u606f\u662f\u4e00\u79cd\u4e3b\u52a8\u7684\u653b\u51fb\u3002</p> <p>\u5a01\u80c1\u6a21\u578b\u53ef\u4ee5\u53ea\u5173\u5fc3\u8f6f\u4ef6\u653b\u51fb\uff0c\u6216\u8005\u4e5f\u5173\u5fc3\u786c\u4ef6\u653b\u51fb\u3002 \u5f3a\u5927\u7684\u7cfb\u7edf\u8f6f\u4ef6\uff0c\u8bf8\u5982\u63a7\u5236\u4e86\u7cfb\u7edf\u8d44\u6e90\u7684\u64cd\u4f5c\u7cfb\u7edf\u548c\u865a\u62df\u673a\u76d1\u89c6\u5668\uff0c\u540c\u6837\u53ef\u4ee5\u662f\u8fdd\u80cc\u534f\u8bae\u7684\uff08\u88ab\u653b\u51fb\u6216\u672c\u8eab\u8150\u8d25\uff09\u3002 \u56e0\u6b64\u5a01\u80c1\u6a21\u578b\u540c\u6837\u53ef\u4ee5\u5305\u62ec\u6076\u610f\u7684\u6216\u8005\u8fdd\u80cc\u534f\u8bae\u7684\u64cd\u4f5c\u7cfb\u7edf\u6216\u865a\u62df\u673a\u76d1\u89c6\u5668\u3002</p> <p>\u6709\u4e9b\u653b\u51fb\u662f\u5df2\u77e5\u7684\uff0c\u5e76\u4e14\u5df2\u7ecf\u53d1\u5c55\u8d77\u4e86\u7528\u4e8e\u68c0\u6d4b\u8fd9\u79cd\u653b\u51fb\u7684\u653b\u51fb\u7b7e\u540d(attack signatures)\u3002 \u653b\u51fb\u7b7e\u540d\u662f\u4e00\u4e2a\u6216\u4e00\u7c7b\u653b\u51fb\u7684\u7279\u5f81\u3002 \u4f8b\u5982\uff0c\u75c5\u6bd2\u626b\u63cf\u7a0b\u5e8f\u5229\u7528\u5df2\u77e5\u7684\u75c5\u6bd2\u7b7e\u540d\u7684\u6570\u636e\u5e93\u6765\u68c0\u6d4b\u8ba1\u7b97\u673a\u4e2d\u7684\u75c5\u6bd2\u3002 \u8fd8\u6709\u4e00\u4e9b\u653b\u51fb\u662f\u4ee5\u524d\u4ece\u672a\u89c1\u8fc7\u7684\uff0c\u88ab\u79f0\u4e3a\u96f6\u65e5\u653b\u51fb(zero-day attacks)\u3002 \u5a01\u80c1\u6a21\u578b\u53ef\u4ee5\u6307\u5b9a\u96f6\u65e5\u653b\u51fb\u662f\u5426\u662f\u76ee\u6807\u6216\u4e0d\u88ab\u8003\u8651\u3002</p> <p>\u5a01\u80c1\u6a21\u578b\u5e94\u8be5\u6e05\u695a\u5730\u9610\u660e\u5bf9\u4e8e\u7cfb\u7edf\u7684\u5047\u8bbe\uff0c\u7cfb\u7edf\u7684\u7528\u6237\u4ee5\u53ca\u653b\u51fb\u8005\u7684\u80fd\u529b\u3002 \u5a01\u80c1\u6a21\u578b\u5e94\u8be5\u9610\u660e\u54ea\u4e9b\u79cd\u7c7b\u7684\u5a01\u80c1\u88ab\u8003\u8651\uff0c\u54ea\u4e9b\u4e0d\u88ab\u8003\u8651\u3002 \u5a01\u80c1\u6a21\u578b\u4e0d\u9700\u8981\u63cf\u8ff0\u5176\u9632\u5fa1\u7684\u653b\u51fb\u7684\u7ec6\u8282\u3002</p>"},{"location":"SBCA/C1.html#security-architecture-design-methodology","title":"SECURITY ARCHITECTURE DESIGN METHODOLOGY \u5b89\u5168\u67b6\u6784\u8bbe\u8ba1\u65b9\u6cd5","text":"<p>\u56fe1.1\u5c55\u793a\u4e86\u6211\u4eec\u63a8\u8350\u7684\u8bbe\u8ba1\u5b89\u5168\u8ba1\u7b97\u673a\u7cfb\u7edf\u7684\u65b9\u6cd5\uff0c\u5c24\u5176\u662f\u90a3\u4e9b\u6d89\u53ca\u5230\u65b0\u7684\u786c\u4ef6\u5b89\u5168\u65b9\u6cd5\u6216\u7279\u6027\u7684\u7cfb\u7edf\u3002 \u5b83\u5c55\u793a\u4e86\u6211\u4eec\u5982\u4f55\u5c06\u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5\u878d\u5165\u8ba1\u7b97\u673a\u8bbe\u8ba1\u6d41\u7a0b\u3002</p> <p>\u9996\u5148\uff0c\u63cf\u8ff0\u4f60\u6b63\u5728\u8bbe\u8ba1\u7684\u4f7f\u7528\u573a\u666f\u3002 \u7136\u540e\uff0c\u5e94\u8be5\u6e05\u695a\u7b80\u6d01\u5730\u5b9a\u4e49\u5b89\u5168\u95ee\u9898\uff08\u6700\u597d\u53ea\u7528\u4e00\u53e5\u8bdd\uff09\u3002 \u63a5\u4e0b\u6765\uff0c\u5e94\u8be5\u5b9a\u4e49\u5a01\u80c1\u6a21\u578b\uff0c\u4ee5\u9610\u660e\u89e3\u51b3\u65b9\u6848\u5c06\u89e3\u51b3\u54ea\u4e9b\u5a01\u80c1\uff0c\u4ee5\u53ca\u672a\u8003\u8651\u7684\u5a01\u80c1\u53ca\u5176\u539f\u56e0\u3002 \u901a\u5e38\uff0c\u5728\u7279\u5b9a\u7684\u4f7f\u7528\u6a21\u578b\u4e2d\uff0c\u67d0\u4e9b\u5a01\u80c1\u4e0d\u592a\u53ef\u80fd\u53d1\u751f\u6216\u4f18\u5148\u7ea7\u6bd4\u5176\u4ed6\u5a01\u80c1\u4f4e\u5f97\u591a\u3002 \u7136\u540e\uff0c\u5e94\u8be5\u5b9a\u4e49\u9002\u5408\u4f7f\u7528\u573a\u666f\u7684\u5b89\u5168\u7b56\u7565\uff08\u6216\u4e00\u7cfb\u5217\u7b56\u7565\uff09\uff0c\u5e76\u5728\u6b63\u786e\u6267\u884c\u9002\u5f53\u7684\u7b56\u7565\u65f6\u9632\u5fa1\u5a01\u80c1\u6a21\u578b\u4e2d\u7684\u5a01\u80c1\u3002 \uff08\u6211\u4eec\u5c06\u5728\u540e\u9762\u7684\u7ae0\u8282\u4e2d\u8ba8\u8bba\u5b89\u5168\u7b56\u7565\u3002\uff09</p> <p>\u89e3\u51b3\u65b9\u6848\u53ef\u80fd\u6d89\u53ca\u589e\u5f3a\u73b0\u6709\u67b6\u6784\u6216\u521b\u5efa\u65b0\u67b6\u6784\u4ee5\u6267\u884c\u6240\u9700\u7684\u5b89\u5168\u7b56\u7565\uff0c\u4ece\u800c\u9632\u5fa1\u5a01\u80c1\u6a21\u578b\u4e2d\u8003\u8651\u7684\u5a01\u80c1\u3002 \u5b89\u5168\u793e\u533a\u5c06\u8fd9\u4e9b\u79f0\u4e3a\u5b89\u5168\u673a\u5236(security mechanisms)\u3002 \u5728\u67b6\u6784\u793e\u533a\u4e2d\uff0c\u6211\u4eec\u79f0\u5b83\u4eec\u4e3a\u5b89\u5168\u67b6\u6784\u529f\u80fd\u3002</p> <p>\u5b89\u5168\u7b56\u7565\u89c4\u5b9a\u4e86\u4fdd\u62a4\u6240\u9700\u5b89\u5168\u7279\u6027\u3001\u63d0\u4f9b\u6240\u9700\u5b89\u5168\u7279\u6027\u548c\u9632\u5fa1\u653b\u51fb\u7684\u89c4\u5219\uff0c\u800c\u5b89\u5168\u673a\u5236\u5219\u65e8\u5728\u6267\u884c\u8fd9\u4e9b\u5b89\u5168\u7b56\u7565\u3002 \u5982\u679c\u5b9a\u4e49\u4e86\u9519\u8bef\u7684\u5b89\u5168\u7b56\u7565\uff0c\u90a3\u4e48\u518d\u591a\u7684\u5b89\u5168\u673a\u5236\u4e5f\u65e0\u6cd5\u9632\u6b62\u5b89\u5168\u6f0f\u6d1e\u3002 \u540c\u6837\uff0c\u5373\u4f7f\u5b9a\u4e49\u4e86\u6700\u5168\u9762\u3001\u6700\u6b63\u786e\u7684\u5b89\u5168\u7b56\u7565\uff0c\u5982\u679c\u6ca1\u6709\u53ef\u4ee5\u6267\u884c\u8be5\u7b56\u7565\u7684\u5b89\u5168\u673a\u5236\uff0c\u90a3\u4e48\u8fd9\u4e5f\u6ca1\u6709\u7528\u3002 \u5b89\u5168\u673a\u5236\u53ef\u4ee5\u5728\u8ba1\u7b97\u673a\u6216\u5206\u5e03\u5f0f\u8ba1\u7b97\u673a\u7cfb\u7edf\u4e2d\u7684\u4efb\u4f55\u8f6f\u4ef6\u3001\u786c\u4ef6\u6216\u7f51\u7edc\u5c42\u4e2d\u5b9e\u73b0\u3002</p> <p>\u7406\u60f3\u60c5\u51b5\u4e0b\uff0c\u8fd9\u4e9b\u5b89\u5168\u673a\u5236\u6700\u597d\u662f\u8ba1\u7b97\u673a\u521d\u59cb\u8bbe\u8ba1\u7684\u4e00\u90e8\u5206\u3002 \u901a\u5e38\uff0c\u5b83\u4eec\u4e5f\u53ef\u4ee5\u96c6\u6210\u5230\u73b0\u6709\u8bbe\u8ba1\u4e2d\u3002\u7136\u540e\u83b7\u5f97\u6574\u4e2a\u67b6\u6784\u3002 \u9664\u4e86\u5b89\u5168\u76ee\u6807\u4e4b\u5916\uff0c\u8fd8\u5fc5\u987b\u786e\u4fdd\u6027\u80fd\u3001\u529f\u8017\u3001\u9762\u79ef\u3001\u6210\u672c\u548c\u53ef\u7528\u6027\u76ee\u6807\u4e5f\u5f97\u5230\u6ee1\u8db3\u3002 \u5426\u5219\uff0c\u7528\u6237\u5c06\u9009\u62e9\u6027\u80fd\u66f4\u9ad8\u3001\u66f4\u8282\u80fd\uff08\u8282\u7701\u7535\u6c60\uff09\u6216\u6210\u672c\u66f4\u4f4e\u7684\u8ba1\u7b97\u673a\uff0c\u800c\u4e0d\u662f\u66f4\u5b89\u5168\u7684\u8ba1\u7b97\u673a\u3002 \u56e0\u6b64\uff0c\u5728\u8bbe\u8ba1\u53ef\u4fe1\u8ba1\u7b97\u673a\u65f6\uff0c\u6211\u5efa\u8bae\u5b89\u5168\u67b6\u6784(security-aware architecture)\u7684\u76ee\u6807\uff08\u6211\u7684\u5b66\u751f\u6709\u65f6\u79f0\u4e4b\u4e3a Lee's mantra\uff09\u662f\uff1a     \u201c\u5b9e\u73b0\u5b89\u5168\u6027\uff0c\u800c\u4e0d\u8fdd\u53cd\u6027\u80fd\uff0c \u529f\u8017\uff0c\u6210\u672c\u548c\u53ef\u7528\u6027\u3002\u201d (Security without compromising performance, power consumption, cost and usability.)</p> <p>\u867d\u7136\u9664\u4e86\u7279\u5b9a\u60c5\u51b5\u5916\uff0c\u8fd9\u901a\u5e38\u662f\u65e0\u6cd5\u5b9e\u73b0\u7684\uff0c\u4f46\u6211\u4eec\u5e0c\u671b\u5bcc\u6709\u521b\u9020\u529b\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u793e\u533a\u63d0\u51fa\u975e\u5e38\u5de7\u5999\u7684\u89e3\u51b3\u65b9\u6848\u6765\u6ee1\u8db3\u8fd9\u4e00\u76ee\u6807\u3002</p> <p>\u65b0\u67b6\u6784\u63d0\u4f9b\u7684\u5b89\u5168\u7279\u6027\u5e94\u8be5\u5728\u8bbe\u8ba1\u65f6\u88ab\u4ed4\u7ec6\u5730\u9a8c\u8bc1\u3002 \u8fd9\u662f\u8bbe\u8ba1\u9a8c\u8bc1\u7684\u4e00\u4e2a\u65b0\u65b9\u9762\uff0c\u9700\u8981\u4e3a\u6b64\u5f00\u53d1\u65b0\u7684\u5de5\u5177\u548c\u65b9\u6cd5\u3002 \u4e3a\u5b89\u5168\u9a8c\u8bc1\u800c\u5f00\u53d1\u7684\u5f62\u5f0f\u5316\u9a8c\u8bc1\u6280\u672f\u76ee\u524d\u65e0\u6cd5\u6269\u5c55\u5230\u590d\u6742\u7684\u8f6f\u786c\u4ef6\u7cfb\u7edf\u3002 \u4e8b\u5b9e\u4e0a\uff0c\u5927\u591a\u6570\u5de5\u5177\u9002\u7528\u4e8e\u7eaf\u8f6f\u4ef6\u8bbe\u8ba1\u6216\u7eaf\u786c\u4ef6\u8bbe\u8ba1\uff0c\u4f46\u4e0d\u9002\u7528\u4e8e\u8f6f\u786c\u4ef6\u67b6\u6784\u3002</p> <p>\u8bbe\u8ba1\u8fd8\u5fc5\u987b\u8bc4\u4f30\u5176\u6027\u80fd\u3001\u529f\u8017\u3001\u9762\u79ef\u3001\u6210\u672c\u3001\u53ef\u7528\u6027\u548c\u53ef\u90e8\u7f72\u6027\u3002 \u5982\u679c\u65b0\u7684\u5b89\u5168\u673a\u5236\u4e25\u91cd\u964d\u4f4e\u4e86\u9ad8\u6027\u80fd\u3001\u4f4e\u529f\u8017\u7b49\u5e02\u573a\u8981\u6c42\uff0c\u5219\u5e94\u8fed\u4ee3\u8bbe\u8ba1\uff08\u5982\u56fe 2.1 \u6240\u793a\uff09\u3002<sup>3</sup></p> <p>\u8bb8\u591a\u5b89\u5168\u7cfb\u7edf\u4e4b\u6240\u4ee5\u6ca1\u6709\u6210\u529f\uff0c\u662f\u56e0\u4e3a\u5b83\u4eec\u727a\u7272\u4e86\u6027\u80fd\u3001\u957f\u7535\u6c60\u5bff\u547d\u548c\u6613\u7528\u6027\u7b49\u5e02\u573a\u9a71\u52a8\u56e0\u7d20\u3002</p> <p>\u65b0\u7684\u5b89\u5168\u8ba1\u7b97\u673a\u67b6\u6784\u5982\u4f55\u5f71\u54cd\u73b0\u6709\u8f6f\u4ef6\u7a0b\u5e8f\u548c\u8f6f\u786c\u4ef6\u751f\u6001\u7cfb\u7edf\u7684\u4f7f\u7528\uff0c\u4e5f\u5c06\u5f71\u54cd\u5176\u90e8\u7f72\u548c\u4f7f\u7528\u7684\u7b80\u6613\u6027\u3002</p> <p>\u6211\u4eec\u5c06\u5b89\u5168\u9a8c\u8bc1(security varification)\u8bbe\u5b9a\u4e3a\u5728\u8bbe\u8ba1\u65f6\u5b8c\u6210\uff0c\u800c\u5b89\u5168\u8bc4\u4f30\u901a\u5e38\u5728\u6210\u54c1\u6216\u7cfb\u7edf\u4e0a\u5b8c\u6210\u3002 \u597d\u7684\u7684\u5b89\u5168\u89c4\u5b9a\u8981\u6c42\uff0c\u5b89\u5168\u9a8c\u8bc1\u6216\u8bc4\u4f30\u4e0d\u5e94\u7531\u8bbe\u8ba1\u56e2\u961f\u5b8c\u6210\u3002 \u4e3a\u4e86\u8ba9\u5bcc\u6709\u521b\u9020\u529b\u7684\u4eba\u7c7b\u653b\u51fb\u8005\u5bf9\u7cfb\u7edf\u65bd\u52a0\u538b\u529b\uff0c\u901a\u5e38\u4f7f\u7528\u4e00\u79cd\u79f0\u4e3a\u201c\u7ea2\u961f\u3001\u9ed1\u961f\u201d(red team, black team)\u6d4b\u8bd5\u7684\u7b56\u7565\u3002 \u8fd9\u8ba9\u4e00\u7ec4\u653b\u51fb\u8005\u4e0e\u4e00\u7ec4\u7cfb\u7edf\u9632\u5fa1\u8005\u5bf9\u7acb\u8d77\u6765\u3002</p> <ol> <li> <p>\u6211\u4eec\u66f4\u559c\u6b22\u5c06\u8bbf\u95ee\u63a7\u5236\u5b9a\u4e49\u4e3a\u7531\u8ba4\u8bc1\u548c\u6388\u6743\u4e24\u4e2a\u90e8\u5206\u7ec4\u6210\uff0c\u800c\u4e00\u4e9b\u5b89\u5168\u4e13\u5bb6\u5219\u5c06\u8bbf\u95ee\u63a7\u5236\u548c\u6388\u6743\u89c6\u4e3a\u540c\u4e49\u8bcd\u3002\u00a0\u21a9</p> </li> <li> <p>\u4f8b\u5982\uff0c\u786c\u4ef6\u82af\u7247\u8bbe\u8ba1\u6210\u4e3a\u9a8c\u8bc1\u82af\u7247\u4e0d\u540c\u5236\u9020\u7ea7\u522b\u7684\u9ec4\u91d1\u7f51\u8868\u3002(For example, a hardware chip design becomes the golden netlist for verifying different levels of fabrication of the chip.)\u00a0\u21a9</p> </li> <li> <p>\u8bd1\u8005\u6ce8\uff1a\u5e94\u4e3a\u56fe1.1\u3002\u00a0\u21a9</p> </li> </ol>"},{"location":"SBCA/C2.html","title":"Security Policy Models \u5b89\u5168\u7b56\u7565\u6a21\u578b","text":"<p>\u73b0\u5b9e\u751f\u6d3b\u4e2d\u7684\u5b89\u5168\u7b56\u7565\u53ef\u80fd\u4f1a\u975e\u5e38\u590d\u6742\u3002 \u5b83\u4eec\u901a\u5e38\u7531\u4ee3\u8868\u5404\u5229\u76ca\u76f8\u5173\u8005\u5229\u76ca\u7684\u59d4\u5458\u4f1a\u548c/\u6216\u516c\u53f8\u9ad8\u7ba1\u5236\u5b9a\u3002 \u5b89\u5168\u7b56\u7565\u4e0d\u662f\u7531\u5de5\u7a0b\u5e08\u51b3\u5b9a\u7684\u6280\u672f\u95ee\u9898\u3002 \u76f8\u53cd\uff0c\u5de5\u7a0b\u5e08\u8bbe\u8ba1\u4e86\u6267\u884c\u5b89\u5168\u7b56\u7565\u7684\u5b89\u5168\u673a\u5236\u3002</p> <p>\u5b89\u5168\u7b56\u7565\u6a21\u578b\u8ba9\u6211\u4eec\u80fd\u591f\u7406\u89e3\u5b89\u5168\u7b56\u7565\u3002 \u5b83\u4eec\u63d0\u4f9b\u4e86\u4e00\u79cd\u62bd\u8c61\uff0c\u4f7f\u5f97\u6211\u4eec\u53ef\u4ee5\u5173\u6ce8\u5230\u4fdd\u62a4\u6a21\u578b\u4e2d\u7684\u6838\u5fc3\u601d\u60f3\uff0c\u540c\u65f6\u907f\u514d\u9677\u5165\u7279\u5b9a\u5b89\u5168\u7b56\u7565\u4e2d\u9047\u5230\u7684\u590d\u6742\u95ee\u9898\u3002</p> <p>\u5728\u672c\u7ae0\u4e2d\uff0c\u6211\u4eec\u8ba8\u8bba\u591a\u7ea7\u5b89\u5168\uff08MLS\uff09\u7b56\u7565\u6a21\u578b(muti-level security policy model)\uff082.1\u8282\uff09\uff0c\u4ee5\u53ca\u591a\u8fb9\u5b89\u5168\u7b56\u7565\u6a21\u578b(multi-lateral security policy model)\uff082.2\u8282\uff09\u3002 \u56fe2.1\u5c55\u793a\u4e86\u8fd9\u4e24\u79cd\u6a21\u578b\u3002 \u5f15\u7528\u6587\u732e[6,7,8,9]\u4e2d\u53ef\u4ee5\u627e\u5230\u5bf9\u4e8e\u5b89\u5168\u7b56\u7565\u7684\u597d\u7684\u8ba8\u8bba\u3002</p> <p></p>"},{"location":"SBCA/C2.html#multi-level-security-policies","title":"MULTI-LEVEL SECURITY POLICIES \u591a\u7ea7\u5b89\u5168\u7b56\u7565","text":"<p>\u591a\u7ea7\u5b89\u5168\uff08MLS\uff09\u7b56\u7565\u5047\u5b9a\u4e86\u4e00\u79cd\u5c42\u6b21\u5316\u7684\u8bbf\u95ee\u6a21\u578b\uff0c\u5176\u4e2d\u4e3b\u4f53\u548c\u5ba2\u4f53\u88ab\u5212\u5206\u4e3a\u4e0d\u540c\u7684\u5b89\u5168\u6216\u5b8c\u6574\u6027\u7ea7\u522b\u3002 \u5b58\u5728\u4e25\u683c\u7684\u89c4\u5219\u63cf\u8ff0\u5141\u8bb8\u7684\u4fe1\u606f\u6d41\u65b9\u5411\uff0c\u57fa\u4e8e\u8fd9\u4e9b\u5148\u9a8c\u7684\u5206\u7c7b\u3002</p> <p>\u56fe2.1\u5de6\u534a\u90e8\u5206\u5c55\u793a\u4e86\u9632\u5fa1\u7cfb\u7edf\u5bf9\u5ba2\u4f53\u5316\u5206\u4e86\u51e0\u79cd\u4e0d\u540c\u7684\u5b89\u5168\u7b49\u7ea7\uff1a \u9876\u7ea7\u79d8\u5bc6\uff08TS\uff09\uff0c\u79d8\u5bc6\uff08S\uff09\uff0c\u673a\u5bc6\uff08C\uff09\uff0c\u516c\u5f00\uff08U\uff09\u3002 (Top Secret, Secret, Confidential and Unclassified.) \u76f8\u4f3c\u7684\uff0c\u4e3b\u4f53\u7684\u8bbf\u95ee\u8bb8\u53ef\u4e5f\u88ab\u5212\u5206\u4e3a\u56db\u4e2a\u7b49\u7ea7\uff1aTS\uff0cS\uff0cC\uff0cU\u3002 \u516c\u5f00\u7b49\u7ea7\u662f\u4e0d\u53d7\u9650\u5236\u7684\uff0c\u4e14\u66f4\u9ad8\u7684\u8bbf\u95ee\u8bb8\u53ef\u9700\u8981\u66f4\u5e7f\u6cdb\u7684\u80cc\u666f\u68c0\u67e5\u3002 \u8fd9\u56db\u79cd\u5b89\u5168\u7b49\u7ea7\u6709\u5982\u4e0b\u7684\u504f\u5e8f\u5173\u7cfb\uff1a $$ \\text{TS}\\ge\\text{S}\\ge\\text{C}\\ge\\text{U} $$</p> <p>\u67d0\u4e2a\u62e5\u6709TS\u7b49\u7ea7\u8bbf\u95ee\u8bb8\u53ef\u7684\u4eba\u53ef\u4ee5\u8bbf\u95ee\u6240\u6709\u7b49\u7ea7\u7684\u5ba2\u4f53\uff0c\u800c\u62e5\u6709S\u7b49\u7ea7\u8bbf\u95ee\u8bb8\u53ef\u7684\u4eba\u53ea\u80fd\u8bbf\u95eeS\u7b49\u7ea7\u53ca\u4ee5\u4e0b\u7684\u5ba2\u4f53\u3002 \u867d\u7136\u6700\u521d\u662f\u4e3a\u4e86\u519b\u4e8b\u76ee\u7684\u8bbe\u8ba1\u7684\uff0cMLS\u7b56\u7565\u73b0\u5728\u4e5f\u88ab\u7528\u4e8e\u5546\u4e1a\u7cfb\u7edf\u4e2d\uff0c\u4f8b\u5982\u9886\u5bfc\u5c42\uff08TS\uff09\u76f8\u8f83\u4e8e\u7ecf\u7406\uff08S\uff09\u53ef\u4ee5\u8bbf\u95ee\u516c\u53f8\u6240\u6709\u7684\u66f4\u591a\u4fe1\u606f\uff0c\u800c\u7ecf\u7406\uff08S\uff09\u53ef\u4ee5\u6bd4\u5458\u5de5\uff08C\uff09\u8bbf\u95ee\u66f4\u591a\u4fe1\u606f\uff0c\u5458\u5de5\uff08C\uff09\u53ef\u4ee5\u6bd4\u516c\u4f17\uff08U\uff09\u8bbf\u95ee\u66f4\u591a\u4fe1\u606f\u3002</p> <p>\u673a\u5bc6\u6027\u548c\u5b8c\u6574\u6027\u6709\u5355\u72ec\u7684\u89c4\u5219\u3002 \u6211\u4eec\u5728\u4e0b\u9762\u8ba8\u8bba\u8fd9\u4e9b\u89c4\u5219\uff0c\u5373\u7528\u4e8e\u4fdd\u62a4\u673a\u5bc6\u6027\u7684 Bell La Padula (BLP) \u5b89\u5168\u7b56\u7565\u6a21\u578b\u548c\u7528\u4e8e\u4fdd\u62a4\u5b8c\u6574\u6027\u7684 Biba \u6a21\u578b\u3002</p>"},{"location":"SBCA/C2.html#bell-la-padula-blp-for-confidentiality-bell-la-padula-blp","title":"BELL LA PADULA (BLP) FOR CONFIDENTIALITY \u9488\u5bf9\u4fdd\u5bc6\u6027\u7684 Bell La Padula (BLP) \u6a21\u578b","text":"<p>BLP\u662f\u4e00\u79cdMLS\u7b56\u7565\u6a21\u578b\uff0c\u7528\u4e8e\u4fdd\u62a4\u673a\u5bc6\u6027\u3002 \u673a\u5bc6\u6027\u9996\u5148\u4e14\u4e3b\u8981\u5173\u6ce8\u901a\u8fc7\u8bfb\u7684\u65b9\u5f0f\u8bbf\u95ee\u5ba2\u4f53\u3002 \u5176\u540e\uff0c\u5199\u64cd\u4f5c\u4e5f\u9700\u8981\u88ab\u7ba1\u63a7\uff0c\u7531\u4e8e\u9ad8\u8bfb\u6743\u9650\u4e3b\u4f53\u7684\u5199\u64cd\u4f5c\u53ef\u80fd\u5411\u4e0d\u5177\u6709\u9ad8\u8bfb\u6743\u9650\u7684\u4e3b\u4f53\u6cc4\u9732\u4fe1\u606f\u3002 BLP\uff08\u6839\u636e\u4f5c\u8005\u540d\u5b57\u547d\u540d\uff09\u6709\u4e24\u6761\u89c4\u5219\uff0c\u5982\u8868\u683c2.1\u6240\u793a\u3002 \\(L(x)\\)\u8868\u793a\u5ba2\u4f53\\(x\\)\u7684\u5b89\u5168\u7b49\u7ea7\u6216\u4e3b\u4f53\\(x\\)\u7684\u8bbf\u95ee\u8bb8\u53ef\u7b49\u7ea7\u3002</p> <p>\u9488\u5bf9\u8bfb\u7684\u89c4\u5219\uff0c\u4e5f\u88ab\u79f0\u4e3a\u201c\u7b80\u5355\u5b89\u5168\u5c5e\u6027\u201d(Simple Security property)\uff0c\u5f88\u597d\u7406\u89e3\u3002 \u5b83\u8981\u6c42\u4e3b\u4f53\u53ea\u80fd\u8bfb\u53d6\u6bd4\u81ea\u5df1\u8bbf\u95ee\u8bb8\u53ef\u7b49\u7ea7\u4f4e\u7684\u5ba2\u4f53\u3002</p> <p></p> <p>\u9488\u5bf9\u5199\u7684\u89c4\u5219\uff0c\u4e5f\u79f0\u4e3a *-\u5c5e\u6027\uff08\u53d1\u97f3\u4e3a\u201c\u661f\u201d\u5c5e\u6027\uff09\uff0c\u66f4\u96be\u7406\u89e3\u3002 (The write rule, also called the *-property (pronounced \"star\" property), is harder to understand.) \u6211\u5c06\u901a\u8fc7\u4e00\u4e2a\u4f8b\u5b50\u6765\u89e3\u91ca\u8fd9\u4e00\u70b9\u3002 \u5047\u8bbe\u4e00\u4f4d\u62e5\u6709\u6700\u9ad8\u673a\u5bc6\uff08TS\uff09\u6743\u9650\u7684\u8150\u8d25\u5c06\u519b\uff0c\u4ed6\u6b63\u5728\u4e0e\u4e00\u540d\u88ab\u6000\u7591\u662f\u4fc4\u7f57\u65af\u95f4\u8c0d\u7684\u4eba\u8fdb\u884c\u901a\u4fe1\uff0c\u800c\u8be5\u95f4\u8c0d\u7684\u6743\u9650\u4e3a\u975e\u673a\u5bc6\uff08U\uff09\u3002 \u7531\u4e8e\u5c06\u519b\u53ef\u4ee5\u9605\u8bfb\u6700\u9ad8\u673a\u5bc6\u6587\u4ef6\uff0c\u5982\u679c\u5141\u8bb8\u4ed6\u5199\u5165\u975e\u673a\u5bc6\u6587\u4ef6\uff0c\u95f4\u8c0d\u5c31\u53ef\u4ee5\u9605\u8bfb\u975e\u673a\u5bc6\u6587\u4ef6\uff0c\u5176\u4e2d\u53ef\u80fd\u5305\u542b\u5c06\u519b\u5df2\u9605\u8bfb\u7684\u4e00\u4e9b\u6700\u9ad8\u673a\u5bc6\u4fe1\u606f\u3002 *-\u5c5e\u6027\u53ef\u9632\u6b62\u6b64\u7c7b\u4fe1\u606f\u6cc4\u9732\u3002 \uff08\u8fd9\u4e5f\u662f\u4e00\u4e2a\u4fe1\u4efb\u7684\u4e3b\u4f53\u4e0d\u53ef\u4fe1\u7684\u4f8b\u5b50\u3002\uff09</p> <p>\u5f53\u4e24\u4e2a\u6216\u591a\u4e2a\u4e0d\u540c\u5b89\u5168\u7b49\u7ea7\u7684\u5ba2\u4f53\u7ec4\u5408\u5728\u4e00\u8d77\u65f6\uff0cBLP\u5177\u6709\u201c\u9ad8\u6c34\u4f4d\u6807\u8bb0\u201d(high-water mark)\u6548\u679c\uff1a \u7ec4\u5408\u540e\u7684\u5ba2\u4f53\u7684\u5b89\u5168\u7b49\u7ea7\u53d6\u6240\u6709\u7ec4\u5408\u524d\u5ba2\u4f53\u7684\u5b89\u5168\u7b49\u7ea7\u7684\u6700\u9ad8\u503c\u3002</p> <p>\u4e3e\u4e2a\u6700\u8fd1\u7684\u4f8b\u5b50\uff0c\u8003\u8651\u7ef4\u57fa\u89e3\u5bc6\u6848\u3002 \u5982\u679c\u5b9e\u65bd\u4e86\u4e25\u683c\u7684BLP\u5b89\u5168\u7b56\u7565\uff0c\u90a3\u4e48\u58eb\u5175\u5c06\u65e0\u6cd5\u8bbf\u95eeTS\u6587\u4ef6\uff08\u9664\u975e\u4ed6\u6709TS\u8bbf\u95ee\u8bb8\u53ef\uff09\u3002 \u4f46\u662f\u5982\u679c\u4ed6\u6709TS\u8bb8\u53ef\uff0c*-\u89c4\u5219\u5c06\u963b\u6b62\u4ed6\u5c06\u4fe1\u606f\u5199\u5165\u975e\u673a\u5bc6\u6587\u6863\u3001\u5b58\u50a8\u6216\u7f51\u7edc\uff0c\u8fd9\u6837\u4ed6\u5c31\u65e0\u6cd5\u5c06TS\u4fe1\u606f\u6cc4\u9732\u7ed9\u7ef4\u57fa\u89e3\u5bc6\u3002 \u5f53\u7136\uff0c\u771f\u5b9e\u7684\u6545\u4e8b\u8981\u590d\u6742\u5f97\u591a\u3002</p>"},{"location":"SBCA/C2.html#biba-for-integrity-biba","title":"BIBA FOR INTEGRITY \u9488\u5bf9\u5b8c\u6574\u6027\u7684 Biba \u6a21\u578b","text":"<p>Biba\u662f\u4e00\u79cdMLS\u7b56\u7565\u6a21\u578b\uff0c\u7528\u4e8e\u4fdd\u62a4\u5b8c\u6574\u6027\u3002 \u4e3b\u4f53\u7684\u5b8c\u6574\u6027\u8bbf\u95ee\u6743\u9650\u4ee5\u53ca\u5ba2\u4f53\u7684\u5b8c\u6574\u6027\u5b89\u5168\u7b49\u7ea7\u4e0e\u5176\u673a\u5bc6\u6027\u8bbf\u95ee\u6743\u9650\u548c\u5b89\u5168\u7b49\u7ea7\u672a\u5fc5\u4e00\u81f4\u3002 \u4f8b\u5982\uff0c\u4e00\u4e2a\u88ab\u6807\u8bb0\u4e3a\u673a\u5bc6\u6027TS\u7684\u9ad8\u673a\u5bc6\u6027\u6587\u4ef6\u53ef\u80fd\u6765\u81ea\u4e00\u4e2a\u6ca1\u6709\u88ab\u81ea\u4e60\u68c0\u67e5\u7684\u6765\u6e90\uff0c\u56e0\u6b64\u5176\u5b8c\u6574\u6027\u5b89\u5168\u7b49\u7ea7\u53ef\u80fd\u53ea\u662fC\u6216\u8005U\u3002</p> <p>\u8868\u683c2.2\u603b\u7ed3\u4e86Biba\u5b89\u5168\u7b56\u7565\u6a21\u578b\u3002 \u201c\u5199\u4e0d\u5411\u4e0a\u201d(no write up)\u89c4\u5219\u8981\u6c42\u4e3b\u4f53\u4e0d\u80fd\u5199\u5165\u6bd4\u81ea\u5df1\u5b8c\u6574\u6027\u7b49\u7ea7\u9ad8\u7684\u5ba2\u4f53\u3002 \u201c\u8bfb\u4e0d\u5411\u4e0b\u201d(no read down)\u89c4\u5219\u662f\u4e3a\u4e86\u9632\u6b62\u9ad8\u5b8c\u6574\u6027\u7684\u4e3b\u4f53\u7684\u51b3\u7b56\u4fe1\u606f\u53d7\u5230\u4f4e\u5b8c\u6574\u6027\u7684\u4fe1\u606f\u7684\u6c61\u67d3\u3002</p> <p>\u5f53\u4e24\u4e2a\u6216\u591a\u4e2a\u4e0d\u540c\u5b8c\u6574\u6027\u7b49\u7ea7\u7684\u5ba2\u4f53\u7ec4\u5408\u5728\u4e00\u8d77\u65f6\uff0cBiba\u5177\u6709\u201c\u4f4e\u6c34\u4f4d\u6807\u8bb0\u201d(low-water mark)\u6548\u679c\uff1a \u7ec4\u5408\u540e\u7684\u5ba2\u4f53\u7684\u5b8c\u6574\u6027\u7b49\u7ea7\u53d6\u6240\u6709\u7ec4\u5408\u524d\u5ba2\u4f53\u7684\u5b8c\u6574\u6027\u7b49\u7ea7\u7684\u6700\u4f4e\u503c\u3002</p> <p>\u901a\u5e38\uff0c\u53ea\u9700\u4e24\u4e2a\u5b8c\u6574\u6027\u7b49\u7ea7\u5c31\u8db3\u591f\u4e86\uff1a\u9ad8\u6216\u8005\u4f4e(Hi and Lo)\u3002 \u673a\u5bc6\u6027\u7b49\u7ea7\u4e5f\u662f\u5982\u6b64\u3002 \u4e00\u822c\u6765\u8bf4\uff0cMLS \u7cfb\u7edf\u53ef\u4ee5\u5b9a\u4e49\u4efb\u610f\u6570\u91cf\u7684\u673a\u5bc6\u6027\u6216\u5b8c\u6574\u6027\u7ea7\u522b\uff0c\u6700\u4f4e\u6570\u91cf\u4e3a\u4e24\u4e2a\uff1a\u53ef\u4fe1\u6216\u4e0d\u53ef\u4fe1(trusted or not trusted)\u3002</p> <p></p> <p>Comparing BLP and Biba \u6bd4\u8f83 BLP \u548c Biba</p> <p>BLP \u4fdd\u62a4\u673a\u5bc6\u6027\uff0c\u800c Biba \u4fdd\u62a4\u5b8c\u6574\u6027\u3002 BLP \u66f4\u5173\u6ce8\u8bfb\u53d6\uff0c\u800c Biba \u66f4\u5173\u6ce8\u5199\u5165\u3002 BLP \u548c Biba \u662f\u5bf9\u5076\u7684\uff0c\u5982\u8868 2.3 \u6240\u793a\u3002</p> <p></p>"},{"location":"SBCA/C2.html#example","title":"EXAMPLE \u4f8b\u5b50","text":"<p>\u4f8b\u5982\uff0cBLP \u200b\u200b\u53ef\u7528\u4e8e\u9632\u6b62\u6076\u610f\u8f6f\u4ef6\u8bfb\u53d6\u5bc6\u7801\u6587\u4ef6\u3002 \u5c06\u5bc6\u7801\u6587\u4ef6\u5f52\u7c7b\u4e3a Hi \u5b89\u5168\u6027\uff0c\u5c06\u6765\u81ea\u7f51\u7edc\uff08\u6216\u5199\u5165\u7f51\u7edc\uff09\u7684\u4efb\u4f55\u5185\u5bb9\u5f52\u7c7b\u4e3a Lo \u5b89\u5168\u6027\u3002 \u5373\u4f7f\u6076\u610f\u8f6f\u4ef6\uff08Lo \u5b89\u5168\u6027\uff09\u8fdb\u5165\u7cfb\u7edf\uff0c\u5982\u679c\u6267\u884c BLP\uff0c\u5b83\u4e5f\u65e0\u6cd5\u8bfb\u53d6\u5bc6\u7801\u6587\u4ef6\u3002 \u5982\u679c\u6076\u610f\u8f6f\u4ef6\u4ee5\u67d0\u79cd\u65b9\u5f0f\u8bbe\u6cd5\u83b7\u5f97 Hi \u7cfb\u7edf\u7a0b\u5e8f\u7684\u8bb8\u53ef\uff0c\u5b83\u5c06\u80fd\u591f\u8bfb\u53d6\u5bc6\u7801\u6587\u4ef6\u3002 \u4f46\u662f\uff0c\u5b83\u65e0\u6cd5\u5c06\u5bc6\u7801\u6587\u4ef6\u5199\u5165\u7f51\u7edc\uff0c\u56e0\u4e3a\u8fd9\u76f8\u5f53\u4e8e\u5199\u5165 Lo \u6587\u6863\u3002</p> <p>\u7c7b\u4f3c\u5730\uff0cBiba \u53ef\u7528\u4e8e\u9632\u6b62\u672a\u7ecf\u6388\u6743\u4fee\u6539\u7cfb\u7edf\u6587\u4ef6\u3002 \u5047\u8bbe\u7cfb\u7edf\u6587\u4ef6\u88ab\u5f52\u7c7b\u4e3a Hi \u5b8c\u6574\u6027\uff0c\u7f51\u7edc\u8f93\u5165\u548c\u8f93\u51fa\u88ab\u5f52\u7c7b\u4e3a Lo \u5b8c\u6574\u6027\u3002 \u7531\u4e8e\u201c\u7981\u6b62\u5199\u5165\u201d\u89c4\u5219\uff0c\u6765\u81ea\u7f51\u7edc\uff08Lo \u5b8c\u6574\u6027\uff09\u7684\u6076\u610f\u8f6f\u4ef6\u5c06\u65e0\u6cd5\u5199\u5165\uff08\u4fee\u6539\uff09\u7cfb\u7edf\u6587\u4ef6\u3002 \u5982\u679c\u6076\u610f\u8f6f\u4ef6\u4e0e\u7cfb\u7edf\u6587\u4ef6\u7ed3\u5408\uff0c\u5b83\u4f1a\u5c06\u7cfb\u7edf\u6587\u4ef6\u62c9\u4f4e\u5230 Lo \u5b8c\u6574\u6027\u2014\u2014\u56e0\u6b64\uff0c\u7cfb\u7edf\u6587\u4ef6\u5c06\u88ab\u201c\u6c61\u67d3\u201d\uff0c\u5e76\u4e14\u5c06\u4e0d\u518d\u80fd\u591f\u50cf\u5728\u88ab\u6c61\u67d3\u4e4b\u524d\u90a3\u6837\u8bbf\u95ee\u7cfb\u7edf\u6570\u636e\u3002</p> <p>\u8bb8\u591a\u5173\u4e8e\u52a8\u6001\u4fe1\u606f\u6d41\u8ddf\u8e2a(Dynamically Information Flow Tracking, DIFT)\u7684\u8bba\u6587\u90fd\u63d0\u5230\u4e86\u5c06\u7f51\u7edc\u4e2d\u7684\u6570\u636e\u6216\u4ee3\u7801\u6c61\u67d3\u4e3a\u4e0d\u53ef\u4fe1\uff0c\u5e76\u4f20\u64ad\u8fd9\u79cd\u6c61\u67d3\u2014\u2014\u8fd9\u53ea\u662f Biba \u5b89\u5168\u7b56\u7565\u6a21\u578b\u7684\u4e00\u79cd\u5b9e\u73b0\u3002 \u6211\u4eec\u5728\u9644\u5f55\uff1a\u8fdb\u4e00\u6b65\u9605\u8bfb(Appendix: Further Readings)\u4e2d\u7ed9\u51fa\u4e86\u4ee5\u786c\u4ef6\u4e3a\u4e2d\u5fc3\u7684 DIFT \u8bba\u6587\u5217\u8868\uff0c\u4ee5\u53ca\u4e00\u4e9b\u7ecf\u5178\u7684\u9759\u6001\u4fe1\u606f\u6d41\u8ddf\u8e2a\u8bba\u6587\uff0c\u4f9b\u611f\u5174\u8da3\u7684\u8bfb\u8005\u53c2\u8003\u3002</p>"},{"location":"SBCA/C2.html#mls-security-levels-and-privilege-levels-mls","title":"MLS SECURITY LEVELS AND PRIVILEGE LEVELS MLS \u5b89\u5168\u7b49\u7ea7\u548c\u7279\u6743\u7b49\u7ea7","text":"<p>MLS\u5b89\u5168\u7b49\u7ea7(MLS security levels)\u548c\u7279\u6743\u7b49\u7ea7(Privilege Levels, PL)\u662f\u4e0d\u540c\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u672f\u8bed\u3002 \u5c3d\u7ba1\u4e24\u8005\u90fd\u5b9a\u4e49\u4e86\u7ed3\u6784\u5316\u7684\u8bbf\u95ee\u6743\u9650\uff0c\u7279\u6743\u7b49\u7ea7\u5e76\u4e0d\u533a\u5206\u8bfb\u548c\u5199\u3002 \u540c\u6837\uff0c\u4e00\u4e2a\u9ad8\u7684\u7279\u6743\u7b49\u7ea7\uff08\u4f8b\u5982\\(\\text{PL}=0\\)\u7684\u64cd\u4f5c\u7cfb\u7edf\uff09\u53ef\u4ee5\u8bfb\u5199\u6240\u6709\u8f83\u4f4e\u7279\u6743\u7ea7\u522b\uff08\u4f8b\u5982\uff0c\\(\\text{PL}=3\\)\u7684\u7528\u6237\u7a7a\u95f4\u6216\\(\\text{PL}=1/2\\)\u7684\u4e2d\u95f4\u4ef6\uff09\u7684\u6240\u6709\u5bf9\u8c61\u3002 MLS \u5b89\u5168\u7ea7\u522b\u4e0e\u7279\u6743\u7ea7\u522b\u6b63\u4ea4\u3002 \u64cd\u4f5c\u7cfb\u7edf\u662f\u5426\u5e94\u8be5\u6709\u6743\u8bfb\u53d6\u7edd\u5bc6\u6587\u4ef6\uff1f \u7406\u60f3\u60c5\u51b5\u4e0b\u4e0d\u5e94\u8be5\uff0c\u7279\u522b\u662f\u5982\u679c\u5b83\u4e0d\u5728\u53ef\u4fe1\u8ba1\u7b97\u57fa(TCB)\u4e2d\u3002 \u5982\u679c\u64cd\u4f5c\u7cfb\u7edf\u5728TCB\u4e2d\uff0c\u5219\u53ef\u4ee5\u6388\u4e88\u5b83\u8bbf\u95ee\u6240\u6709\u6587\u6863\u7684\u6743\u9650\u3002 \u7531\u4e8e\u5bf9\u4e8e\u5546\u54c1\u7cfb\u7edf\uff0c\u8bbf\u95ee\u63a7\u5236\u901a\u5e38\u7531\u64cd\u4f5c\u7cfb\u7edf\u5f3a\u5236\u6267\u884c\uff08\u5982\u679c\u6709\u7684\u8bdd\uff09\uff0c\u6211\u4eec\u53ef\u4ee5\u8bf4\u8fd9\u4e9b\u64cd\u4f5c\u7cfb\u7edf\u662f\u4fe1\u4efb\u7684\uff0c\u4f46\u4e0d\u4e00\u5b9a\u53ef\u4fe1\u3002 \u56e0\u6b64\uff0c\u9700\u8981\u5728\u64cd\u4f5c\u7cfb\u7edf\u4e0b\u9762\u6709\u4e00\u4e2a\u8f83\u4f4e\u7ea7\u522b\u7684\u4fe1\u4efb\u7684\u8f6f\u4ef6\uff0c\u8fd9\u6837\u64cd\u4f5c\u7cfb\u7edf\u5c31\u4e0d\u9700\u8981\u88ab\u4fe1\u4efb\u3002 \u7136\u800c\uff0c\u8fd9\u79cd\u8f83\u4f4e\u7ea7\u522b\u7684\u7cfb\u7edf\u8f6f\u4ef6\uff08\u4f8b\u5982\u865a\u62df\u673a\u7ba1\u7406\u7a0b\u5e8f\uff09\u4e5f\u53ef\u80fd\u53d7\u5230\u653b\u51fb\uff0c\u56e0\u6b64\u786c\u4ef6\u67b6\u6784\u53ef\u80fd\u9700\u8981\u63d0\u4f9b\u5e2e\u52a9\u3002 \u5f53\u7136\uff0c\u786c\u4ef6\u4e5f\u53ef\u80fd\u53d7\u5230\u653b\u51fb\uff0c\u4f46\u653b\u51fb\u786c\u4ef6\u901a\u5e38\u6bd4\u653b\u51fb\u8f6f\u4ef6\u8981\u56f0\u96be\u51e0\u4e2a\u6570\u91cf\u7ea7\u3002</p>"},{"location":"SBCA/C2.html#multi-lateral-security-policies","title":"MULTI-LATERAL SECURITY POLICIES \u591a\u8fb9\u5b89\u5168\u7b56\u7565","text":"<p>\u5c3d\u7ba1\u8bb8\u591a\u519b\u961f\u548c\u5546\u4e1a\u5b9e\u4f53\u4f7f\u7528\u66fe\u7b56\u5212\u7684\u7ec4\u7ec7\uff0c\u4f7f\u5f97MLS\u7b56\u7565\u53ef\u4ee5\u5b9e\u65bd\uff0c\u8bb8\u591a\u5176\u4ed6\u7684\u5b9e\u4f53\u9700\u8981\u4e00\u79cd\u591a\u8fb9\u7684\u9694\u79bb\u65b9\u5f0f\uff0c\u5c06\u6570\u636e\u9694\u79bb\u5728\u4e0d\u540c\u7684\u4fe1\u4efb\u57df(trust domains)\u4e2d\uff08\u56fe2.1\uff09\u3002 \u8fd9\u79cd\u60c5\u51b5\u5728\u591a\u4e2a\u5546\u4e1a\u516c\u53f8\u95f4\u5c24\u4e3a\u5e38\u89c1\u3002 \u54ea\u6015\u662f\u5728\u4f7f\u7528\u5c42\u6b21\u5316MLS\u7b56\u7565\u7684\u5927\u591a\u6570\u7cfb\u7edf\u4e2d\uff0c\u5bf9\u4e8e\u4e00\u4e2a\u5b89\u5168\u7b49\u7ea7\u8fdb\u884c\u591a\u8fb9\u5212\u5206\u4e5f\u7ecf\u5e38\u662f\u9700\u8981\u7684\u3002 \u8fd9\u662f\u7531\u4e8e\u6240\u8c13\u7684\u201c\u9700\u8981\u77e5\u9053(need to know)\u201d\u7684\u60c5\u51b5\uff0c\u6b63\u5982\u6211\u4eec\u57282.2.3\u8282\u4e2d\u53d9\u8ff0\u7684\u5e26\u6709\u5bc6\u8bed\u7684BLP(BLP with code words)\u4e00\u6837\u3002 \u4e0b\u9762\u6211\u4eec\u8ba8\u8bba\u66f4\u9002\u5408\u591a\u7528\u9014\u573a\u666f\u548c\u7fa4\u7ec4\u7ed3\u6784\u7684\u591a\u8fb9\u5b89\u5168\u7b56\u7565\u3002 \u5728\u8ba8\u8bba\u5176\u4ed6\u7684\u591a\u8fb9\u7b56\u7565\u4e4b\u524d\uff0c\u6211\u4eec\u5148\u4ece\u4e00\u4e2a\u9488\u5bf9\u673a\u5bc6\u6027\u7684\u591a\u8fb9\u7b56\u7565\u5f00\u59cb\uff08the Chinese Wall policy\uff0c\u4e2d\u56fd\u5899\u7b56\u7565\uff09\uff0c\u7136\u540e\u8ba8\u8bba\u4e00\u4e2a\u9488\u5bf9\u5b8c\u6574\u6027\u7684\u591a\u8fb9\u7b56\u7565\uff08the Clark-Wilson policy\uff0c\u514b\u62c9\u514b-\u5a01\u5c14\u900a\u7b56\u7565\uff09\u3002</p>"},{"location":"SBCA/Preface.html","title":"Preface","text":"<p>\u5728\u8bbe\u8ba1\u5b89\u5168\u7684\u6570\u5b57\u4fe1\u606f\u7684\u8ba1\u7b97\u3001\u5b58\u50a8\u3001\u8fd0\u8f93\u7cfb\u7edf\u65f6\u6709\u8bb8\u591a\u5b89\u5168\u95ee\u9898\u4f5c\u4e3a\u57fa\u7840\u3002 \u7406\u89e3\u8fd9\u4e9b\u57fa\u7840\u6982\u5ff5\u4e0e\u5b89\u5168\u793e\u533a\u4f7f\u7528\u7684\u672f\u8bed\u662f\u5341\u5206\u91cd\u8981\u7684\u3002 \u5b83\u4eec\u53ef\u4ee5\u542f\u53d1\u6211\u4eec\u8bbe\u8ba1\u66f4\u5b89\u5168\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u3002 \u8fd9\u672c\u4e66\u5c1d\u8bd5\u53bb\u603b\u7ed3\u6700\u4e3a\u91cd\u8981\u7684\u5b89\u5168\u57fa\u7840\u6982\u5ff5\uff08\u5b83\u4eec\u5f80\u5f80\u5206\u6563\u5730\u5728\u5bc6\u7801\u5b66\u3001\u64cd\u4f5c\u7cfb\u7edf\u5b89\u5168\u3001\u7f51\u7edc\u5b89\u5168\u8bfe\u4e0a\u88ab\u8bb2\u6388\uff09\uff0c\u5e76\u63d0\u4f9b\u7ed9\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u3002</p>"},{"location":"SBCA/Preface.html#outline-of-the-book","title":"OUTLINE OF THE BOOK","text":"<p>\u5728\u7b2c\u4e00\u7ae0\u4e2d\uff0c\u6211\u4eec\u4ecb\u7ecd\u4e86\u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5\uff0c\u63d0\u4f9b\u4e86\u73b0\u6709\u7684\u9762\u5411\u6027\u80fd\u3001\u529f\u8017\u3001\u9762\u79ef\u3001\u6210\u672c\u7684\u5b9e\u9645\u65b9\u6cd5\u4ee5\u5916\u7684\u65b9\u6cd5\u3002 \u6211\u4eec\u5b9a\u4e49\u4e86\u5b89\u5168\u7684\u4e09\u5927\u57fa\u77f3\u7279\u6027\uff1a\u673a\u5bc6\u6027\u3001\u5b8c\u6574\u6027\u3001\u53ef\u7528\u6027\u3002 (We define the cornerstone security properties of Confidentiality, Integrity and Availability.) \u6211\u4eec\u8fd8\u5b9a\u4e49\u4e86\u57fa\u7840\u6027\u7684\u8bbf\u95ee\u63a7\u5236\uff0c\u4ee5\u53ca\u5176\u4ed6\u9700\u8981\u7684\u5b89\u5168\u7279\u6027\u3002 (We also define fundamental access control, as well as other desirable security properties.) \u6211\u4eec\u5b9a\u4e49\u4e86\u6240\u8c13\u7684\u5b89\u5168\u8ba1\u7b97\u673a\uff0c\u5373\u6240\u8c13\u53ef\u4fe1\u8ba1\u7b97\u673a\u3002 (We define what we mean by a security-aware computer, which we also call a trustworthy computer.) \u6211\u4eec\u8fd8\u63d0\u51fa\u4e86\u4e00\u79cd\u7cfb\u7edf\u6027\u7684\u5b89\u5168\u8bbe\u8ba1\u65b9\u6cd5\u3002 (We also propose a systematic security architecture design methodology.)</p> <p>\u4ece\u7b2c\u4e8c\u7ae0\u5230\u7b2c\u516d\u7ae0\uff0c\u6211\u4eec\u4ecb\u7ecd\u4e86\u91cd\u8981\u7684\u5b89\u5168\u6280\u672f\uff0c\u5305\u62ec\u5b89\u5168\u7b56\u7565\u3001\u8bbf\u95ee\u63a7\u5236\u65b9\u6cd5\u3001\u5bc6\u7801\u5b66\u6280\u672f\u3001\u5b89\u5168\u534f\u8bae\u3002 \u672c\u4e66\u6709\u4e00\u4e2a\u7279\u8272\u7248\u5757\uff0c\u6211\u4eec\u5728\u54ea\u91cc\u63d0\u4f9b\u4e86\u5173\u4e8e\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u5982\u4f55\u7528\u5b89\u5168\u6280\u672f\u6765\u8bbe\u8ba1\u53ef\u4fe1\u8ba1\u7b97\u673a\u7684\u4f8b\u5b50\u3002</p> <p>\u7b2c\u4e8c\u7ae0\u4ecb\u7ecd\u4e86\u5b89\u5168\u7b56\u7565\u6a21\u578b\uff0c\u5305\u62ec\u591a\u5c42\u6b21(multi-level)\u548c\u591a\u65b9\u9762(multi-lateral)\u5b89\u5168\u3002 \u8fd9\u6709\u52a9\u4e8e\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u5b66\u4e60\u5b89\u5168\u672f\u8bed\u5e76\u4e14\u7406\u89e3\u5982\u4f55\u8003\u8651\u5b89\u5168\u7b56\u7565\u4ee5\u7528\u4e8e\u786e\u4fdd\u673a\u5bc6\u6027\u548c\u5b8c\u6574\u6027\u3002 \u5b89\u5168\u7b56\u7565\u6a21\u578b\u7684\u4f7f\u7528\u5141\u8bb8\u6211\u4eec\u53bb\u96c6\u4e2d\u5173\u6ce8\u5728\u6d59\u897f\u57fa\u7840\u6982\u5ff5\u4e0a\uff0c\u800c\u4e0d\u662f\u771f\u662f\u7684\u6781\u4e3a\u5e9e\u6742\u7684\u5b89\u5168\u7b56\u7565\u3002</p> <p>\u7b2c\u4e09\u7ae0\u4ecb\u7ecd\u4e86\u57fa\u7840\u7684\u8bbf\u95ee\u63a7\u5236\uff0c\u5305\u62ec\u8ba4\u8bc1(authentication)\u3001\u6388\u6743(authorization)\u65b9\u6cd5\u3002 \u5c3d\u7ba1\u8fd9\u4e9b\u65b9\u6cd5\u88ab\u5178\u578b\u5730\u7528\u4e8e\u64cd\u4f5c\u7cfb\u7edf\u5b89\u5168\uff0c\u4f46\u662f\u4ed6\u4eec\u9700\u8981\u5047\u5b9a\u6709\u53ef\u4fe1\u7684\u76d1\u7ba1\u7a0b\u5e8f(hypervisor)\u4e0e\u786c\u4ef6(hardware)\uff0c\u5c24\u5176\u662f\u5f53\u64cd\u4f5c\u7cfb\u7edf\u88ab\u7eb3\u5165\u8003\u91cf\u4e4b\u540e\u3002</p> <p>\u7b2c\u56db\u7ae0\u548c\u7b2c\u4e94\u7ae0\u63d0\u4f9b\u4e86\u5bf9\u4e8e\u5bc6\u7801\u5b66\u6280\u672f\u7684\u4ecb\u7ecd\u3002 \u8fd9\u662f\u4e00\u4e2a\u5df2\u7ecf\u5145\u5206\u53d1\u5c55\u4e86\u7684\u9886\u57df\uff0c\u56e0\u6b64\u4e5f\u6709\u5b9d\u8d35\u7684\u53ef\u4f9b\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u76f4\u63a5\u4f7f\u7528\u7684\u5bc6\u7801\u5b66\u539f\u8bed(cryptographic primitives)\u3002 \u6211\u4eec\u5c06\u5176\u89c6\u4e3a\u4e00\u79cd\u65b0\u7684\u601d\u8003\u65b9\u5f0f\uff0c\u7528\u4e8e\u4ee3\u66ff\u6240\u8c13\u201c\u9650\u5236\u8bbf\u95ee\u201d\u7684\u6a21\u5f0f\uff08\u6b63\u5982\u6211\u4eec\u5728\u7b2c\u4e8c\u7ae0\u548c\u7b2c\u4e09\u7ae0\u8ba8\u8bba\u7684\u8bb8\u591a\u5b89\u5168\u7b56\u7565\u6a21\u578b\u548c\u8bbf\u95ee\u63a7\u5236\u65b9\u6cd5\u4e2d\u5e7f\u6cdb\u4f7f\u7528\u7684\uff09\u3002 \u8fd9\u79cd\u601d\u8003\u65b9\u5f0f\u4e0b\u5141\u8bb8\u5bf9\u4e8e\u52a0\u5bc6\u5185\u5bb9\u7684\u968f\u610f\u8bbf\u95ee\uff0c\u53ea\u5bf9\u4e8e\u7528\u4e8e\u4f7f\u5f97\u52a0\u5bc6\u5185\u5bb9\u6709\u610f\u4e49\u7684\u5bc6\u7801\u5b66\u5bc6\u94a5(cryptographic keys)\u7684\u8bbf\u95ee\u8fdb\u884c\u9650\u5236\u3002</p> <p>\u7b2c\u56db\u7ae0\u4ecb\u7ecd\u4e86\u5bf9\u79f0\u5bc6\u94a5\u5bc6\u7801(symmetric-key cryptography)\u548c\u5bc6\u7801\u5b66\u54c8\u5e0c\u7b97\u6cd5(crpytographic hash algorithms)\uff0c\u5b83\u4eec\u5206\u522b\u53ef\u7528\u4e8e\u4fdd\u62a4\u8ba1\u7b97\u673a\u7cfb\u7edf\u4e2d\u7684\u673a\u5bc6\u6027\u548c\u5b8c\u6574\u6027\u3002</p> <p>\u7b2c\u4e94\u7ae0\u4ecb\u7ecd\u4e86\u516c\u94a5\u5bc6\u7801\u5b66(public-key cryptography)\uff0c\u5b83\u53ef\u4ee5\u7528\u4e8e\u63d0\u4f9b\u63d0\u4f9b\u957f\u671f\u7684\u6570\u5b57\u8eab\u4efd\u9a8c\u8bc1(digital identities)\u3002 \u6211\u4eec\u8ba8\u8bba\u4e86\u6570\u5b57\u7b7e\u540d(digital signatures)\u3001\u516c\u94a5\u57fa\u7840\u8bbe\u65bd(Public Key Infrastructure, PKI)\u3001\u6570\u5b57\u8bc1\u4e66\u548c\u6570\u5b57\u8bc1\u4e66\u9881\u53d1\u673a\u6784(Certificate Authorities, CAs)\uff0c\u4ee5\u53ca\u4e2d\u95f4\u4eba\u653b\u51fb(man-in-the-middle attacks)\u548c\u8bef\u7528\u516c\u94a5\u5bc6\u7801\u5b66\u7684\u5371\u5bb3\u3002</p> <p>\u7b2c\u516d\u7ae0\u63d0\u4f9b\u4e86\u5b89\u5168\u534f\u8bae\u7684\u4ecb\u7ecd\uff0c\u5b83\u53ef\u4ee5\u7528\u4e8e\u5efa\u7acb\u8ba1\u7b97\u673a\u95f4\u7684\u7f51\u7edc\u5b89\u5168\u901a\u4fe1\u3002 \u5b83\u4eec\u540c\u6837\u53ef\u4ee5\u88ab\u7528\u4e8e\u8868\u8ff0\u540c\u4e00\u4e2a\u8ba1\u7b97\u673a\u5185\u90e8\u7684\u4e0d\u540c\u90e8\u5206\u4e4b\u95f4\u7684\u5b89\u5168\u901a\u4fe1\u3002 \u5b89\u5168\u534f\u8bae\u5bf9\u4e8e\u5b89\u5168\u67b6\u6784\u662f\u5f88\u91cd\u8981\u7684\uff0c\u6db5\u76d6\u5176\u8f6f\u4ef6\u3001\u786c\u4ef6\u548c\u7f51\u7edc\u7ec4\u4ef6\u3002 \u5982\u679c\u7528\u4e8e\u53d1\u9001\u65b9\u548c\u63a5\u6536\u65b9\u4e4b\u95f4\u4ea4\u4e92\u7684\u534f\u8bae\u4e0d\u5b89\u5168\uff0c\u90a3\u4e48\u4f7f\u7528\u7684\u5f3a\u5927\u7684\u5bc6\u7801\u5b66\u624b\u6bb5\u5c31\u6beb\u65e0\u7528\u5904\u3002</p> <p>\u7b2c\u4e03\u7ae0\u603b\u7ed3\u4e86\u4e0a\u8ff0\u8986\u76d6\u7684\u4e3b\u9898\uff0c\u6307\u51fa\u4e86\u4e00\u4e9b\u6709\u8da3\u7684\u5e94\u7528\u9886\u57df\u4ee5\u53ca\u786c\u4ef6\u76f8\u5173\u7684\u5b89\u5168\u4e3b\u9898\uff0c\u4ee5\u53ca\u901a\u5411\u8bbe\u8ba1\u5b89\u5168\u7684\u67b6\u6784\u7684\u9053\u8def\u548c\u65b9\u5411\u3002</p> <p>\u53ea\u60f3\u4e86\u89e3\u57fa\u7840\u7684\u5b89\u5168\u6982\u5ff5\u4f46\u662f\u5e76\u4e0d\u60f3\u8bbe\u8ba1\u5b89\u5168\u8ba1\u7b97\u673a\u7684\u8bfb\u8005\u53ef\u4ee5\u8df3\u8fc7\u67b6\u6784\u8bbe\u8ba1\u7684\u4f8b\u5b50\u3002 \u53ea\u60f3\u4e86\u89e3\u6216\u4f7f\u7528\u7b80\u5355\u7684\u5bc6\u7801\u5b66\u6280\u672f\u7684\u8bfb\u8005\u53ef\u4ee5\u8df3\u8fc7\u7b2c\u4e8c\u7ae0\u548c\u7b2c\u4e09\u7ae0\u3002 \u7136\u800c\uff0c\u4efb\u4f55\u8ba4\u771f\u8003\u8651\u8bbe\u8ba1\u5b89\u5168\u8ba1\u7b97\u673a\u7684\u8bfb\u8005\u90fd\u5e94\u8be5\u9605\u8bfb\u5168\u4e66\u3002 \u672c\u4e66\u63cf\u8ff0\u7684\u57fa\u7840\u5b89\u5168\u6982\u5ff5\u5141\u8bb8\u6211\u4eec\u540c\u5b89\u5168\u793e\u533a\u4ea4\u6d41\u5e76\u4e14\u7406\u89e3\u5982\u4f55\u4f7f\u7528\u9762\u5411\u5a01\u80c1\u7684\u8bbe\u8ba1\u65b9\u6cd5\u3002</p> <p>\u4e3a\u4e86\u7b80\u6d01\uff0c\u6211\u7ecf\u5e38\u4f7f\u7528PALMS(Princeton Architecture Lab for Multimedia and Security, http://palms.ee.princeton.edu )\u5b9e\u9a8c\u5ba4\u8bbe\u8ba1\u7684\u67b6\u6784\u4f5c\u4e3a\u4f8b\u5b50\uff0c\u4ee5\u4fbf\u63ed\u793a\u5982\u4f55\u672c\u4e66\u4e2d\u5c55\u793a\u7684\u5b89\u5168\u7406\u5ff5\u53ef\u4ee5\u7528\u4e8e\u8bbe\u8ba1\u8f6f\u786c\u4ef6\u5b89\u5168\u67b6\u6784\u3002 \u8fd9\u4e9b\u4f8b\u5b50\u5bf9\u6211\u975e\u5e38\u719f\u6089\uff0c\u56e0\u6b64\u6211\u53ef\u4ee5\u66f4\u5feb\u5730\u5199\u4f5c\u3002 \u6211\u540c\u6837\u7ed9\u51fa\u4e86\u4e00\u4e9b\u5176\u4ed6\u8bbe\u8ba1\u7684\u4f8b\u5b50\uff0c\u4ee5\u53ca\u8bb8\u591a\u9886\u57df\u5e7f\u6cdb\u7684\u53c2\u8003\u6587\u732e\u548c\u76f8\u5173\u5de5\u4f5c\u7684\u5217\u8868\u3002 \u4e00\u672c\u540e\u7eed\u7684\u4e66\u4f1a\u66f4\u52a0\u8be6\u7ec6\u5730\u8ba8\u8bba\u65b0\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u5b89\u5168\u7814\u7a76\u4e3b\u9898\u3002 \u8fd9\u672c\u4e66\u7684\u76ee\u7684\u662f\u6d53\u7f29\u5927\u91cf\u7684\u5b89\u5168\u57fa\u7840\u6982\u5ff5\u6210\u4e00\u672c\u7b80\u77ed\u7684\u624b\u518c\u3002 \u56e0\u6b64\uff0c\u6211\u9009\u62e9\u7684\u4e3b\u9898\u662f\u5bf9\u4e8e\u7406\u89e3\u5b89\u5168\u7684\u4e00\u4e9b\u7ef4\u5ea6\u5e76\u8fa8\u6790\u4e4b\u7684\u57fa\u7840\u4e14\u91cd\u8981\u7684\u5185\u5bb9\uff0c\u80fd\u591f\u542f\u53d1\u65b0\u7684\u8bbe\u8ba1\u5b89\u5168\u7cfb\u7edf\u7684\u601d\u8def\u3002</p> <p>\u90a3\u4e9b\u719f\u6089\u6784\u5efa\u7cfb\u7edf\u7684\u8ba1\u7b97\u673a\u67b6\u6784\u5e08\u73b0\u5728\u4e5f\u5fc5\u987b\u5b66\u4f1a\u601d\u8003\u7cfb\u7edf\u4f1a\u5982\u4f55\u88ab\u653b\u51fb\u8005\u7834\u574f\u6216\u5229\u7528\u3002 \u6211\u4eec\u9700\u8981\u53bb\u5b66\u4e60\u5982\u4f55\u4e3b\u52a8\u5728\u8bbe\u8ba1\u4e2d\u62b5\u6297\u8fd9\u79cd\u6076\u610f\u884c\u4e3a\u3002 \u672c\u4e66\u4e2d\u63cf\u8ff0\u7684\u57fa\u672c\u5b89\u5168\u6982\u5ff5\u63d0\u4f9b\u4e86\u4e30\u5bcc\u7684\u70b9\u5b50\u548c\u6280\u672f\u4f5c\u4e3a\u51fa\u53d1\u70b9\u4ee5\u4f9b\u601d\u8003\u5982\u4f55\u8bbe\u8ba1\u65b0\u7684\u8f6f\u786c\u4ef6\u67b6\u6784\u3002</p> <p>\u6211\u8981\u611f\u8c22\u6211\u5728 Princeton \u672c\u79d1\u73ed ELE/EGR 386 \u7f51\u7edc\u5b89\u5168\u548c\u7814\u7a76\u751f\u7814\u8ba8\u73ed ELE/COS 580 \u53ef\u4fe1\u8ba1\u7b97\u7684\u52a9\u6559\u548c\u5b66\u751f\uff0c\u611f\u8c22\u4ed6\u4eec\u5bf9\u6211\u7684\u8bb2\u5ea7\u548c\u8ba8\u8bba\u7684\u6709\u8da3\u6295\u5165\u3002 \u672c\u4e66\u53cd\u6620\u4e86\u6211\u5728\u8fd9\u4e9b\u8bfe\u7a0b\u4e2d\u7684\u4e00\u4e9b\u8bb2\u5ea7\u6750\u6599\u3002 \u975e\u5e38\u611f\u8c22 Mark Hill\uff0c\u4ed6\u672c\u80fd\u5730\u610f\u8bc6\u5230\u4e86\u8ba1\u7b97\u673a\u67b6\u6784\u4e2d\u5b89\u5168\u6027\u7684\u91cd\u8981\u6027\uff0c\u591a\u6b21\u9080\u8bf7\u6211\u5199\u4e00\u672c\u5173\u4e8e\u5b89\u5168\u6027\u7684\u4e66\uff0c\u5e76\u4e14\u4e0d\u63a5\u53d7\u62d2\u7edd\u3002 Mike Morgan \u4e5f\u4e0d\u65ad\u9f13\u52b1\u6211\u5b8c\u6210\u8fd9\u672c\u4e66\u3002\u6700\u540e\uff0c\u6211\u8981\u611f\u8c22\u6211\u4eb2\u7231\u7684\u4e08\u592b Howard\uff0c\u65e0\u8bba\u6211\u662f\u5426\u5728\u5199\u4e66\uff0c\u4ed6\u90fd\u8ba9\u6211\u7684\u751f\u6d3b\u5145\u6ee1\u4e50\u8da3\u5e76\u5982\u6b64\u6df1\u60c5\u5730\u652f\u6301\u6211\u3002</p>"},{"location":"SBCA/translator.html","title":"\u8bd1\u5e8f","text":"<p>\u5c1d\u8bd5\u7ffb\u8bd1\u672c\u4e66\uff0c\u4e0d\u77e5\u6548\u679c\u5982\u4f55\u3002</p>"},{"location":"about/index.html","title":"About","text":"<p>\u6211\u662f\u6e05\u534e\u5927\u5b66\u7535\u5b50\u5de5\u7a0b\u7cfb\u7684\u4e00\u540d\u672c\u79d1\u751f\u3002</p> <p>\u6211\u7684\u90ae\u7bb1\u662f fanyc22[at]mails.tsinghua.edu.cn\u3002</p> <p>\u6211\u7684Github\u4e3b\u9875\u662f@fanyc22</p>"},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html","title":"Early Load Execution via Constant Address and Stride Prediction","text":"","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#abstract","title":"Abstract","text":"<p>\u4e00\u79cd\u6709\u6548\u51cf\u5c11\u52a0\u8f7d\u64cd\u4f5c\u5ef6\u8fdf\u7684\u7cfb\u7edf\u548c\u65b9\u6cd5\u3002 \u5728\u5404\u79cd\u5b9e\u65bd\u4f8b\u4e2d\uff0c\u5904\u7406\u5668\u7684\u903b\u8f91\u5728\u83b7\u53d6\u6307\u4ee4\u4e4b\u540e\u8bbf\u95ee\u9884\u6d4b\u8868\u3002 \u5bf9\u4e8e\u9884\u6d4b\u8868\u547d\u4e2d\uff0c\u903b\u8f91\u4f7f\u7528\u4ece\u9884\u6d4b\u8868\u4e2d\u68c0\u7d22\u5230\u7684\u9884\u6d4b\u5730\u5740\u6267\u884c\u52a0\u8f7d\u6307\u4ee4\u3002 \u5bf9\u4e8e\u9884\u6d4b\u8868\u672a\u547d\u4e2d\uff0c\u5f53\u903b\u8f91\u786e\u5b9a\u52a0\u8f7d\u6307\u4ee4\u7684\u5730\u5740\u5e76\u547d\u4e2d\u5b66\u4e60\u8868\u65f6\uff0c\u4e14\u5f53\u5b66\u4e60\u8868\u4e2d\u5b58\u50a8\u7684\u5730\u5740\u4e0e\u786e\u5b9a\u7684\u5730\u5740\u5339\u914d\u65f6\uff0c\u903b\u8f91\u66f4\u65b0\u7f6e\u4fe1\u5ea6\u6307\u793a\u4ee5\u6307\u793a\u66f4\u9ad8\u7684\u7f6e\u4fe1\u5ea6\u3002 \u5f53\u903b\u8f91\u786e\u5b9a\u5b58\u50a8\u5728\u5b66\u4e60\u8868\u7684\u7ed9\u5b9a\u8868\u6761\u76ee\u4e2d\u7684\u7f6e\u4fe1\u5ea6\u6307\u793a\u8fbe\u5230\u9608\u503c\u65f6\uff0c\u903b\u8f91\u5728\u9884\u6d4b\u8868\u4e2d\u5206\u914d\u5b58\u50a8\u5728\u7ed9\u5b9a\u6761\u76ee\u4e2d\u7684\u4fe1\u606f\u3002 \u56e0\u6b64\uff0c\u5728\u4e0b\u4e00\u6b21\u67e5\u627e\u9884\u6d4b\u8868\u65f6\uff0c\u9884\u6d4b\u5730\u5740\u53ef\u7528\u3002</p> <p>Patent \u5b9e\u5728\u662f\u4e0d\u597d\u8bfb\u3002 \u5341\u5206\u5570\u55e6\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#processor-core","title":"Processor Core","text":"<p>\u6ce8\u610f\u8fd9\u91cc\u5229\u7528\u4e86 PC history akey \u53bb\u505a\u67e5\u627e\u3002\u4e14\u67e5\u627e\u53ef\u80fd\u5728 decoder \u524d/\u540c\u65f6/\u540e\u3002</p> <p>Map Unit \u7528\u4e8e\u7ed9\u8bd1\u7801\u7ed3\u679c\u6216\u8005 uop \u5206\u914d\u7269\u7406\u5bc4\u5b58\u5668\u3002</p> <p>STL \u4f1a\u88ab\u8ba4\u4e3a mispredict \u8fd9\u662f\u7528\u4e8e\u9632\u6b62\u4ece cache \u8bfb\u9020\u6210\u7684 RAW \u9519\u8bef\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#early-load-method","title":"Early Load Method","text":"<p>intsr. \u4f1a\u88ab\u62c6\u5206\u4e3a\u4e24\u6761\u6307\u4ee4 pred. instr. \u548c non-pred. instr.\u3002</p> <p>\u6ce8\u610f\u5230\u8fd9\u91cc\u5f3a\u8c03 predicted load \u9700\u8981\u5728 cache \u4e2d\u3002 \u8fd9\u5f88\u5408\u7406\uff0c\u56e0\u4e3a\u5982\u679c\u4e0d\u5728\uff0cpredicted \u548c non-predicted load \u4e4b\u95f4\u7684\u5ef6\u8fdf\u5dee\u522b\u4e0d\u5927\u3002</p> <p>\u4f46\u662f\u6587\u4e2d\u4e5f\u8bf4\u4e5f\u53ef\u80fd\u4f1a\u8fdb\u4e00\u6b65\u5411\u66f4\u4f4e\u7684 cache \u67e5\u627e\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#load-addr-predicting-method","title":"Load Addr. Predicting Method","text":"<p>\u6ce8\u610f\u5230\u8fd9\u91cc\u5f3a\u8c03\u4e86\u4e00\u4e2a arbitration logic\uff0c\u8fd9\u610f\u5473\u7740\u8fdb\u7a0b\u4fe1\u606f\u7b49\u8bb8\u591a\u56e0\u7d20\u51b3\u5b9a\u4e86 load \u662f\u5426\u4f1a\u88ab\u9884\u6d4b\u3002 \u56e0\u7d20\u7684\u6743\u91cd\u88ab\u4e00\u4e2a programable reg. \u4fdd\u5b58\u3002</p> <p>\u5728\u8fd9\u4e2a\u65b9\u6cd5\u4e2d\uff0c\u88ab\u6267\u884c\u7684 pred. load \u548c cache miss \u7684 pred. load \u4f1a\u88ab\u653e\u5230 retire queue\u3002 \u57fa\u4e8e PA \u5bf9 retire queue \u4e2d\u7684 load \u8fdb\u884c\u68c0\u67e5\uff0c\u66f4\u65b0 learning table\u3002</p> <p>\u4e0d\u662f\u6240\u6709\u7684 retire queue \u4e2d\u7684 instr. \u90fd\u4f1a\u88ab\u5b66\u4e60\u3002 \u4f8b\u5982\u603b\u662f\u9884\u6d4b\u9519\u8bef\u7684\u53ef\u80fd\u4f1a\u88ab\u8bb0\u5f55\u5230 filter\uff0c\u540e\u7eed\u4e0d\u518d\u5b66\u4e60\u4e4b\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#table-entry","title":"Table Entry","text":"<p>Securty tag \u53ef\u80fd\u5305\u62ecASID\u3001VMID\u3002</p> <p>\u8fd9\u91cc\u7684 intermittent strided load \u5f88\u6709\u610f\u601d\u3002 \u7531\u4e8e\u63d0\u9ad8 LT \u4e2d\u7f6e\u4fe1\u5ea6\u5bfc\u81f4\u5728 PT \u4e2d\u5206\u914d entry \u7684 load \u548c\u4e0b\u4e00\u4e2a\u5468\u671f\u88ab\u9884\u6d4b\u7684 load \u4e2d\u6709\u591a\u4e2a\u6307\u4ee4\u6b63\u5728\u6d41\u6c34\u7ea7\uff0c\u6545\u53ef\u80fd\u4f1a\u5bfc\u81f4 stride \u9884\u6d4b\u9519\u8bef\u3002 \u8fd9\u91cc\u91c7\u7528\u4e24\u79cd\u65b9\u5f0f\u89e3\u51b3\uff1a</p> <ol> <li>\u8ba4\u4e3a\u7b2c\u4e00\u4e2a\u5728 PT \u4e2d\u67e5\u627e\u5230\u7684\u662f probing instr.\uff0c\u963b\u585e\u540e\u9762\u7684\u67e5\u8be2\uff0c\u76f4\u5230 probing tnstr. \u88ab\u5904\u7406\u7ed3\u675f\uff0c\u786e\u5b9a intermittent \u7684\u6570\u91cf\u3002</li> <li>\u8ddf\u8e2a\u8bb0\u5f55\u6d41\u6c34\u7ea7\u4e2d instr. \u7684 PC\uff0c\u76f4\u63a5\u786e\u5b9a intermittent \u7684\u6570\u91cf\u3002</li> </ol>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#pt-miss-handling-method","title":"PT Miss Handling Method","text":"<p>\u4f1a\u5728 accessing LT \u4e4b\u524d\u9996\u5148\u505a STLF\u3002 \u8fd9\u91cc\u63d0\u5230 STLF \u4e5f\u4f1a\u6709 prediction\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#lt-entry-updating-method","title":"LT Entry Updating Method","text":"<p>\u6ce8\u610f\u5230\u8fd9\u91cc\u6709\u79cd\u5b9e\u73b0\u662f\u66f4\u65b0 base addr. \u4e3a\u539f\u672c\u7684 base addr. + stride\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#pt-entry-updating-based-on-lt-entry-updating-method","title":"PT Entry Updating (Based on LT Entry Updating) Method","text":"<p>LT entry \u4e2d\u7684\u7f6e\u4fe1\u5ea6\u4f1a\u51b3\u5b9a\u662f\u5426\u6dfb\u52a0/\u6e05\u9664 PT entry\u3002</p> <p>PT enrty \u6e05\u9664\u7684\u9608\u503c\u53ef\u80fd\u4f1a\u6bd4 LT entry \u6e05\u9664\u7684\u9608\u503c\u9ad8\u3002 \u4e5f\u6709\u53ef\u80fd LT entry \u4e0d\u4e3b\u52a8\u6e05\u9664\uff0c\u53ea\u4f1a\u88ab evict\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#ltpt-resource-saving-method","title":"LT&amp;PT Resource Saving Method","text":"<p>\u8fd9\u91cc\u5f88\u6709\u8da3\uff0c\u5982\u679c\u8861\u91cf\u5230\u67d0\u6761 pred. instr. \u548c\u5176 non-pred. instr. \u7684\u5ef6\u8fdf\u5dee\u522b\u4e0d\u5927\uff0c\u90a3\u4e48\u5c31\u5728\u540e\u7eed\u4e0d\u518d\u9884\u6d4b\u8be5\u6761 instr.\u3002</p> <p>\u6587\u4e2d\u7ed9\u51fa\u4e86\u5ef6\u8fdf\u4e0d\u540c\u7684\u5b9a\u4e49\u3002</p> <p>\u5177\u4f53\u4ec0\u4e48\u56e0\u7d20\u4f1a\u5f71\u54cd\u5355\u4e2a pred. instr. \u548c non-pred. instr. \u7684\u5ef6\u8fdf\u5dee\u522b\uff0c\u6587\u4e2d\u6ca1\u6709\u7ed9\u51fa\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#lt-entry-invalidating-method-using-consecutive-mismatch-count","title":"LT Entry Invalidating Method Using Consecutive Mismatch Count","text":"<p>\u8fd9\u662f\u4e00\u79cd\u65b9\u6cd5\uff0c\u4e0d\u540c\u4e8e\u4e0a\u8ff0\u7684\u57fa\u4e8e\u7f6e\u4fe1\u5ea6\u7684 LT entry \u6e05\u9664\u65b9\u6cd5\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#avoiding-discrepancies-in-memory-access-ordering","title":"Avoiding Discrepancies in Memory Access Ordering","text":"<p>\u56fe\u4f8b\u7591\u4f3c\u6709\u9519\uff0cAR6 \u5e94\u8be5\u662f A\u3002</p> <p>\u8fd9\u91cc\u5047\u5b9a\uff1a</p> <ul> <li>store instr. \u5728\u6240\u6709 non-pred. load instr. \u4e4b\u524d\u5747\u5b8c\u6210\u3002</li> <li>pred. load \u5728 store1 \u548c store2 \u4e4b\u95f4\u6267\u884c\u3002</li> <li>\u5bf9\u4e8e load2 \u7684\u9884\u6d4b\u662f\u6b63\u786e\u7684\u3002</li> </ul> <p>\u5018\u82e5\u4e0d\u8fdb\u884c\u9884\u6d4b\uff0c\u8fd9\u91cc\u7684 load2 \u4f1a\u5728 load1 \u4e4b\u540e\u6267\u884c\uff0cPR2 \u7684\u503c\u662f AR5 \u7684\u503c\u3002 \u4f46\u662f\u8fdb\u884c\u9884\u6d4b\u540e\uff0cPR2 \u7684\u503c\u662f AR4 \u7684\u503c\u3002\u8fd9\u9020\u6210\u903b\u8f91\u4e0a\u5e94\u8be5\u5148\u6267\u884c\u7684\u6307\u4ee4 load1 \u770b\u5230\u7684\u5185\u5b58\u72b6\u6001\u6bd4 \u903b\u8f91\u4e0a\u5e94\u8be5\u540e\u6267\u884c\u7684\u6307\u4ee4 load2 \u770b\u5230\u7684\u5185\u5b58\u72b6\u6001\u8981\u5728\u65f6\u5e8f\u4e0a\u9760\u540e\u3002\u4e14\u7531\u4e8e\u9884\u6d4b\u5730\u5740\u6ca1\u6709\u9519\u8bef\uff0cCore1 \u65e0\u6cd5\u53d1\u73b0\u8be5\u9519\u8bef\u3002</p> <p>\u4e3a\u4e86\u907f\u514d\u8fd9\u79cd\u8bbf\u5b58\u987a\u5e8f\u4e0d\u4e00\u81f4\uff0c\u4e0d\u5141\u8bb8\u5b58\u5728\u64cd\u4f5c\u6570\u4f9d\u8d56\u4e8e\u5148\u524d\u7684 load instr. \u7684 load instr. \u88ab\u9884\u6d4b\u3002</p> <p>\u5b9e\u9645\u4e0a\u6211\u5e76\u4e0d\u662f\u5f88\u7406\u89e3\u8fd9\u4e00\u90e8\u5206\u3002\u4e0d\u5b58\u5728\u64cd\u4f5c\u6570\u4f9d\u8d56\u7684 load instr. \u5982\u679c\u88ab\u63d0\u524d\u6267\u884c\u4e86\uff0c\u4f3c\u4e4e\u770b\u5230\u7684\u5185\u5b58\u65f6\u5e8f\u548c\u903b\u8f91\u4e0a\u7684\u6267\u884c\u65f6\u5e8f\u4e5f\u662f\u4e0d\u4e00\u81f4\u7684\u3002\u5982\u679c AR6 \u5c31\u662f A\uff0c\u90a3\u4e48\u68c0\u67e5 load2 \u662f\u5426\u9884\u6d4b\u6b63\u786e\u7684\u65f6\u5019\u5e94\u8be5\u5c31\u662f\u4e0d\u6b63\u786e\uff0c\u548c\u6587\u4e2d\u63cf\u8ff0\u4e5f\u4e0d\u7b26\u5408\u3002</p>","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2024/12/13/early-load-execution-via-constant-address-and-stride-prediction.html#soc-system","title":"Soc &amp; System","text":"","tags":["Apple Inc.","US Patent","Microarchitecture"]},{"location":"blog/2025/03/25/modify-compile-and-install-the-kernel-from-source-on-asahi-linux.html","title":"(Modify,) Compile and Install the Kernel from Source on Asahi Linux","text":"<p>This is the first tutorial of building and installing the kernel from source on Asahi Linux since they moved to the Fedora kernel. This blog is not wriiten by me, but by Minghong Sun.</p>","tags":["Asahi Linux","Kernel","Building Kernel from Source"]},{"location":"blog/2025/03/25/modify-compile-and-install-the-kernel-from-source-on-asahi-linux.html#preparation","title":"Preparation","text":"<ol> <li>Install Asahi Linux (if not already installed):</li> </ol> <pre><code>curl https://alx.sh | sh\n</code></pre> <ol> <li>Download the kernel source:</li> </ol> <p>Download the appropriate version from the Fedora Asahi Repo and extract it:</p> <pre><code>tar -xf kernel-asahi-kernel-6.12.1-404.asahi.tar.gz\ncd kernel-asahi-kernel-6.12.1-404.asahi/\n</code></pre> <ol> <li>Install the building essentials:</li> </ol> <pre><code>sudo dnf install make automake gcc gcc-c++ openssl-devel ncurses-devel flex bison\n</code></pre>","tags":["Asahi Linux","Kernel","Building Kernel from Source"]},{"location":"blog/2025/03/25/modify-compile-and-install-the-kernel-from-source-on-asahi-linux.html#config-and-complie","title":"Config and Complie","text":"<ol> <li>Copy the current kernel configuration:</li> </ol> <p>Copy your existing kernel configuration as a starting point and then open it with the menuconfig interface to adjust settings if needed.</p> <pre><code>sudo cp -v /boot/config-$(uname -r) .config\nmake menuconfig\n</code></pre> <ol> <li>Compile the kernel:</li> </ol> <p>Use the <code>-j</code> flag (adjust the number according to your CPU cores) for faster compilation:</p> <pre><code>make -j 24\n</code></pre> <ol> <li>Install the modules, device trees, vdso, and kernel:</li> </ol> <pre><code>sudo make modules_install dtbs_install vdso_install install\n</code></pre> <pre><code>But we are not done now, if you reboot immediatly, you'll **BRICK** the whole system.\n</code></pre>","tags":["Asahi Linux","Kernel","Building Kernel from Source"]},{"location":"blog/2025/03/25/modify-compile-and-install-the-kernel-from-source-on-asahi-linux.html#deal-with-dtb-problems","title":"Deal with DTB problems","text":"<ol> <li> <p>Move the DTB files to the correct location:</p> <p>The <code>dtbs_install</code> command installs dtbs in the wrong place, if you go to <code>/boot</code> and run <code>ls -la</code>, you'll see <code>dtb</code> is a symlink to <code>/boot/dtb-$(uname -r)</code>, but it's invalid. That's because our dtb files are installed in <code>/boot/dtbs/$(uname -r)</code>. So what you need to do is move it to the right place:</p> </li> </ol> <pre><code>sudo mv /boot/dtbs/6.12.1/ /boot/dtb-6.12.1\n</code></pre> <pre><code>Replace the `6.12.1` with the name of your newly installed kernel.\n</code></pre> <ol> <li> <p>(Optional) Sync DTB files into <code>/lib/modules</code>:</p> <p>We also found that in a fresh-installed system, the dtb files are also in <code>/lib/modules/$(uname -r)/dtb/</code>. But the Asahi Linux Docs said that it is \"nonstandard\" and they will \"have better tooling for this in the future\". So I have no idea whether these files are still necessary, but just in case, we do:</p> </li> </ol> <pre><code>sudo mkdir /lib/modules/6.12.1/dtb\nsudo cp -r /boot/dtb-6.12.1/* /lib/modules/6.12.1/dtb/\n</code></pre>","tags":["Asahi Linux","Kernel","Building Kernel from Source"]},{"location":"blog/2025/03/25/modify-compile-and-install-the-kernel-from-source-on-asahi-linux.html#update-m1n1","title":"Update m1n1","text":"<p>Now we have one last thing to do, run:</p> <pre><code>sudo update-m1n1\n</code></pre> <p>The Asahi Linux Docs said this is necessary after every kernel upgrade.</p>","tags":["Asahi Linux","Kernel","Building Kernel from Source"]},{"location":"blog/2025/03/25/modify-compile-and-install-the-kernel-from-source-on-asahi-linux.html#done-and-reboot","title":"Done and reboot","text":"<p>Before rebooting, double-check that you have completed every step. Skipping any part could result in an unbootable system or boot loops. A critical note: due to issues like the absence of USB keyboard support in GRUB (see this issue), recovering from such a scenario can be very challenging.</p> <p>When you\u2019re certain that everything is in place, you can safely reboot:</p> <pre><code>sudo grubby --info=ALL # Find the index of the new kernel\nsudo vim /etc/default/grub # Change the default kernel to the new one\nsudo grub2-mkconfig -o /boot/grub2/grub.cfg\nsudo reboot\n</code></pre>","tags":["Asahi Linux","Kernel","Building Kernel from Source"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html","title":"The Microarchitecture of Superscalar Processors","text":"","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_1","title":"\u80cc\u666f","text":"<p>\u300a\u73b0\u4ee3\u8ba1\u7b97\u673a\u4f53\u7cfb\u7ed3\u6784\u300b\u8bfe\u7a0b\u4f5c\u4e1a\u8981\u6c42\u9605\u8bfb1995\u5e74 J. Smith \u548c G. Sohi \u7684\u8bba\u6587 The Microarchitecture of Superscalar Processors \u3002\u672c\u6587\u662f\u5bf9\u8fd9\u7bc7\u8bba\u6587\u7684\u5b66\u4e60\u548c\u6574\u7406\u7684\u7b14\u8bb0\u3002</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#abstract","title":"Abstract","text":"<p>\u6587\u7ae0\u4e3b\u8981\u4ece4\u4e2a\u65b9\u9762\u8ba8\u8bba\uff1a</p> <ol> <li>\u53d6\u6307\u548c\u6761\u4ef6\u5206\u652f\u5904\u7406</li> <li>\u6d89\u53ca\u5bc4\u5b58\u5668\u503c\u7684\u6570\u636e\u4f9d\u8d56\u7684\u786e\u5b9a</li> <li>\u9488\u5bf9\u5e76\u884c\u6267\u884c\u7684\u6307\u4ee4\u521d\u59cb\u5316\u4e0e\u53d1\u5c04</li> <li>\u987a\u5e8f\u63d0\u4ea4\u6307\u4ee4\u72b6\u6001\u4ee5\u652f\u6301\u7cbe\u786e\u4e2d\u65ad</li> </ol> <p>\u4e3e\u4f8b\u7528\u4e86 MIPS R10000\uff0cDEC 21164\uff0cAMD K5\u3002</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#introduction","title":"Introduction","text":"<p>95\u5e74\u9644\u8fd1 SS \u5904\u7406\u5668\u5df2\u7ecf\u5e7f\u6cdb\u5e94\u7528\u5728\u5404\u5382\u5546\u9ad8\u7aef\u5904\u7406\u5668\uff0c\u8986\u76d6 DEC Alpha\uff0cRSIC\uff0cx86 \u7b49\u6307\u4ee4\u96c6\u3002</p> <p>\u5178\u578b SS \u5904\u7406\u5668\uff1a</p> <p>A typical superscalar processor fetches and decodes the incoming instruction stream several instructions at a time. As part of the instruction fetching process, the outcomes of conditional branch instructions are usually predicted in advance to ensure an uninterrupted stream of instructions. The incoming instruction stream is then analyzed for data dependences, and instructions are distributed to functional units, often according to instruction type. Next, instructions are initiated for execution in parallel, based primarily on the availability of operand data, rather than their original program sequence. This important feature, present in many superscalar implementations, is referred to as dynamic instruction scheduling. Upon completion, instruction re- sults are resequenced so that they can be used to update the process state in the correct (original) program order in the event that an interrupt condition occurs. Because individual instructions are the entities being executed in parallel, superscalar processors exploit what is referred to as instruction level parallelism (ILP).</p> <ol> <li>\u5e76\u884c\u53d6\u6307\uff08\u5206\u652f\u9884\u6d4b\uff09</li> <li>\u5206\u6790\u6570\u636e\u4f9d\u8d56\uff0c\u5206\u914dFU</li> <li>\u57fa\u4e8e\u64cd\u4f5c\u6570\u53ef\u83b7\u53d6\u6027\u4e71\u5e8f\u542f\u52a8\u6307\u4ee4\u6267\u884c\uff08i.e. \u52a8\u6001\u6307\u4ee4\u8c03\u5ea6\uff09</li> <li>\u6307\u4ee4\u7ed3\u679c\u91cd\u6392\u5e8f\uff0c\u4ee5\u4fbf\u7cbe\u786e\u4e2d\u65ad</li> </ol> <p>\u6307\u4ee4\u6267\u884c\u6a21\u578b\u7531\u4e8e\u5386\u53f2\u539f\u56e0\u88ab\u8ba4\u4e3a\u662f\u987a\u5e8f\u6267\u884c\u7684\uff0c\u56e0\u6b64\u7cbe\u786e\u4e2d\u65ad\u4e00\u76f4\u88ab\u4f7f\u7528\u3002</p> <p>SS \u5904\u7406\u5668\u5305\u62ec\u4ee5\u4e0b\u6280\u672f\uff1a</p> <ol> <li>\u5e76\u884c\u591a\u6307\u4ee4\u53d6\u6307\uff0c\u901a\u5e38\u5229\u7528\u5206\u652f\u9884\u6d4b</li> <li>\u771f\u4f9d\u8d56\u7684\u68c0\u6d4b\u53ca\u6570\u636e\u8f6c\u53d1</li> <li>\u540c\u65f6\u53d1\u5c04\u591a\u6307\u4ee4\u7684\u6280\u672f</li> <li>\u786c\u4ef6\u8d44\u6e90\u4ee5\u4f9b\u540c\u65f6\u6267\u884c\uff08\u591a\u4e2a FU\uff0c\u5185\u5b58\u652f\u6301\u591a\u5730\u5740\u8bbf\u95ee\uff09</li> <li>Methods for communicating data values through memory via load and store instructions, and memory interfaces that allow for the dynamic and often unpredictable performance behavior of memory hierarchies. These interfaces must be well matched with the instruction execution strategies.</li> <li>\u987a\u5e8f\u63d0\u4ea4\u4ee5\u7ef4\u62a4\u987a\u5e8f\u6267\u884c\u6a21\u578b</li> </ol>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_2","title":"\u7a0b\u5e8f\u8868\u793a\uff0c\u4f9d\u8d56\uff0c\u5e76\u884c\u6267\u884c","text":"<p>\u6570\u636e\u4f9d\u8d56\u5728\u8bfb\u5199\u540c\u4e00\u4e2a\u5b58\u50a8\u4f4d\u7f6e\uff08\u5bc4\u5b58\u5668\u6216\u8005\u5185\u5b58\uff09\u65f6\u51fa\u73b0\u3002\u7406\u60f3\u60c5\u51b5\u4e0b\uff0c\u6307\u4ee4\u6267\u884c\u4ec5\u670d\u4ece\u771f\u4f9d\u8d56\uff08RAW\uff0cread-after-write\uff09\u3002</p> <p>\u7136\u800c\u5176\u4ed6\u56e0\u7d20\u9020\u6210\u7684\u5047\u4f9d\u8d56\u4e5f\u5b58\u5728\u3002\u5047\u4f9d\u8d56\u7531 WAR (write-after-read) \u548c WAW (write-after-write) \u5bfc\u81f4\u3002</p> <p>Artificial dependences can be caused in a number of ways, for example: by unoptimized code, by limited register storage, by the desire to economize on main memory storage, and by loops where an instruction can cause a hazard with itself.</p> <p>\u56e0\u6b64\uff0c\u786c\u4ef6\u8c03\u5ea6\u53ef\u80fd\u8981\u6c42\u4e71\u5e8f\u6267\u884c\u3001\u63a8\u6d4b\u6267\u884c\u3001\u5b58\u50a8\u4e0d\u53ef\u4ee5\u7acb\u523b\u66f4\u65b0\uff0c\u6570\u636e\u8f6c\u53d1\u3002\u72b6\u6001\u66f4\u65b0\uff08\u901a\u5e38\u79f0\u4e3a\u6307\u4ee4\u7684\u63d0\u4ea4 committing \u6216\u8005\u8fc7\u65f6 retiring\uff09\u4e0d\u5728\u6267\u884c\u540e\u800c\u5728\u786e\u5b9a\u987a\u5e8f\u6267\u884c\u6a21\u578b\u4f1a\u6267\u884c\u8be5\u6307\u4ee4\u540e\u3002</p> <p></p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#ss","title":"\u5178\u578b SS \u5904\u7406\u5668\u7684\u5fae\u4f53\u7cfb\u7ed3\u6784","text":"<p>\u5178\u578b\u7ed3\u6784\uff1a</p> <ol> <li>\u53d6\u6307\u4e0e\u5206\u652f\u9884\u6d4b</li> <li>\u8bd1\u7801\u4e0e\u5bc4\u5b58\u5668\u4f9d\u8d56\u5206\u6790</li> <li>\u53d1\u5c04\u4e0e\u6267\u884c</li> <li>\u5185\u5b58\u64cd\u4f5c\u5206\u6790\u4e0e\u6267\u884c</li> <li>\u6307\u4ee4\u91cd\u6392\u5e8f\u4e0e\u63d0\u4ea4</li> </ol> <p>\u6ce8\u610f\u8fd9\u79cd\u5206\u6bb5\u53ef\u80fd\u672a\u5fc5\u80fd\u548c\u6d41\u6c34\u7ebf\u9636\u6bb5\u5bf9\u5e94\u3002\u9019\u4e9b\u5de5\u4f5c\u6703\u7d66\u5225\u4eba\u505a\u53bb\u4e86\uff01\u653e\u4e00\u6bb5\u539f\u6587\uff1a</p> <p>Keep in mind that underlying this organization there is a pipelined implementation where specific pipeline stages may or may not be aligned with the major phases of superscalar execution. The underlying pipeline stages are to some extent a lower-level logic design issue, depending on how much work is done in each pipeline stage. This will affect the clock period and causes some very important design tradeoffs regarding the degree of pipelining and the width of parallel instruction issue. However, we will not discuss these issues in detail here; discussions of these types of tradeoffs can be found in [13], [34], [38].</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_3","title":"\u53d6\u6307","text":"<p>\u9700\u8981\u7f13\u5b58\u652f\u6301\u4e00\u5468\u671f\u591a\u5730\u5740\u8bfb\uff0c\u5e76\u4e14\u6570\u91cf\u5e94\u8be5\u4e0d\u5c0f\u4e8e\u8bd1\u7801\u548c\u6267\u884c\u7684\u5355\u5468\u671f\u5cf0\u503c\u3002\u4f7f\u7528 buffer \u6765\u51cf\u5c11\u7531\u4e8e cache miss \u6216\u8005\u5206\u652f\u9020\u6210\u7684\u963b\u585e\u3002</p> <p>\u5bf9\u4e8e\u5206\u652f\u6307\u4ee4\u7684\u5904\u7406\u5f88\u91cd\u8981\u3002\u5206\u6790\u5206\u652f\u6307\u4ee4\u5224\u65ad\u7684\u4e00\u822c\u6d41\u7a0b\uff1a</p> <ol> <li>\u9274\u522b\u5206\u652f\u6307\u4ee4</li> <li>\u8ba1\u7b97\u662f\u5426\u5206\u652f</li> <li>\u8ba1\u7b97\u5206\u652f\u5730\u5740</li> <li>\u91cd\u5b9a\u4f4d\u53d6\u6307</li> </ol> <p>\u901a\u5e38\u91c7\u7528\u5982\u4e0b\u7684\u6280\u672f\u5904\u7406\uff1a</p> <ol> <li>\u9274\u522b\u5206\u652f\u6307\u4ee4\uff1acache \u4e2d\u901a\u8fc7 pre-decode \u7684\u624b\u6bb5\u5b58\u50a8\u989d\u5916\u7684\u4fe1\u606f\u3002\u5f88\u96be\u901a\u8fc7 opcode \u7684\u9009\u62e9\u5b9e\u73b0\uff0c\u7531\u4e8e\u517c\u5bb9\u6027\u548c\u7801\u5b57\u957f\u5ea6\u7b49\u9650\u5236\u3002</li> <li>\u8ba1\u7b97\u662f\u5426\u5206\u652f\uff1a\u901a\u5e38\u7528\u4e8e\u5224\u65ad\u7684\u6570\u636e\u5c1a\u5b58\u5728\u4f9d\u8d56\u5173\u7cfb\uff0c\u56e0\u6b64\u91c7\u7528\u9884\u6d4b\u3002</li> <li>\u8ba1\u7b97\u5206\u652f\u5730\u5740\uff1a\u91c7\u7528\u7f13\u5b58\u3002</li> <li>\u91cd\u5b9a\u4f4d\u53d6\u503c\uff1a\u4e0d\u7ba1\u662f\u5206\u652f\u53d1\u751f\u8fd8\u662f\u9884\u6d4b\u5206\u652f\u53d1\u751f\uff0c\u90fd\u4f1a\u9020\u6210\u81f3\u5c11\u4e00\u5468\u671f\u7684\u5ef6\u65f6\u3002\u6709\u4e9b buffer \u4f1a\u540c\u65f6\u53d6\u4e24\u79cd\u60c5\u51b5\u7684\u6307\u4ee4\u3002</li> </ol>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_4","title":"\u8bd1\u7801\uff0c\u91cd\u547d\u540d\u5bc4\u5b58\u5668\uff0c\u6307\u4ee4\u5206\u914d","text":"<p>\u8bd1\u7801\u9636\u6bb5\u4e3a\u6bcf\u4e2a\u6307\u4ee4\u751f\u6210\u4e00\u4e2a\u6267\u884c\u5143\u7ec4 execution tuple\u3002</p> <p>An execution tuple is an ordered list containing: 1) an operation to be executed, 2) the identities of storage elements where the input operands reside (or will eventually reside), and 3) locations where the instruction\u2019s result must be placed.</p> <p>\u7c7b\u4f3c\u4e8e RUU\uff0c\u4e0d\u8fc7\u8fd9\u7bc7\u6587\u7ae0\u4e2d\u53eb reorder buffer\u3002</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_5","title":"\u6307\u4ee4\u53d1\u5c04\u4e0e\u5e76\u884c\u6267\u884c","text":"<p>\u7b2c\u4e09\u79cd\u60c5\u51b5\uff0c\u4fdd\u7559\u7ad9\uff0c\u5b9e\u9645\u4e0a\u5c31\u662f\u8bfe\u4e0a\u5b66\u7684 RUU \u7684\u4e00\u90e8\u5206</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_6","title":"\u5904\u7406\u5185\u5b58\u64cd\u4f5c","text":"<p>Rather than have rename tables with information for each memory location, as we did in the case of registers, the general approach is to keep information only for a currently active subset of the memory locations, i.e., memory locations with currently pending memory operations, and search this subset associatively when memory needs to be accessed.</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_7","title":"\u63d0\u4ea4","text":"","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_8","title":"\u8f6f\u4ef6\u534f\u540c","text":"<p>Though a major selling point of superscalar processors is to speed up the execution of existing program binaries, their performance can be enhanced if new, optimized binaries can be created. (The new binary could use the same instruction set and the same sequential execution model as the old binary; the only difference might be the order in which the instructions are arranged.)</p> <p>\u6c47\u7f16\u6307\u4ee4\u7684\u4f18\u5316\u6392\u5e8f\u53ef\u4ee5\u4f7f\u5f97\u53d6\u6307\u66f4\u6709\u6548\u7387\u3002</p> <ol> <li>\u4f7f\u5f97\u4e00\u7ec4\u6307\u4ee4\u53ef\u4ee5\u88ab\u540c\u65f6\u53d1\u5c04</li> <li>\u51cf\u5c11\u5b58\u5728\u771f\u6570\u636e\u4f9d\u8d56\u7684\u53ef\u80fd\u6027</li> </ol>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#_9","title":"\u4e09\u4e2a\u4f8b\u5b50","text":"<ul> <li>MIPS R10000: Typical framework described above.</li> <li>DEC Alpha 21164: Striving for greter simplicity.</li> <li>AMD K5: Implementing a more complex and older instruction set, the Intel x86.</li> </ul>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#mips-r10000","title":"MIPS R10000","text":"<p>\u540c\u65f6\u53d6\u56db\u6761\u6307\u4ee4\u3002\u6307\u4ee4\u5728\u8fdb\u5165 icache \u65f6\u4f1a predecode \u4ea7\u751f 4 bit \u4fe1\u606f\u3002\u5177\u4f53\u53c2\u6570\u7565\u3002\u6709\u8da3\u7684\u662f\u4f1a\u540c\u65f6\u5728 resume cache \u4e2d\u4fdd\u5b58\u5206\u652f\u9884\u6d4b\u4ea7\u751f\u8df3\u8f6c\u65f6\u7684\u539f\u672c\u987a\u5e8f\u6307\u4ee4\u3002</p> <p>\u91c7\u7528\u7269\u7406\u5bc4\u5b58\u5668\u7684\u65b9\u5f0f\uff0c\u5176\u5bb9\u91cf\u65f6\u903b\u8f91\u5bc4\u5b58\u5668\u7684\u4e24\u500d\u3002</p> <p>\u4e09\u4e2a instruction queues\u3002\u4e71\u5e8f\u6267\u884c\uff08\u5e76\u4e0d\u6309\u7167 queue \u4e2d\u7684\u987a\u5e8f\uff09\u3002</p> <p>\u540e\u7565\u3002</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/24/the-microarchitecture-of-superscalar-processors.html#conclusion","title":"Conclusion","text":"<p>After being fetched, the sequential instruction stream is torn apart with only true dependences holding the instructions together.</p> <p>\u968f\u7740\u786c\u4ef6\u8d44\u6e90\u7684\u589e\u52a0\uff0c\u8d85\u6807\u91cf\u5904\u7406\u5668\u7684\u6548\u76ca\u9012\u51cf\uff1a</p> <ol> <li>\u5373\u4f7f\u91c7\u7528\u975e\u5e38\u6fc0\u8fdb\u7684\u624b\u6bb5\uff0c\u76ee\u524d\u7684\u8d85\u6807\u91cf\u5904\u7406\u5668\u5728\u6307\u4ee4\u5e76\u884c\u5c42\u9762\u4ecd\u6709\u6781\u9650\u3002\u8fd9\u79cd\u6781\u9650\u4e3b\u8981\u662f\u6761\u4ef6\u5206\u652f\u3002\u771f\u5b9e\u5206\u652f\u9884\u6d4b\u76f8\u8f83\u4e8e\u5b8c\u7f8e\u5206\u652f\u9884\u6d4b\u8bd5\u5f97\u5230\u7684\u6027\u80fd\u6709\u8f83\u5927\u4e0b\u964d\u3002</li> <li>\u5e76\u884c\u6307\u4ee4\u6570\u7684\u589e\u52a0\u5bfc\u81f4\u786c\u4ef6\u5b9e\u73b0\u7684\u590d\u6742\u5ea6\u6fc0\u589e\uff0c\u4e5f\u5bfc\u81f4\u63a7\u5236\u903b\u8f91\uff08\u4ea4\u53c9\u68c0\u67e5\uff09\u5e73\u65b9\u589e\u52a0\uff0c\u5f71\u54cd\u4e3b\u9891\u3002</li> </ol> <p>\u6b64\u5916\uff0c\u5904\u7406\u5668\u6027\u80fd\u548c\u5185\u5b58\u6027\u80fd\u7684\u5dee\u8ddd\u5728\u589e\u52a0\u3002\u5305\u62ec\u66f4\u597d\u7684\u6570\u636e cache \u8bbe\u8ba1\uff0c\u66f4\u597d\u7684 prefetch \u624b\u6bb5\uff0c\u66f4\u590d\u6742\u7684\u5b58\u50a8\u5c42\u6b21\uff0c\u6570\u636e\u63d0\u4f9b\u80fd\u529b\u66f4\u4f18\u7684\u5185\u5b58\u7b49\u624b\u6bb5\u4e5f\u5728\u88ab\u63a2\u7d22\u3002\u8fd9\u4e5f\u662f\u5236\u7ea6\u6307\u4ee4\u5c42\u6b21\u5e76\u884c\u8fdb\u4e00\u6b65\u63d0\u5347\u7684\u56e0\u7d20\u3002</p> <p>8\u8def\u8d85\u6807\u91cf\u88ab\u8ba4\u4e3a\u662f\u5b9e\u9645\u7684\u6781\u9650\u3002\u4e0b\u4e00\u6b65\u662f\u4ec0\u4e48\uff1f\u6709\u7684\u5b66\u6d3e\u8ba4\u4e3a\u4f1a\u662f VLIW\uff0c\u4ed6\u4eec\u6709\u4e24\u4e2a\u652f\u6301\u539f\u56e0\uff1a</p> <ol> <li>\u8f6f\u4ef6\u5206\u6790\u4ea7\u751f\u7684\u5e76\u884c\u7a97\u53e3\u4f1a\u6bd4\u786c\u4ef6\u5206\u6790\u66f4\u5927\u3002</li> <li>\u786c\u4ef6\u4e0d\u5fc5\u505a\u4efb\u4f55\u4f9d\u8d56\u68c0\u67e5\uff0cVLIW \u786c\u4ef6\u66f4\u597d\u5b9e\u65bd\uff0c\u4e5f\u53ef\u4ee5\u6709\u66f4\u9ad8\u7684\u4e3b\u9891</li> </ol> <p>\u53cd\u5bf9\u8005\u8ba4\u4e3a\u8d85\u6807\u91cf\u7684\u63a7\u5236\u903b\u8f91\u4ea7\u751f\u7684\u5b9e\u9645\u6027\u80fd\u5f71\u54cd\u5e76\u4e0d\u5f88\u5927\uff1b\u4e14\u7f16\u8bd1\u65f6\u8c03\u5ea6\u672a\u5fc5\u6709\u5229\u7528\u8fd0\u884c\u65f6\u4fe1\u606f\u505a\u51fa\u7684\u52a8\u6001\u8c03\u5ea6\u597d\u3002</p> <p>\u53e6\u4e00\u79cd\u5b66\u6d3e\u8ba4\u4e3a\u53ef\u4ee5\u4e0d\u5fc5\u9075\u5b88\u987a\u5e8f\u6267\u884c\u6a21\u578b\uff08\u591a\u5904\u7406\u5668\uff09\u3002</p>","tags":["Superscalar","Microarchitecture","Proceedings of the IEEE"]},{"location":"blog/2024/10/26/s2adc-a-12-bit-125-mss-secure-sar-adc-with-power-side-channel-attack-resistance.html","title":"S2ADC: A 12-bit, 1.25-MS/s Secure SAR ADC With Power Side-Channel Attack Resistance","text":"","tags":["JSSC","DAC","Analog Security"]},{"location":"blog/2024/10/26/s2adc-a-12-bit-125-mss-secure-sar-adc-with-power-side-channel-attack-resistance.html#abstract","title":"abstract","text":"<p>\u6458\u8981\u63d0\u5230 ADC \u5728\u505a\u6570\u636e\u8f6c\u6362\u7684\u65f6\u5019\u4f1a\u66b4\u9732\u786c\u4ef6\u6f0f\u6d1e\u3002\u5229\u7528\u8f93\u51fa\u548c\u7535\u6e90\u7535\u6d41\u6ce2\u5f62\u7684\u5f3a\u76f8\u5173\uff0c\u53ef\u4ee5\u5b9e\u65bd ADC power side-channel attach (PSA) \u653b\u51fb\uff0c\u901a\u8fc7\u63a5\u5165\u7535\u6e90\u5077\u53d6\u8f6c\u6362\u7ed3\u679c\u3002\u672c\u6587\u63d0\u4f9b\u4e86\u4e24\u79cd\u57fa\u4e8e\u795e\u7ecf\u7f51\u7edc\u7684 SAR ADC PSA \u653b\u51fb\u7684\u65b9\u6cd5\uff0c\u5e76\u63d0\u4f9b\u4e86\u4e00\u4e2a 12-bit, 1.25-MS/s \u7684\u539f\u578b SAR ADC\uff0c\u5229\u7528\u7535\u6d41\u5e73\u8861\u62b5\u6297 PSA \u653b\u51fb\u3002\u7b2c\u4e00\u4e2a PSA \u624b\u6bb5\u5229\u7528\u4e86\u591a\u5c42\u611f\u77e5\u673a\uff0c\u7b2c\u4e8c\u4e2a\u5229\u7528\u4e86\u5377\u79ef\u795e\u7ecf\u7f51\u7edc\u3002\u5728\u4e0d\u8fdb\u884c\u9632\u8303\u7684\u60c5\u51b5\u4e0b\u5747\u53ef\u4ee5\u8fbe\u5230 99% \u4ee5\u4e0a\u7684\u51c6\u786e\u7387\uff1b\u9632\u8303\u63aa\u65bd\u5bf9\u4e8e MLP-PSA\u6709\u6781\u5f3a\u7684\u4f5c\u7528\uff0c\u5bf9 CNN-PSA \u7a0d\u5f31\uff0c\u4f46\u4ecd\u7136\u63d0\u4f9b\u4e86\u91cd\u8981\u7684\u624b\u6bb5\u3002</p>","tags":["JSSC","DAC","Analog Security"]},{"location":"blog/2024/10/26/s2adc-a-12-bit-125-mss-secure-sar-adc-with-power-side-channel-attack-resistance.html#introduction","title":"Introduction","text":"<p>\u6587\u4e2d\u63d0\u5230\u63ed\u9732ADC\u6f0f\u6d1e\u7684\u5de5\u4f5c\u6709:  1. An Encryption-Authentication Unified A/D Conversion Scheme for IoT Sensor Nodes A-SSCC 2018 2. A Random Interrupt Dithering SAR Technique for Secure ADC Against Reference-Charge Side-Channel Attack ISCAS 2020</p> <p>\u6587\u4e2d\u7684\u6a21\u578b\uff1a</p> <p></p> <p>Eavesdropping \u90e8\u5206\u53ef\u4ee5\u901a\u8fc7\u6570\u636e\u52a0\u5bc6\u7684\u65b9\u5f0f\u6d88\u9664\uff08\u8fd9\u91cc\u6d89\u53ca\u5230AES\u7b49\uff0c\u9700\u8981\u8fdb\u4e00\u6b65\u53bb\u770b\uff09\u3002\u9488\u5bf9\u6570\u636e\u52a0\u5bc6\uff0c\u53ef\u4ee5\u7528 PSA \u53bb\u653b\u51fb\u52a0\u5bc6\u786c\u4ef6\u3002\u8fd9\u4e00\u90e8\u5206\u5728\u6587\u7ae0\u53c2\u8003\u6587\u732e\u4e2d\u6709\u89e3\u51b3\uff0c\u4e3b\u8981\u662f ISSCC 2009 \u7b49\u3002\u76f4\u63a5\u63a5\u89e6\u53ef\u4ee5\u7528 tamper-proof package \u963b\u6b62\u3002\u56e0\u6b64\u672c\u6587\u9488\u5bf9\u7684\u90e8\u5206\uff0c\u5373\u5bf9\u6a21\u62df/\u6570\u6a21\u6df7\u5408\u7535\u8def\u7684 PSA \u653b\u51fb\u6709\u91cd\u8981\u6027\u3002\uff08tamper-proof package?)</p> <p>SAR ADC \u662f\u4ec0\u4e48\uff1f\u7b80\u5355\u6765\u8bf4\uff0c\u5c31\u662f\u7528\u4e00\u4e2a DAC \u6309\u7167\u4e8c\u5206\u67e5\u627e\u7684\u65b9\u5f0f\u641c\u7d22\u4e00\u4e2a\u548c\u5f53\u524d\u8f93\u5165\u7684\u6a21\u62df\u4fe1\u53f7\u63a5\u8fd1\u7684\u6570\u5b57\u4fe1\u53f7\u3002</p>","tags":["JSSC","DAC","Analog Security"]},{"location":"blog/2024/10/26/s2adc-a-12-bit-125-mss-secure-sar-adc-with-power-side-channel-attack-resistance.html#neural-network-based-sar-adc-psa-methods","title":"NEURAL-NETWORK-BASED SAR ADC PSA METHODS","text":"","tags":["JSSC","DAC","Analog Security"]},{"location":"blog/2024/10/26/s2adc-a-12-bit-125-mss-secure-sar-adc-with-power-side-channel-attack-resistance.html#circuit-implementation-and-information-leakage-sources-of-unprotected-sar-adc","title":"CIRCUIT IMPLEMENTATION AND INFORMATION LEAKAGE SOURCES OF UNPROTECTED SAR ADC","text":"<p>\u4e3b\u4ece\u7684 CDAC \u7684\u7ed3\u6784\u633a\u6709\u610f\u601d\u3002</p> <p></p> <p>\u8fd9\u4e2a\u7ed3\u6784\u975e\u5e38\u7684\u6709\u8da3\uff0c\u4e0d\u59a8\u5148\u53ea\u8003\u8651\u4e0b\u9762\u7684\u90e8\u5206\u30024-bit Sub-CDAC \u7b49\u6548\u4e8e\u4e00\u4e2a\u770b\u5165\u963b\u6297\u4e3a \\(1/16j\\omega C+1/j\\omega C_B\\) \u7684\u5f00\u8def\u7535\u538b\u662f \\(V_{Sub}\\) \u7535\u538b\u6e90\uff0c\u540c\u7406\u53e6\u4e00\u4fa7\u662f\u4e00\u4e2a\u770b\u5165\u963b\u6297\u4e3a \\(1/127j\\omega C\\) \u7684\u5f00\u8def\u7535\u538b\u662f \\(V_{Main}\\) \u7684\u7535\u538b\u6e90\u3002\u5219\u8f93\u51fa\u7684 \\(V_{DAC}\\) \u662f\uff1a $$ V_{DAC}=\\frac{(1/16C+1/C_B)V_{Main}+(1/127C)V_{Sub}}{1/16C+1/C_B+1/127C} $$</p> <p>\u663e\u7136\uff0c\u4e3a\u4e86\u4f7f Sub \u7535\u8def\u8d77\u5230 LSB \u7684\u4f5c\u7528\uff0c\u6211\u4eec\u8981\u6c42 $$ (\\frac{1}{16C}+\\frac{1}{C_B})\\times\\frac{V_{REF}}{127}=2^1\\times\\frac{1}{127C}\\times\\frac{V_{REF}}{2} $$</p> <p>\u5373\\(C_B=\\frac{16}{15}C\\)\u3002\u771f\u662f\u592a\u5999\u4e86\uff01\u5f88\u96be\u60f3\u8c61\u8fd9\u662f JSSC 1970 \u5e74\u4ee3\u53d1\u8868\u7684\u7535\u8def\u3002\u4e0d\u59a8\u8fdb\u4e00\u6b65\u5206\u6790\u4e00\u4e0b\u7535\u8def\u3002\u6b64\u65f6 \\(V_{DAC}=(127V_{Main}+V_{Sub})/128\\)\uff0c\u5176\u4e2d \\(V_{Main}\\in [0,V_{REF}]\\)\uff0c\\(V_{Sub}\\in[0,\\frac{15}{16}V_{REF}]\\)\u3002\u800c\u56fe\u4e2d\u4e0a\u534a\u90e8\u5206\u5bf9\u5076\u7684\u7535\u8def\u770b\u5165\u963b\u6297\u4e00\u81f4\uff0c\u552f\u4e00\u7684\u533a\u522b\u5728\u4e8e\u5176 \\(V_{Sub}\\in[\\frac{1}{16}V_{REF},V_{REF}]\\)\uff0c\u8fd9\u4ee3\u8868\u7740\u5176\u8f93\u51fa\u7535\u538b\u6700\u9ad8\u53ef\u4ee5\u4ea7\u751f \\(V_{REF}\\) \u7684\u7535\u538b\u3002\u8fd9\u5c31\u5b8c\u5168\u7406\u89e3\u4e86\u6574\u4e2a\u7535\u8def\u3002</p> <p>\u5bf9 PSA \u653b\u51fb\u505a\u9632\u5fa1\u7684\u6838\u5fc3\u90e8\u5206\u662f\u4e0b\u56fe\u7684\u7535\u6d41\u5747\u8861\u5668\u3002</p> <p></p> <p>\u8fd9\u4e2a\u7535\u8def\u7684\u5206\u6790\u76f8\u5bf9\u5e73\u51e1\uff0c\u7565\u53bb\u3002</p>","tags":["JSSC","DAC","Analog Security"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html","title":"SLAP: Data Speculation Attacks via Load Address Prediction on Apple Silicon","text":"","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#abstract","title":"Abstract","text":"<p>\u5229\u7528 Apple \u7684 Early Load \u673a\u5236\u7684\u653b\u51fb\u88ab\u505a\u51fa\u6765\u4e86\u3002</p> <p>\u81ea 2018 \u5e74 Spectre \u9996\u6b21\u62ab\u9732\u4ee5\u6765\uff0c\u7531\u4e8e\u96be\u4ee5\u5728\u786c\u4ef6\u4e2d\u5b8c\u5168\u7f13\u89e3\u63a8\u6d4b\u6267\u884c\u653b\u51fb\uff0c\u8fc7\u53bb\u516d\u5e74\u4e2d\u51fa\u73b0\u4e86\u51e0\u79cd\u65b0\u7684\u53d8\u4f53\u548c\u653b\u51fb\u9762\u3002 \u5927\u591a\u6570\u884d\u751f\u90fd\u5efa\u7acb\u5728\u539f\u59cb Spectre \u653b\u51fb\u7684\u5173\u952e\u6d1e\u5bdf\u4e4b\u4e0a\uff0c\u5373 CPU \u53ef\u4ee5\u5728\u5c1d\u8bd5\u7f13\u89e3\u63a7\u5236\u51b2\u7a81\uff08\u4f8b\u5982\u6761\u4ef6\u6216\u95f4\u63a5\u5206\u652f\u548c\u8fd4\u56de\u8bed\u53e5\uff09\u65f6\u6682\u65f6\u6267\u884c\u9519\u8bef\u7684\u63a7\u5236\u6d41\u5e76\u901a\u8fc7\u4fa7\u4fe1\u9053\u8ddf\u8e2a\u6cc4\u9732\u673a\u5bc6\u3002</p> <p>\u672c\u6587\u4e2d\uff0c\u6211\u4eec\u8d85\u8d8a\u4e86\u5f71\u54cd\uff08\u63a8\u6d4b\u7684\uff09\u63a7\u5236\u6d41\uff0c\u5e76\u63d0\u51fa\u4e86\u4e00\u79cd\u65b0\u7684\u6570\u636e\u63a8\u6d4b\u539f\u8bed\uff0c\u5b83\u6e90\u4e8e\u65e8\u5728\u7f13\u89e3\u6570\u636e\u98ce\u9669\u7684\u5fae\u67b6\u6784\u4f18\u5316\u3002 \u66f4\u5177\u4f53\u5730\u8bf4\uff0c\u6211\u4eec\u8868\u660e Apple CPU \u914d\u5907\u4e86\u52a0\u8f7d\u5730\u5740\u9884\u6d4b\u5668 (LAP)\u3002 LAP \u76d1\u63a7\u6765\u81ea\u76f8\u540c\u52a0\u8f7d\u6307\u4ee4\u7684\u8fc7\u53bb\u5730\u5740\uff0c\u4ee5\u63a8\u6d4b\u6027\u5730\u52a0\u8f7d\u9884\u6d4b\u5730\u5740\uff0c\u8be5\u5730\u5740\u53ef\u80fd\u4f1a\u9519\u8bef\u5730\u6307\u5411\u9759\u6b62\u7684\u79d8\u5bc6\uff08\u5373\uff0c\u4ece\u672a\u88ab CPU \u4ece\u67b6\u6784\u4e0a\u8bfb\u53d6\uff09\u3002 \u4e00\u65e6\u68c0\u7d22\u5230\u79d8\u5bc6\uff0cLAP \u5c31\u4f1a\u63d0\u4f9b\u4e00\u4e2a\u5f88\u5927\u7684\u63a8\u6d4b\u7a97\u53e3\uff0c\u8db3\u4ee5\u8ba9\u5bf9\u624b\u8ba1\u7b97\u79d8\u5bc6\uff0c\u4f8b\u5982\u901a\u8fc7\u9690\u853d\u901a\u9053\u6cc4\u9732\u79d8\u5bc6\u3002 \u6211\u4eec\u5c55\u793a\u4e86 LAP \u5728\u6700\u8fd1\u7684 Apple CPU\uff08\u4f8b\u5982 M2\u3001A15 \u548c\u66f4\u65b0\u578b\u53f7\uff09\u4e0a\u7684\u5b58\u5728\u3002 \u7136\u540e\uff0c\u6211\u4eec\u901a\u8fc7\u5c55\u793a\u5176\u8bfb\u53d6\u8d8a\u754c\u3001\u63a8\u6d4b\u6027\u8c03\u7528\u6076\u610f\u51fd\u6570\u3001\u7834\u574f ASLR \u548c\u7834\u574f Safari \u7f51\u7edc\u6d4f\u89c8\u5668\u7684\u80fd\u529b\u6765\u8bc4\u4f30 LAP \u5bf9\u5b89\u5168\u6027\u7684\u5f71\u54cd\u3002 \u5728\u8fd9\u91cc\uff0c\u6211\u4eec\u5229\u7528 LAP \u5411\u8fdc\u7a0b\u7f51\u7edc\u5bf9\u624b\u62ab\u9732\u654f\u611f\u7684\u8de8\u7ad9\u70b9\u6570\u636e\uff08\u4f8b\u5982\u6765\u81ea Gmail \u7684\u6536\u4ef6\u7bb1\u5185\u5bb9\uff09\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#introduction","title":"Introduction","text":"<p>\u5728\u5df2\u6709\u7684\u5bf9\u4e8e\u63a7\u5236\u6d41\u7684\u63a8\u6d4b\u6267\u884c\u4ee5\u5916\uff0c\u8fd8\u53ef\u4ee5\u6709\u5bf9\u4e8e\u6570\u636e\u6d41\u7684\u63a8\u6d4b\u6267\u884c\u3002 \u867d\u7136\u5df2\u7ecf\u89c2\u5bdf\u5230\u67d0\u4e9b\u5f62\u5f0f\u7684\u6b64\u7c7b\u6570\u636e\u63a8\u6d4b\uff0c\u4e3b\u8981\u662f\u901a\u8fc7\u6570\u636e\u76f8\u5173\u7684\u786c\u4ef6\u9884\u53d6\u5668\u3001\u5b58\u50a8\u5230\u52a0\u8f7d\u8f6c\u53d1\u9884\u6d4b\u6216\u6d6e\u70b9\u95ee\u9898\uff0c\u4f46\u8981\u5b8c\u5168\u8868\u5f81\u73b0\u4ee3 CPU \u5e73\u53f0\u4e0a\u5b58\u5728\u7684\u6240\u6709\u5f62\u5f0f\u7684\u6570\u636e\u63a8\u6d4b\uff0c\u8fd8\u6709\u5f88\u591a\u5de5\u4f5c\u8981\u505a\u3002</p> <p>\u73b0\u4ee3 CPU \u4e0a\u662f\u5426\u5b58\u5728\u989d\u5916\u7684\u6570\u636e\u63a8\u6d4b\u673a\u5236\uff1f \u5982\u679c\u6709\uff0c\u8fd9\u79cd\u63a8\u6d4b\u7684\u5b89\u5168\u9690\u60a3\u662f\u4ec0\u4e48\uff1f</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#_1","title":"\u8d21\u732e","text":"","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#reverse-engineering-the-lap","title":"Reverse Engineering the LAP","text":"<p>\u6587\u7ae0\u5f88\u5de7\u5999\u7684\u5229\u7528\u4e86\u65f6\u95f4\u53bb\u63a8\u6d4b LAP \u7684\u5b58\u5728\u3002\u76f8\u8f83\u4e8e\u6211\u4e4b\u524d\u662f\u571f\u901a\u8fc7 Load Bypass \u673a\u5236\u4ee5\u53ca\u540e\u7eed\u7684\u6682\u6001\u6267\u884c\u6765\u9006\u5411\uff0c\u8fd9\u79cd\u65b9\u6cd5\u66f4\u52a0\u76f4\u63a5\u4e5f\u66f4\u52a0\u6709\u6548\u3002</p> <p>\u6587\u7ae0\u9996\u5148\u786e\u8ba4\u4e86\u5b58\u5728 Load Data Speculation\uff0c\u8fdb\u4e00\u6b65\u786e\u8ba4\u662f\u901a\u8fc7 LAP \u5b9e\u73b0\u7684\u3002 \u5728\u6b64\u57fa\u7840\u4e0a\uff0c\u786e\u8ba4 LAP \u7684\u89e6\u53d1\u6761\u4ef6\u4ee5\u53ca\u5b58\u5728\u57fa\u4e8e LAP \u7ed3\u679c\u7684\u6682\u6001\u6267\u884c\u3002 \u6700\u7ec8\u8ba8\u8bba\u5904\u7406\u5668\u5bf9 LAP \u7684\u9650\u5236\uff0c\u5982 address checks and instruction tagging\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#observing-load-data-speculation","title":"Observing Load Data Speculation","text":"<p>\u7528 pointer-chasing \u6784\u9020\u51fa\u4e00\u4e2a\u4f9d\u8d56\u94fe\uff0c\u6d4b\u91cf Strding \u548c Random \u7684\u65f6\u95f4\u3002</p> <p>\u9996\u5148 dry-run \u4e00\u6b21\uff0c\u5168\u90e8\u52a0\u8f7d\u5230 cache \u907f\u514d prefetching \u7684\u5f71\u54cd\u3002</p> <p>\u4e3a\u4ec0\u4e48\u4f1a\u51fa\u73b0drop\uff1f</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#confirming-load-address-prediction","title":"Confirming Load Address Prediction","text":"<p>\u6d4b\u91cf Striding Address from Random Value \u7684\u65f6\u95f4\u3002</p> <p>\u8fd9\u91cc\u5bf9 iPhone \u7684\u5904\u7406\u529e\u6cd5\u5f88\u5de7\u5999\uff1a</p> <p>However, A-series CPUs are available only on iOS devices, where we do not have access to CPU cycle counters. As such, we develop a portable version of the Random, Striding, and SA+RV experiments by compiling them to WebAssembly. We then compile the WebAssembly binary to machine code using WebKit, the engine underlying the Safari web browser. Since the timer resolution in WebKit is coarse (1 ms), we fix the number of iterations to one million to amplify the timing difference, while keeping the stride unchanged at 32 bytes.</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#confirming-speculative-execution-via-lap","title":"Confirming Speculative Execution via LAP","text":"<p>\u8bef\u5bfc+FR\u7684\u65b9\u5f0f\u9a8c\u8bc1\u3002</p> <p>\u6ce8\u610f\u5230\uff1a</p> <p>For accurate measurements, we require the ability to count cycles and flush cache lines from userspace programs. Furthermore, to reduce noise and variation, we require the ability to manually control CPU frequency, isolate CPU cores from being used by operating system processes, and pin programs to the isolated cores.</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#spatial-conditions-for-speculation","title":"Spatial Conditions for Speculation","text":"<p>\u4fee\u6539\u8bad\u7ec3\u5e8f\u5217\u957f\u5ea6\u548c\u6b65\u957f\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#temporal-conditions-for-speculation","title":"Temporal Conditions for Speculation","text":"<p>\u5728\u7a97\u53e3\u671f\u63d2\u5165\u989d\u5916\u7684\u6307\u4ee4\u3002</p> <p>\u6ce8\u610f\u5230\u8fd9\u91cc\u63d0\u5230\u4e86\u5982\u679c LAP \u5f97\u5230\u7684\u5730\u5740\u4e0d\u5728 cache \u4e2d\uff0c\u4f1a\u4e0d\u8fdb\u884c\u63a8\u6d4b\u3002 \u8fd9\u548c patent \u4e2d\u7684\u5185\u5bb9\u662f\u4e00\u81f4\u7684\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#confirming-instruction-address-tagging","title":"Confirming Instruction Address Tagging","text":"<p>\u4f7f\u7528\u5168\u90e8\u7684 canonical address bits \u4f5c\u4e3a tag\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#weaponizing-the-lap-for-attacks","title":"Weaponizing the LAP for Attacks","text":"<p>\u8bc1\u660e\u904d\u5386\u94fe\u8868\u6fc0\u6d3b LAP \u53ef\u4ee5\u52ab\u6301\u63a7\u5236\u6d41\u548c\u6570\u636e\u6d41\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#spectre-lap","title":"Spectre-LAP","text":"<p>\u7531\u4e8e\u9884\u6d4b\u7684\u5730\u5740\u53d7\u5236\u4e8e\u6b65\u957f 255 bytes\uff0c\u653b\u51fb\u5b58\u5728\u4e00\u5b9a\u7684\u56f0\u96be\u3002 \u4f46\u662f\u7531\u4e8e\u9884\u6d4b\u6267\u884c\u7684\u7a97\u53e3\u671f\u5f88\u957f\uff0c\u6211\u4eec\u53ef\u4ee5\u6682\u6001\u5730\u8bbf\u95ee\u4efb\u4f55\u5730\u5740\u7a7a\u95f4\u3002</p> <p>\u53ef\u4ee5\u5b9e\u73b0\u6570\u636e\u548c\u63a7\u5236\u6d41\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#_2","title":"\u5b9e\u9a8c\u590d\u73b0","text":"<p>\u5c1d\u8bd5\u5728 Mac mini M2 (t8112) , macOS 15.2 (24C101) \u4e0a\u590d\u73b0\u5b9e\u9a8c\u3002 \u53c2\u8003\u7f51\u7ad9 [https://github.com/slap-flop/slap-artifacts]\u3002 \u7531\u4e8e OS \u6709\u5927\u7248\u672c\u66f4\u65b0\uff0c\u8bb0\u5f55\u548c README \u6709\u6240\u4e0d\u540c\u7684\u90e8\u5206\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#kernel","title":"\u6253\u7528\u4e8e\u83b7\u53d6\u7cbe\u786e\u65f6\u95f4\u6253 Kernel \u8865\u4e01","text":"<ol> <li>\u4ece [https://developer.apple.com/download/all/] \u4e0b\u8f7d\u5bf9\u5e94 macOS \u7248\u672c\u7684 Kernel Debug Kit\u3002</li> <li>\u5728 Recovery Mode \u4e0b\u5173\u95ed SIP <code>csrutil disable</code>\uff0c\u5e76\u5173\u95ed\u542f\u52a8\u76d8\u7684\u6240\u6709\u5b89\u5168\u9009\u9879\u3002\u8fd9\u4e00\u6b65\u9700\u8981\u5148\u505a\uff0c\u4e0d\u7136\u65e0\u6cd5\u4fee\u6539\u542f\u52a8\u53c2\u6570\u3002</li> <li>\u4fee\u6539\u542f\u52a8\u53c2\u6570<code>sudo nvram boot-args=\"-unsafe_kernel_text\"</code>\uff0c\u907f\u514d\u542f\u52a8\u65f6 kernel panic\u3002</li> <li>\u5176\u4f59\u6309\u7167 README \u64cd\u4f5c\u3002</li> </ol>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#enable-dc-civac-cache","title":"enable-dc-civac \u5141\u8bb8\u5bf9 cache \u7684\u64cd\u4f5c","text":"<ol> <li>\u9996\u5148\u4fee\u6539\u542f\u52a8\u53c2\u6570<code>sudo nvram boot-args=\"enable_skstb=1\"</code>\uff0c\u5141\u8bb8\u5bf9<code>kern.sched_thread_bind_cpu</code>\u7684\u64cd\u4f5c\u3002\u8fd9\u4e00\u6b65\u5728 README \u4e2d\u6ca1\u6709\u63d0\u5230\uff0c\u5982\u679c\u4e0d\u64cd\u4f5c\u4f1a\u5728\u8fd0\u884c\u6d4b\u8bd5\u7a0b\u5e8f\u65f6\u62a5\u6743\u9650\u9519\u8bef\u3002</li> <li>\u5176\u4f59\u6309\u7167 README \u64cd\u4f5c\u3002</li> </ol>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#slap","title":"slap \u590d\u73b0","text":"","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2025/02/11/slap-data-speculation-attacks-via-load-address-prediction-on-apple-silicon.html#raw-loop","title":"Raw Loop","text":"<p>\u590d\u73b0\u6210\u529f\u3002</p>","tags":["S&P","Apple Silicon","Early Load"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html","title":"Securing Time in Untrusted Operating Systems with TimeSeal","text":"<p>\u8fd9\u7bc7RTSS\u20182019\u6587\u7ae0\u4e3b\u8981\u5173\u6ce8\u6297delay attack\u548cscheduling attack\u53ef\u4fe1\u7ec6\u7c92\u5ea6\u65f6\u95f4\u3002</p>","tags":["RTSS","TCS"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html#_1","title":"\u80cc\u666f","text":"<p>\u5bf9 time stack \u7684\u653b\u51fb\u6587\u7ae0\u5f52\u7ed3\u4e3a\u4e09\u4e2a\u90e8\u5206\uff1a \u5bf9\u786c\u4ef6\u5bc4\u5b58\u5668\u7684\u7279\u6743\u5199\uff0c\u5bf9\u65f6\u95f4\u4fe1\u606f\u4f20\u8f93\u8fc7\u7a0b\u7684\u5ef6\u8fdf\uff0c\u5b89\u5168\u7684 timekeeping software\u3002</p> <p>\u6587\u7ae0\u8ba4\u4e3a SGX \u63d0\u4f9b\u7684\u65f6\u949f\u662f trusted \u7684\uff0c\u4f46\u662f coarse-grained\u3002 \u4e14\u6587\u7ae0\u63d0\u51fa\u7684\u5a01\u80c1\u6a21\u578b\u8ba4\u4e3a compromised OS \u662f\u4e00\u4e2a stealthy attacker\u3002 \u56e0\u6b64\u4e0d\u4f1a\u6253\u4e71\u65f6\u95f4\u5305\u7684\u987a\u5e8f\u6216\u8005\u4e22\u5f03\u65f6\u95f4\u5305\uff08\u8fd9\u91cc\u5176\u5b9e\u6bd4\u8f83\u5f31\uff09\u3002 \u6b64\u5916\uff0c\u64cd\u4f5c\u7cfb\u7edf\u5177\u6709\u6076\u610f\u8c03\u5ea6\u7684\u80fd\u529b\uff08\u4f46\u5f88\u5feb\u6211\u4eec\u4f1a\u770b\u5230\u7531\u4e8e stealthy \u7684\u539f\u56e0\uff0c\u8fd9\u4e2a\u80fd\u529b\u4e5f\u662f\u6709\u9650\u7684\uff09\u3002</p>","tags":["RTSS","TCS"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html#_2","title":"\u8bbe\u8ba1","text":"","tags":["RTSS","TCS"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html#fine-grained-time","title":"\u63d2\u503c\u83b7\u5f97 fine-grained time","text":"<p>\u601d\u8def\u5f88\u7b80\u5355\uff0c\u7528 \u4e00\u4e2a\u8f6f\u4ef6\u5faa\u73af\u9012\u589e\u4e00\u4e2a counter\uff0c\u7136\u540e\u7528\u4e0a\u4e00\u4e2a\u5468\u671f\u7684 counter \u589e\u52a0\u91cf\u6765\u4f30\u8ba1\u5f53\u524d\u7684\u65f6\u95f4\u3002 \u8fd9\u91cc\u4f1a\u51fa\u73b0\u7531\u4e8eOS\u538b\u529b\u7684\u95ee\u9898\u5bfc\u81f4 counter \u589e\u52a0\u91cf\u4e0d\u7a33\u5b9a\u7684\u95ee\u9898\uff0c\u8fdb\u800c\u5bfc\u81f4\u4e0d\u5355\u8c03\u7684\u95ee\u9898\u3002 \u6587\u7ae0\u91c7\u7528\u4e86\u5728\u5e73\u53f0\u7b49\u5f85\u7684\u65b9\u5f0f\uff0c\u7b49\u5f85\u7684counter\u589e\u91cf\u662f\u7531\u8d85\u51fa\u91cf\u4f30\u8ba1\u5f97\u5230\u3002</p>","tags":["RTSS","TCS"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html#scheduling-attack","title":"scheduling attack","text":"<p>\u8fd9\u91cc\u91c7\u7528\u591a\u4e2a thread \u6765\u8ba1\u6570\u3002 \u4e3a\u4e86\u6240\u8c13\u7684 stealthy\uff0c\u8fd9\u91cc\u5c45\u7136\u5047\u5b9a\u5728 1 sec \u5185\u963b\u585e\u6240\u6709\u8ba1\u65f6\u7ebf\u7a0b\u662f\u4e0d\u5141\u8bb8\u7684\u3002</p>","tags":["RTSS","TCS"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html#delay-attack","title":"delay attack","text":"<p>\u8fd9\u91cc\u91c7\u7528\u9608\u503c\u52a0\u8bef\u5dee\u4f30\u8ba1\u7684\u65b9\u5f0f\u5b9e\u73b0\u3002</p> <p></p>","tags":["RTSS","TCS"]},{"location":"blog/2024/11/27/securing-time-in-untrusted-operating-systems-with-timeseal.html#rmk","title":"rmk","text":"<p>\u672c\u6587\u5176\u5b9e\u633a trivial \u7684\u3002\u4f46\u662f\u6587\u4e2d\u63d0\u5230\u7684\u4e00\u4e9bapplications\u548crelated works\u53ef\u4ee5\u53c2\u8003\u3002</p>","tags":["RTSS","TCS"]},{"location":"blog/2024/11/01/ubuntu-2404-%E5%AE%89%E8%A3%85-ads2020update2-%E7%A0%B4%E8%A7%A3%E7%89%88.html","title":"Ubuntu 24.04 \u5b89\u88c5 ads2020Update2 \u7834\u89e3\u7248","text":"<p>\u8bfe\u7a0b\u9700\u8981\u4f7f\u7528 ads \u4eff\u771f\uff0c\u4f46\u662f\u53ea\u7ed9\u4e86 windows \u7684\u5b89\u88c5\u5305\u3002\u4ee5\u4e0b\u662f\u5728 Ubuntu 24.04 \u4e0a\u5b89\u88c5\u7684\u8fc7\u7a0b\u3002</p> <p>\u9996\u5148\u5b89\u88c5\u5fc5\u8981\u7684\u7a0b\u5e8f\u548c\u5e93\uff1a</p> <pre><code>sudo ln -s /lib64/ld-linux-x86-64.so.2 /lib64/ld-lsb-x86-64.so.3\nsudo apt install ksh\n</code></pre> <p>\u5b98\u7f51\u4e0b\u8f7d ads2020Update2\u3002\u5b89\u88c5\u3002</p> <pre><code>tar \u2013xvf ads_2020_update2.0_linux_x64.tar\nsudo SETUP.SH\n</code></pre> <p>\u9ed8\u8ba4\u7684\u5b89\u88c5\u76ee\u5f55\u662f<code>/usr/local/ADS2020_update2</code></p> <p>\u8bbe\u7f6e\u73af\u5883\u53d8\u91cf\uff1a</p> <pre><code>export HPEESOF_DIR=\"/usr/local/ADS2020_update2\"\nexport ADS_LICENSE_FILE=\"/usr/local/ADS2020_update2/license.lic\"\nexport PATH=\"$HPEESOF_DIR/bin:$PATH\"\n</code></pre> <p>\u4e0b\u8f7d\u7834\u89e3\u6587\u4ef6\u3002</p> <pre><code>cp ./pubkey_verify $HPEESOF_DIR\ncp ./license.lic $HPEESOF_DIR\nsudo $HPEESOF_DIR/pubkey_verify -y\n$HPEESOF_DIR/Licensing/2020.20/linux_x86_64/bin/aglmmgr\n</code></pre>","tags":["Ubuntu 24.04","ADS","\u8bfe\u7a0b\u8f6f\u4ef6"]},{"location":"blogroll/index.html","title":"Blogroll","text":"ClF3's blog \u81f3\u5c11\u5728\u8fd9\u4e00\u523b\uff0c\u70ed\u7231\u4e0d\u95ee\u4e3a\u4f55\uff01"},{"location":"blog/archive/2025.html","title":"2025","text":""},{"location":"blog/archive/2024.html","title":"2024","text":""},{"location":"blog/category/tools.html","title":"tools","text":""},{"location":"blog/category/paper.html","title":"paper","text":""},{"location":"blog/page/2/index.html","title":"Index","text":""}]}